# SINGLE-FILE BUNDLE — auto-generated by build_bundle.py. DO NOT EDIT.
# Edit the real sources (main_bot.py + helper modules) and re-run:
#     python build_bundle.py
# Deploy this file AS main_bot.py so `uvicorn main_bot:app` keeps working.
