import sys as _bundle_sys
import types as _bundle_types


def _bundle_load(_name, _src):
    """Compile an embedded helper as its own module (from __future__ legal)."""
    _mod = _bundle_types.ModuleType(_name)
    _mod.__file__ = _name + ".py"
    _bundle_sys.modules[_name] = _mod
    exec(compile(_src, _name + ".py", "exec"), _mod.__dict__)

_bundle_load('state_store', r'''
"""
Distributed state store — Redis-first, with a loud in-memory fallback.
=====================================================================

Replaces the old STATE_FILE + in-memory dicts (_open_positions, _stop_guards)
and the _TTL idempotency store with Redis so that:

  • multiple workers share ONE source of truth (safe horizontal scaling)
  • Railway/Render cold starts lose nothing (state lives in Redis, not RAM/disk)
  • critical sections (order placement, close, reconciliation) run under a
    distributed lock so two workers can never double-place or double-close

Key layout (exact names, no surprises):

  open_positions:{TICKER}      JSON position record
  open_positions:index         SET of tickers with an open position
  stop_guard:{TICKER}          JSON guard record (equity or option)
  stop_guards:index            SET of tickers with a guard record
  daily:{YYYY-MM-DD}           HASH {trades_today, realized_pnl_today_pct} (3-day TTL)
  balance:snapshot             JSON {value, ts} — last broker buying-power fetch
  balance:delta                HASH {delta} — running win/loss/cost adjustment since snapshot
  killed                       "1" when the kill switch is engaged
  sig:{sha1}                   idempotency keys (24h TTL, SET NX)
  cooldown:{TICKER}            ticker cooldown (TTL)
  lock:{name}                  distributed locks (SET NX PX + token + Lua release)
  reconcile:last               JSON report of the last reconciliation pass

Every method is async. When REDIS_URL is absent or Redis is unreachable the
store degrades to a single-process in-memory backend and logs a loud warning —
correct for local dev, NOT safe for multi-worker production.

DURABLE MEMORY MODE: when no Redis is available but a `persistence` adapter is
supplied (duck-typed: async `load_all() -> [(key, kind, value)]`,
`save(key, kind, value)`, `delete(key)` — the bot wires this to Postgres), the
memory backend becomes restart-safe: durable keys (positions, guards, indexes,
daily counters, kill switch, and any un-TTL'd config like the pinned account or
alert webhook) are written through to the adapter on every mutation and
hydrated back at boot. Ephemeral keys (locks, idempotency sig:, cooldowns,
balance snapshots — anything with a TTL) deliberately stay memory-only: their
expiry IS their meaning, and resurrecting them stale would be wrong. This was
the production gap: LIVE trading with no REDIS_URL meant every container
restart erased open positions, ratcheted trails, today's realized P&L (the
daily loss limit's memory) and the kill switch.
"""
from __future__ import annotations

import asyncio
import json
import logging
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

logger = logging.getLogger("etrade-bot.state")

# Lua: release the lock only if we still own it (token match) — never delete
# a lock another worker re-acquired after our TTL expired.
_RELEASE_LUA = """
if redis.call("get", KEYS[1]) == ARGV[1] then
    return redis.call("del", KEYS[1])
else
    return 0
end
"""

# Lua: extend the lock only if we still own it.
_EXTEND_LUA = """
if redis.call("get", KEYS[1]) == ARGV[1] then
    return redis.call("pexpire", KEYS[1], ARGV[2])
else
    return 0
end
"""

POSITIONS_INDEX = "open_positions:index"
GUARDS_INDEX = "stop_guards:index"
DAILY_TTL_SECONDS = 3 * 24 * 3600
BALANCE_SNAPSHOT_KEY = "balance:snapshot"
BALANCE_DELTA_KEY = "balance:delta"
# A tracked balance older than this is unusable — sizing must fail closed
# (or fall back to the broker's own funds check) instead of trusting it.
BALANCE_TTL_SECONDS = 15 * 60


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


def _today() -> str:
    return _utcnow().date().isoformat()


def _dumps(value: Any) -> str:
    return json.dumps(value, default=str)


class LockNotAcquired(Exception):
    """Raised when a blocking lock acquire times out."""


class DistributedLock:
    """SET key token NX PX lock with safe (token-checked) release.

    Usage:
        async with state.lock("order:AAPL", ttl_ms=30_000):
            ... critical section ...

    Non-blocking probe:
        lock = state.lock("reconcile", ttl_ms=60_000)
        if await lock.try_acquire():
            try: ...
            finally: await lock.release()
    """

    def __init__(self, store: "StateStore", name: str, ttl_ms: int = 30_000,
                 wait_timeout: float = 10.0, retry_delay: float = 0.1) -> None:
        self._store = store
        self.key = f"lock:{name}"
        self.ttl_ms = int(ttl_ms)
        self.wait_timeout = wait_timeout
        self.retry_delay = retry_delay
        self.token = uuid.uuid4().hex
        self.acquired = False

    async def try_acquire(self) -> bool:
        ok = await self._store._set_raw(self.key, self.token, px=self.ttl_ms, nx=True)
        self.acquired = bool(ok)
        return self.acquired

    async def acquire(self) -> None:
        deadline = time.monotonic() + self.wait_timeout
        while True:
            if await self.try_acquire():
                return
            if time.monotonic() >= deadline:
                raise LockNotAcquired(f"could not acquire {self.key} within {self.wait_timeout}s")
            await asyncio.sleep(self.retry_delay)

    async def extend(self, ttl_ms: Optional[int] = None) -> bool:
        if not self.acquired:
            return False
        return await self._store._extend_lock(self.key, self.token, ttl_ms or self.ttl_ms)

    async def release(self) -> None:
        if not self.acquired:
            return
        self.acquired = False
        await self._store._release_lock(self.key, self.token)

    async def __aenter__(self) -> "DistributedLock":
        await self.acquire()
        return self

    async def __aexit__(self, *_exc: Any) -> None:
        await self.release()


class _MemoryBackend:
    """Single-process fallback with the same semantics (TTLs, NX, sets).
    Only used when Redis is unavailable — logged loudly at startup."""

    def __init__(self) -> None:
        self._kv: Dict[str, Tuple[str, float]] = {}   # key -> (value, expiry_ts or 0)
        self._sets: Dict[str, set] = {}
        self._hashes: Dict[str, Tuple[Dict[str, str], float]] = {}
        self._lock = asyncio.Lock()

    def _purge(self) -> None:
        now = time.time()
        for k in [k for k, (_, exp) in self._kv.items() if exp and exp < now]:
            self._kv.pop(k, None)
        for k in [k for k, (_, exp) in self._hashes.items() if exp and exp < now]:
            self._hashes.pop(k, None)

    async def set(self, key: str, value: str, px: Optional[int] = None,
                  ex: Optional[int] = None, nx: bool = False) -> bool:
        async with self._lock:
            self._purge()
            if nx and key in self._kv:
                return False
            ttl = 0.0
            if px:
                ttl = time.time() + px / 1000.0
            elif ex:
                ttl = time.time() + ex
            self._kv[key] = (value, ttl)
            return True

    async def get(self, key: str) -> Optional[str]:
        async with self._lock:
            self._purge()
            item = self._kv.get(key)
            return item[0] if item else None

    async def delete(self, *keys: str) -> None:
        async with self._lock:
            for key in keys:
                self._kv.pop(key, None)
                self._sets.pop(key, None)
                self._hashes.pop(key, None)

    async def exists(self, key: str) -> bool:
        return (await self.get(key)) is not None

    async def eval_compare_del(self, key: str, token: str) -> bool:
        async with self._lock:
            item = self._kv.get(key)
            if item and item[0] == token:
                self._kv.pop(key, None)
                return True
            return False

    async def eval_compare_extend(self, key: str, token: str, px: int) -> bool:
        async with self._lock:
            item = self._kv.get(key)
            if item and item[0] == token:
                self._kv[key] = (item[0], time.time() + px / 1000.0)
                return True
            return False

    async def sadd(self, key: str, member: str) -> None:
        async with self._lock:
            self._sets.setdefault(key, set()).add(member)

    async def srem(self, key: str, member: str) -> None:
        async with self._lock:
            self._sets.get(key, set()).discard(member)

    async def smembers(self, key: str) -> List[str]:
        async with self._lock:
            return sorted(self._sets.get(key, set()))

    async def hincrbyfloat(self, key: str, field: str, amount: float, ex: int) -> float:
        async with self._lock:
            self._purge()
            fields, _ = self._hashes.get(key, ({}, 0.0))
            new_val = float(fields.get(field, "0") or 0) + amount
            fields[field] = repr(new_val)
            self._hashes[key] = (fields, time.time() + ex)
            return new_val

    async def hgetall(self, key: str) -> Dict[str, str]:
        async with self._lock:
            self._purge()
            fields, _ = self._hashes.get(key, ({}, 0.0))
            return dict(fields)

    async def incr(self, key: str, ex: Optional[int] = None) -> int:
        async with self._lock:
            self._purge()
            item = self._kv.get(key)
            try:
                val = int(float(item[0])) + 1 if item else 1
            except (TypeError, ValueError):
                val = 1
            ttl = time.time() + ex if ex else (item[1] if item else 0.0)
            self._kv[key] = (str(val), ttl)
            return val

    async def lpush_capped(self, key: str, value: str, max_len: int) -> None:
        async with self._lock:
            existing = self._kv.get(key)
            items: List[str] = json.loads(existing[0]) if existing else []
            items.insert(0, value)
            self._kv[key] = (json.dumps(items[:max_len]), 0.0)

    async def lrange_head(self, key: str, count: int) -> List[str]:
        async with self._lock:
            existing = self._kv.get(key)
            if not existing:
                return []
            try:
                items: List[str] = json.loads(existing[0])
            except json.JSONDecodeError:
                return []
            return items[:count]

    async def rpush(self, key: str, value: str) -> None:
        async with self._lock:
            existing = self._kv.get(key)
            queue: List[str] = json.loads(existing[0]) if existing else []
            queue.append(value)
            self._kv[key] = (json.dumps(queue), 0.0)

    async def lpop(self, key: str) -> Optional[str]:
        async with self._lock:
            existing = self._kv.get(key)
            if not existing:
                return None
            queue: List[str] = json.loads(existing[0])
            if not queue:
                return None
            head = queue.pop(0)
            self._kv[key] = (json.dumps(queue), 0.0)
            return head

    async def ping(self) -> bool:
        return True

    async def close(self) -> None:
        return None

    async def restore(self, kind: str, key: str, value: str) -> None:
        """Hydrate one persisted row back into the backend (boot only)."""
        async with self._lock:
            if kind == "set":
                try:
                    members = json.loads(value)
                except json.JSONDecodeError:
                    return
                self._sets[key] = set(str(m) for m in members)
            elif kind == "hash":
                try:
                    fields = json.loads(value)
                except json.JSONDecodeError:
                    return
                self._hashes[key] = ({str(k): str(v) for k, v in fields.items()}, 0.0)
            else:  # "kv" and "list" both live in _kv (lists are stored as JSON)
                self._kv[key] = (value, 0.0)


class StateStore:
    """Unified async state API over Redis (or the memory fallback)."""

    def __init__(self, redis_client: Any = None, persistence: Any = None) -> None:
        self.redis = redis_client            # redis.asyncio client or None
        self._memory = _MemoryBackend()
        # Durable write-through adapter — only consulted in memory mode.
        # Redis is already durable, so persistence is ignored when Redis is up.
        self._persistence = persistence if redis_client is None else None
        self._release_sha: Optional[str] = None
        self._extend_sha: Optional[str] = None

    @property
    def backend_name(self) -> str:
        if self.redis is not None:
            return "redis"
        return "memory+durable" if self._persistence is not None else "memory"

    @property
    def is_distributed(self) -> bool:
        return self.redis is not None

    @classmethod
    async def create(cls, redis_url: Optional[str], persistence: Any = None) -> "StateStore":
        """Connect to Redis when configured; otherwise return the memory
        fallback — durable when a persistence adapter is supplied, loud
        warning when not."""
        if redis_url:
            try:
                from redis.asyncio import from_url as redis_from_url
                client = redis_from_url(
                    redis_url,
                    decode_responses=True,
                    socket_connect_timeout=5,
                    socket_timeout=10,
                    health_check_interval=30,
                )
                await client.ping()
                logger.info("✅ StateStore: Redis connected — distributed state + locks active")
                return cls(client)
            except Exception as e:
                logger.error(
                    f"⛔ StateStore: Redis unreachable ({e}) — falling back to "
                    f"{'DURABLE memory (persistence adapter)' if persistence is not None else 'in-memory state — NOT safe for multi-worker deployments'}."
                )
        store = cls(None, persistence=persistence)
        if store._persistence is not None:
            await store.hydrate()
            logger.info(
                "✅ StateStore: durable memory mode — positions/guards/daily P&L/kill "
                "switch persist to the database across restarts (single worker)."
            )
        else:
            logger.warning(
                "⚠️ StateStore: no REDIS_URL and no persistence — using in-memory state. "
                "A restart LOSES positions, trails, daily P&L and the kill switch."
            )
        return store

    # ---------------- durable write-through ----------------
    # Ephemeral prefixes whose TTL/locality IS their semantics — never persisted.
    _EPHEMERAL_PREFIXES = ("lock:", "sig:", "cooldown:", "queue:", "balance:")

    def _durable_kv(self, key: str, px: Optional[int], ex: Optional[int]) -> bool:
        """A KV write is durable when it carries no TTL and is not ephemeral by
        prefix. TTL'd values (idempotency keys, cooldowns, balance snapshots,
        breaker counters) MUST die on schedule — resurrecting them stale after
        a restart would be worse than losing them."""
        if self._persistence is None or px or ex:
            return False
        return not any(key.startswith(p) for p in self._EPHEMERAL_PREFIXES)

    async def _persist(self, key: str, kind: str, value: str) -> None:
        if self._persistence is None:
            return
        try:
            await self._persistence.save(key, kind, value)
        except Exception as e:
            logger.warning(f"state persistence save failed for {key} (non-fatal): {e}")

    async def _persist_delete(self, key: str) -> None:
        if self._persistence is None:
            return
        try:
            await self._persistence.delete(key)
        except Exception as e:
            logger.warning(f"state persistence delete failed for {key} (non-fatal): {e}")

    async def _persist_set_members(self, key: str) -> None:
        members = await self._memory.smembers(key)
        await self._persist(key, "set", json.dumps(members))

    async def _persist_hash(self, key: str) -> None:
        fields = await self._memory.hgetall(key)
        await self._persist(key, "hash", json.dumps(fields))

    async def hydrate(self) -> int:
        """Load every persisted row back into the memory backend (boot only).
        Returns the number of rows restored."""
        if self._persistence is None:
            return 0
        try:
            rows = await self._persistence.load_all()
        except Exception as e:
            logger.error(f"state hydration failed — starting empty: {e}")
            return 0
        count = 0
        for key, kind, value in rows:
            await self._memory.restore(str(kind), str(key), str(value))
            count += 1
        if count:
            logger.info(f"✅ StateStore: hydrated {count} durable row(s) from the database")
        return count

    # ---------------- raw primitives ----------------
    async def _set_raw(self, key: str, value: str, px: Optional[int] = None,
                       ex: Optional[int] = None, nx: bool = False) -> bool:
        if self.redis is not None:
            ok = await self.redis.set(key, value, px=px, ex=ex, nx=nx if nx else None)
            return bool(ok)
        return await self._memory.set(key, value, px=px, ex=ex, nx=nx)

    async def _release_lock(self, key: str, token: str) -> bool:
        if self.redis is not None:
            try:
                res = await self.redis.eval(_RELEASE_LUA, 1, key, token)
                return bool(res)
            except Exception as e:
                logger.warning(f"lock release failed for {key}: {e}")
                return False
        return await self._memory.eval_compare_del(key, token)

    async def _extend_lock(self, key: str, token: str, px: int) -> bool:
        if self.redis is not None:
            try:
                res = await self.redis.eval(_EXTEND_LUA, 1, key, token, px)
                return bool(res)
            except Exception as e:
                logger.warning(f"lock extend failed for {key}: {e}")
                return False
        return await self._memory.eval_compare_extend(key, token, px)

    # ---------------- generic KV (idempotency, cooldowns) ----------------
    async def set(self, key: str, value: str, ex: Optional[int] = None, nx: bool = False) -> bool:
        ok = await self._set_raw(key, value, ex=ex, nx=nx)
        if ok and self.redis is None and self._durable_kv(key, None, ex):
            await self._persist(key, "kv", value)
        return ok

    async def get(self, key: str) -> Optional[str]:
        if self.redis is not None:
            return await self.redis.get(key)
        return await self._memory.get(key)

    async def exists(self, key: str) -> bool:
        if self.redis is not None:
            return bool(await self.redis.exists(key))
        return await self._memory.exists(key)

    async def delete(self, *keys: str) -> None:
        if not keys:
            return
        if self.redis is not None:
            await self.redis.delete(*keys)
            return
        await self._memory.delete(*keys)
        for key in keys:
            if self._durable_kv(key, None, None):
                await self._persist_delete(key)

    # ---------------- counters (circuit breaker) ----------------
    async def incr(self, key: str, ex: Optional[int] = None) -> int:
        """Atomic increment (used by the distributed circuit breaker's
        consecutive-failure counter). `ex` refreshes the TTL on every hit so
        the failure window is rolling."""
        if self.redis is not None:
            val = await self.redis.incr(key)
            if ex:
                await self.redis.expire(key, ex)
            return int(val)
        return await self._memory.incr(key, ex)

    # ---------------- capped lists (recent alerts) ----------------
    async def list_push_capped(self, key: str, value: str, max_len: int = 200) -> None:
        """LPUSH + LTRIM: newest first, bounded memory."""
        if self.redis is not None:
            await self.redis.lpush(key, value)
            await self.redis.ltrim(key, 0, max_len - 1)
            return
        await self._memory.lpush_capped(key, value, max_len)
        if self._durable_kv(key, None, None):
            items = await self._memory.lrange_head(key, max_len)
            await self._persist(key, "list", json.dumps(items))

    async def list_range(self, key: str, count: int = 50) -> List[str]:
        if self.redis is not None:
            return await self.redis.lrange(key, 0, count - 1)
        return await self._memory.lrange_head(key, count)

    # ---------------- queue (placement worker) ----------------
    async def queue_push(self, key: str, value: str) -> None:
        if self.redis is not None:
            await self.redis.rpush(key, value)
            return
        await self._memory.rpush(key, value)

    async def queue_pop(self, key: str) -> Optional[str]:
        if self.redis is not None:
            return await self.redis.lpop(key)
        return await self._memory.lpop(key)

    # ---------------- positions ----------------
    @staticmethod
    def _pos_key(ticker: str) -> str:
        return f"open_positions:{ticker.upper()}"

    async def get_position(self, ticker: str) -> Optional[dict]:
        raw = await self.get(self._pos_key(ticker))
        if not raw:
            return None
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return None

    async def _sadd_index(self, index_key: str, ticker: str) -> None:
        if self.redis is not None:
            await self.redis.sadd(index_key, ticker)
            return
        await self._memory.sadd(index_key, ticker)
        if self._persistence is not None:
            await self._persist_set_members(index_key)

    async def _srem_index(self, index_key: str, ticker: str) -> None:
        if self.redis is not None:
            await self.redis.srem(index_key, ticker)
            return
        await self._memory.srem(index_key, ticker)
        if self._persistence is not None:
            await self._persist_set_members(index_key)

    async def set_position(self, ticker: str, position: dict) -> None:
        ticker = ticker.upper()
        payload = _dumps(position)
        await self._set_raw(self._pos_key(ticker), payload)
        if self.redis is None and self._durable_kv(self._pos_key(ticker), None, None):
            await self._persist(self._pos_key(ticker), "kv", payload)
        await self._sadd_index(POSITIONS_INDEX, ticker)

    async def delete_position(self, ticker: str) -> Optional[dict]:
        ticker = ticker.upper()
        existing = await self.get_position(ticker)
        await self.delete(self._pos_key(ticker))
        await self._srem_index(POSITIONS_INDEX, ticker)
        return existing

    async def position_tickers(self) -> List[str]:
        if self.redis is not None:
            members = await self.redis.smembers(POSITIONS_INDEX)
            return sorted(members)
        return await self._memory.smembers(POSITIONS_INDEX)

    async def all_positions(self) -> Dict[str, dict]:
        out: Dict[str, dict] = {}
        stale: List[str] = []
        for ticker in await self.position_tickers():
            pos = await self.get_position(ticker)
            if pos is not None:
                out[ticker] = pos
            else:
                stale.append(ticker)
        # Self-heal index entries whose value key vanished.
        for ticker in stale:
            await self._srem_index(POSITIONS_INDEX, ticker)
        return out

    async def position_count(self) -> int:
        return len(await self.all_positions())

    # ---------------- stop guards ----------------
    @staticmethod
    def _guard_key(ticker: str) -> str:
        return f"stop_guard:{ticker.upper()}"

    async def get_guard(self, ticker: str) -> Optional[dict]:
        raw = await self.get(self._guard_key(ticker))
        if not raw:
            return None
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return None

    async def set_guard(self, ticker: str, guard: dict) -> None:
        ticker = ticker.upper()
        payload = _dumps(guard)
        await self._set_raw(self._guard_key(ticker), payload)
        if self.redis is None and self._durable_kv(self._guard_key(ticker), None, None):
            await self._persist(self._guard_key(ticker), "kv", payload)
        await self._sadd_index(GUARDS_INDEX, ticker)

    async def update_guard(self, ticker: str, **fields: Any) -> Optional[dict]:
        """Read-modify-write of guard fields. Callers mutating from concurrent
        workers must hold the guard's distributed lock."""
        guard = await self.get_guard(ticker)
        if guard is None:
            return None
        guard.update(fields)
        await self.set_guard(ticker, guard)
        return guard

    async def delete_guard(self, ticker: str) -> None:
        ticker = ticker.upper()
        await self.delete(self._guard_key(ticker))
        await self._srem_index(GUARDS_INDEX, ticker)

    async def all_guards(self) -> Dict[str, dict]:
        """Every live guard record, self-healing the index as it goes.

        `all_positions` already drops index entries whose value key vanished;
        guards did not, so an evicted or manually-deleted `stop_guard:{T}` left
        its ticker in `stop_guards:index` permanently. The set then grew without
        bound and every caller paid an extra round-trip per dead entry on every
        reconcile, trail and flatten pass.
        """
        out: Dict[str, dict] = {}
        stale: List[str] = []
        tickers = (await self.redis.smembers(GUARDS_INDEX)) if self.redis is not None \
            else await self._memory.smembers(GUARDS_INDEX)
        for ticker in sorted(tickers):
            guard = await self.get_guard(ticker)
            if guard is not None:
                out[ticker] = guard
            else:
                stale.append(ticker)
        for ticker in stale:
            await self._srem_index(GUARDS_INDEX, ticker)
        return out

    async def pending_guards(self) -> Dict[str, dict]:
        return {t: g for t, g in (await self.all_guards()).items() if not g.get("done")}

    # ---------------- daily counters ----------------
    @staticmethod
    def _daily_key() -> str:
        return f"daily:{_today()}"

    async def get_daily(self) -> Dict[str, float]:
        key = self._daily_key()
        fields = (await self.redis.hgetall(key)) if self.redis is not None \
            else await self._memory.hgetall(key)
        return {
            "trades_today": int(float(fields.get("trades_today", "0") or 0)),
            "realized_pnl_today_pct": float(fields.get("realized_pnl_today_pct", "0") or 0),
            "realized_pnl_today_usd": float(fields.get("realized_pnl_today_usd", "0") or 0),
        }

    async def incr_trades_today(self) -> int:
        key = self._daily_key()
        if self.redis is not None:
            val = await self.redis.hincrby(key, "trades_today", 1)
            await self.redis.expire(key, DAILY_TTL_SECONDS)
            return int(val)
        result = int(await self._memory.hincrbyfloat(key, "trades_today", 1, DAILY_TTL_SECONDS))
        # The daily counters are the loss limit's memory — a restart must not
        # hand the bot a fresh risk budget. The key is date-scoped, so a stale
        # hydrated day simply never gets read.
        if self._persistence is not None:
            await self._persist_hash(key)
        return result

    async def add_realized_pnl(self, pct: float) -> float:
        key = self._daily_key()
        if self.redis is not None:
            val = await self.redis.hincrbyfloat(key, "realized_pnl_today_pct", pct)
            await self.redis.expire(key, DAILY_TTL_SECONDS)
            return float(val)
        result = await self._memory.hincrbyfloat(key, "realized_pnl_today_pct", pct, DAILY_TTL_SECONDS)
        if self._persistence is not None:
            await self._persist_hash(key)
        return result

    async def add_realized_usd(self, usd: float) -> float:
        """Accumulate today's realized P&L in REAL DOLLARS.

        The percent counter answers "how much of the account did today move?".
        The daily profit objective is denominated in DOLLARS, and a percent of a
        moving balance cannot answer it. Only closes carrying a broker-verified
        fill contribute here, so this is settled money — never a mark-to-market
        estimate, and never an app-side guess.
        """
        key = self._daily_key()
        if self.redis is not None:
            val = await self.redis.hincrbyfloat(key, "realized_pnl_today_usd", usd)
            await self.redis.expire(key, DAILY_TTL_SECONDS)
            return float(val)
        result = await self._memory.hincrbyfloat(key, "realized_pnl_today_usd", usd, DAILY_TTL_SECONDS)
        if self._persistence is not None:
            await self._persist_hash(key)
        return result

    # ---------------- balance tracker ----------------
    # Tracks available funds between broker refreshes so consecutive entries
    # (and wins/losses) can never over-spend during a balance-fetch outage.
    # A fresh broker fetch is ALWAYS preferred; the delta only bridges gaps.
    async def set_balance_snapshot(self, value: float) -> None:
        """Store a fresh broker buying-power snapshot and clear the running
        win/loss delta (the snapshot already reflects settled reality)."""
        payload = _dumps({"value": float(value), "ts": _utcnow().timestamp()})
        await self.set(BALANCE_SNAPSHOT_KEY, payload, ex=BALANCE_TTL_SECONDS)
        await self.delete(BALANCE_DELTA_KEY)

    async def adjust_balance(self, amount: float) -> float:
        """Adjust tracked funds between broker refreshes: order costs subtract,
        closed-position proceeds add back. Returns the accumulated delta."""
        if self.redis is not None:
            val = await self.redis.hincrbyfloat(BALANCE_DELTA_KEY, "delta", amount)
            await self.redis.expire(BALANCE_DELTA_KEY, BALANCE_TTL_SECONDS)
            return float(val)
        return await self._memory.hincrbyfloat(BALANCE_DELTA_KEY, "delta", amount, BALANCE_TTL_SECONDS)

    async def tracked_balance(self) -> Optional[float]:
        """Snapshot ± win/loss delta, or None when no fresh snapshot exists
        (the key TTL enforces staleness — expired snapshots simply vanish)."""
        raw = await self.get(BALANCE_SNAPSHOT_KEY)
        if not raw:
            return None
        try:
            snap = json.loads(raw)
            value = float(snap.get("value") or 0)
        except (json.JSONDecodeError, TypeError, ValueError):
            return None
        fields = (await self.redis.hgetall(BALANCE_DELTA_KEY)) if self.redis is not None \
            else await self._memory.hgetall(BALANCE_DELTA_KEY)
        try:
            delta = float(fields.get("delta", "0") or 0)
        except (TypeError, ValueError):
            delta = 0.0
        return value + delta

    # ---------------- kill switch ----------------
    async def is_killed(self) -> bool:
        return (await self.get("killed")) == "1"

    async def set_killed(self, killed: bool) -> None:
        if killed:
            await self.set("killed", "1")
        else:
            await self.delete("killed")

    # ---------------- locks ----------------
    def lock(self, name: str, ttl_ms: int = 30_000, wait_timeout: float = 10.0) -> DistributedLock:
        return DistributedLock(self, name, ttl_ms=ttl_ms, wait_timeout=wait_timeout)

    # ---------------- legacy STATE_FILE migration ----------------
    async def migrate_from_file(self, path: Path) -> bool:
        """One-time migration of the old JSON STATE_FILE into Redis. Only runs
        when the store has no positions AND no guards yet (never clobbers live
        Redis state), then renames the file so it never re-imports."""
        if not path.exists():
            return False
        if await self.position_tickers() or await self.all_guards():
            logger.info("StateStore: Redis already has state — skipping STATE_FILE migration")
            return False
        try:
            data = json.loads(path.read_text())
        except (OSError, json.JSONDecodeError) as e:
            logger.error(f"StateStore: legacy state file unreadable ({e}) — skipping migration")
            return False
        positions = dict(data.get("open_positions") or {})
        guards = dict(data.get("stop_guards") or {})
        for ticker, pos in positions.items():
            await self.set_position(str(ticker), dict(pos))
        for ticker, guard in guards.items():
            await self.set_guard(str(ticker), dict(guard))
        if bool(data.get("killed", False)):
            await self.set_killed(True)
        if str(data.get("date") or "") == _today():
            trades = int(data.get("trades_today") or 0)
            for _ in range(trades):
                await self.incr_trades_today()
            pnl = float(data.get("realized_pnl_today_pct") or 0.0)
            if pnl:
                await self.add_realized_pnl(pnl)
        try:
            path.rename(path.with_suffix(path.suffix + ".migrated"))
        except OSError as e:
            logger.warning(f"StateStore: could not rename migrated state file: {e}")
        logger.info(
            f"✅ StateStore: migrated legacy state file → {len(positions)} positions, "
            f"{len(guards)} guards, killed={bool(data.get('killed', False))}"
        )
        return True

    async def close(self) -> None:
        if self.redis is not None:
            try:
                await self.redis.close()
            except Exception:
                pass

''')

_bundle_load('etrade_async', r'''
"""
Async E*TRADE client — httpx + OAuth1 + raw Order API payloads.
===============================================================

Replaces synchronous pyetrade for ORDER PLACEMENT with direct, fully-controlled
JSON payloads against E*TRADE's Order API:

  POST /v1/accounts/{accountIdKey}/orders/preview.json
  POST /v1/accounts/{accountIdKey}/orders/place.json
  PUT  /v1/accounts/{accountIdKey}/orders/cancel.json
  GET  /v1/accounts/{accountIdKey}/orders.json
  GET  /v1/accounts/{accountIdKey}/portfolio.json

Why raw payloads:
  • pyetrade rebuilds Order/Instrument/Product from flat kwargs and cannot
    express multi-detail structures at all.
  • Raw JSON gives a realistic path to linked Entry+Stop+Target (OTOCO-style)
    submissions where E*TRADE accepts them, with clean fallback where not.

E*TRADE REALITY (important): the public Order API documents single-Order
requests (orderType EQ / OPTN / SPREADS ...). True OCO/OTOCO is NOT officially
supported. `place_otoco_best_effort` therefore ATTEMPTS an atomic multi-detail
submission once, and raises `OTOCOUnsupported` on rejection so the caller can
fall back to entry + stop-guard (the proven hybrid). The result is maximum
control with zero regression risk.

OAuth1 signing is done with oauthlib directly (HMAC-SHA1, header auth) — the
same scheme pyetrade uses via requests_oauthlib, but async-safe over httpx.
pyetrade remains in use for simpler read paths elsewhere (quotes, auth/renew).
"""
from __future__ import annotations

import asyncio
import json
import logging
import os
import random
from typing import Any, Dict, List, Optional

import httpx
from oauthlib.oauth1 import Client as OAuth1Client

logger = logging.getLogger("etrade-bot.async-client")

PROD_BASE = "https://api.etrade.com"
SANDBOX_BASE = "https://apisb.etrade.com"

# ---- Exponential backoff (shared env config with main_bot.py) ----
RETRY_MAX_ATTEMPTS = max(1, int(os.getenv("ETRADE_RETRY_ATTEMPTS", "4")))
RETRY_BASE_SECONDS = float(os.getenv("ETRADE_RETRY_BASE_SECONDS", "2"))
RETRY_MAX_SECONDS = float(os.getenv("ETRADE_RETRY_MAX_SECONDS", "8"))
# Statuses worth retrying: throttle, timeout, and server-side failures.
RETRYABLE_STATUSES = {408, 429, 500, 502, 503, 504}


def backoff_delay(attempt: int, exact: bool = False) -> float:
    """Exponential backoff: base * 2^attempt capped at the max.
    exact=True (429 throttle) honours the full schedule — 2s, 4s, 8s with the
    defaults — because a throttle wait must never be shortened. Other errors
    apply a [0.5, 1.0] jitter factor to de-synchronize workers."""
    delay = min(RETRY_MAX_SECONDS, RETRY_BASE_SECONDS * (2 ** attempt))
    if exact:
        return delay
    return delay * (0.5 + random.random() * 0.5)


class ETradeAPIError(Exception):
    """Non-2xx response from E*TRADE. Carries status + parsed error message."""

    def __init__(self, status_code: int, message: str, body: str = "") -> None:
        super().__init__(f"E*TRADE {status_code}: {message}")
        self.status_code = status_code
        self.message = message
        self.body = body


class OTOCOUnsupported(ETradeAPIError):
    """The atomic multi-leg submission was rejected — fall back to sequential
    placement + stop guard."""


# 4xx statuses that say nothing about whether the broker accepts multi-leg
# orders: the session, the permissions, or the rate budget failed instead.
_NOT_AN_OTOCO_VERDICT = {401, 403, 429}


def _extract_error_message(body: str) -> str:
    try:
        data = json.loads(body)
        err = (data.get("Error") or {}) if isinstance(data, dict) else {}
        msg = err.get("message") or err.get("Message")
        if msg:
            code = err.get("code") or err.get("Code")
            return f"[{code}] {msg}" if code else str(msg)
    except (json.JSONDecodeError, AttributeError):
        pass
    return body[:300] if body else "no error body"


class ETradeAsyncClient:
    """OAuth1-signed async client. One instance per (token, secret) session —
    cheap to build per request batch; the underlying httpx client pools."""

    def __init__(self, consumer_key: str, consumer_secret: str,
                 oauth_token: str, oauth_token_secret: str,
                 sandbox: bool = False, timeout: float = 20.0) -> None:
        self._signer = OAuth1Client(
            client_key=consumer_key,
            client_secret=consumer_secret,
            resource_owner_key=oauth_token,
            resource_owner_secret=oauth_token_secret,
            signature_type="AUTH_HEADER",
        )
        self.base = SANDBOX_BASE if sandbox else PROD_BASE
        self._timeout = timeout

    async def _request(self, method: str, path: str,
                       params: Optional[Dict[str, Any]] = None,
                       json_body: Optional[Dict[str, Any]] = None,
                       idempotent: bool = True) -> Dict[str, Any]:
        """Signed request with EXPONENTIAL BACKOFF. `idempotent=False` (order
        place) is retried ONLY when the request provably never reached the
        broker (connect failure) or was throttled before processing (429) —
        a blind retry of a placed order risks a double fill."""
        url = f"{self.base}{path}"
        if params:
            url = f"{url}?{httpx.QueryParams(params)}"
        body_bytes: Optional[bytes] = None
        if json_body is not None:
            body_bytes = json.dumps(json_body).encode()

        last_exc: Optional[Exception] = None
        for attempt in range(RETRY_MAX_ATTEMPTS):
            headers: Dict[str, str] = {"Accept": "application/json"}
            if body_bytes is not None:
                headers["Content-Type"] = "application/json"
            # Re-sign EVERY attempt — OAuth1 nonces/timestamps are single-use,
            # so a retried request must carry a fresh Authorization header.
            # (For non-form bodies OAuth1 signs only the URL + oauth params —
            # the JSON body is intentionally NOT part of the signature base,
            # matching how requests_oauthlib/pyetrade sign JSON requests.)
            signed_url, signed_headers, _ = self._signer.sign(url, http_method=method.upper())
            headers["Authorization"] = signed_headers["Authorization"]
            try:
                async with httpx.AsyncClient(timeout=self._timeout) as client:
                    resp = await client.request(method.upper(), signed_url, content=body_bytes, headers=headers)
            except (httpx.TimeoutException, httpx.TransportError) as e:
                # Network-level failure. Non-idempotent requests retry only on
                # connect errors — a timeout AFTER sending may have landed.
                last_exc = e
                can_retry = idempotent or isinstance(e, httpx.ConnectError)
                if can_retry and attempt < RETRY_MAX_ATTEMPTS - 1:
                    delay = backoff_delay(attempt)
                    logger.warning(
                        f"E*TRADE network error on {method} {path} "
                        f"(attempt {attempt + 1}/{RETRY_MAX_ATTEMPTS}): {e} — retrying in {delay:.1f}s"
                    )
                    await asyncio.sleep(delay)
                    continue
                raise
            if resp.status_code >= 400:
                # 429 never processed the request — always safe to retry.
                # Other retryable statuses (408/5xx) retry only when the call
                # is idempotent (a 5xx on place.json may follow acceptance).
                retryable_status = resp.status_code in RETRYABLE_STATUSES and (
                    idempotent or resp.status_code == 429
                )
                if retryable_status and attempt < RETRY_MAX_ATTEMPTS - 1:
                    # 429 uses the exact schedule (2s → 4s → 8s by default);
                    # other statuses keep jitter to spread retries.
                    delay = backoff_delay(attempt, exact=(resp.status_code == 429))
                    logger.warning(
                        f"E*TRADE {resp.status_code} on {method} {path} "
                        f"(attempt {attempt + 1}/{RETRY_MAX_ATTEMPTS}) — retrying in {delay:.1f}s"
                    )
                    await asyncio.sleep(delay)
                    continue
                raise ETradeAPIError(resp.status_code, _extract_error_message(resp.text), resp.text)
            if not resp.text.strip():
                return {}
            try:
                return resp.json()
            except json.JSONDecodeError:
                raise ETradeAPIError(resp.status_code, f"non-JSON response: {resp.text[:200]}")
        raise last_exc if last_exc else ETradeAPIError(0, "E*TRADE request retries exhausted")

    # ------------------------------------------------------------------
    # Read endpoints
    # ------------------------------------------------------------------
    async def list_accounts(self) -> Dict[str, Any]:
        return await self._request("GET", "/v1/accounts/list.json")

    async def list_orders(self, account_id_key: str,
                          status: Optional[str] = None, count: int = 50) -> Dict[str, Any]:
        params: Dict[str, Any] = {"count": count}
        if status:
            params["status"] = status
        return await self._request("GET", f"/v1/accounts/{account_id_key}/orders.json", params=params)

    async def get_portfolio(self, account_id_key: str) -> Dict[str, Any]:
        return await self._request("GET", f"/v1/accounts/{account_id_key}/portfolio.json")

    async def get_balance(self, account_id_key: str, institution_type: str = "BROKERAGE") -> Dict[str, Any]:
        return await self._request(
            "GET", f"/v1/accounts/{account_id_key}/balance.json",
            params={"instType": institution_type, "realTimeNAV": "true"},
        )

    # ------------------------------------------------------------------
    # Payload builders (pure functions — unit-testable)
    # ------------------------------------------------------------------
    @staticmethod
    def equity_instrument(symbol: str, order_action: str, quantity: int) -> Dict[str, Any]:
        return {
            "Product": {"securityType": "EQ", "symbol": symbol.upper()},
            "orderAction": order_action,
            "quantityType": "QUANTITY",
            "quantity": int(quantity),
        }

    @staticmethod
    def option_instrument(symbol: str, call_put: str, strike: float,
                          expiry_iso: str, order_action: str, quantity: int) -> Dict[str, Any]:
        y, m, d = str(expiry_iso)[:10].split("-")
        return {
            "Product": {
                "securityType": "OPTN",
                "symbol": symbol.upper(),
                "callPut": "CALL" if str(call_put).upper().startswith("C") else "PUT",
                "strikePrice": float(strike),
                "expiryYear": int(y),
                "expiryMonth": int(m),
                "expiryDay": int(d),
            },
            "orderAction": order_action,
            "orderedQuantity": int(quantity),
            "quantity": int(quantity),
        }

    @staticmethod
    def order_detail(instruments: List[Dict[str, Any]], price_type: str,
                     limit_price: Optional[float] = None, stop_price: Optional[float] = None,
                     order_term: str = "GOOD_FOR_DAY", market_session: str = "REGULAR",
                     all_or_none: bool = False) -> Dict[str, Any]:
        detail: Dict[str, Any] = {
            "allOrNone": bool(all_or_none),
            "priceType": price_type,
            "orderTerm": order_term,
            "marketSession": market_session,
            "Instrument": instruments,
        }
        if limit_price is not None:
            detail["limitPrice"] = round(float(limit_price), 2)
        if stop_price is not None:
            detail["stopPrice"] = round(float(stop_price), 2)
        return detail

    # ------------------------------------------------------------------
    # Preview → place flow
    # ------------------------------------------------------------------
    @staticmethod
    def _preview_ids(preview_resp: Dict[str, Any]) -> List[Dict[str, Any]]:
        body = preview_resp.get("PreviewOrderResponse", preview_resp) or {}
        ids = body.get("PreviewIds") or []
        if isinstance(ids, dict):
            ids = [ids]
        out = []
        for entry in ids:
            pid = entry.get("previewId") if isinstance(entry, dict) else entry
            if pid is not None:
                out.append({"previewId": pid})
        return out

    @staticmethod
    def order_id_from_place(place_resp: Dict[str, Any]) -> Optional[str]:
        body = place_resp.get("PlaceOrderResponse", place_resp) if isinstance(place_resp, dict) else {}
        ids = body.get("OrderIds") or body.get("orderIds") or []
        if isinstance(ids, dict):
            ids = [ids]
        for entry in ids:
            oid = entry.get("orderId") if isinstance(entry, dict) else entry
            if oid:
                return str(oid)
        oid = body.get("orderId") or body.get("OrderId")
        return str(oid) if oid else None

    async def preview_and_place(self, account_id_key: str, order_type: str,
                                client_order_id: str, details: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Atomic preview → place of a raw order request. `details` is the
        Order array — one detail for standard orders, multiple for the OTOCO
        best-effort path."""
        preview_req = {
            "PreviewOrderRequest": {
                "orderType": order_type,
                "clientOrderId": client_order_id,
                "Order": details,
            }
        }
        logger.info(f"📤 RAW preview {order_type}: {json.dumps(preview_req)[:600]}")
        preview = await self._request(
            "POST", f"/v1/accounts/{account_id_key}/orders/preview.json", json_body=preview_req,
        )
        preview_ids = self._preview_ids(preview)
        if not preview_ids:
            raise ETradeAPIError(422, "preview returned no previewId", json.dumps(preview)[:300])
        place_req = {
            "PlaceOrderRequest": {
                "orderType": order_type,
                "clientOrderId": client_order_id,
                "PreviewIds": preview_ids,
                "Order": details,
            }
        }
        # NON-IDEMPOTENT: place.json is retried only on connect errors / 429
        # (see _request) — never after the order may have reached the broker.
        placed = await self._request(
            "POST", f"/v1/accounts/{account_id_key}/orders/place.json", json_body=place_req,
            idempotent=False,
        )
        logger.info(f"✅ RAW placed {order_type} clientOrderId={client_order_id} orderId={self.order_id_from_place(placed)}")
        return placed

    async def cancel_order(self, account_id_key: str, order_id: int) -> Dict[str, Any]:
        return await self._request(
            "PUT", f"/v1/accounts/{account_id_key}/orders/cancel.json",
            json_body={"CancelOrderRequest": {"orderId": int(order_id)}},
        )

    # ------------------------------------------------------------------
    # High-level order helpers
    # ------------------------------------------------------------------
    async def place_equity(self, account_id_key: str, client_order_id: str, symbol: str,
                           order_action: str, quantity: int, price_type: str,
                           limit_price: Optional[float] = None,
                           stop_price: Optional[float] = None) -> Dict[str, Any]:
        detail = self.order_detail(
            [self.equity_instrument(symbol, order_action, quantity)],
            price_type, limit_price=limit_price, stop_price=stop_price,
        )
        return await self.preview_and_place(account_id_key, "EQ", client_order_id, [detail])

    async def place_option(self, account_id_key: str, client_order_id: str, symbol: str,
                           call_put: str, strike: float, expiry_iso: str,
                           order_action: str, quantity: int, price_type: str,
                           limit_price: Optional[float] = None,
                           stop_price: Optional[float] = None) -> Dict[str, Any]:
        detail = self.order_detail(
            [self.option_instrument(symbol, call_put, strike, expiry_iso, order_action, quantity)],
            price_type, limit_price=limit_price, stop_price=stop_price,
        )
        return await self.preview_and_place(account_id_key, "OPTN", client_order_id, [detail])

    async def place_otoco_best_effort(self, account_id_key: str, client_order_id: str,
                                      order_type: str, entry_detail: Dict[str, Any],
                                      stop_detail: Dict[str, Any],
                                      target_detail: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """ATTEMPT a linked Entry + Protective Stop (+ Take-Profit) in one
        atomic request. E*TRADE's public API does not officially support OCO/
        OTOCO, so a 4xx here raises OTOCOUnsupported — callers MUST catch it
        and fall back to sequential entry + stop-guard."""
        details = [entry_detail, stop_detail] + ([target_detail] if target_detail else [])
        try:
            return await self.preview_and_place(account_id_key, order_type, client_order_id, details)
        except ETradeAPIError as e:
            # Only a genuine REJECTION of the multi-leg shape means "OTOCO is not
            # supported here". An expired session (401), a permissions problem
            # (403) or an exhausted throttle budget (429) are 4xx too, and
            # relabelling them as OTOCOUnsupported sent the caller down the
            # sequential fallback path where the identical failure was guaranteed
            # to repeat — burning a second round-trip and writing a log line that
            # blamed the order shape for an auth or rate-limit problem.
            if e.status_code in _NOT_AN_OTOCO_VERDICT:
                raise
            if 400 <= e.status_code < 500:
                raise OTOCOUnsupported(e.status_code, e.message, e.body) from e
            raise

''')

_bundle_load('alerts', r'''
"""
Real-time alerting — kill switch, failed guards, API problems.
==============================================================

Severity levels: info | warning | error | critical.

Delivery (every alert, in order):
  • ALWAYS logged, greppable:  [ALERT][SEVERITY] event — message
  • Stored in the Redis capped list `alerts:recent` (newest first, last 200)
    so the app can poll GET /alerts
  • Pushed to ALERT_WEBHOOK_URL when configured. The payload carries `text`
    (Slack-compatible), `content` (Discord-compatible) AND the full structured
    record, so a single URL works for Slack, Discord, ntfy, or any generic
    JSON receiver.

Duplicate storms are suppressed: the same `dedupe_key` reaches the webhook at
most once per `dedupe_seconds` (Redis SET NX + TTL — multi-worker safe).
Deduped alerts still land in the log and the recent list.

TRADE FILLS BYPASS THE SEVERITY FLOOR (`force_deliver=True`). A real-money buy
or sell is not a warning to be filtered — it is the event the operator most
needs to see, and it is factually `info` severity. With the default floor at
`warning`, an honestly-labelled fill notice would be logged and then silently
dropped before the webhook. `force_deliver` is delivery-path only: it skips the
floor, NOT the dedupe key, so a re-poll of the same fill cannot double-post.

Fire-and-forget by design: an alerting failure must NEVER break trading, so
every path here swallows and logs its own errors.
"""
from __future__ import annotations

import json
import logging
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

logger = logging.getLogger("etrade-bot.alerts")

ALERTS_RECENT_KEY = "alerts:recent"
ALERTS_CONFIG_KEY = "alerts:config"
ALERTS_LAST_DELIVERY_KEY = "alerts:last_delivery"
ALERTS_RECENT_MAX = 200
_VALID_SEVERITIES = {"info", "warning", "error", "critical"}
_SEVERITY_RANK = {"info": 0, "warning": 1, "error": 2, "critical": 3}
DEFAULT_MIN_SEVERITY = "warning"


def _utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def mask_webhook_url(url: Optional[str]) -> Optional[str]:
    """Keep scheme + host + first path segment; hide the secret tail.
    e.g. https://discord.com/api/webhooks/123…/abc… → https://discord.com/api/…9xYz
    """
    if not url:
        return None
    try:
        from urllib.parse import urlparse
        p = urlparse(url)
        tail = url[-4:] if len(url) > 24 else ""
        return f"{p.scheme}://{p.netloc}/…{tail}"
    except Exception:
        return "…" + url[-4:]


class AlertManager:
    def __init__(self, state: Any, webhook_url: Optional[str] = None,
                 dedupe_seconds: int = 300) -> None:
        self._state = state
        self._webhook_url = (webhook_url or "").strip() or None
        self._min_severity = DEFAULT_MIN_SEVERITY
        self._dedupe_seconds = max(10, int(dedupe_seconds))

    @property
    def webhook_configured(self) -> bool:
        return self._webhook_url is not None

    async def load_persisted(self) -> None:
        """Apply a webhook config saved via POST /alerts/config (survives
        restarts; overrides the env default when present)."""
        try:
            raw = await self._state.get(ALERTS_CONFIG_KEY)
            if not raw:
                return
            cfg = json.loads(raw)
            url = (cfg.get("webhook_url") or "").strip()
            self._webhook_url = url or None
            sev = str(cfg.get("min_severity", "")).lower()
            if sev in _VALID_SEVERITIES:
                self._min_severity = sev
            logger.info(
                f"alerting: loaded persisted config — webhook={'configured' if self._webhook_url else 'cleared'}, "
                f"min_severity={self._min_severity}"
            )
        except Exception as e:
            logger.warning(f"alert config load failed (using env default): {e}")

    async def set_config(self, webhook_url: Optional[str],
                         min_severity: Optional[str]) -> Dict[str, Any]:
        """Apply + persist a new delivery config. Empty/None URL clears delivery."""
        if webhook_url is not None:
            url = webhook_url.strip()
            if url and not (url.startswith("https://") or url.startswith("http://")):
                raise ValueError("webhook_url must start with http(s)://")
            self._webhook_url = url or None
        if min_severity is not None:
            sev = min_severity.lower()
            if sev not in _VALID_SEVERITIES:
                raise ValueError(f"min_severity must be one of {sorted(_VALID_SEVERITIES)}")
            self._min_severity = sev
        payload = {"webhook_url": self._webhook_url or "", "min_severity": self._min_severity}
        try:
            await self._state.set(ALERTS_CONFIG_KEY, json.dumps(payload))
        except Exception as e:
            logger.warning(f"alert config persist failed (applied in-memory only): {e}")
        return await self.get_config()

    async def get_config(self) -> Dict[str, Any]:
        last: Optional[Dict[str, Any]] = None
        try:
            raw = await self._state.get(ALERTS_LAST_DELIVERY_KEY)
            if raw:
                last = json.loads(raw)
        except Exception:
            last = None
        return {
            "webhook_configured": self.webhook_configured,
            "webhook_url_masked": mask_webhook_url(self._webhook_url),
            "min_severity": self._min_severity,
            "last_delivery": last,
        }

    async def test_fire(self) -> Dict[str, Any]:
        """Send a test alert through the FULL delivery chain (log + recent list +
        webhook), bypassing dedupe and the min-severity filter, and return the
        webhook delivery result so the app can show it immediately."""
        record: Dict[str, Any] = {
            "ts": _utcnow_iso(),
            "severity": "info",
            "event": "alert_delivery_test",
            "message": "Test alert from TSIT Trading — delivery chain is working. "
                       "Critical bot alerts (kill switch, unprotected positions, loss limits) will arrive here.",
        }
        logger.info(f"[ALERT][TEST] {record['message']}")
        try:
            await self._state.list_push_capped(
                ALERTS_RECENT_KEY, json.dumps(record, default=str), ALERTS_RECENT_MAX,
            )
        except Exception as e:
            logger.warning(f"test alert store failed: {e}")
        if not self._webhook_url:
            return {"delivered": False, "detail": "No webhook URL configured"}
        ok, detail = await self._post_webhook(record)
        return {"delivered": ok, "detail": detail}

    async def send(self, severity: str, event: str, message: str,
                   dedupe_key: Optional[str] = None,
                   data: Optional[Dict[str, Any]] = None,
                   force_deliver: bool = False,
                   webhook_text: Optional[str] = None) -> None:
        severity = severity.lower() if severity.lower() in _VALID_SEVERITIES else "warning"
        record: Dict[str, Any] = {
            "ts": _utcnow_iso(),
            "severity": severity,
            "event": event,
            "message": str(message)[:1000],
        }
        if data:
            record["data"] = data

        # 1) Always log.
        log_fn = logger.info if severity == "info" else (
            logger.warning if severity == "warning" else logger.error
        )
        log_fn(f"[ALERT][{severity.upper()}] {event} — {record['message']}")

        # 2) Always store in the recent list (best-effort).
        try:
            await self._state.list_push_capped(
                ALERTS_RECENT_KEY, json.dumps(record, default=str), ALERTS_RECENT_MAX,
            )
        except Exception as e:
            logger.warning(f"alert store failed: {e}")

        # 3) Webhook — severity-filtered, deduped, best-effort.
        if not self._webhook_url:
            return
        if not force_deliver and (
            _SEVERITY_RANK.get(severity, 1) < _SEVERITY_RANK.get(self._min_severity, 1)
        ):
            return  # below the configured delivery floor — log + /alerts only
        if dedupe_key:
            try:
                fresh = await self._state.set(
                    f"alert:dedupe:{dedupe_key}", "1",
                    ex=self._dedupe_seconds, nx=True,
                )
                if not fresh:
                    return  # same alert fired recently — webhook suppressed
            except Exception as e:
                logger.warning(f"alert dedupe check failed (sending anyway): {e}")
        await self._post_webhook(record, text_override=webhook_text)

    async def _post_webhook(self, record: Dict[str, Any],
                            text_override: Optional[str] = None) -> tuple:
        """POST to the webhook; returns (ok, detail) and records the outcome so
        GET /alerts/config can show whether real delivery is actually working."""
        ok = False
        detail = ""
        try:
            import httpx  # lazy import — alerting must not hard-require httpx
            text = text_override or (
                f"[{record['severity'].upper()}] {record['event']}: {record['message']}"
            )
            # Discord rejects content over 2000 chars with a 400 — a long alert
            # would fail delivery entirely rather than arrive clipped.
            if len(text) > 1900:
                text = text[:1897] + "…"
            payload = {"text": text, "content": text, **record}
            async with httpx.AsyncClient(timeout=8.0) as client:
                resp = await client.post(self._webhook_url, json=payload)
                ok = resp.status_code < 400
                detail = f"HTTP {resp.status_code}"
                if not ok:
                    logger.warning(f"alert webhook returned {resp.status_code}")
        except Exception as e:
            detail = str(e)[:200]
            logger.warning(f"alert webhook delivery failed: {e}")
        try:
            await self._state.set(ALERTS_LAST_DELIVERY_KEY, json.dumps({
                "ts": _utcnow_iso(),
                "ok": ok,
                "detail": detail,
                "event": record.get("event", ""),
                "severity": record.get("severity", ""),
            }))
        except Exception:
            pass
        return ok, detail

    async def recent(self, count: int = 50) -> List[Dict[str, Any]]:
        try:
            raw = await self._state.list_range(ALERTS_RECENT_KEY, count)
        except Exception as e:
            logger.warning(f"alert list read failed: {e}")
            return []
        out: List[Dict[str, Any]] = []
        for item in raw:
            try:
                out.append(json.loads(item))
            except (TypeError, json.JSONDecodeError):
                continue
        return out


_manager: Optional[AlertManager] = None


def init(state: Any, webhook_url: Optional[str], dedupe_seconds: int = 300) -> None:
    """Configure the module-level manager (called once at startup)."""
    global _manager
    _manager = AlertManager(state, webhook_url, dedupe_seconds)
    logger.info(
        f"alerting ready — webhook={'configured' if _manager.webhook_configured else 'NOT configured (log + /alerts only)'}"
    )


def webhook_configured() -> bool:
    return _manager is not None and _manager.webhook_configured


async def load_persisted() -> None:
    """Load a previously saved webhook config from the state store (startup)."""
    if _manager is not None:
        await _manager.load_persisted()


async def get_config() -> Dict[str, Any]:
    if _manager is None:
        return {"webhook_configured": False, "webhook_url_masked": None,
                "min_severity": DEFAULT_MIN_SEVERITY, "last_delivery": None}
    return await _manager.get_config()


async def set_config(webhook_url: Optional[str], min_severity: Optional[str]) -> Dict[str, Any]:
    """Apply + persist delivery config. Raises ValueError on bad input."""
    if _manager is None:
        raise RuntimeError("alerting not initialised")
    return await _manager.set_config(webhook_url, min_severity)


async def test_fire() -> Dict[str, Any]:
    if _manager is None:
        return {"delivered": False, "detail": "alerting not initialised"}
    return await _manager.test_fire()


async def send(severity: str, event: str, message: str,
               dedupe_key: Optional[str] = None,
               data: Optional[Dict[str, Any]] = None,
               force_deliver: bool = False,
               webhook_text: Optional[str] = None) -> None:
    """Fire an alert. Safe to call before init (logs only) and never raises.

    `force_deliver` delivers regardless of the configured min-severity floor —
    for real-money fills, which are `info` by nature but must never be filtered
    away. `webhook_text` carries a multi-line Discord body while the log line
    stays single-line and greppable.
    """
    try:
        if _manager is None:
            logger.warning(f"[ALERT][{severity.upper()}] {event} — {message} (alerting not initialised)")
            return
        await _manager.send(severity, event, message, dedupe_key=dedupe_key, data=data,
                            force_deliver=force_deliver, webhook_text=webhook_text)
    except Exception as e:
        logger.error(f"alert send failed ({event}): {e}")


async def recent(count: int = 50) -> List[Dict[str, Any]]:
    if _manager is None:
        return []
    return await _manager.recent(count)

''')

_bundle_load('trade_ledger', r'''
"""
Immutable trade ledger — append-only, hash-chained JSONL.
=========================================================

Every trading-relevant event (orders placed, positions opened/closed,
protective stops, guard results, kill switch, circuit breaker trips,
reconciliation heals, failures) is appended as one JSON line to
TRADE_LEDGER_FILE. Records are NEVER modified or deleted.

Tamper evidence: each record carries `prev_hash` (the SHA-256 of the previous
record) and `hash` (SHA-256 over prev_hash + the record's canonical JSON).
Editing or removing any historical line breaks the chain, which
`verify_chain()` detects — exposed via GET /ledger.

Durability: writes append + flush + fsync under an asyncio lock, so a crash
can lose at most the record being written, never corrupt existing history.

Best-effort by design: a ledger failure must never block an order, so the
module-level `record()` swallows and logs its own errors.
"""
from __future__ import annotations

import asyncio
import hashlib
import json
import logging
import os
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Awaitable, Callable, Dict, List, Optional, Tuple

logger = logging.getLogger("etrade-bot.ledger")

GENESIS_HASH = "0" * 64


def _utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _canonical(record: Dict[str, Any]) -> str:
    return json.dumps(record, sort_keys=True, default=str)


def _chain_hash(prev_hash: str, body: str) -> str:
    return hashlib.sha256((prev_hash + body).encode("utf-8")).hexdigest()


class TradeLedger:
    def __init__(self, path: Path) -> None:
        self.path = Path(path)
        self._lock = asyncio.Lock()
        self._seq, self._prev_hash = self._load_tail()
        logger.info(
            f"trade ledger ready at {self.path} — {self._seq} record(s), chain head {self._prev_hash[:12]}…"
        )

    def _load_tail(self) -> Tuple[int, str]:
        """Resume the hash chain from the last line of an existing ledger."""
        try:
            if not self.path.exists():
                return 0, GENESIS_HASH
            last_line = ""
            with open(self.path, "r", encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        last_line = line
            if not last_line:
                return 0, GENESIS_HASH
            rec = json.loads(last_line)
            return int(rec.get("seq") or 0), str(rec.get("hash") or GENESIS_HASH)
        except (OSError, json.JSONDecodeError, TypeError, ValueError) as e:
            logger.error(f"ledger tail unreadable ({e}) — starting a fresh chain segment")
            return 0, GENESIS_HASH

    def _append_line(self, line: str) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with open(self.path, "a", encoding="utf-8") as f:
            f.write(line + "\n")
            f.flush()
            os.fsync(f.fileno())

    async def record(self, event: str, data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        async with self._lock:
            self._seq += 1
            rec: Dict[str, Any] = {
                "seq": self._seq,
                "ts": _utcnow_iso(),
                "event": str(event),
                "data": data or {},
                "prev_hash": self._prev_hash,
            }
            rec["hash"] = _chain_hash(self._prev_hash, _canonical(rec))
            await asyncio.to_thread(self._append_line, _canonical(rec))
            self._prev_hash = rec["hash"]
            return rec

    def tail(self, count: int = 100) -> List[Dict[str, Any]]:
        """Last `count` records, newest first."""
        out = self.recent(count)
        out.reverse()
        return out

    def recent(self, count: int = 100) -> List[Dict[str, Any]]:
        """Last `count` records in CHRONOLOGICAL order (oldest first).

        Replaying history (e.g. recomputing a day's realized P&L) needs events
        in the order they happened, so opens are seen before the closes that
        reference them."""
        out: List[Dict[str, Any]] = []
        try:
            if not self.path.exists():
                return []
            with open(self.path, "r", encoding="utf-8") as f:
                lines = [ln for ln in f if ln.strip()]
            for line in lines[-count:]:
                try:
                    out.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
        except OSError as e:
            logger.warning(f"ledger read failed: {e}")
        return out

    def verify_chain(self) -> Tuple[bool, int, Optional[str]]:
        """Walk the full chain and recompute every hash.
        Returns (ok, records_checked, first_error)."""
        checked = 0
        prev = GENESIS_HASH
        try:
            if not self.path.exists():
                return True, 0, None
            with open(self.path, "r", encoding="utf-8") as f:
                for line_no, line in enumerate(f, start=1):
                    if not line.strip():
                        continue
                    try:
                        rec = json.loads(line)
                    except json.JSONDecodeError:
                        return False, checked, f"line {line_no}: unparseable"
                    claimed = str(rec.pop("hash", ""))
                    if str(rec.get("prev_hash")) != prev:
                        # A fresh chain segment is allowed after a tail-read
                        # failure — a segment restart references GENESIS.
                        if str(rec.get("prev_hash")) != GENESIS_HASH:
                            return False, checked, f"line {line_no}: prev_hash broken"
                    if _chain_hash(str(rec.get("prev_hash")), _canonical(rec)) != claimed:
                        return False, checked, f"line {line_no}: hash mismatch (record altered)"
                    prev = claimed
                    checked += 1
            return True, checked, None
        except OSError as e:
            return False, checked, f"read failed: {e}"


_ledger: Optional[TradeLedger] = None
# Optional durable mirror: async (seq, hash, line) → None. The JSONL file lives
# on an EPHEMERAL container filesystem — every redeploy wiped the "immutable"
# ledger back to 0 records, so the daily P&L repair had nothing to replay and
# the app could never recover a real exit across a restart. The mirror writes
# each record to Postgres as it is appended; `restore_lines()` rebuilds the
# local file from those rows at boot. Best-effort by design: a mirror failure
# must never block an order.
_mirror: Optional[Callable[[int, str, str], Awaitable[None]]] = None


def init(path: Path) -> None:
    """Configure the module-level ledger (called once at startup)."""
    global _ledger
    _ledger = TradeLedger(path)


def set_mirror(fn: Optional[Callable[[int, str, str], Awaitable[None]]]) -> None:
    """Install the durable mirror callback (async (seq, hash, line) → None)."""
    global _mirror
    _mirror = fn


def restore_lines(path: Path, lines: List[str]) -> int:
    """Rebuild the local JSONL file from mirrored rows BEFORE `init()` — only
    when the local file is missing or empty (a restart on an ephemeral disk).
    A non-empty local file is always preferred: it is the chain `init()` will
    resume, and overwriting it could drop records newer than the mirror.
    Returns the number of lines written."""
    try:
        if path.exists() and path.stat().st_size > 0:
            return 0
        payload = [ln for ln in lines if ln and ln.strip()]
        if not payload:
            return 0
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write("\n".join(payload) + "\n")
        logger.info(f"✅ trade ledger restored from durable mirror — {len(payload)} record(s)")
        return len(payload)
    except OSError as e:
        logger.error(f"ledger restore failed ({e}) — starting fresh")
        return 0


async def record(event: str, data: Optional[Dict[str, Any]] = None) -> None:
    """Append an event. Never raises — a ledger failure must not block trading."""
    try:
        if _ledger is None:
            logger.warning(f"ledger not initialised — dropped event '{event}'")
            return
        rec = await _ledger.record(event, data)
        if _mirror is not None:
            try:
                await _mirror(int(rec["seq"]), str(rec["hash"]), _canonical(rec))
            except Exception as e:
                logger.warning(f"ledger mirror write failed (non-fatal, {event}): {e}")
    except Exception as e:
        logger.error(f"ledger append failed ({event}): {e}")


def tail(count: int = 100) -> List[Dict[str, Any]]:
    if _ledger is None:
        return []
    return _ledger.tail(count)


def recent(count: int = 100) -> List[Dict[str, Any]]:
    """Last `count` records in CHRONOLOGICAL order (oldest first).

    This module-level export was MISSING: `recent()` existed only as a method
    on TradeLedger, yet the daily P&L repair called `trade_ledger.recent(...)`
    — an AttributeError on every boot and every /pnl/repair call, so the one
    mechanism that corrects a polluted daily loss-limit figure never ran."""
    if _ledger is None:
        return []
    return _ledger.recent(count)


def verify() -> Tuple[bool, int, Optional[str]]:
    if _ledger is None:
        return True, 0, None
    return _ledger.verify_chain()

''')

_bundle_load('reconciliation', r'''
"""
Background Reconciliation Engine — Redis + async.
=================================================

A continuous async task that, every RECONCILE_INTERVAL_SECONDS during market
hours (and at a slower cadence off-hours), pulls:

  • open orders from E*TRADE   (GET /orders.json)
  • current positions          (GET /portfolio.json)

…compares them against Redis state, and auto-heals discrepancies:

  • updates filled quantities on tracked positions
  • CAPTURES BROKER-SIDE FILLS: when a tracked position has vanished at the
    broker, the pass first looks for the EXECUTED closing order that flattened
    it (usually the bot's own resting protective stop) and books a REAL close
    with the actual fill price via the injected `record_close` callback — so
    realized P&L, the daily loss limit and the learning stack all see the
    outcome instead of a silent "ghost removed"
  • marks/removes GHOST positions (tracked in Redis, absent at the broker,
    older than a grace period so an in-flight entry is never nuked)
  • detects ORPHANED protective stops (live stop order at the broker with no
    tracked position) and cancels them when auto-heal is enabled
  • flags UNPROTECTED positions (tracked position, no live stop order, no
    active guard) and re-arms the stop guard via the injected callback
  • enforces the PROTECTION INVARIANT: exactly ONE resting protective stop per
    position, for exactly the position's quantity (see `plan_protection_repair`)

Only ONE instance reconciles at a time — the pass runs under the Redis
distributed lock `lock:reconcile`, so this is safe with multiple workers.
The reconciled Redis state is the single source of truth the Stop Guard and
close logic read from. The last report is stored at `reconcile:last`.

All broker/client access is dependency-injected so this module never imports
main_bot (no circular imports) and stays unit-testable.
"""
from __future__ import annotations

import asyncio
import json
import logging
import time
from datetime import datetime, timezone
from typing import Any, Awaitable, Callable, Dict, List, Optional

try:  # package-style import (python -m bot...) or flat (uvicorn main_bot:app)
    from .state_store import StateStore
except ImportError:
    from state_store import StateStore

logger = logging.getLogger("etrade-bot.reconcile")

RECONCILE_LOCK = "reconcile"
RECONCILE_REPORT_KEY = "reconcile:last"
# The account as the BROKER sees it, refreshed every reconcile pass. Read by
# /status and /etrade/positions so the app never has to trust bot memory.
ACCOUNT_SNAPSHOT_KEY = "account:snapshot"
# A just-placed entry may not appear in /portfolio yet — never ghost-remove
# a position younger than this.
GHOST_GRACE_SECONDS = 180
_OPEN_ORDER_STATUSES = {"OPEN", "PARTIAL", "INDIVIDUAL_FILLS", "PENDING", "DO_NOT_EXERCISE"}
_PROTECTIVE_PRICE_TYPES = {"STOP", "STOP_LIMIT", "TRAILING_STOP_CNST", "TRAILING_STOP_PRCT"}
# Order actions that CLOSE a position — the only ones a protective stop uses.
_CLOSING_ACTIONS = {"SELL", "SELL_CLOSE", "BUY_TO_COVER", "BUY_CLOSE"}
# A stop armed against a partial fill is legitimate for a few seconds while the
# rest of the entry completes; only repair coverage once the dust settles.
COVERAGE_GRACE_SECONDS = 60
# A live guard owns its position's stop, so the protection-invariant audit stands
# down while one is running. It may NOT stand down forever: a guard whose task
# died leaves `done` unset, which would exempt the position from the audit for as
# long as it is held. Past its own deadline plus this slack, audit it anyway.
GUARD_TRUST_SLACK_SECONDS = 120
# Ghost-resolution verdicts: the vanished position CLOSED (an executed closing
# order with a readable fill was found) vs a true GHOST (no evidence of a fill).
GHOST_CLOSED = "closed"
GHOST_UNKNOWN = "ghost"
# An executed close must postdate the position's open (minus clock slack) —
# otherwise a stale EXECUTED order from an EARLIER round-trip on the same
# symbol would be booked as this position's exit at the wrong price.
FILL_CAPTURE_SLACK_SECONDS = 60


def protective_level(position: dict) -> float:
    """The protective price a tracked position is supposed to have resting.

    Equity positions keep it in `stop`; OPTION positions keep it in
    `stop_premium` (the premium trigger) and `stop` may legitimately be None or
    hold the underlying-price stop instead. Reading only `stop` made every
    option position look like it had no stop to check, so the UNPROTECTED
    detector skipped options entirely. `trail` is included because a ratcheted
    position's live protection is the trail, not the original stop.
    """
    best = 0.0
    for key in ("stop", "stop_premium", "trail"):
        try:
            value = float(position.get(key) or 0)
        except (TypeError, ValueError):
            continue
        if value > best:
            best = value
    return best


def guard_owns_stop(guard: Optional[dict], now: float) -> bool:
    """True while an active guard is still credibly responsible for the stop.

    An unfinished guard past its deadline is assumed dead (worker restart, task
    exception) — trusting it forever would exempt the position from every
    protection audit below.
    """
    if not guard or guard.get("done"):
        return False
    try:
        deadline = float(guard.get("deadline_ts") or 0)
    except (TypeError, ValueError):
        deadline = 0.0
    if deadline <= 0:
        return True  # no deadline recorded — take the guard at its word
    return now <= deadline + GUARD_TRUST_SLACK_SECONDS


def _utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _as_list(node: Any) -> List[dict]:
    if isinstance(node, dict):
        return [node]
    if isinstance(node, list):
        return [n for n in node if isinstance(n, dict)]
    return []


def parse_broker_positions(portfolio_resp: Dict[str, Any]) -> Dict[str, dict]:
    """Flatten a PortfolioResponse into
    {SYMBOL: {qty, eq_qty, optn_qty, security_type, occ}}.

    Options are keyed by UNDERLYING symbol (matching how the bot tracks
    positions) but counted SEPARATELY from any equity lot on the same symbol.
    Summing them (100 AAPL shares + 2 AAPL calls → qty=102) "healed" the
    option's filled_qty to 102, made the correctly-sized 2-lot stop look
    under-covering, cancelled it, and asked for a 102-contract replacement
    the broker rejected — protection destroyed by the repair meant to
    enforce it. `qty` remains the blended total for display only; sizing
    logic must go through `broker_qty_for()`."""
    out: Dict[str, dict] = {}
    root = (portfolio_resp or {}).get("PortfolioResponse", {}) or {}
    for acct in _as_list(root.get("AccountPortfolio")):
        for pos in _as_list(acct.get("Position")):
            product = pos.get("Product") or {}
            sec_type = str(product.get("securityType") or "EQ").upper()
            symbol = str(product.get("symbol") or "").upper()
            if not symbol:
                continue
            try:
                qty = int(float(pos.get("quantity") or 0))
            except (TypeError, ValueError):
                qty = 0
            record = out.setdefault(symbol, {
                "qty": 0, "eq_qty": 0, "optn_qty": 0,
                "security_type": sec_type, "occ": None,
            })
            record["qty"] += qty
            if sec_type == "OPTN":
                record["optn_qty"] += qty
                record["security_type"] = "OPTN"
                record["occ"] = pos.get("symbolDescription") or product.get("displaySymbol")
            else:
                record["eq_qty"] += qty
    return out


def broker_qty_for(record: Optional[dict], is_option: bool) -> int:
    """Broker quantity on the SAME basis as a tracked position — option
    contracts for option positions, shares for equities. Never the blended
    total. Falls back to the legacy `qty` for records written before the
    split (a restart mid-deploy replaying an old report)."""
    if not isinstance(record, dict):
        return 0
    key = "optn_qty" if is_option else "eq_qty"
    if key in record:
        try:
            return int(record.get(key) or 0)
        except (TypeError, ValueError):
            return 0
    try:
        return int(record.get("qty") or 0)
    except (TypeError, ValueError):
        return 0


def parse_open_orders(orders_resp: Dict[str, Any]) -> List[dict]:
    """Flatten an OrdersResponse into order records (live AND terminal):
    {order_id, symbol, status, price_type, order_action, filled, ordered,
     exec_price, executed_ts}. `exec_price` is the average execution price of
    a filled instrument (0 when not filled); `executed_ts` is the epoch-seconds
    execution time (0 when unknown) — both are what fill capture books a
    broker-side close from."""
    out: List[dict] = []
    root = (orders_resp or {}).get("OrdersResponse", {}) or {}
    for order in _as_list(root.get("Order")):
        order_id = str(order.get("orderId") or "")
        for detail in _as_list(order.get("OrderDetail")):
            status = str(detail.get("status") or "OPEN").upper()
            try:
                # E*TRADE stamps executedTime in epoch MILLISECONDS.
                executed_ts = float(detail.get("executedTime") or 0) / 1000.0
            except (TypeError, ValueError):
                executed_ts = 0.0
            for inst in _as_list(detail.get("Instrument")):
                product = inst.get("Product") or {}
                try:
                    filled = int(float(inst.get("filledQuantity") or 0))
                except (TypeError, ValueError):
                    filled = 0
                try:
                    ordered = int(float(inst.get("orderedQuantity") or inst.get("quantity") or 0))
                except (TypeError, ValueError):
                    ordered = 0
                try:
                    exec_price = float(inst.get("averageExecutionPrice") or 0)
                except (TypeError, ValueError):
                    exec_price = 0.0
                out.append({
                    "order_id": order_id,
                    "symbol": str(product.get("symbol") or "").upper(),
                    "security_type": str(product.get("securityType") or "EQ").upper(),
                    "status": status,
                    "price_type": str(detail.get("priceType") or "").upper(),
                    "order_action": str(inst.get("orderAction") or "").upper(),
                    "filled": filled,
                    "ordered": ordered,
                    "exec_price": exec_price,
                    "executed_ts": executed_ts,
                })
    return out


def protective_stops_by_symbol(live_orders: List[dict]) -> Dict[str, List[dict]]:
    """Group live CLOSING stop orders by symbol — the resting protection the
    broker is actually holding for each position."""
    out: Dict[str, List[dict]] = {}
    for order in live_orders:
        if order.get("price_type") not in _PROTECTIVE_PRICE_TYPES:
            continue
        action = str(order.get("order_action") or "")
        if action and action not in _CLOSING_ACTIONS:
            continue
        symbol = str(order.get("symbol") or "").upper()
        if not symbol:
            continue
        out.setdefault(symbol, []).append(order)
    return out


def build_account_snapshot(
    broker_positions: Dict[str, dict],
    all_orders: List[dict],
    tracked: Dict[str, dict],
    guards: Dict[str, dict],
    balances: Optional[Dict[str, Optional[float]]] = None,
    now: Optional[float] = None,
) -> Dict[str, Any]:
    """THE ACCOUNT AS THE BROKER SEES IT — not as the bot remembers it.

    Everything the app called "broker truth" was actually `state.all_positions()`:
    the bot's OWN Redis memory of trades the bot itself placed. That memory is
    wrong in exactly the situations that matter most — a manual trade in the
    E*TRADE app, a position left over from a crashed process, a stop that filled
    while nothing was watching, a partial close remainder. In every one of those
    the bot's memory says one thing and the account says another, and the account
    is the one holding the money.

    The real broker portfolio WAS being fetched — once every 15 minutes, inside
    the reconciler — and then thrown away, leaving only a count (`broker_positions:
    3`) in the report. This builds the durable, exportable view instead, so both
    the bot's own risk math and the app can read the account itself.

    Pure: takes already-parsed broker data, returns a JSON-safe dict.
    """
    now = time.time() if now is None else now
    live_orders = [o for o in all_orders if o.get("status") in _OPEN_ORDER_STATUSES]
    stops_by_symbol = protective_stops_by_symbol(live_orders)

    positions: List[dict] = []
    untracked: List[str] = []
    unprotected: List[str] = []

    for symbol, record in sorted(broker_positions.items()):
        try:
            qty = int(record.get("qty") or 0)
        except (TypeError, ValueError):
            qty = 0
        if qty == 0:
            continue
        pos = tracked.get(symbol)
        is_tracked = pos is not None
        stops = stops_by_symbol.get(symbol) or []
        covered = sum(_stop_remaining(o) for o in stops)
        guard_active = guard_owns_stop(guards.get(symbol), now)
        # "Protected" means a resting CLOSING stop covers the whole position, or
        # a live guard is mid-flight placing one. Anything else is naked risk
        # regardless of what the bot's own record claims.
        is_protected = guard_active or (covered > 0 and covered >= abs(qty))
        if not is_tracked:
            untracked.append(symbol)
        if not is_protected:
            unprotected.append(symbol)
        positions.append({
            "symbol": symbol,
            "qty": qty,
            "eq_qty": int(record.get("eq_qty") or 0),
            "optn_qty": int(record.get("optn_qty") or 0),
            "security_type": str(record.get("security_type") or "EQ"),
            "occ": record.get("occ"),
            "tracked": is_tracked,
            "protected": is_protected,
            "guard_active": guard_active,
            "stop_orders": len(stops),
            "stop_covered_qty": covered,
            "entry": (pos or {}).get("entry"),
            "stop": protective_level(pos) or None if pos else None,
            "target": (pos or {}).get("target"),
            "opened_ts": (pos or {}).get("ts"),
        })

    # Tracked-but-absent: the bot believes it owns something the account does
    # not hold. Reported as its own class because the fix is the opposite of an
    # untracked position — nothing to close, a memory to clear.
    ghosts = [s for s in sorted(tracked.keys()) if not _broker_holds(broker_positions, s)]

    orders_out = [{
        "order_id": o.get("order_id"),
        "symbol": o.get("symbol"),
        "security_type": o.get("security_type"),
        "status": o.get("status"),
        "price_type": o.get("price_type"),
        "order_action": o.get("order_action"),
        "filled": o.get("filled"),
        "ordered": o.get("ordered"),
    } for o in live_orders]

    bal = balances or {}
    return {
        "ts": _utcnow_iso(),
        "epoch": now,
        "equity": bal.get("total"),
        "cash_available": bal.get("available"),
        "positions": positions,
        "open_orders": orders_out,
        "untracked": untracked,
        "ghosts": ghosts,
        "unprotected": unprotected,
        "counts": {
            "broker_positions": len(positions),
            "tracked_positions": len(tracked),
            "open_orders": len(orders_out),
            "untracked": len(untracked),
            "ghosts": len(ghosts),
            "unprotected": len(unprotected),
        },
    }


def _broker_holds(broker_positions: Dict[str, dict], symbol: str) -> bool:
    record = broker_positions.get(symbol)
    if not record:
        return False
    try:
        return int(record.get("qty") or 0) != 0
    except (TypeError, ValueError):
        return False


def _stop_remaining(order: dict) -> int:
    """Contracts/shares a resting stop would still sell if it triggered."""
    try:
        ordered = int(order.get("ordered") or 0)
        filled = int(order.get("filled") or 0)
    except (TypeError, ValueError):
        return 0
    return max(ordered - filled, 0)


def plan_protection_repair(
    symbol: str,
    position_qty: int,
    stops: List[dict],
    tracked_stop_id: Optional[str] = None,
) -> Optional[dict]:
    """Enforce the protection invariant: **exactly one** resting protective stop,
    sized to **exactly** the position.

    Both ways of breaking it cost real money:

      OVER-COMMITTED — several stops (or one oversized stop) pledge more
        contracts than the position holds. E*TRADE then refuses genuine exits
        with error 3004 ("shares for this security may already be allocated to
        an existing open order"), and if the stops trigger, the surplus fills
        open a NAKED SHORT option position.

      UNDER-COVERED — the stop covers fewer contracts than are held (a stop
        armed off a partial fill that later completed). The uncovered remainder
        has no protection at all.

    Returns None when the invariant already holds, otherwise the repair plan:

      {symbol, position_qty, covered_qty, keep_order_id, cancel_order_ids,
       rearm, reason}

    `keep_order_id` is a stop that already covers the position exactly — keeping
    it means protection is never lifted, so cancelling the surplus is safe. When
    no stop fits, every stop is cancelled and `rearm` asks the caller to place
    one correct stop. Cancel-then-place is deliberate in that order: placing
    first would trip the very 3004 allocation error being repaired.
    """
    if position_qty < 1 or not stops:
        return None

    remaining = {str(o.get("order_id")): _stop_remaining(o) for o in stops}
    unknown_qty = any(q <= 0 for q in remaining.values())
    covered = 0 if unknown_qty else sum(remaining.values())

    if len(stops) == 1 and covered == position_qty:
        return None  # invariant holds

    exact = [oid for oid, q in remaining.items() if q == position_qty]
    keep: Optional[str] = None
    if tracked_stop_id and str(tracked_stop_id) in exact:
        keep = str(tracked_stop_id)
    elif exact:
        keep = exact[0]

    if unknown_qty:
        reason = "duplicate_stops"
        # Quantities unreadable: the only safe assumption is that stacked stops
        # over-commit, so thin them down to the one the bot tracks.
        if keep is None and tracked_stop_id and str(tracked_stop_id) in remaining:
            keep = str(tracked_stop_id)
    elif covered > position_qty:
        reason = "over_committed"
    elif covered < position_qty:
        reason = "under_covered"
        keep = None  # a partial stop must be replaced, not kept
    else:
        reason = "duplicate_stops"  # right total, split across orders

    cancel_ids = [oid for oid in remaining if oid != keep]
    if not cancel_ids and keep is not None:
        return None
    return {
        "symbol": symbol,
        "position_qty": int(position_qty),
        "covered_qty": int(covered),
        "unknown_qty": unknown_qty,
        "keep_order_id": keep,
        "cancel_order_ids": cancel_ids,
        "rearm": keep is None,
        "reason": reason,
    }


def plan_ghost_resolution(
    ticker: str,
    pos: dict,
    all_orders: List[dict],
    opened_ts: float = 0.0,
) -> dict:
    """A tracked position has vanished at the broker. Decide whether it CLOSED
    — an EXECUTED closing order with a readable fill exists for it — or is a
    true ghost with no evidence of an exit.

    Before this, every broker-side stop fill was handled as "ghost position
    removed": the trade's exit price, realized P&L and outcome were silently
    discarded, so the daily loss limit never saw the loss and the learning
    stack never saw the win.

    Resolution order:
      1. the position's own tracked closing orders — the protective stop
         (`stop_order_id`) or a deferred close the bot placed but could not
         price inline (`close_order_id`, set with pending_close) — the
         authoritative close when either EXECUTED,
      2. any other EXECUTED order on the symbol with an explicit CLOSING
         action (manual close, app exit whose ack was lost).

    A stop-ENTRY order executing OPENS a position, so anything with a non-
    closing action is never a close. Fills stamped BEFORE the position opened
    (minus `FILL_CAPTURE_SLACK_SECONDS`) belong to an earlier round-trip on
    the same symbol and are ignored.

    Returns {kind: GHOST_CLOSED, order_id, exit_price, basis, source} or
    {kind: GHOST_UNKNOWN}. `basis` is "premium" for option positions (the fill
    price of an option order IS the premium) and "underlying" for equities.
    """
    symbol = str(ticker or "").upper()
    basis = "premium" if (pos or {}).get("contract") else "underlying"
    tracked_stop_id = str((pos or {}).get("stop_order_id") or "")
    tracked_close_id = str((pos or {}).get("close_order_id") or "")
    tracked_ids = [i for i in (tracked_stop_id, tracked_close_id) if i]

    def _fill_of(order: dict, require_closing_action: bool) -> Optional[dict]:
        if str(order.get("status") or "").upper() != "EXECUTED":
            return None
        action = str(order.get("order_action") or "")
        if require_closing_action:
            if action not in _CLOSING_ACTIONS:
                return None
        elif action and action not in _CLOSING_ACTIONS:
            return None
        try:
            filled = int(order.get("filled") or 0)
            price = float(order.get("exec_price") or 0)
            executed_ts = float(order.get("executed_ts") or 0)
        except (TypeError, ValueError):
            return None
        if filled <= 0 or price <= 0:
            return None
        if require_closing_action and executed_ts <= 0:
            # An UNTRACKED closing order with an unreadable execution time
            # cannot be proven to belong to THIS round-trip — booking it can
            # price today's position off yesterday's close. Tracked ids
            # (our own stop/close orders) keep the lenient rule.
            return None
        if opened_ts > 0 and executed_ts > 0 and executed_ts < opened_ts - FILL_CAPTURE_SLACK_SECONDS:
            return None  # a fill from BEFORE this position opened is not its exit
        return {
            "kind": GHOST_CLOSED,
            "order_id": str(order.get("order_id") or ""),
            "exit_price": price,
            "basis": basis,
        }

    if tracked_ids:
        for order in all_orders:
            oid = str(order.get("order_id") or "")
            if oid not in tracked_ids:
                continue
            hit = _fill_of(order, require_closing_action=False)
            if hit:
                hit["source"] = "tracked_stop" if oid == tracked_stop_id else "tracked_close"
                return hit

    for order in all_orders:
        if str(order.get("symbol") or "").upper() != symbol:
            continue
        if str(order.get("order_id") or "") in tracked_ids:
            continue  # already checked above
        hit = _fill_of(order, require_closing_action=True)
        if hit:
            hit["source"] = "closing_order"
            return hit

    return {"kind": GHOST_UNKNOWN}


class BrokerSessionExpired(Exception):
    """The broker session is known-DEAD (midnight-ET hard expiry or a user
    unlink). Raised by the fetch callbacks so a reconcile pass can skip
    QUIETLY: every broker call during a dead session is a guaranteed 401,
    and treating each one as a fresh reconcile_fetch_failed ERROR spammed
    an alert every 15 minutes all night (observed 2026-08-09, 04:06→12:36
    UTC — 34+ Discord alerts for one expired token). The expiry itself is
    alerted ONCE at the state transition by the session tracker."""


async def reconcile_once(
    state: StateStore,
    fetch_portfolio: Callable[[], Awaitable[Dict[str, Any]]],
    fetch_orders: Callable[[], Awaitable[Dict[str, Any]]],
    cancel_order: Callable[[str], Awaitable[bool]],
    rearm_guard: Optional[Callable[[str, dict], Awaitable[None]]] = None,
    record_close: Optional[Callable[[str, dict, dict], Awaitable[None]]] = None,
    auto_heal: bool = True,
    alert: Optional[Callable[..., Awaitable[None]]] = None,
    fetch_balance: Optional[Callable[[], Awaitable[Optional[Dict[str, Optional[float]]]]]] = None,
) -> Dict[str, Any]:
    """One reconciliation pass. Caller must already hold the reconcile lock.
    `alert(severity, event, message, dedupe_key=...)` is an optional async
    callback for real-time alerting — failures in it are swallowed."""

    async def _alert(severity: str, event: str, message: str,
                     dedupe_key: Optional[str] = None) -> None:
        if alert is None:
            return
        try:
            await alert(severity, event, message, dedupe_key=dedupe_key)
        except Exception:
            logger.debug("reconcile alert delivery failed", exc_info=True)

    report: Dict[str, Any] = {
        "ts": _utcnow_iso(),
        "ok": False,
        "healed": [],
        "warnings": [],
        "tracked_positions": 0,
        "broker_positions": 0,
        "live_orders": 0,
    }
    try:
        portfolio_resp, orders_resp = await asyncio.gather(fetch_portfolio(), fetch_orders())
    except BrokerSessionExpired as e:
        # Known-dead session — not a new failure. The transition was already
        # alerted once; repeating an ERROR per cycle is pure noise.
        report["warnings"].append(f"skipped — broker session expired, awaiting relink: {e}")
        await state.set(RECONCILE_REPORT_KEY, json.dumps(report))
        logger.info(f"[RECONCILE] skipped — session expired, awaiting relink ({e})")
        return report
    except Exception as e:
        report["warnings"].append(f"broker fetch failed: {e}")
        await state.set(RECONCILE_REPORT_KEY, json.dumps(report))
        logger.warning(f"[RECONCILE] broker fetch failed: {e}")
        await _alert("error", "reconcile_fetch_failed",
                     f"Reconciliation could not read broker state: {e}",
                     dedupe_key="reconcile_fetch")
        return report

    broker_positions = parse_broker_positions(portfolio_resp)
    all_orders = parse_open_orders(orders_resp)
    live_orders = [o for o in all_orders if o["status"] in _OPEN_ORDER_STATUSES]
    tracked = await state.all_positions()
    guards = await state.all_guards()

    report["tracked_positions"] = len(tracked)
    report["broker_positions"] = len(broker_positions)
    report["live_orders"] = len(live_orders)

    now = time.time()
    # PROTECTION means a resting stop that CLOSES the position. A stop-entry
    # order (BUY_STOP on a breakout) is also priceType STOP, and counting it as
    # protection reported a naked position as protected — a false green on the
    # one check that exists to catch naked risk.
    stops_by_symbol = protective_stops_by_symbol(live_orders)
    live_stop_symbols = set(stops_by_symbol.keys())

    # --- 1) tracked positions vs broker ---
    for ticker, pos in tracked.items():
        broker = broker_positions.get(ticker)
        is_opt_pos = bool(pos.get("contract"))
        basis_qty = abs(broker_qty_for(broker, is_opt_pos))
        opened_ts = 0.0
        try:
            opened_ts = datetime.fromisoformat(str(pos.get("ts"))).timestamp()
        except (TypeError, ValueError):
            pass
        age = now - opened_ts if opened_ts else 1e9

        # "Present" means present ON THE SAME BASIS: a tracked option with
        # only equity shares at the broker is a ghost of the option position.
        if broker is None or basis_qty == 0:
            # Not at the broker. In-flight entries get a grace period; a live
            # unfilled entry order also keeps the position tracked.
            has_live_entry = any(
                o["symbol"] == ticker and o["order_action"] in {"BUY", "BUY_OPEN", "SELL_SHORT"}
                for o in live_orders
            )
            if has_live_entry or age < GHOST_GRACE_SECONDS:
                continue
            # FILL CAPTURE — before writing the position off as a ghost, look
            # for the executed closing order that actually flattened it. A
            # protective stop filling at the broker is a real trade outcome:
            # it must be BOOKED (realized P&L, daily loss limit, ledger,
            # learning), not silently deleted.
            resolution = plan_ghost_resolution(ticker, pos, all_orders, opened_ts=opened_ts)
            if not auto_heal:
                if resolution["kind"] == GHOST_CLOSED:
                    report["warnings"].append(
                        f"{ticker}: closed at broker (order {resolution['order_id']} filled "
                        f"@ {resolution['exit_price']}) — not booked, auto-heal off"
                    )
                else:
                    report["warnings"].append(f"{ticker}: ghost position (not at broker)")
                continue
            if resolution["kind"] == GHOST_CLOSED and record_close is not None:
                booked = False
                try:
                    # record_close pops the position from state itself so the
                    # close is booked exactly once.
                    await record_close(ticker, pos, resolution)
                    booked = True
                except Exception as e:
                    logger.error(
                        f"[RECONCILE] fill-capture close for {ticker} failed: {e} — "
                        f"falling back to ghost removal"
                    )
                if booked:
                    guard = guards.get(ticker)
                    if guard and not guard.get("done"):
                        await state.update_guard(ticker, done=True, result="reconciled_stop_filled")
                    detail = (
                        f"{ticker}: broker-side fill captured — closed @ "
                        f"{resolution['exit_price']:.2f} ({resolution['basis']}, "
                        f"order {resolution['order_id']}, {resolution['source']})"
                    )
                    report["healed"].append(detail)
                    logger.warning(f"[RECONCILE] 💰 {detail}")
                    await _alert("warning", "stop_fill_captured",
                                 f"{ticker}: position closed at the broker — order "
                                 f"{resolution['order_id']} filled @ {resolution['exit_price']}. "
                                 f"Realized P&L booked; daily loss limit and learning updated.",
                                 dedupe_key=f"fill_capture:{ticker}")
                    continue
            await state.delete_position(ticker)
            guard = guards.get(ticker)
            if guard and not guard.get("done"):
                await state.update_guard(ticker, done=True, result="reconciled_ghost")
            report["healed"].append(f"{ticker}: ghost position removed (not at broker)")
            logger.warning(f"[RECONCILE] 👻 {ticker} ghost position removed — not present at broker")
            await _alert("warning", "ghost_position_removed",
                         f"{ticker}: tracked position absent at broker — removed from state",
                         dedupe_key=f"ghost:{ticker}")
            continue

        # Sync filled quantity from the broker's actual position size — on the
        # position's OWN basis (contracts for options, shares for equities).
        broker_qty = basis_qty
        tracked_qty = int(pos.get("filled_qty") or pos.get("qty") or 0)
        if broker_qty > 0 and broker_qty != tracked_qty:
            pos["filled_qty"] = broker_qty
            pos["reconciled_at"] = _utcnow_iso()
            await state.set_position(ticker, pos)
            report["healed"].append(f"{ticker}: filled_qty {tracked_qty} → {broker_qty}")
            logger.info(f"[RECONCILE] {ticker} filled_qty synced {tracked_qty} → {broker_qty}")

        # Unprotected: real position, no live stop order, no active guard.
        guard = guards.get(ticker)
        guard_active = guard_owns_stop(guards.get(ticker), now)
        if ticker not in live_stop_symbols and not guard_active and protective_level(pos) > 0:
            msg = f"{ticker}: UNPROTECTED — position at broker with no live stop and no active guard"
            report["warnings"].append(msg)
            logger.error(f"[RECONCILE] 🚨 {msg}")
            await _alert("critical", "position_unprotected", msg,
                         dedupe_key=f"unprotected:{ticker}")
            if auto_heal and rearm_guard is not None:
                try:
                    await rearm_guard(ticker, pos)
                    report["healed"].append(f"{ticker}: stop guard re-armed")
                except Exception as e:
                    report["warnings"].append(f"{ticker}: guard re-arm failed: {e}")
                    await _alert("critical", "guard_rearm_failed",
                                 f"{ticker}: protective stop re-arm FAILED: {e}",
                                 dedupe_key=f"rearm_fail:{ticker}")
        elif ticker not in live_stop_symbols and not guard_active:
            # The position most in need of the UNPROTECTED alert — one that
            # never got ANY stop level recorded (e.g. a MARKET option entry
            # with no readable fill reference) — was silently exempt forever
            # because protective_level() == 0 skipped the whole check.
            msg = (f"{ticker}: NO STOP LEVEL RECORDED — live position with no protective "
                   f"level to re-arm; set a stop or close it manually")
            report["warnings"].append(msg)
            logger.error(f"[RECONCILE] 🚨 {msg}")
            await _alert("critical", "position_no_stop_level", msg,
                         dedupe_key=f"nostop:{ticker}")

    # --- 1b) protection invariant: exactly ONE resting stop, sized to the
    #         position. Runs after the filled_qty sync above so the audit
    #         compares against the broker's real position size.
    for ticker, pos in tracked.items():
        broker = broker_positions.get(ticker)
        if broker is None:
            continue
        basis_qty_1b = abs(broker_qty_for(broker, bool(pos.get("contract"))))
        if basis_qty_1b == 0:
            continue  # not present on this basis — section 1 handled the ghost
        if guard_owns_stop(guards.get(ticker), now):
            continue  # a live guard owns this position's stop right now
        stops = stops_by_symbol.get(ticker) or []
        position_qty = basis_qty_1b or int(pos.get("filled_qty") or 0)
        plan = plan_protection_repair(ticker, position_qty, stops,
                                      tracked_stop_id=pos.get("stop_order_id"))
        if plan is None:
            continue

        opened_ts = 0.0
        try:
            opened_ts = datetime.fromisoformat(str(pos.get("ts"))).timestamp()
        except (TypeError, ValueError):
            pass
        if plan["reason"] == "under_covered" and opened_ts and (now - opened_ts) < COVERAGE_GRACE_SECONDS:
            continue  # entry still filling — its stop is sized to the partial fill

        detail = (
            f"{ticker}: {plan['reason'].replace('_', ' ')} — {len(stops)} resting stop"
            f"{'' if len(stops) == 1 else 's'} covering {plan['covered_qty']} of {position_qty}"
        )
        report["warnings"].append(detail)
        logger.error(f"[RECONCILE] 🛡️ protection invariant broken — {detail}")
        await _alert(
            "critical", f"protection_{plan['reason']}",
            f"{detail}. Surplus stops block real exits (E*TRADE 3004) and can leave a naked "
            f"short; uncovered contracts have no stop at all. Repairing now.",
            dedupe_key=f"protect:{ticker}",
        )
        if not auto_heal:
            continue

        cancelled_all = True
        for order_id in plan["cancel_order_ids"]:
            try:
                ok = await cancel_order(order_id)
            except Exception as e:
                ok = False
                logger.error(f"[RECONCILE] cancel of surplus stop {order_id} on {ticker} failed: {e}")
            if ok:
                report["healed"].append(f"{ticker}: surplus stop {order_id} cancelled")
            else:
                cancelled_all = False
                report["warnings"].append(f"{ticker}: surplus stop {order_id} cancel FAILED")

        if plan["keep_order_id"]:
            # One correctly-sized stop survived: adopt it so the trailing engine
            # cancel/replaces the order that is actually resting.
            if str(pos.get("stop_order_id") or "") != str(plan["keep_order_id"]):
                pos["stop_order_id"] = plan["keep_order_id"]
                await state.set_position(ticker, pos)
                report["healed"].append(f"{ticker}: adopted resting stop {plan['keep_order_id']}")
            continue

        if not cancelled_all:
            # Something is still pledged at the broker; placing another stop now
            # would re-create the over-commitment. Leave it for the next pass.
            await _alert("critical", "protection_repair_blocked",
                         f"{ticker}: could not clear the surplus stops, so no replacement was "
                         f"placed. Check the open orders at E*TRADE.",
                         dedupe_key=f"protect_blocked:{ticker}")
            continue

        if rearm_guard is None:
            continue
        try:
            pos["stop_order_id"] = None
            pos["filled_qty"] = position_qty
            await rearm_guard(ticker, pos)
            report["healed"].append(f"{ticker}: single stop re-armed for {position_qty}")
            logger.warning(f"[RECONCILE] 🛡️ {ticker} protection rebuilt — one stop for {position_qty}")
        except Exception as e:
            report["warnings"].append(f"{ticker}: protection rebuild failed: {e}")
            await _alert("critical", "protection_rebuild_failed",
                         f"{ticker}: the surplus stops were cancelled but the replacement stop "
                         f"failed to rest — position is UNPROTECTED: {e}",
                         dedupe_key=f"protect_rebuild:{ticker}")

    # --- 1c) broker positions NOBODY tracks — the most dangerous state on
    #         the book: no stop, no trail, no heat accounting, no cap slot.
    #         Real paths here: process death between placement and recording,
    #         a guard timeout that deleted the position before the entry
    #         filled, a partial close remainder, or a manual trade.
    for symbol, record in broker_positions.items():
        if symbol in tracked:
            continue
        try:
            qty_untracked = abs(int(record.get("qty") or 0))
        except (TypeError, ValueError):
            qty_untracked = 0
        if qty_untracked <= 0:
            continue
        sec = str(record.get("security_type") or "EQ")
        msg = (f"{symbol}: UNTRACKED position at broker ({qty_untracked} "
               f"{'contract(s)' if sec == 'OPTN' else 'share(s)'}) — no stop, no trail, "
               f"no risk accounting. Close it at E*TRADE or re-enter it through the bot.")
        report["warnings"].append(msg)
        logger.error(f"[RECONCILE] 🚨 {msg}")
        await _alert("critical", "untracked_position", msg,
                     dedupe_key=f"untracked:{symbol}")

    # --- 2) orphaned protective stops (stop order live, no tracked position,
    #        no broker position) ---
    for order in live_orders:
        if order["price_type"] not in {"STOP", "STOP_LIMIT"}:
            continue
        # Only CLOSING stops can be orphaned. A BUY_STOP entry order legitimately
        # rests with no position behind it — that is the whole point of a
        # stop-entry — and cancelling it silently deleted pending breakout
        # entries the user was waiting on.
        action = str(order.get("order_action") or "")
        if action and action not in _CLOSING_ACTIONS:
            continue
        symbol = order["symbol"]
        if symbol in tracked or symbol in broker_positions:
            continue
        if auto_heal:
            cancelled = await cancel_order(order["order_id"])
            if cancelled:
                report["healed"].append(f"{symbol}: orphaned stop {order['order_id']} cancelled")
                logger.warning(f"[RECONCILE] 🧹 cancelled orphaned stop {order['order_id']} on {symbol}")
            else:
                report["warnings"].append(f"{symbol}: orphaned stop {order['order_id']} cancel FAILED")
                await _alert("critical", "orphan_stop_cancel_failed",
                             f"{symbol}: orphaned stop order {order['order_id']} could not be cancelled",
                             dedupe_key=f"orphan:{symbol}")
        else:
            report["warnings"].append(f"{symbol}: orphaned stop order {order['order_id']}")

    # --- 3) finished guards referencing dead entry orders (stale cleanup) ---
    live_order_ids = {o["order_id"] for o in live_orders}
    for ticker, guard in guards.items():
        if guard.get("done"):
            continue
        entry_id = str(guard.get("entry_order_id") or "")
        deadline = float(guard.get("deadline_ts") or 0)
        if entry_id and entry_id not in live_order_ids and ticker not in broker_positions \
                and deadline and now > deadline + GHOST_GRACE_SECONDS:
            await state.update_guard(ticker, done=True, result="reconciled_stale_guard")
            report["healed"].append(f"{ticker}: stale guard closed (entry gone, no position)")

    # --- 4) publish the account as the broker sees it -----------------------
    # The portfolio and order data above was already paid for; throwing it away
    # after the heal pass is what forced every other consumer (the app, the risk
    # math, the operator) to fall back to the bot's own memory.
    balances: Optional[Dict[str, Optional[float]]] = None
    if fetch_balance is not None:
        try:
            balances = await fetch_balance()
        except Exception as e:
            logger.debug(f"[RECONCILE] balance fetch failed (snapshot still published): {e}")
    try:
        snapshot = build_account_snapshot(
            broker_positions, all_orders, tracked, guards, balances=balances, now=now,
        )
        await state.set(ACCOUNT_SNAPSHOT_KEY, json.dumps(snapshot))
        report["account_snapshot_ts"] = snapshot["ts"]
    except Exception as e:
        logger.warning(f"[RECONCILE] account snapshot publish failed: {e}")

    report["ok"] = True
    await state.set(RECONCILE_REPORT_KEY, json.dumps(report))
    if report["healed"] or report["warnings"]:
        logger.info(f"[RECONCILE] pass done — healed={len(report['healed'])} warnings={len(report['warnings'])}")
    return report


async def reconciliation_loop(
    state: StateStore,
    fetch_portfolio: Callable[[], Awaitable[Dict[str, Any]]],
    fetch_orders: Callable[[], Awaitable[Dict[str, Any]]],
    cancel_order: Callable[[str], Awaitable[bool]],
    is_market_open: Callable[[], bool],
    has_tokens: Callable[[], bool],
    rearm_guard: Optional[Callable[[str, dict], Awaitable[None]]] = None,
    record_close: Optional[Callable[[str, dict, dict], Awaitable[None]]] = None,
    interval_seconds: int = 300,
    offhours_interval_seconds: int = 900,
    auto_heal: bool = True,
    stop_flag: Callable[[], bool] = lambda: False,
    alert: Optional[Callable[..., Awaitable[None]]] = None,
    fetch_balance: Optional[Callable[[], Awaitable[Optional[Dict[str, Optional[float]]]]]] = None,
) -> None:
    """Continuous reconciler. Runs each pass under the distributed
    `lock:reconcile` so exactly one worker reconciles at a time.

    Cadence: every 5 minutes in-session / 15 minutes off-hours by default —
    reconciliation is a periodic safety net, not the fast path. Fill-time
    protection is event-driven (stop guards poll their own orders), so a
    minute-level reconcile cadence only burns broker API quota."""
    logger.info(
        f"[RECONCILE] engine started — every {interval_seconds}s in-session, "
        f"{offhours_interval_seconds}s off-hours, auto_heal={auto_heal}"
    )
    while not stop_flag():
        delay = interval_seconds if is_market_open() else offhours_interval_seconds
        try:
            if has_tokens():
                lock = state.lock(RECONCILE_LOCK, ttl_ms=max(60_000, interval_seconds * 2000))
                if await lock.try_acquire():
                    try:
                        await reconcile_once(
                            state, fetch_portfolio, fetch_orders, cancel_order,
                            rearm_guard=rearm_guard, record_close=record_close,
                            auto_heal=auto_heal, alert=alert,
                            fetch_balance=fetch_balance,
                        )
                    finally:
                        await lock.release()
                # else: another worker holds the lock — its pass covers us.
        except Exception as e:
            logger.error(f"[RECONCILE] loop error: {e}")
            if alert is not None:
                try:
                    await alert("error", "reconcile_loop_error", str(e), dedupe_key="reconcile_loop")
                except Exception:
                    logger.debug("reconcile loop alert failed", exc_info=True)
        await asyncio.sleep(delay)

''')

_bundle_load('trailing_engine', r'''
"""
Server-side Trailing-Stop Engine — pure math, no I/O.
=====================================================

Python port of the app's `trailingEngine.ts` so the SAME tiered, real-money
trail runs at the broker even when the phone is locked or the app is killed.

The ladder mirrors how a disciplined day trader manages a live position:

1. BREAKEVEN LOCK — once the trade has shown +0.75R of open profit, the stop
   can never sit below entry again. A winner never round-trips to a full loss.
2. TIERED TIGHTENING — the trail distance shrinks as profit grows:
     • < 1R open profit → trail 1.00R behind the high-water mark ("initial")
     • ≥ 1R             → trail 0.75R ("protect")
     • ≥ 2R             → trail 0.50R ("locked")
     • ≥ 3R             → trail 0.35R ("runner")
3. ATR NOISE FLOOR — never tighter than 0.45 × ATR (capped at the initial 1R)
   so intraday noise can't shake out a healthy runner.
4. MONOTONIC RATCHET — the stop only ever moves in the trade's favor.
5. GIVE-BACK CAP — an R-only ladder is useless when R itself is enormous. An
   option bought at $4.90 with a 30%-of-premium broker stop has R = $1.50, so
   +0.75R means the premium must run +23% before ANY protection tightens — a
   trade can run +20% and still round-trip to a full −30% loss. The give-back
   cap works in PERCENT of the entry price instead of R: past +8% it surrenders
   only a bounded fraction of the open profit, and it governs the trail whenever
   it is tighter than the R tier.
6. SPREAD FLOOR — the trail is never placed inside 1.5 × the round-trip bid/ask
   spread (capped at 1R), so a wide option chain can't be stopped out by its
   own quote rather than by the market.

Percent rungs are self-scaling: a 0.5% underlying swing never reaches the +8%
give-back trigger, so equity/underlying trails are unchanged. They only bite on
option premiums, where a 10-30% swing is a normal afternoon.

`plan_ratchet` adds the broker-aware layer: given a tracked position record
and a live mark, it returns the watermark updates plus whether the resting
stop order should be cancel/replaced (only when the improvement clears a
minimum step, so broker API quota isn't burned on penny moves).

Pure functions only — the caller owns quotes, order placement, and state.
"""
from __future__ import annotations

import math
from typing import Any, Dict, Optional

# MFE (in R) at which the stop locks to breakeven.
BREAKEVEN_TRIGGER_R = 0.75
# Fraction of ATR the trail must always leave for normal noise.
ATR_NOISE_FLOOR = 0.45
# MFE as a fraction of entry price that ALSO locks breakeven, independent of R.
BREAKEVEN_TRIGGER_PCT = 0.12
# MFE percent at which the give-back cap starts governing the trail.
GIVEBACK_TRIGGER_PCT = 0.08
# Multiple of the bid/ask spread the trail must always clear.
SPREAD_FLOOR_MULT = 1.5

# Profit-tier ladder: (minimum MFE in R, trail distance as fraction of R, tier).
TIER_LADDER = (
    (3.0, 0.35, "runner"),
    (2.0, 0.50, "locked"),
    (1.0, 0.75, "protect"),
)

# Give-back ladder: (minimum MFE percent, fraction of the open profit KEPT).
GIVEBACK_LADDER = (
    (0.30, 0.70),
    (0.20, 0.60),
    (0.12, 0.50),
    (GIVEBACK_TRIGGER_PCT, 0.33),
)

TRAIL_TIER_LABEL = {
    "initial": "Initial 1R trail",
    "breakeven": "Breakeven locked",
    "protect": "+1R — trailing 0.75R",
    "locked": "+2R — trailing 0.50R",
    "runner": "+3R runner — trailing 0.35R",
    "giveback": "Profit give-back capped",
}


def _round2(n: float) -> float:
    """Round to 2dp with JS `Math.round` semantics (half away from -inf).

    Python's built-in `round` is banker's rounding, so `round(10012.5)` is
    10012 while JavaScript's `Math.round` gives 10013. The app and the bot
    must agree on the cent, or the same trade shows two different stops.
    """
    return math.floor(n * 100 + 0.5) / 100.0


def _finite(value: Any) -> Optional[float]:
    try:
        f = float(value)
    except (TypeError, ValueError):
        return None
    if f != f or f in (float("inf"), float("-inf")):
        return None
    return f


def trail_tier_for(r_multiple: float) -> Dict[str, Any]:
    """Resolve the tier + trail fraction for a given MFE in R multiples."""
    for min_r, frac, tier in TIER_LADDER:
        if r_multiple >= min_r:
            return {"tier": tier, "frac": frac}
    if r_multiple >= BREAKEVEN_TRIGGER_R:
        return {"tier": "breakeven", "frac": 1.0}
    return {"tier": "initial", "frac": 1.0}


def giveback_keep_for(mfe_percent: float) -> Optional[float]:
    """Fraction of the open profit the give-back cap keeps at this MFE percent,
    or None when the run is too small for the cap to govern."""
    pct = _finite(mfe_percent)
    if pct is None:
        return None
    for min_pct, keep in GIVEBACK_LADDER:
        if pct >= min_pct:
            return keep
    return None


def compute_trail_level(
    side: str,
    entry_price: float,
    stop_loss: float,
    high_since: float,
    low_since: float,
    atr: Optional[float] = None,
    prev_trail: Optional[float] = None,
    spread: Optional[float] = None,
) -> Dict[str, Any]:
    """Compute the current trailing-stop level for a position.

    side: "BUY" (long) or "SELL" (short). Degenerate inputs fall back to the
    hard stop with the initial tier — a protective level is always returned.
    """
    is_buy = str(side or "BUY").upper() != "SELL"
    entry = _finite(entry_price) or 0.0
    stop = _finite(stop_loss) or 0.0
    risk = abs(entry - stop)

    fallback = {
        "trail_price": _round2(stop),
        "trail_distance": _round2(risk),
        "tier": "initial",
        "r_multiple": 0.0,
        "breakeven_locked": False,
        "mfe_percent": 0.0,
        "giveback_active": False,
    }
    if entry <= 0 or risk <= 0:
        return fallback

    # Only the side-relevant watermark matters; a missing one is a degenerate
    # input and falls back to the hard stop (mirrors the TypeScript engine).
    mark = _finite(high_since) if is_buy else _finite(low_since)
    if mark is None:
        return fallback
    water_mark = max(entry, mark) if is_buy else min(entry, mark)
    if water_mark <= 0:
        return fallback

    mfe = (water_mark - entry) if is_buy else (entry - water_mark)
    r_multiple = mfe / risk
    mfe_percent = mfe / entry

    rung = trail_tier_for(r_multiple)
    tier = rung["tier"]
    # A big percent run locks breakeven even when R is too wide to reach 0.75R.
    if tier == "initial" and mfe_percent >= BREAKEVEN_TRIGGER_PCT:
        tier = "breakeven"

    tier_distance = rung["frac"] * risk
    atr_f = _finite(atr)
    if atr_f is not None and atr_f > 0:
        tier_distance = max(tier_distance, min(risk, ATR_NOISE_FLOOR * atr_f))

    # Give-back cap: surrender only a bounded slice of the run. Takes over
    # whenever it is TIGHTER than the R-tier trail (the normal case on option
    # premiums, where R is a huge fraction of the entry price).
    distance = tier_distance
    giveback_active = False
    keep = giveback_keep_for(mfe_percent)
    if keep is not None and mfe > 0:
        giveback_distance = mfe * (1.0 - keep)
        if giveback_distance < distance:
            distance = giveback_distance
            giveback_active = True
            tier = "giveback"

    # Spread floor LAST: nothing may rest inside the round-trip spread. If the
    # floor erases the give-back edge the tier label reverts to the R rung.
    spread_f = _finite(spread)
    if spread_f is not None and spread_f > 0:
        floor = min(risk, SPREAD_FLOOR_MULT * spread_f)
        if floor > distance:
            distance = floor
            if distance >= tier_distance:
                giveback_active = False
                tier = (
                    "breakeven"
                    if rung["tier"] == "initial" and mfe_percent >= BREAKEVEN_TRIGGER_PCT
                    else rung["tier"]
                )

    raw = (water_mark - distance) if is_buy else (water_mark + distance)

    if r_multiple >= BREAKEVEN_TRIGGER_R or mfe_percent >= BREAKEVEN_TRIGGER_PCT:
        raw = max(raw, entry) if is_buy else min(raw, entry)

    trail = max(stop, raw) if is_buy else min(stop, raw)
    prev = _finite(prev_trail)
    if prev is not None and prev > 0:
        trail = max(trail, prev) if is_buy else min(trail, prev)
    trail = _round2(trail)

    return {
        "trail_price": trail,
        "trail_distance": _round2(distance),
        "tier": tier,
        "r_multiple": round(r_multiple * 100) / 100.0,
        "breakeven_locked": (trail >= entry) if is_buy else (trail <= entry),
        "mfe_percent": math.floor(mfe_percent * 10000 + 0.5) / 10000.0,
        "giveback_active": giveback_active,
    }


def plan_ratchet(
    position: Dict[str, Any],
    mark: float,
    min_step_frac: float = 0.10,
    min_step_abs: float = 0.02,
    spread: Optional[float] = None,
) -> Optional[Dict[str, Any]]:
    """Decide whether a position's resting stop should be ratcheted.

    `position` is a bot position record. For options the caller must pass the
    option PREMIUM as `mark` and premium-basis entry/stop via the
    `entry_premium` / `stop_premium` fields. Returns None when the position
    can't be trailed (missing basis), otherwise a plan dict:

      {
        "entry", "initial_stop", "current_stop",   # basis used
        "high_since", "low_since",                  # updated watermarks
        "trail": {...compute_trail_level result},
        "should_replace": bool,                     # cancel/replace at broker?
        "new_stop": float,                          # level to rest if so
      }

    A replace is only proposed when the improvement over the currently resting
    level clears max(min_step_abs, min_step_frac × initial risk) — small
    ratchets aren't worth a cancel/replace round-trip at the broker.

    `spread` is the live bid/ask spread on the SAME basis as `mark` (premium for
    options). It floors the trail distance so a wide chain is never stopped out
    by its own quote. The min step is likewise floored at half the spread: a
    ratchet smaller than the spread is noise, not progress.
    """
    is_option = bool((position.get("contract") or {}).get("right"))
    side = str(position.get("action") or "BUY").upper()
    if is_option:
        side = "BUY"  # options are held long here; exits are SELL_CLOSE
        entry = _finite(position.get("entry_premium"))
        initial = _finite(position.get("initial_stop") or position.get("stop_premium"))
    else:
        entry = _finite(position.get("entry"))
        initial = _finite(position.get("initial_stop") or position.get("stop"))

    mark_f = _finite(mark)
    if entry is None or entry <= 0 or initial is None or initial <= 0 \
            or mark_f is None or mark_f <= 0:
        return None
    risk = abs(entry - initial)
    if risk <= 0:
        return None

    is_buy = side != "SELL"
    high = _finite(position.get("trail_high")) or entry
    low = _finite(position.get("trail_low")) or entry
    high = max(high, mark_f)
    low = min(low, mark_f)

    prev_trail = _finite(position.get("trail"))
    current_stop = prev_trail if (prev_trail is not None and prev_trail > 0) else initial

    trail = compute_trail_level(
        side=side,
        entry_price=entry,
        stop_loss=initial,
        high_since=high,
        low_since=low,
        atr=position.get("atr"),
        prev_trail=current_stop,
        spread=spread,
    )

    step = max(float(min_step_abs), float(min_step_frac) * risk)
    spread_f = _finite(spread)
    if spread_f is not None and spread_f > 0:
        step = max(step, 0.5 * spread_f)
    improvement = (trail["trail_price"] - current_stop) if is_buy else (current_stop - trail["trail_price"])
    return {
        "entry": entry,
        "initial_stop": initial,
        "current_stop": current_stop,
        "high_since": _round2(high),
        "low_since": _round2(low),
        "trail": trail,
        "should_replace": improvement >= step,
        "new_stop": trail["trail_price"],
    }

''')

_bundle_load('scanner', r'''
"""
Server-Side Market Scanner — the bot's own eyes.
================================================

WHY THIS EXISTS
---------------
Every signal this bot ever executed was born in the phone app: the app polled
quotes, scored setups and POSTed them to /webhook. The bot was a hands-only
service — it could place, protect, trail and reconcile orders, but it could
not SEE the market. Close the app (phone locked, backgrounded, killed) and the
pipeline went blind: observed live on 2026-07-31, quote polling stopped at
20:11 UTC and nothing but the 15-minute reconcile ticked for the rest of the
session.

This module gives the bot its own perception loop. It samples real E*TRADE
quotes for a configurable universe on a fixed cadence, keeps a rolling
intraday series in the shared state store, measures relative volume from the
broker's own numbers, detects a small set of well-defined setups, scores them
from those measurements, and dispatches qualifying candidates through the
EXACT same path a webhook signal takes (so every server-side risk gate,
cooldown, cap, kill switch and stop-guard still applies).

DATA-TRUST RULES (non-negotiable)
---------------------------------
* RVOL is computed ONLY from broker-reported `totalVolume` and the 10-day
  average daily volume, prorated by how much of the session has elapsed. If
  either input is missing, rvol is None — the candidate can never be sent
  live (the entry filter refuses unmeasured RVOL).
* Scores are a weighted blend of MEASURED factors (rvol, momentum vs. open,
  position vs. sampled VWAP, spread). Nothing is invented to clear a gate.
* A candidate needs at least MIN_SAMPLES observations of its own before any
  setup can be claimed — the scanner never judges a ticker it just met.

MODES
-----
    off     — loop idles; nothing is measured or emitted.
    shadow  — full measurement + scoring; candidates are recorded and visible
              via /scanner/status, but NOTHING is dispatched. (default)
    live    — qualifying candidates are dispatched as real signals.

Everything (mode, universe, cadence, thresholds) is stored in the state store
and changeable at runtime via POST /scanner/config — no redeploy.

All broker/dispatch access is dependency-injected so this module never imports
main_bot (no circular imports) and its helpers stay unit-testable.
"""
from __future__ import annotations

import asyncio
import json
import logging
import math
import re
from datetime import datetime, time as dtime, timedelta, timezone
from typing import Any, Awaitable, Callable, Dict, List, Optional, Tuple

try:  # package-style import (python -m bot...) or flat (uvicorn main_bot:app)
    from .state_store import StateStore
except ImportError:
    from state_store import StateStore

logger = logging.getLogger("etrade-bot.scanner")

SCANNER_LOCK = "scanner"
CONFIG_KEY = "scanner:config"
REPORT_KEY = "scanner:last"
SERIES_KEY_FMT = "scanner:series:{}"
EMIT_KEY_FMT = "scanner:emits:{}"

# A ticker must have this many of its own samples before a setup may be
# claimed — no judging a symbol the scanner just started watching.
MIN_SAMPLES = 4
# Rolling samples kept per ticker (60s cadence → ~2h of session memory).
MAX_SAMPLES = 120
# E*TRADE accepts batched quote symbols; keep chunks conservative.
QUOTE_CHUNK = 20

MODES = ("off", "shadow", "live")

DEFAULT_UNIVERSE = [
    "AAPL", "NVDA", "TSLA", "MSFT", "META", "AMZN", "AMD", "GOOGL",
    "PLTR", "NFLX", "AVGO", "MU", "COIN", "SMCI", "SPY", "QQQ",
]

DEFAULT_CONFIG: Dict[str, Any] = {
    "mode": "shadow",
    "universe": list(DEFAULT_UNIVERSE),
    "interval_seconds": 60,
    "min_score": 75,
    "min_rvol": 1.5,
    "max_spread_pct": 0.35,
    "min_price": 5.0,
    "max_signals_per_day": 3,
    "risk_pct": 0.5,
}

# Symbols may never exceed this — one pasted watchlist must not blow the
# broker's quote budget. Mirrored by the app's parseUniverse().
UNIVERSE_LIMIT = 40
# A watchlist may be typed with commas, spaces or semicolons; the app splits
# on all three, so the bot must too or "AAPL NVDA TSLA" silently collapses.
_SYMBOL_SPLIT = re.compile(r"[\s,;]+")
_SYMBOL_RE = re.compile(r"^[A-Z]{1,6}$")

# The scanner is UPSTREAM of the bot's live entry filter: everything it
# dispatches is re-judged by _passes_entry_filters(). A scanner floor looser
# than that filter can only ever produce candidates that are guaranteed to be
# rejected server-side — noise in the log, no trade, and a user staring at a
# threshold the bot silently overrides. main_bot injects its REAL (env-aware)
# gate here at wiring time; the defaults mirror main_bot's own defaults.
ENTRY_GATE_FLOORS: Dict[str, float] = {"min_score": 75.0, "min_rvol": 1.5}


def set_entry_gate_floors(min_score: float, min_rvol: float) -> Dict[str, float]:
    """Bind the scanner's configurable floors to the bot's live entry gate.
    Called once from main_bot so the two can never drift apart."""
    ENTRY_GATE_FLOORS["min_score"] = float(min_score)
    ENTRY_GATE_FLOORS["min_rvol"] = float(min_rvol)
    for key in ("min_score", "min_rvol"):
        if DEFAULT_CONFIG[key] < ENTRY_GATE_FLOORS[key]:
            DEFAULT_CONFIG[key] = type(DEFAULT_CONFIG[key])(ENTRY_GATE_FLOORS[key])
    return dict(ENTRY_GATE_FLOORS)


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


# ---------------------------------------------------------------------------
# Pure helpers (no I/O — unit-testable)
# ---------------------------------------------------------------------------
def parse_universe(raw: Any) -> List[str]:
    """Free-text or list watchlist → clean symbols.

    Byte-for-byte the same rules as the app's parseUniverse(): split on
    whitespace/comma/semicolon, uppercase, ASCII A–Z only, 1–6 chars,
    de-duplicated, capped at UNIVERSE_LIMIT."""
    tokens: List[str] = []
    if isinstance(raw, str):
        tokens = _SYMBOL_SPLIT.split(raw)
    elif isinstance(raw, list):
        for item in raw:
            tokens.extend(_SYMBOL_SPLIT.split(str(item or "")))
    out: List[str] = []
    for token in tokens:
        sym = token.strip().upper()
        if not sym or not _SYMBOL_RE.match(sym) or sym in out:
            continue
        out.append(sym)
    return out[:UNIVERSE_LIMIT]


def normalize_config(raw: Any) -> Dict[str, Any]:
    """Coerce a stored/posted config blob into a complete, sane config.

    `min_score` / `min_rvol` can be tightened but never loosened past the
    bot's live entry gate — see ENTRY_GATE_FLOORS."""
    cfg = dict(DEFAULT_CONFIG)
    if isinstance(raw, dict):
        mode = str(raw.get("mode") or "").lower().strip()
        if mode in MODES:
            cfg["mode"] = mode
        if raw.get("universe") is not None:
            cleaned = parse_universe(raw["universe"])
            if cleaned:
                cfg["universe"] = cleaned
        for key, lo, hi, cast in (
            ("interval_seconds", 20, 600, int),
            ("min_score", ENTRY_GATE_FLOORS["min_score"], 100, int),
            ("min_rvol", ENTRY_GATE_FLOORS["min_rvol"], 10.0, float),
            ("max_spread_pct", 0.01, 5.0, float),
            ("min_price", 0.0, 10_000.0, float),
            ("max_signals_per_day", 0, 20, int),
            ("risk_pct", 0.05, 5.0, float),
        ):
            if raw.get(key) is None:
                continue
            try:
                cfg[key] = cast(max(lo, min(hi, cast(raw[key]))))
            except (TypeError, ValueError):
                continue
    # A stored config written before a gate change must still be re-floored.
    cfg["min_score"] = int(max(cfg["min_score"], ENTRY_GATE_FLOORS["min_score"]))
    cfg["min_rvol"] = float(max(cfg["min_rvol"], ENTRY_GATE_FLOORS["min_rvol"]))
    return cfg


def session_progress(now_et: datetime) -> float:
    """Fraction of the 9:30–16:00 ET regular session elapsed, clamped to
    [0.05, 1.0]. The floor stops a 9:31 reading from dividing by ~0 and
    manufacturing an absurd RVOL."""
    open_m = 9 * 60 + 30
    close_m = 16 * 60
    minutes = now_et.hour * 60 + now_et.minute + now_et.second / 60.0
    frac = (minutes - open_m) / float(close_m - open_m)
    return max(0.05, min(1.0, frac))


def compute_rvol(
    total_volume: Optional[float],
    avg_daily_volume: Optional[float],
    progress: float,
) -> Optional[float]:
    """Relative volume from BROKER numbers only.

    total_volume  — shares traded so far today (E*TRADE `totalVolume`)
    avg_daily_volume — 10-day average daily volume (E*TRADE `volume10Day`)
    progress      — fraction of the session elapsed (see session_progress)

    Returns None when either input is missing/zero: an unmeasurable RVOL must
    stay unmeasured rather than be guessed."""
    try:
        tv = float(total_volume or 0)
        adv = float(avg_daily_volume or 0)
    except (TypeError, ValueError):
        return None
    if tv <= 0 or adv <= 0 or progress <= 0:
        return None
    expected = adv * progress
    if expected <= 0:
        return None
    return round(tv / expected, 2)


def spread_pct(bid: Optional[float], ask: Optional[float]) -> Optional[float]:
    """Bid/ask spread as a percent of the mid price (None when unquotable)."""
    try:
        b = float(bid or 0)
        a = float(ask or 0)
    except (TypeError, ValueError):
        return None
    if b <= 0 or a <= 0 or a < b:
        return None
    mid = (a + b) / 2.0
    if mid <= 0:
        return None
    return round((a - b) / mid * 100.0, 3)


# Quote statuses that represent a live print. Anything else (DELAYED, CLOSING,
# an empty string) is treated as not-real-time — the safe direction.
REALTIME_QUOTE_STATUSES = {"REALTIME", "EH_REALTIME"}


def parse_quotes(resp: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Flatten an E*TRADE QuoteResponse into measured per-symbol readings.
    Only fields the broker actually returned are populated — absent numbers
    stay None so downstream logic can refuse to guess."""
    out: List[Dict[str, Any]] = []
    data = ((resp or {}).get("QuoteResponse") or {}).get("QuoteData")
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list):
        return out

    def num(node: Dict[str, Any], key: str) -> Optional[float]:
        val = node.get(key)
        if val is None or val == "":
            return None
        try:
            f = float(val)
        except (TypeError, ValueError):
            return None
        return f if math.isfinite(f) else None

    for entry in data:
        if not isinstance(entry, dict):
            continue
        all_q = entry.get("All") or {}
        product = entry.get("Product") or {}
        symbol = str(product.get("symbol") or entry.get("symbol") or "").upper().strip()
        if not symbol:
            continue
        last = num(all_q, "lastTrade")
        if last is None or last <= 0:
            continue
        # E*TRADE stamps every quote REALTIME / DELAYED / CLOSING. Without the
        # real-time market data agreement the broker serves 15-MINUTE-OLD
        # prints, and the scanner was reading `lastTrade` from them as though
        # they were live: a "breakout above the prior high" measured on a
        # quarter-hour-old tape is a breakout that already happened, and the
        # entry/stop derived from it were quoted against a market that had
        # moved on. Carried here so scan_once can refuse to DISPATCH on them.
        status = str(entry.get("quoteStatus") or "").upper().strip()
        out.append({
            "symbol": symbol,
            "last": last,
            "quote_status": status,
            "realtime": status in REALTIME_QUOTE_STATUSES,
            "bid": num(all_q, "bid"),
            "ask": num(all_q, "ask"),
            "open": num(all_q, "open"),
            "high": num(all_q, "high"),
            "low": num(all_q, "low"),
            "previous_close": num(all_q, "previousClose"),
            "total_volume": num(all_q, "totalVolume"),
            "avg_daily_volume": num(all_q, "volume10Day"),
        })
    return out


def sampled_vwap(series: List[Dict[str, Any]]) -> Optional[float]:
    """Volume-weighted average price built from the scanner's OWN samples,
    weighting each observation by the volume traded since the previous one.
    Returns None until at least two samples with a positive volume delta."""
    num = 0.0
    den = 0.0
    prev_vol: Optional[float] = None
    for sample in series:
        price = sample.get("last")
        vol = sample.get("total_volume")
        if price is None:
            continue
        if vol is None:
            prev_vol = None
            continue
        if prev_vol is not None and vol > prev_vol:
            delta = vol - prev_vol
            num += float(price) * delta
            den += delta
        prev_vol = float(vol)
    if den <= 0:
        return None
    return round(num / den, 4)


def pct_change(now: Optional[float], base: Optional[float]) -> Optional[float]:
    try:
        n = float(now or 0)
        b = float(base or 0)
    except (TypeError, ValueError):
        return None
    if b <= 0:
        return None
    return round((n - b) / b * 100.0, 3)


def detect_setup_side(
    series: List[Dict[str, Any]],
    quote: Dict[str, Any],
    vwap: Optional[float],
) -> Optional[Tuple[str, str]]:
    """Name the (setup, side) a reading satisfies, or None.

    Setup names deliberately match the bot's ALLOWED_SETUPS vocabulary so a
    scanner signal is judged by the exact same allowlist as an app signal.

    TWO-SIDED: each long setup has an exact short mirror ('vwap rejection',
    'breakdown', 'momentum fade'). The long-only scanner went structurally
    SILENT in a down tape — the sessions with the most opportunity produced
    zero scanner flow while the app alone carried the short side. Short
    exposure is expressed downstream as a LONG PUT (capped risk), never a
    short sale.

    `series` holds the observations BEFORE this reading (the caller appends the
    current quote only after evaluating it), so every element is prior history.
    Dropping the last one — as `series[:-1]` did — hid the most recent
    observation from `prior_high`, letting a price BELOW the real sampled high
    be called a breakout, and made `prev_price` two observations stale so the
    VWAP-reclaim test compared against the wrong bar."""
    if len(series) < MIN_SAMPLES:
        return None
    last = quote.get("last")
    if last is None:
        return None
    prior = [s.get("last") for s in series if s.get("last") is not None]
    if len(prior) < MIN_SAMPLES:
        return None
    prior_high = max(prior)
    prior_low = min(prior)
    prev_price = prior[-1]
    open_px = quote.get("open")
    prev_close = quote.get("previous_close")
    change_open = pct_change(last, open_px)

    # VWAP reclaim: was below the sampled VWAP on the previous observation and
    # is now above it, with the session still positive on the day.
    # VWAP rejection is the mirror: lost the VWAP with the session negative.
    if vwap is not None and prev_price is not None:
        if prev_price < vwap <= float(last) and (change_open or 0) > 0:
            return ("vwap reclaim", "long")
        if prev_price > vwap >= float(last) and (change_open or 0) < 0:
            return ("vwap rejection", "short")

    # Breakout: new session high across the sampled window AND above the prior
    # close by a real margin. Breakdown is the mirror.
    if float(last) > prior_high and (pct_change(last, prev_close) or 0) >= 0.5:
        return ("breakout", "long")
    if float(last) < prior_low and (pct_change(last, prev_close) or 0) <= -0.5:
        return ("breakdown", "short")

    # Momentum: sustained push off the open with price leading the VWAP.
    if change_open is not None and change_open >= 0.3 and (vwap is None or float(last) >= vwap):
        if float(last) >= prior_high:
            return ("momentum", "long")
    if change_open is not None and change_open <= -0.3 and (vwap is None or float(last) <= vwap):
        if float(last) <= prior_low:
            return ("momentum fade", "short")
    return None


def detect_setup(
    series: List[Dict[str, Any]],
    quote: Dict[str, Any],
    vwap: Optional[float],
) -> Optional[str]:
    """Legacy long-only view of `detect_setup_side` — kept so callers written
    before the two-sided scanner keep their exact behavior."""
    hit = detect_setup_side(series, quote, vwap)
    return hit[0] if hit is not None and hit[1] == "long" else None


# Score anatomy. A score is BASE plus a weighted share of SPAN, so the worst
# readable candidate scores SCORE_BASE and a perfect one scores 100. Kept as
# named constants because the app renders the same arithmetic back to the user
# (see expo/services/botScanner.ts — asserted equal by scannerParity.test.ts).
SCORE_BASE = 55
SCORE_SPAN = 45
# weight, and the measured reading at which the factor is fully earned.
SCORE_WEIGHTS: Dict[str, float] = {"rvol": 0.40, "momentum": 0.25, "vwap": 0.20, "liquidity": 0.15}
# rvol is credited from 1.0x (market-average) up to FULL_RVOL.
FULL_RVOL = 3.0
FULL_MOVE_PCT = 1.5
FULL_VWAP_PCT = 0.5


def score_factors(
    rvol: Optional[float],
    change_from_open_pct: Optional[float],
    vwap_distance_pct: Optional[float],
    spread: Optional[float],
    max_spread_pct: float,
) -> List[Dict[str, Any]]:
    """Per-factor attribution of a candidate's score.

    Returns one record per factor with the MEASURED reading, the reading that
    would fully earn it, how much of it is earned (0–1), and the points that
    contributes. Summing `points` and adding SCORE_BASE reproduces the score
    exactly, so a user can see which single measurement is holding a candidate
    below the gate instead of staring at an unexplained number.

    A missing measurement earns 0 — never an assumed midpoint."""
    def clamp01(x: float) -> float:
        return max(0.0, min(1.0, x))

    ceiling = max(max_spread_pct, 0.01)
    readings: List[Tuple[str, str, Optional[float], float, str, float]] = [
        ("rvol", "Relative volume", rvol, FULL_RVOL,
         "x", clamp01(((rvol or 0.0) - 1.0) / (FULL_RVOL - 1.0))),
        # Long-side only: credit UPSIDE movement. `abs()` here paid full
        # momentum points to a stock down 1.5% off the open, so a gap-up that
        # faded hard scored like a leader.
        ("momentum", "Move off the open", change_from_open_pct, FULL_MOVE_PCT,
         "%", clamp01((change_from_open_pct or 0.0) / FULL_MOVE_PCT)),
        ("vwap", "Lead over VWAP", vwap_distance_pct, FULL_VWAP_PCT,
         "%", clamp01((vwap_distance_pct or 0.0) / FULL_VWAP_PCT)),
        ("liquidity", "Spread", spread, ceiling,
         "%", clamp01(1.0 - (spread if spread is not None else ceiling) / ceiling)),
    ]
    out: List[Dict[str, Any]] = []
    for key, label, value, target, unit, fill in readings:
        weight = SCORE_WEIGHTS[key]
        out.append({
            "key": key,
            "label": label,
            "value": None if value is None else round(float(value), 3),
            "target": round(float(target), 3),
            "unit": unit,
            "fill": round(fill, 4),
            "points": round(SCORE_SPAN * weight * fill, 2),
            "max_points": round(SCORE_SPAN * weight, 2),
            "measured": value is not None,
        })
    return out


def score_candidate(
    rvol: Optional[float],
    change_from_open_pct: Optional[float],
    vwap_distance_pct: Optional[float],
    spread: Optional[float],
    max_spread_pct: float,
) -> int:
    """Composite 55–100 score from MEASURED factors only.

    Each factor is normalized to 0–1 and blended by weight; the result is
    mapped onto 55..100. A candidate strong on every measured dimension lands
    in the low 90s — nothing is padded to clear a threshold, and a missing
    factor contributes 0 rather than an assumed value."""
    factors = score_factors(rvol, change_from_open_pct, vwap_distance_pct, spread, max_spread_pct)
    blended = sum(SCORE_WEIGHTS[f["key"]] * f["fill"] for f in factors)
    return int(round(SCORE_BASE + SCORE_SPAN * blended))


def risk_levels(entry: float, series: List[Dict[str, Any]], side: str = "long") -> Tuple[float, float]:
    """(stop, target) from the observed intraday range.

    Long: stop = entry − max(observed swing, 0.4% floor); target = 2R.
    Short: the exact mirror — stop ABOVE entry, target below. The swing is
    the scanner's own sampled high−low, so the stop reflects real volatility
    rather than a fixed guess."""
    prices = [float(s["last"]) for s in series if s.get("last") is not None]
    swing = (max(prices) - min(prices)) if len(prices) >= 2 else 0.0
    distance = max(swing, entry * 0.004)
    if side == "short":
        stop = round(entry + distance, 2)
        target = round(max(0.01, entry - 2 * distance), 2)
        return stop, target
    stop = round(max(0.01, entry - distance), 2)
    target = round(entry + 2 * (entry - stop), 2)
    return stop, target


def next_friday_expiry(now_et: datetime) -> str:
    """Nearest Friday (today when it IS Friday) as YYYY-MM-DD. The bot snaps
    every expiry to a contract that actually exists on the chain, so market
    holidays self-correct server-side."""
    days_ahead = (4 - now_et.weekday()) % 7
    return (now_et.date() + timedelta(days=days_ahead)).isoformat()


def build_signal(quote: Dict[str, Any], candidate: Dict[str, Any], mode: str) -> Dict[str, Any]:
    """Webhook-shaped payload for a qualifying candidate.

    `position_size_shares` is deliberately omitted — the bot sizes equity
    entries from live account equity, the configured risk percent and the stop
    distance, which is strictly safer than a scanner-side guess.

    SHORT candidates are expressed as a LONG PUT (one contract): the bot
    refuses bare short-equity entries (a naked short at the broker), and a
    bought put caps the worst case at the premium paid. Strike and expiry are
    hints only — the bot snaps both to a contract that actually exists and
    prices the entry from the REAL bid/ask."""
    side = str(candidate.get("side") or "long")
    payload: Dict[str, Any] = {
        "ticker": candidate["ticker"],
        "action": "BUY" if side == "long" else "SELL",
        "mode": mode,
        "instrument": "stock",
        "entry": candidate["entry"],
        "stop": candidate["stop"],
        "target": candidate["target"],
        "score": candidate["score"],
        "rvol": candidate["rvol"],
        "setup": candidate["setup"],
        "source": "bot_scanner",
        "timestamp": candidate["ts"],
    }
    if side == "short":
        payload["instrument"] = "option"
        payload["option_right"] = "PUT"
        payload["option_contracts"] = 1
        payload["strike_hint"] = round(float(candidate["entry"]))
        payload["expiration_hint"] = candidate.get("expiry") or next_friday_expiry(_utcnow())
    return payload


def evaluate_quote(
    quote: Dict[str, Any],
    series: List[Dict[str, Any]],
    cfg: Dict[str, Any],
    progress: float,
) -> Dict[str, Any]:
    """Turn one broker reading + its rolling series into a scored candidate.

    Always returns a record (so /scanner/status can show WHY a ticker didn't
    qualify); `qualifies` is only true when every measured requirement is met."""
    last = float(quote["last"])
    rvol = compute_rvol(quote.get("total_volume"), quote.get("avg_daily_volume"), progress)
    spread = spread_pct(quote.get("bid"), quote.get("ask"))
    vwap = sampled_vwap(series)
    change_open = pct_change(last, quote.get("open"))
    vwap_dist = pct_change(last, vwap) if vwap else None
    hit = detect_setup_side(series, quote, vwap)
    setup = hit[0] if hit is not None else None
    side = hit[1] if hit is not None else "long"
    # Side-adjusted readings: a short earns momentum/VWAP credit from movement
    # in ITS direction (down, price trailing VWAP). The factor arithmetic
    # itself is unchanged — the app renders the same math.
    momo_reading = change_open if side == "long" else (None if change_open is None else -change_open)
    vwap_reading = vwap_dist if side == "long" else (None if vwap_dist is None else -vwap_dist)
    factors = score_factors(rvol, momo_reading, vwap_reading, spread, float(cfg["max_spread_pct"]))
    score = score_candidate(rvol, momo_reading, vwap_reading, spread, float(cfg["max_spread_pct"]))

    reasons: List[str] = []
    if len(series) < MIN_SAMPLES:
        reasons.append(f"warming up ({len(series)}/{MIN_SAMPLES} samples)")
    if rvol is None:
        reasons.append("rvol not measurable (broker volume fields missing)")
    elif rvol < float(cfg["min_rvol"]):
        reasons.append(f"rvol {rvol} < {cfg['min_rvol']}")
    if last < float(cfg["min_price"]):
        reasons.append(f"price {last} < {cfg['min_price']}")
    if spread is None:
        reasons.append("no two-sided quote")
    elif spread > float(cfg["max_spread_pct"]):
        reasons.append(f"spread {spread}% > {cfg['max_spread_pct']}%")
    if setup is None:
        reasons.append("no setup")
    if score < int(cfg["min_score"]):
        reasons.append(f"score {score} < {cfg['min_score']}")

    stop, target = risk_levels(last, series + [quote], side)
    return {
        "ticker": quote["symbol"],
        "side": side,
        "action": "BUY" if side == "long" else "SELL",
        "entry": round(last, 2),
        "stop": stop,
        "target": target,
        "rvol": rvol,
        "spread_pct": spread,
        "change_from_open_pct": change_open,
        "vwap": vwap,
        "setup": setup,
        "score": score,
        "score_base": SCORE_BASE,
        "score_factors": factors,
        "points_to_gate": max(0, int(cfg["min_score"]) - score),
        "samples": len(series),
        "qualifies": not reasons,
        "blocked_by": reasons,
        "ts": _utcnow().isoformat(),
    }


# ---------------------------------------------------------------------------
# Stateful engine
# ---------------------------------------------------------------------------
class Scanner:
    """Perception loop. Broker + dispatch access is injected."""

    def __init__(
        self,
        state: StateStore,
        fetch_quotes: Callable[[List[str]], Awaitable[Dict[str, Any]]],
        dispatch: Callable[[Dict[str, Any]], Awaitable[Dict[str, Any]]],
        is_market_open: Callable[[], bool],
        has_tokens: Callable[[], bool],
        now_et: Callable[[], datetime],
        alert: Optional[Callable[..., Awaitable[None]]] = None,
        stop_flag: Callable[[], bool] = lambda: False,
    ) -> None:
        self.state = state
        self.fetch_quotes = fetch_quotes
        self.dispatch = dispatch
        self.is_market_open = is_market_open
        self.has_tokens = has_tokens
        self.now_et = now_et
        self.alert = alert
        self.stop_flag = stop_flag
        self._config: Dict[str, Any] = dict(DEFAULT_CONFIG)

    # ---- config -----------------------------------------------------------
    async def load_config(self) -> Dict[str, Any]:
        raw = await self.state.get(CONFIG_KEY)
        if raw:
            try:
                self._config = normalize_config(json.loads(raw))
            except (json.JSONDecodeError, TypeError):
                logger.warning("scanner config unreadable — using defaults")
                self._config = dict(DEFAULT_CONFIG)
        return dict(self._config)

    async def set_config(self, patch: Dict[str, Any]) -> Dict[str, Any]:
        merged = {**self._config, **(patch or {})}
        self._config = normalize_config(merged)
        await self.state.set(CONFIG_KEY, json.dumps(self._config))
        logger.info(
            f"🔭 Scanner config updated — mode={self._config['mode']} "
            f"universe={len(self._config['universe'])} symbols "
            f"every {self._config['interval_seconds']}s, min_score={self._config['min_score']}"
        )
        return dict(self._config)

    @property
    def config(self) -> Dict[str, Any]:
        return dict(self._config)

    # ---- rolling series ---------------------------------------------------
    async def _series(self, ticker: str) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        try:
            raw_items = await self.state.list_range(SERIES_KEY_FMT.format(ticker), MAX_SAMPLES)
        except Exception as e:
            logger.warning(f"series read failed for {ticker}: {e}")
            return out
        for raw in raw_items:
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError:
                continue
            if isinstance(parsed, dict):
                out.append(parsed)
        # list_range returns newest-first; the analytics want chronological.
        out.reverse()
        return out

    async def _append_sample(self, quote: Dict[str, Any]) -> None:
        sample = {
            "ts": _utcnow().isoformat(),
            "last": quote.get("last"),
            "total_volume": quote.get("total_volume"),
        }
        try:
            await self.state.list_push_capped(
                SERIES_KEY_FMT.format(quote["symbol"]), json.dumps(sample), max_len=MAX_SAMPLES,
            )
        except Exception as e:
            logger.warning(f"series write failed for {quote.get('symbol')}: {e}")

    # ---- emission budget --------------------------------------------------
    def _emit_key(self) -> str:
        return EMIT_KEY_FMT.format(self.now_et().date().isoformat())

    async def emits_today(self) -> int:
        try:
            raw = await self.state.get(self._emit_key())
            return int(raw or 0)
        except (TypeError, ValueError):
            return 0

    async def _note_emit(self, used: int) -> int:
        """Consume one unit of the daily signal budget.

        `used` is the caller's running count. A failed increment must still
        consume the slot: returning 0 here reset the caller's counter, so the
        `used >= budget` check could never fire again and the scanner would
        dispatch EVERY qualifying candidate — real live orders, unbounded — for
        the rest of the pass. Budget accounting fails CLOSED.
        """
        try:
            return int(await self.state.incr(self._emit_key(), ex=36 * 3600))
        except Exception as e:
            logger.warning(f"emit counter failed ({e}) — counting the signal locally to preserve the daily budget")
            return used + 1

    # ---- one pass ---------------------------------------------------------
    async def scan_once(self) -> Dict[str, Any]:
        cfg = self._config
        universe: List[str] = list(cfg["universe"])
        quotes: List[Dict[str, Any]] = []
        errors: List[str] = []
        for i in range(0, len(universe), QUOTE_CHUNK):
            chunk = universe[i:i + QUOTE_CHUNK]
            try:
                quotes.extend(parse_quotes(await self.fetch_quotes(chunk)))
            except Exception as e:
                errors.append(f"{chunk[0]}…: {str(e)[:120]}")
                logger.warning(f"scanner quote fetch failed for {len(chunk)} symbols: {e}")

        progress = session_progress(self.now_et())
        candidates: List[Dict[str, Any]] = []
        for quote in quotes:
            series = await self._series(quote["symbol"])
            candidates.append(evaluate_quote(quote, series, cfg, progress))
            await self._append_sample(quote)

        candidates.sort(key=lambda c: (c["qualifies"], c["score"]), reverse=True)
        emitted: List[Dict[str, Any]] = []
        budget = int(cfg["max_signals_per_day"])
        try:
            used = await self.emits_today()
        except Exception as e:
            # Unknown usage must not read as "zero used" — that would hand the
            # scanner a fresh budget on every storage hiccup. Assume spent.
            logger.warning(f"emit counter unreadable ({e}) — treating the daily budget as spent this pass")
            used = budget

        for cand in candidates:
            if not cand["qualifies"]:
                continue
            if cfg["mode"] != "live":
                cand["dispatch"] = "shadow (not sent)"
                continue
            if used >= budget:
                cand["dispatch"] = f"daily scanner budget reached ({budget})"
                continue
            quote = next((q for q in quotes if q["symbol"] == cand["ticker"]), None)
            if quote is None:
                continue
            # REAL-TIME GATE. The scanner may still analyse and report on a
            # delayed quote — that context is useful — but it must never turn
            # one into a real order. The entry, stop and target were all priced
            # off `last`; if that print is 15 minutes old every one of them is
            # aimed at a market that no longer exists.
            if not quote.get("realtime"):
                status = quote.get("quote_status") or "unknown"
                cand["dispatch"] = f"blocked: broker quote is {status}, not real-time"
                logger.warning(
                    f"🔭 Scanner refused to dispatch {cand['ticker']} — E*TRADE quote status "
                    f"'{status}' is not real-time (accept the market data agreement to enable live scanning)"
                )
                continue
            payload = build_signal(
                quote,
                {**cand, "expiry": next_friday_expiry(self.now_et())},
                "live",
            )
            try:
                result = await self.dispatch(payload)
                verdict = str((result or {}).get("status") or "unknown")
            except Exception as e:
                verdict = f"error: {str(e)[:120]}"
                logger.error(f"scanner dispatch failed for {cand['ticker']}: {e}")
            cand["dispatch"] = verdict
            used = await self._note_emit(used)
            emitted.append({"ticker": cand["ticker"], "setup": cand["setup"], "side": cand.get("side") or "long",
                            "score": cand["score"], "rvol": cand["rvol"], "verdict": verdict})
            logger.info(
                f"🔭 Scanner signal → {cand['ticker']} {cand.get('side') or 'long'} {cand['setup']} score={cand['score']} "
                f"rvol={cand['rvol']} entry={cand['entry']} stop={cand['stop']} → {verdict}"
            )
            if self.alert is not None:
                try:
                    await self.alert(
                        "info", "scanner_signal",
                        f"Scanner dispatched {cand['ticker']} {cand['setup']} "
                        f"(score {cand['score']}, rvol {cand['rvol']}) → {verdict}",
                        dedupe_key=f"scanner:{cand['ticker']}",
                    )
                except Exception:
                    logger.debug("scanner alert failed", exc_info=True)

        report = {
            "ts": _utcnow().isoformat(),
            "mode": cfg["mode"],
            "universe_size": len(universe),
            "quotes_read": len(quotes),
            "session_progress": round(progress, 3),
            "qualifying": sum(1 for c in candidates if c["qualifies"]),
            "emitted": emitted,
            "emits_today": used,
            "max_signals_per_day": budget,
            "errors": errors[:5],
            "candidates": candidates[:12],
        }
        try:
            await self.state.set(REPORT_KEY, json.dumps(report), ex=36 * 3600)
        except Exception as e:
            logger.warning(f"scanner report write failed: {e}")
        return report

    async def last_report(self) -> Optional[Dict[str, Any]]:
        raw = await self.state.get(REPORT_KEY)
        if not raw:
            return None
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError:
            return None
        return parsed if isinstance(parsed, dict) else None

    async def status(self) -> Dict[str, Any]:
        return {
            "config": self.config,
            "entry_gate": dict(ENTRY_GATE_FLOORS),
            "market_open": self.is_market_open(),
            "broker_linked": self.has_tokens(),
            "emits_today": await self.emits_today(),
            "last_scan": await self.last_report(),
        }

    # ---- loop -------------------------------------------------------------
    async def run(self) -> None:
        await self.load_config()
        logger.info(
            f"🔭 Scanner engine started — mode={self._config['mode']}, "
            f"{len(self._config['universe'])} symbols every {self._config['interval_seconds']}s"
        )
        while not self.stop_flag():
            cfg = await self.load_config()  # picks up live config changes
            delay = int(cfg["interval_seconds"])
            try:
                if cfg["mode"] == "off":
                    delay = 60
                elif not self.has_tokens():
                    delay = 120
                elif not self.is_market_open():
                    delay = 300
                else:
                    lock = self.state.lock(SCANNER_LOCK, ttl_ms=max(30_000, delay * 2000))
                    if await lock.try_acquire():
                        try:
                            await self.scan_once()
                        finally:
                            await lock.release()
                    # else: another instance owns this pass.
            except Exception as e:
                logger.error(f"scanner loop error: {e}")
                if self.alert is not None:
                    try:
                        await self.alert("error", "scanner_loop_error", str(e)[:200],
                                         dedupe_key="scanner_loop")
                    except Exception:
                        logger.debug("scanner loop alert failed", exc_info=True)
            await asyncio.sleep(max(5, delay))

''')

# =========================================================================
# main_bot.py source follows (its `from x import y` calls resolve to the
# embedded modules registered in sys.modules above).
# =========================================================================
"""
E*TRADE Trading Bot — corrected drop-in
=======================================

This is the production webhook bot the Rork app dispatches to. It is a corrected
version of the earlier `main_bot.py` that was failing live OPTION orders with
E*TRADE "Missing required parameters".

ROOT CAUSE OF THE OLD FAILURE
-----------------------------
`pyetrade.ETradeOrder.place_option_order(**kwargs)` does NOT accept a pre-built
nested `order={...}` payload. Internally it does:

    place_option_order(**kwargs)      # sets securityType="OPTN"
      -> place_equity_order(**kwargs) # calls check_order(**kwargs)
        -> build_order_payload(...)   # builds Order/Instrument/Product ITSELF
                                      # from FLAT kwargs and parses expiryDate
                                      # (a "YYYY-MM-DD" string) via dateutil.

The old code passed `order=order_payload` (a nested dict). pyetrade ignored that
unknown `order=` kwarg, `check_order` found none of the required flat params
(symbol, orderAction, priceType, quantity, callPut, strikePrice, expiryDate) and
raised "Missing required parameters".

THE FIX
-------
Pass FLAT keyword arguments and let pyetrade build the payload + auto-preview.
`expiryDate` is passed as a plain "YYYY-MM-DD" string (dateutil handles it).

V2.9.0 (merged trailing-stop drop-in)
-------------------------------------
Merges the user-deployed "2.8.0-trailing-stop" variant back into this corrected
bot. Key decisions:

- ENTRY orders (BUY_OPEN) are ALWAYS plain LIMIT (from `option_limit_price`)
  or MARKET. Never STOP/TRAILING_STOP on an entry — a stop price type turns
  the entry into a trigger order that may never fill, and E*TRADE rejects
  trailing stops on option opens anyway.
- EXIT orders (SELL_CLOSE) default to MARKET so protective exits always fill.
  The app's Auto-Exit engine tracks the ratcheting trailing stop client-side
  and dispatches the SELL_CLOSE the moment it's breached. An optional resting
  broker-side STOP is supported when the payload sends `broker_stop: true`
  plus a `stop_price` (or `trail_stop`).
- Quantity comes from `option_contracts` (the field the app actually sends),
  with `contracts` and `quantity` as fallbacks.
- Tokens persist to the DB (`preload_tokens` on startup) so restarts don't
  unlink the account, and a keepalive worker proactively renews the E*TRADE
  access token every ~50 minutes so it never goes idle-inactive (E*TRADE
  deactivates tokens after ~2h idle; they hard-expire at midnight ET).
- The webhook secret is accepted from the JSON body `secret` field OR the
  `X-Rork-Secret` header (the app sends both).
- Response statuses stay in the vocabulary the app's parser understands:
  `queued`, `processed_directly` (with nested `result`), `skipped`, `error`.

V5.0.0 (redis-async foundation)
-------------------------------
• ALL trading state (positions, stop guards, daily counters, kill switch,
  idempotency keys, cooldowns) now lives in Redis via state_store.py — the
  old STATE_FILE + in-memory dicts are migrated once at startup and retired.
  Multi-worker deployments are safe; Railway/Render cold starts lose nothing.
• Critical sections (order placement, close, reconciliation, stop guards) run
  under Redis distributed locks (SET NX PX + token + Lua release).
• Order placement moved to raw async JSON payloads against E*TRADE's Order
  API (httpx + OAuth1, etrade_async.py) with an atomic Entry+Stop OTOCO
  best-effort and automatic fallback to pyetrade. pyetrade remains for simple
  reads (quotes, accounts, order listing) wrapped in asyncio.to_thread.
• A background reconciliation engine (reconciliation.py) polls broker orders
  + positions every RECONCILE_INTERVAL_SECONDS under the reconcile lock and
  auto-heals Redis state (fill sync, ghost positions, orphaned stops,
  unprotected positions → guard re-arm). Reconciled Redis state is the single
  source of truth for the stop guard and close logic.
• Option positions now get the same broker-resting protection as equities:
  an async option guard polls the entry fill and rests a SELL_CLOSE STOP on
  the same OCC contract, state persisted in Redis so it survives restarts.

V5.1.0 (hardening)
------------------
• STARTUP RECONCILIATION: a blocking broker→Redis reconciliation pass runs at
  boot — BEFORE the placement worker accepts any job — so cold starts begin
  from broker truth, not stale state.
• REAL-TIME ALERTING (alerts.py): kill switch, failed guards, unprotected
  positions, circuit-breaker trips and API problems are logged, kept in Redis
  (`alerts:recent`, GET /alerts) and pushed to ALERT_WEBHOOK_URL
  (Slack/Discord/generic JSON), with per-key dedupe to stop alert storms.
• IMMUTABLE TRADE LEDGER (trade_ledger.py): every order, position open/close,
  protective stop, guard result and safety event is appended to a
  hash-chained JSONL file. GET /ledger returns the tail and verifies the
  chain end-to-end.
• DISTRIBUTED CIRCUIT BREAKER: the consecutive-failure breaker moved to Redis
  (`breaker:*`), so ALL workers halt order placement together. It auto-resets
  via TTL after the cooldown and immediately on account relink; trips are
  alerted and ledgered.
• RECONCILIATION CADENCE: default every 5 minutes in-session (was 30s) and
  15 minutes off-hours — reconciliation is a periodic safety net; fill-time
  protection stays event-driven via the stop guards.

Run:
    pip install -r requirements.txt
    cp .env.example .env   # fill in keys + WEBHOOK_SECRET + REDIS_URL
    uvicorn main_bot:app --host 0.0.0.0 --port 8000
"""
