load_dotenv()

# ==================== CONFIG ====================
# Defaults match the deployed production bot: this bot exists to trade live.
# Set ETRADE_ENV=sandbox / LIVE_TRADING=false explicitly for testing.
ENV = os.getenv("ETRADE_ENV", "production").lower()
LIVE_TRADING = os.getenv("LIVE_TRADING", "true").lower() == "true"
WEBHOOK_SECRET = os.getenv("WEBHOOK_SECRET")
TARGET_ACCOUNT_ID = os.getenv("ETRADE_ACCOUNT_ID")
REDIS_URL = os.getenv("REDIS_URL")
DATABASE_URL = os.getenv("DATABASE_URL")
CONSUMER_KEY = os.getenv("ETRADE_CONSUMER_KEY")
CONSUMER_SECRET = os.getenv("ETRADE_CONSUMER_SECRET")

is_sandbox = ENV == "sandbox"

# Bump on every deploy-relevant change. Reported by /health and /etrade/auth/start
# so the app/user can verify the running container matches the repo code.
BOT_VERSION = "5.31.0-real-eyes"

# ---- Safety / parity config (mirrors etrade_bot_handler.py) ----
# Gate parity with the Rork app (app defaults: minScore 75 / trending 70).
# A stricter bot default silently rejects every score the app clears — the
# thresholds MUST match unless deliberately overridden via env.
MIN_SCORE = int(os.getenv("MIN_SCORE", "75"))
MIN_SCORE_TRENDING = int(os.getenv("MIN_SCORE_TRENDING", "70"))
MIN_RVOL = float(os.getenv("MIN_RVOL", "1.5"))
MIN_MTF = int(os.getenv("MIN_MTF", "3"))
ALLOWED_SETUPS = {
    s.strip().lower()
    for s in os.getenv(
        "ALLOWED_SETUPS",
        "ema cross + adx,ema cross,bull flag + adx,bull flag,bear flag + adx,"
        "bear flag,volume breakout,breakout,vwap reclaim,momentum,"
        # Short-side vocabulary — the scanner's bearish setups route through
        # long PUTs; without these names in the allowlist every scanner short
        # is dead on arrival at the entry filter.
        "breakdown,vwap rejection,momentum fade",
    ).split(",")
    if s.strip()
}
RISK_PER_TRADE_PCT = float(os.getenv("RISK_PER_TRADE_PCT", "0.5"))
DAILY_LOSS_LIMIT_PCT = float(os.getenv("DAILY_LOSS_LIMIT_PCT", "2.0"))
# A daily TRADE COUNT is not a risk control and no longer gates entries. It let
# 6 trades at 1% risk (6% of the account) through while refusing 20 at 0.25%
# (5%) — exactly backwards — and it killed the 7th good setup on a day the first
# six worked. Risk is measured in DOLLARS by `plan_risk_budget` below. The count
# is still tracked for reporting, and this ceiling survives only as a runaway
# circuit breaker (a loop placing hundreds of orders is a BUG, not a strategy).
RUNAWAY_TRADE_CIRCUIT_BREAKER = int(os.getenv("RUNAWAY_TRADE_CIRCUIT_BREAKER", "60"))
# ---- Execution cost ----
# The edge must survive the round trip. E*TRADE charges per contract each way,
# which is brutal on cheap options: $0.65 on a $0.30 contract is 2.2% each way
# before the spread. A gross edge smaller than the cost of capturing it is a fee
# generator that looks profitable on a chart.
COMMISSION_PER_CONTRACT = float(os.getenv("COMMISSION_PER_CONTRACT", "0.65"))
# Round-trip cost above this share of premium refuses the entry outright.
MAX_ROUND_TRIP_COST_PCT = float(os.getenv("MAX_ROUND_TRIP_COST_PCT", "12.0"))
MAX_CONCURRENT_POSITIONS = int(os.getenv("MAX_CONCURRENT_POSITIONS", "3"))
PORTFOLIO_HEAT_PCT = float(os.getenv("PORTFOLIO_HEAT_PCT", "6.0"))
TICKER_COOLDOWN_MINUTES = int(os.getenv("TICKER_COOLDOWN_MINUTES", "15"))
# ---- Daily profit objective ----
# The standing minimum daily profit target, in REAL dollars. Once the ledger
# proves it banked, the bot stops handing the day back: further entries are
# allowed only while a full loss would still finish at or above the target.
DAILY_PROFIT_TARGET_USD = float(os.getenv("DAILY_PROFIT_TARGET_USD", "500"))
# Cushion below which a made day takes NO further risk at all.
PROFIT_LOCK_MIN_CUSHION_USD = float(os.getenv("PROFIT_LOCK_MIN_CUSHION_USD", "50"))
# ---- Scale-out / runner ----
# Measured on real fills 2026-08-11/12: winners averaged +13.8% and losers
# −9.5%, with an average hold of 7 minutes and exits at 0m. Every winner was
# closed in full at the first exit, so no trade ever paid for the losers.
# Banking half at the capture the book actually achieves while letting the rest
# run is the only lever that raises the average winner.
# Echo E*TRADE's raw QuoteResponse alongside the normalized quotes on
# /etrade/quote. Diagnostic only — the app ignores the extra key.
DEBUG_QUOTES = os.getenv("DEBUG_QUOTES", "false").lower() == "true"
SCALE_OUT_ENABLED = os.getenv("SCALE_OUT_ENABLED", "true").lower() == "true"
SCALE_OUT_FIRST_TARGET_PCT = float(os.getenv("SCALE_OUT_FIRST_TARGET_PCT", "14.0"))
# A trailing exit may not fire inside this many seconds of the entry fill. The
# hard stop is NEVER delayed — this only stops quote noise from flattening a
# position that has barely started working.
MIN_HOLD_SECONDS_FOR_TRAIL = int(os.getenv("MIN_HOLD_SECONDS_FOR_TRAIL", "120"))
# Stop-guard: how long an entry may sit unfilled before it is cancelled, and
# how often the guard polls the broker for fill state.
ENTRY_FILL_TIMEOUT_MIN = int(os.getenv("ENTRY_FILL_TIMEOUT_MIN", "20"))
STOP_GUARD_POLL_SECONDS = int(os.getenv("STOP_GUARD_POLL_SECONDS", "10"))
# Legacy JSON state file — migrated into Redis once at startup, then retired.
STATE_FILE = Path(os.getenv("ETRADE_STATE_FILE", ".etrade_state.json"))

# ---- V5 architecture config ----
# Raw async Order API (httpx + OAuth1) is the primary placement path; pyetrade
# remains the fallback and handles simple reads (quotes, auth, renew).
USE_RAW_ORDER_API = os.getenv("USE_RAW_ORDER_API", "true").lower() == "true"
# Attempt an atomic Entry+Stop (OTOCO-style) submission. E*TRADE's public API
# doesn't officially support OCO/OTOCO, so a rejection falls back to entry +
# stop guard and is remembered for OTOCO_UNSUPPORTED_TTL to stop retrying.
ENABLE_RAW_OTOCO = os.getenv("ENABLE_RAW_OTOCO", "true").lower() == "true"
OTOCO_UNSUPPORTED_TTL = int(os.getenv("OTOCO_UNSUPPORTED_TTL", str(24 * 3600)))
# Background reconciliation engine cadence (seconds). Periodic safety net —
# NOT the fast path (stop guards are event-driven), so 5–10 min is the right
# cadence: broker-API friendly, still catches drift quickly. A blocking pass
# also runs at startup before any order is accepted.
RECONCILE_INTERVAL_SECONDS = int(os.getenv("RECONCILE_INTERVAL_SECONDS", "300"))
RECONCILE_OFFHOURS_SECONDS = int(os.getenv("RECONCILE_OFFHOURS_SECONDS", "900"))
RECONCILE_AUTO_HEAL = os.getenv("RECONCILE_AUTO_HEAL", "true").lower() == "true"
STARTUP_RECONCILE_TIMEOUT_SECONDS = int(os.getenv("STARTUP_RECONCILE_TIMEOUT_SECONDS", "90"))
# Server-side trailing-stop engine — ratchets the RESTING protective stop at
# the broker using the same tiered ladder as the app (breakeven at +0.75R,
# 0.75R/0.50R/0.35R tiers), so the trail keeps working with the app closed.
# A cancel/replace only fires when the improvement clears the min step
# (fraction of initial risk), keeping broker API usage sane.
TRAIL_ENGINE_ENABLED = os.getenv("TRAIL_ENGINE_ENABLED", "true").lower() == "true"
TRAIL_INTERVAL_SECONDS = int(os.getenv("TRAIL_INTERVAL_SECONDS", "30"))
TRAIL_MIN_STEP_FRAC = float(os.getenv("TRAIL_MIN_STEP_FRAC", "0.10"))
# ---- V5.10 server-side scanner ----
# The bot's own eyes: samples E*TRADE quotes for a universe on a fixed cadence,
# measures RVOL from broker volume, detects setups and dispatches qualifying
# candidates through the SAME gated path a webhook signal takes — so signals
# keep being found with the phone app closed. Runtime config (mode/universe/
# cadence/thresholds) lives in the state store and is changed via
# POST /scanner/config; these env vars only seed the very first boot.
# Default mode is "shadow": it measures and reports but dispatches nothing
# until the user explicitly promotes it to "live".
SCANNER_ENABLED = os.getenv("SCANNER_ENABLED", "true").lower() == "true"
SCANNER_MODE = os.getenv("SCANNER_MODE", "shadow").lower()
SCANNER_UNIVERSE = os.getenv("SCANNER_UNIVERSE", "")
SCANNER_INTERVAL_SECONDS = int(os.getenv("SCANNER_INTERVAL_SECONDS", "60"))
SCANNER_MAX_SIGNALS_PER_DAY = int(os.getenv("SCANNER_MAX_SIGNALS_PER_DAY", "3"))
# Real-time alerting: Slack/Discord/generic JSON webhook. Alerts always land
# in the log and GET /alerts even without a webhook.
ALERT_WEBHOOK_URL = os.getenv("ALERT_WEBHOOK_URL")
ALERT_DEDUPE_SECONDS = int(os.getenv("ALERT_DEDUPE_SECONDS", "300"))
# Immutable trade ledger — append-only, hash-chained JSONL (GET /ledger).
TRADE_LEDGER_FILE = Path(os.getenv("TRADE_LEDGER_FILE", "trade_ledger.jsonl"))
# Option stop protection: when the app doesn't send an explicit option stop
# premium, protect at this percent below the entry premium (0 disables).
OPTION_STOP_LOSS_PCT = float(os.getenv("OPTION_STOP_LOSS_PCT", "30"))
# Sanity band for an APP-SUPPLIED `option_stop_price` (delta-derived, premium
# basis — see expo/services/optionStop.ts). The app owns the policy; these are
# guardrails against a bad number, not a second policy. Tighter than MIN% of
# the fill is inside ordinary option noise and scratches instantly; wider than
# MAX% risks more than the blind percentage stop it replaces. Out-of-band
# values are CLAMPED and logged, so systematic drift is visible instead of
# silently resting a dangerous level.
OPTION_STOP_MIN_HAIRCUT_PCT = float(os.getenv("OPTION_STOP_MIN_HAIRCUT_PCT", "8"))
OPTION_STOP_MAX_HAIRCUT_PCT = float(os.getenv("OPTION_STOP_MAX_HAIRCUT_PCT", "45"))

# ---- V5.2 hardening ----
# Exponential backoff for ALL E*TRADE API calls. The same env vars configure
# the raw async client (etrade_async.py). Non-idempotent calls (order
# placement) are NEVER blind-retried — a failed place may still have landed.
# 429 throttles follow the exact schedule: 2s → 4s → 8s (base × 2^attempt,
# capped at max, no jitter). Other transient errors keep jitter.
ETRADE_RETRY_ATTEMPTS = max(1, int(os.getenv("ETRADE_RETRY_ATTEMPTS", "4")))
ETRADE_RETRY_BASE_SECONDS = float(os.getenv("ETRADE_RETRY_BASE_SECONDS", "2"))
ETRADE_RETRY_MAX_SECONDS = float(os.getenv("ETRADE_RETRY_MAX_SECONDS", "8"))
# STOP PLACEMENT TIMEOUT: a guarded entry must have its protective stop
# RESTING at the broker within this many seconds of entry placement. At the
# deadline with no stop: an unfilled entry is auto-cancelled; a filled entry
# is emergency-flattened at market (a fill cannot be cancelled). 0 disables.
STOP_PLACEMENT_TIMEOUT_SECONDS = int(os.getenv("STOP_PLACEMENT_TIMEOUT_SECONDS", "60"))
# CANCEL SETTLEMENT: E*TRADE answers a cancel with CANCEL_REQUESTED, which is a
# PENDING state — the contracts/shares stay allocated to the dying order for a
# beat afterwards. Sending the replacement stop or the closing order inside that
# window earns error 1037/3004 ("not enough available contracts … may already be
# allocated to an existing open order"). Wait for a TERMINAL status first.
CANCEL_SETTLE_TIMEOUT_SECONDS = float(os.getenv("CANCEL_SETTLE_TIMEOUT_SECONDS", "8"))
CANCEL_SETTLE_POLL_SECONDS = float(os.getenv("CANCEL_SETTLE_POLL_SECONDS", "0.6"))


def _utcnow() -> datetime:
    """Timezone-aware UTC now (datetime.utcnow() is deprecated in 3.12+)."""
    return datetime.now(timezone.utc)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("etrade-bot")

app = FastAPI(title="E*TRADE Trading Bot")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

# ==================== GLOBALS ====================
# Distributed state store (Redis-first; loud in-memory fallback for local dev).
# Replaced at startup by StateStore.create(REDIS_URL).
state: StateStore = StateStore(None)
engine = None
async_session = None
# Circuit breaker — DISTRIBUTED (Redis `breaker:*` keys) so every worker halts
# order placement together. Opens after MAX_CONSECUTIVE_FAILURES broker API
# failures within a rolling BREAKER_FAILURE_WINDOW_SECONDS; auto-resets via
# TTL after the cooldown, and immediately on account relink.
MAX_CONSECUTIVE_FAILURES = int(os.getenv("MAX_CONSECUTIVE_FAILURES", "5"))
CIRCUIT_BREAKER_COOLDOWN_SECONDS = int(os.getenv("CIRCUIT_BREAKER_COOLDOWN_SECONDS", str(10 * 60)))
BREAKER_FAILURE_WINDOW_SECONDS = int(os.getenv("BREAKER_FAILURE_WINDOW_SECONDS", "600"))
BREAKER_OPEN_KEY = "breaker:open"
BREAKER_FAILURES_KEY = "breaker:failures"
QUEUE_KEY = "etrade:placement_queue"
_worker_task = None
_worker_stop = False
# Outcome of the last daily-P&L-vs-ledger verification (surfaced via /status).
_last_pnl_repair: Optional[Dict[str, Any]] = None

# In-memory token cache
_current_tokens: Optional[Dict[str, str]] = None

# Live signals that failed ONLY because the E*TRADE session was expired (401)
# are parked here and replayed automatically the moment the account is
# relinked. Entries expire after PARKED_SIGNAL_TTL_SECONDS and never replay
# into a closed market; closes always replay (they reduce risk).
_parked_signals: List[Dict[str, Any]] = []
PARKED_SIGNAL_TTL_SECONDS = int(os.getenv("PARKED_SIGNAL_TTL_SECONDS", "600"))
_MAX_PARKED_SIGNALS = 10

# Cached E*TRADE accountIdKey. Order APIs require the opaque accountIdKey from
# /accounts/list — NOT the visible account number. Users typically set
# ETRADE_ACCOUNT_ID to the account number, which E*TRADE rejects with
# "Code: 102, Please enter valid Account Key". We resolve the real key once
# per session and cache it here (cleared on relink/disconnect).
_resolved_account_id_key: Optional[str] = None

# Account-binding provenance for the resolved key: which account real orders
# actually route to, whether it matched the configured ETRADE_ACCOUNT_ID, and
# whether the pick was an ambiguous fallback. Surfaced via /status so the app
# can refuse to call the live path "trusted" while orders would land in an
# account the user never named. Reset alongside the key on relink/disconnect.
_account_binding: Optional[Dict[str, Any]] = None

# USER-PINNED ACCOUNT (set from the app via POST /etrade/account/select).
# Persisted in the state store under ACCOUNT_PIN_KEY so it survives restarts
# and is shared by every worker. Takes precedence over ETRADE_ACCOUNT_ID —
# an env var can only be changed with a redeploy, and picking the account that
# receives real orders must not require one. Cleared explicitly, never on
# relink (the pin is the user's intent, not session state).
ACCOUNT_PIN_KEY = "etrade:pinned_account"
_pinned_account_id: Optional[str] = None

# Pending OAuth request tokens (token -> secret). E*TRADE request tokens are
# single-use and expire ~5 minutes after issue. Memory is the PRIMARY store —
# the DB row is only a backup — so a DB failure can never cause /auth/complete
# to exchange a stale token (the cause of "oauth_problem=token_rejected").
_pending_request_tokens: Dict[str, str] = {}
_latest_request_token: Optional[str] = None
_MAX_PENDING_REQUEST_TOKENS = 5

