def _is_market_open() -> bool:
    """Exchange-aware regular-session check: 9:30–16:00 US/Eastern (13:00 close
    on half days), weekdays only, NYSE holidays excluded. DST-safe via zoneinfo."""
    now_et = _utcnow().astimezone(_ET_ZONE)
    if now_et.weekday() >= 5:
        return False
    day = now_et.date().isoformat()
    if day in _MARKET_HOLIDAYS:
        return False
    close = dtime(13, 0) if day in _MARKET_HALF_DAYS else dtime(16, 0)
    return dtime(9, 30) <= now_et.time() <= close


# ==================== WEBHOOK AUTH / IDEMPOTENCY ====================
def _verify_webhook_auth(
    raw: bytes,
    body_secret: Optional[str],
    secret_header: Optional[str],
    sig_header: Optional[str],
) -> None:
    """Accept the shared secret (body `secret` field or X-Rork-Secret header)
    or an HMAC-SHA256 signature of the raw body (X-Rork-Signature)."""
    if not WEBHOOK_SECRET:
        return
    if sig_header:
        expected = hmac.new(WEBHOOK_SECRET.encode(), raw, hashlib.sha256).hexdigest()
        provided = sig_header.split("=", 1)[-1].strip()
        if hmac.compare_digest(expected, provided):
            return
        raise HTTPException(401, "invalid signature")
    if body_secret == WEBHOOK_SECRET or secret_header == WEBHOOK_SECRET:
        return
    raise HTTPException(403, "Unauthorized")


def _signal_key(p: dict) -> str:
    # intent is part of the key so a close is never deduped against the entry
    # that opened the position.
    base = (
        f"{p.get('ticker')}|{p.get('action')}|{p.get('entry')}|{p.get('stop')}|"
        f"{p.get('target')}|{p.get('timestamp')}|{str(p.get('intent') or 'open').lower()}"
    )
    return "sig:" + hashlib.sha1(base.encode()).hexdigest()


def _is_auth_error(err: str) -> bool:
    """True when a broker failure is an expired/invalid OAuth session (401)."""
    low = str(err).lower()
    return "401" in low or "unauthorized" in low


def _park_signal(pd: dict) -> None:
    """Park a live signal that failed ONLY because the session was expired.
    One parked signal per ticker — the newest wins."""
    ticker = str(pd.get("ticker") or "").upper()
    _parked_signals[:] = [
        p for p in _parked_signals
        if str(p["payload"].get("ticker") or "").upper() != ticker
    ]
    _parked_signals.append({"payload": dict(pd), "ts": time.time()})
    while len(_parked_signals) > _MAX_PARKED_SIGNALS:
        _parked_signals.pop(0)
    logger.warning(
        f"\U0001f17f\ufe0f Parked live signal {ticker} {pd.get('action')} — E*TRADE session expired; "
        f"will auto-replay after relink (entries valid {PARKED_SIGNAL_TTL_SECONDS // 60} min)"
    )


async def _replay_parked_signals() -> None:
    """Runs right after a successful relink: replay signals that failed solely
    on the expired session. Closes always replay (they reduce risk); entries
    only while fresh AND the market is open."""
    if not _parked_signals:
        return
    await asyncio.sleep(2.0)  # let the fresh session settle before ordering
    pending = list(_parked_signals)
    _parked_signals.clear()
    for item in pending:
        pd = dict(item["payload"])
        ticker = str(pd.get("ticker") or "").upper()
        age = time.time() - float(item.get("ts") or 0)
        if not _is_close_payload(pd):
            if age > PARKED_SIGNAL_TTL_SECONDS:
                logger.info(f"\U0001f17f\ufe0f Dropping stale parked entry {ticker} (age {age:.0f}s)")
                await trade_ledger.record("parked_signal_dropped", {"ticker": ticker, "age_seconds": int(age), "reason": "stale"})
                continue
            if not _is_market_open() and not bool(pd.get("force_execute")):
                logger.info(f"\U0001f17f\ufe0f Dropping parked entry {ticker} — market closed")
                await trade_ledger.record("parked_signal_dropped", {"ticker": ticker, "age_seconds": int(age), "reason": "market_closed"})
                continue
            # Risk state may have changed during the outage (positions filled,
            # daily loss accrued, duplicate ticker) — a replay must clear the
            # same gates a fresh signal would.
            try:
                ok, reasons = await _passes_entry_filters(pd)
            except Exception as gate_err:
                ok, reasons = False, [f"entry filter check failed: {gate_err}"]
            if not ok:
                logger.info(f"\U0001f17f\ufe0f Dropping parked entry {ticker} — {'; '.join(reasons)[:200]}")
                await trade_ledger.record("parked_signal_dropped", {
                    "ticker": ticker, "age_seconds": int(age),
                    "reason": f"entry_filters: {'; '.join(reasons)[:180]}",
                })
                continue
        try:
            result = await execute_live_order(pd)
            logger.info(f"\u2705 Replayed parked signal {ticker}: {result.get('status')}")
            await trade_ledger.record("parked_signal_replayed", {
                "ticker": ticker, "action": pd.get("action"),
                "age_seconds": int(age), "result": str(result.get("status") or ""),
            })
        except Exception as e:
            logger.error(f"\u274c Parked signal replay failed for {ticker}: {e}")
            await alerts.send(
                "error", "parked_replay_failed",
                f"{ticker} {pd.get('action')}: replay after relink failed: {e}",
                dedupe_key=f"parked:{ticker}",
            )


def _is_close_payload(p: dict) -> bool:
    """An exit/close must bypass entry gating — closing always reduces risk."""
    if str(p.get("intent") or "").lower() == "close":
        return True
    if str(p.get("order_action") or "").upper() == "SELL_CLOSE":
        return True
    return str(p.get("action") or "").upper() in {"EXIT", "CLOSE"}


# ==================== ENTRY FILTERS (live entries only) ====================
def _is_connectivity_test(p: dict) -> bool:
    """A `test: true` payload is a one-contract end-to-end connectivity probe,
    not a strategy signal. It carries no real market measurements."""
    return bool(p.get("test")) is True


async def _passes_entry_filters(p: dict) -> Tuple[bool, List[str]]:
    """Server-side re-filter mirroring the Rork app's gating, evaluated against
    the reconciled Redis state (single source of truth). Quality checks apply
    only when the payload carries the field (score/rvol/mtf/setup); risk
    limits (kill switch, daily loss, trade count, positions, heat, duplicate
    ticker) always apply.

    CONNECTIVITY TESTS (`test: true`) skip the QUALITY gates only. A probe
    ships placeholder quality fields by definition, so the old behaviour made
    it structurally impossible to pass: observed live 2026-07-31 18:30 UTC as
    `REJECTED - rvol 1 < 1.5; setup 'Connectivity Test' not allowlisted`,
    leaving the user with no way to prove the real-money path works. Every
    RISK gate below still applies to a probe — kill switch, daily loss, trade
    count, position cap, portfolio heat and duplicate ticker are absolute."""
    blocked: List[str] = []
    if await state.is_killed():
        blocked.append("kill switch active")

    is_probe = _is_connectivity_test(p)
    if not is_probe:
        regime = str(p.get("regime") or "").lower()
        score = p.get("score")
        if isinstance(score, (int, float)):
            required = MIN_SCORE_TRENDING if "trending" in regime else MIN_SCORE
            if score < required:
                blocked.append(f"score {score} < {required}")
        rvol = p.get("rvol")
        if rvol is None:
            # An absent RVOL means the app never MEASURED relative volume.
            # Silently waving that through would place real money on an
            # unverified decision input, so a live entry is refused outright.
            blocked.append("rvol not measured (volume feed gap) — live entry needs a real reading")
        elif isinstance(rvol, (int, float)) and rvol < MIN_RVOL:
            blocked.append(f"rvol {rvol} < {MIN_RVOL}")
        mtf = p.get("mtf_alignment")
        if isinstance(mtf, str) and mtf.strip():
            try:
                if int(mtf.split("/")[0]) < MIN_MTF:
                    blocked.append(f"mtf {mtf} < {MIN_MTF}/5")
            except (ValueError, IndexError):
                blocked.append("mtf_alignment unparseable")
        setup = p.get("setup")
        if isinstance(setup, str) and setup.strip() and ALLOWED_SETUPS and setup.lower().strip() not in ALLOWED_SETUPS:
            blocked.append(f"setup '{setup}' not allowlisted")
    else:
        logger.info("🧪 Connectivity test payload — quality gates skipped, risk gates still enforced")

    daily = await state.get_daily()
    open_positions = await state.all_positions()
    if daily["realized_pnl_today_pct"] <= -abs(DAILY_LOSS_LIMIT_PCT):
        blocked.append(f"daily loss limit ({daily['realized_pnl_today_pct']:.2f}%)")
    # PROFIT LOCK — a banked day is not a licence to keep swinging. Once the
    # objective is proven met in broker-verified dollars, further entries are
    # refused while the cushion is too thin to absorb a full loss. Giving a made
    # day back to chase a bigger one is the most expensive habit a daily-target
    # system can form, and it is invisible in percent terms.
    lock = plan_profit_lock(daily.get("realized_pnl_today_usd"))
    if lock["locked"]:
        blocked.append(lock["reason"])
    # The daily trade COUNT no longer gates entries — see the config note on
    # RUNAWAY_TRADE_CIRCUIT_BREAKER. This ceiling only catches a dispatch loop,
    # which is a bug rather than a strategy, and is set far above any real day.
    if daily["trades_today"] >= RUNAWAY_TRADE_CIRCUIT_BREAKER:
        blocked.append(
            f"runaway circuit breaker: {daily['trades_today']} entries today — this is a "
            f"dispatch loop, not a trading day"
        )
    if len(open_positions) >= MAX_CONCURRENT_POSITIONS:
        blocked.append(f"max positions ({MAX_CONCURRENT_POSITIONS}) open")
    ticker = str(p.get("ticker") or "").upper()
    if ticker and ticker in open_positions:
        blocked.append(f"already in {ticker}")

    account_ref = 50000.0
    try:
        account_ref = float(os.getenv("ACCOUNT_SIZE", "50000"))
        open_risk = sum(position_risk_usd(pos) for pos in open_positions.values())
        new_risk = account_ref * (RISK_PER_TRADE_PCT / 100.0)
        heat = (open_risk + new_risk) / max(account_ref, 1) * 100.0
        if heat > PORTFOLIO_HEAT_PCT:
            blocked.append(f"portfolio heat {heat:.2f}% > {PORTFOLIO_HEAT_PCT}%")
    except (TypeError, ValueError):
        pass

    # RISK BUDGET — the DOLLAR limit that replaced the trade count. Realized
    # losses and committed open risk draw from one budget (the daily loss limit),
    # so the limit is enforced on exposure rather than discovered at the close.
    try:
        open_risk_usd = sum(position_risk_usd(pos) for pos in open_positions.values())
        budget = plan_risk_budget(
            account_size=account_ref,
            realized_usd=daily.get("realized_pnl_today_usd"),
            open_risk_usd=open_risk_usd,
            profit_lock_max_risk=(lock["max_risk_usd"] if lock["cushion_usd"] > 0 else None),
        )
        requested_risk = account_ref * (RISK_PER_TRADE_PCT / 100.0)
        if budget["remaining_usd"] < requested_risk * 0.25:
            blocked.append(
                f"daily risk budget spent: ${budget['used_usd']:,.0f} of "
                f"${budget['budget_usd']:,.0f} committed (realized losses + open risk) — "
                f"${budget['remaining_usd']:,.0f} left against a ${requested_risk:,.0f} entry"
            )
    except (TypeError, ValueError):
        pass

    # EXECUTION COST — refuse a contract whose round trip eats the edge. A
    # $0.30 option pays 4.3% in commission alone before the spread; no win rate
    # survives that. Only applied when the payload priced a real contract.
    cost = assess_entry_cost(p)
    if cost["prohibitive"]:
        blocked.append(cost["reason"])

    return len(blocked) == 0, blocked


def position_risk_usd(pos: dict) -> float:
    """Dollars at risk on one tracked position, from ENTRY to protective stop.

    Options are priced on the PREMIUM, not the underlying, and one contract
    controls 100 shares. The portfolio-heat gate used to compute
    `abs(entry - stop) * qty` for everything, which on an option position
    multiplied an UNDERLYING dollar move by a CONTRACT count — two different
    units. A 3-contract NVDA call risking $1,470 of premium was counted as $9 of
    heat, so the gate that is supposed to cap total exposure never fired on the
    instrument the bot actually trades most.

    Falls back to the underlying basis when premium fields are absent, and to 0
    when nothing is measurable — an unmeasurable position must not be invented
    into the heat sum either way.
    """
    def num(key: str) -> float:
        try:
            value = float(pos.get(key) or 0)
        except (TypeError, ValueError):
            return 0.0
        return value if math.isfinite(value) else 0.0

    try:
        qty = abs(int(float(pos.get("filled_qty") or pos.get("qty") or 0)))
    except (TypeError, ValueError):
        qty = 0
    if qty < 1:
        return 0.0

    contract = pos.get("contract") or {}
    if isinstance(contract, dict) and contract.get("right"):
        entry_premium = num("entry_premium")
        # The live protective level is the trail once the engine has ratcheted.
        stop_premium = max(num("stop_premium"), num("trail"))
        if entry_premium > 0 and stop_premium > 0:
            return max(0.0, entry_premium - stop_premium) * 100.0 * qty
        if entry_premium > 0:
            # Stop unknown: the whole premium is at risk. Never report 0 — that
            # reads as "no exposure" on a position that can lose everything.
            return entry_premium * 100.0 * qty
        return 0.0

    entry = num("entry")
    stop = max(num("stop"), num("trail")) if num("trail") > 0 else num("stop")
    if entry <= 0 or stop <= 0:
        return 0.0
    return abs(entry - stop) * qty


def _occ_symbol(ticker: str, expiry: str, right: str, strike: float) -> str:
    """Build an OCC 21-char option symbol: ROOT(6) + YYMMDD + C/P + STRIKE*1000(8)."""
    try:
        d = datetime.strptime(str(expiry)[:10], "%Y-%m-%d")
        date_part = d.strftime("%y%m%d")
    except ValueError:
        date_part = "000000"
    cp = "C" if str(right).upper().startswith("C") else "P"
    return f"{ticker.upper().ljust(6)}{date_part}{cp}{int(round(float(strike) * 1000)):08d}"

Base = declarative_base()


class ETradeSessionState(Base):
    __tablename__ = "etrade_session_state"
    id = Column(String(50), primary_key=True, default="active_state")
    oauth_token = Column(Text, nullable=False)
    oauth_token_secret = Column(Text, nullable=False)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)


# ==================== MODELS ====================
class WebhookPayload(BaseModel):
    # Secret can also arrive via the X-Rork-Secret header — see /webhook.
    secret: Optional[str] = None
    ticker: str
    action: str
    mode: Optional[str] = "paper"
    instrument: Optional[str] = "stock"
    strike: Optional[float] = None
    strike_hint: Optional[float] = None
    expiry: Optional[str] = None
    expiration_hint: Optional[str] = None
    # Discrete expiration components the app also sends (used as a fallback to
    # rebuild a clean "YYYY-MM-DD" string for pyetrade).
    expiration_year: Optional[int] = None
    expiration_month: Optional[int] = None
    expiration_day: Optional[int] = None
    option_right: Optional[str] = None
    call_put: Optional[str] = None
    contracts: Optional[int] = None
    option_contracts: Optional[int] = None
    quantity: Optional[int] = None
    limit_price: Optional[float] = None
    option_limit_price: Optional[float] = None
    position_size_shares: Optional[int] = None
    # Stop / trailing-stop telemetry from the app. Informational on entries —
    # the Auto-Exit engine handles exits app-side by dispatching SELL_CLOSE.
    # Used broker-side ONLY on a SELL_CLOSE with broker_stop=true.
    stop: Optional[float] = None
    trail_stop: Optional[float] = None
    trail_amount: Optional[float] = None
    stop_price: Optional[float] = None
    trailing_stop_amount: Optional[float] = None
    trailing_stop_percent: Optional[float] = None
    broker_stop: Optional[bool] = None
    exit_limit_price: Optional[float] = None
    # Option stop protection: explicit protective stop PREMIUM for the option
    # guard (falls back to OPTION_STOP_LOSS_PCT below the entry premium).
    option_stop_price: Optional[float] = None

    class Config:
        # Keep unknown fields instead of silently dropping them. A trimmed
        # payload model was exactly what caused "strike=None, expiry=None" on
        # a previously deployed variant — the app DID send strike_hint /
        # expiration_hint, but pydantic stripped them before payload.dict().
        extra = "allow"

    @validator("action")
    def validate_action(cls, v):
        if str(v).upper() not in {"BUY", "SELL", "EXIT", "CLOSE"}:
            raise ValueError("Invalid action")
        return str(v).upper()


# ==================== TOKEN PERSISTENCE ====================
# Broker SESSION HEALTH — tokens on disk are not the same thing as a live
# session (E*TRADE access tokens hard-expire at midnight ET). The app polls
# /etrade/account and /status; `token_valid` lets it distinguish "linked with
# a working session" from "linked but the session is DEAD — relink required",
# so a token-expired weekend can never look armed in the app again.
_token_session: Dict[str, Any] = {"valid": None, "reason": None, "checked_at": None}


def _mark_token_session(valid: bool, reason: str = "") -> None:
    prev = _token_session["valid"]
    _token_session["valid"] = valid
    _token_session["reason"] = reason or None
    _token_session["checked_at"] = _utcnow().isoformat()
    if prev is not False and valid is False:
        logger.warning(f"Broker session marked EXPIRED — {reason}")
        # ONE alert at the TRANSITION — the keepalive and reconcile loops
        # quiesce while expired, so this is the only relink prompt the user
        # gets (instead of an ERROR every 15 minutes all night).
        _alert_session_transition(
            "error", "broker_session_expired",
            f"E*TRADE session is DEAD ({reason}). Broker polling is paused until "
            f"you relink — open the app and tap Link Account.",
        )
    elif prev is not True and valid is True:
        logger.info("Broker session marked ACTIVE")
        if prev is False:
            _alert_session_transition(
                "info", "broker_session_restored",
                "E*TRADE session restored — broker polling resumed.",
            )


def _alert_session_transition(severity: str, event: str, message: str) -> None:
    """Best-effort one-shot alert on a session-state TRANSITION. Fire-and-forget:
    session marking is synchronous and must never block or fail on alerting."""
    try:
        asyncio.get_running_loop()
        asyncio.create_task(alerts.send(severity, event, message, dedupe_key=event))
    except RuntimeError:
        pass  # no running loop (import/startup) — the log line already records it
    except Exception as e:
        logger.debug(f"session transition alert failed: {e}")


# While the session is EXPIRED every broker call is a guaranteed 401. One
# probe per window keeps a self-heal path open in case the flag was set by a
# transient 401 mislabelled as expiry — without hammering E*TRADE all night.
EXPIRED_SESSION_PROBE_SECONDS = int(os.getenv("EXPIRED_SESSION_PROBE_SECONDS", str(4 * 3600)))
_expired_probe_ts: float = 0.0


def _session_probe_due(now_ts: float, last_probe_ts: float,
                       probe_seconds: float = None) -> bool:
    """True when the quiesced (expired) session is due one broker probe."""
    window = EXPIRED_SESSION_PROBE_SECONDS if probe_seconds is None else probe_seconds
    return (float(now_ts) - float(last_probe_ts)) >= float(window)


def _keepalive_should_run(session_valid: Optional[bool]) -> bool:
    """renew_access_token can only EXTEND a live session — a midnight-ET-expired
    token can never be renewed back to life; only a full relink issues a working
    session. Attempting renewal against a known-dead session burns E*TRADE rate
    budget and fires a warning alert per cycle (observed 2026-08-09: 8+ hours of
    401/404/500 renew attempts overnight)."""
    return session_valid is not False


def _require_probeable_session() -> None:
    """Gate for reconcile broker fetches: while the session is expired, skip
    the guaranteed-401 call with a QUIET BrokerSessionExpired — except one
    probe every EXPIRED_SESSION_PROBE_SECONDS so a wrongly-flagged session
    still self-heals without a relink."""
    global _expired_probe_ts
    if _token_session["valid"] is not False:
        return
    now = time.time()
    if _session_probe_due(now, _expired_probe_ts):
        _expired_probe_ts = now
        return
    raise reconciliation.BrokerSessionExpired(
        _token_session["reason"] or "token expired — relink required"
    )


def _looks_like_auth_failure(err: Exception) -> bool:
    text = str(err)
    return "401" in text or "oauth_problem" in text or "Unauthorized" in text


def _token_session_fields() -> Dict[str, Any]:
    valid = _token_session["valid"]
    return {
        "token_valid": valid,
        "session_state": "expired" if valid is False else ("active" if valid is True else "unknown"),
        "session_checked_at": _token_session["checked_at"],
        "session_reason": _token_session["reason"],
    }


def save_tokens(token: str, token_secret: str):
    global _current_tokens, _resolved_account_id_key, _account_binding
    logger.info("=== NEW TOKENS RECEIVED ===")
    # Fresh tokens are validated by the auth flow before they get here — the
    # session starts ACTIVE.
    _mark_token_session(True, "new tokens adopted")
    _current_tokens = {"oauth_token": token, "oauth_token_secret": token_secret}
    _resolved_account_id_key = None  # re-resolve accountIdKey for the new session
    _account_binding = None
    # A fresh link is an explicit user action — clear any tripped breaker so
    # the relinked session starts clean instead of rejecting with 503.
    try:
        asyncio.create_task(_reset_circuit_breaker("account relinked"))
        # Replay live signals that failed solely on the expired session — this
        # closes the disconnect→relink gap where dispatches used to be lost.
        asyncio.create_task(_replay_parked_signals())
    except RuntimeError:
        pass  # no running loop (e.g. import-time) — TTL reset still applies
    if async_session:
        try:
            asyncio.create_task(_save_tokens_to_db(token, token_secret))
        except Exception as e:
            logger.warning(f"Failed to persist tokens to DB: {e}")


async def _save_tokens_to_db(token: str, token_secret: str):
    if not async_session:
        return
    try:
        async with async_session() as session:
            async with session.begin():
                state = ETradeSessionState(id="active_tokens", oauth_token=token, oauth_token_secret=token_secret)
                await session.merge(state)
        logger.info("✅ Tokens saved to database")
    except Exception as e:
        logger.error(f"Error saving tokens to DB: {e}")


def load_tokens() -> Optional[Dict[str, str]]:
    global _current_tokens
    if _current_tokens:
        return _current_tokens
    token = os.getenv("ETRADE_ACCESS_TOKEN")
    secret = os.getenv("ETRADE_ACCESS_TOKEN_SECRET")
    if token and secret:
        _current_tokens = {"oauth_token": token, "oauth_token_secret": secret}
        return _current_tokens
    return None


async def _load_tokens_from_db():
    if not async_session:
        return None
    try:
        async with async_session() as session:
            state = await session.get(ETradeSessionState, "active_tokens")
            if state:
                return {"oauth_token": state.oauth_token, "oauth_token_secret": state.oauth_token_secret}
    except Exception as e:
        logger.error(f"Error loading tokens from DB: {e}")
    return None


async def preload_tokens():
    global _current_tokens
    if async_session:
        try:
            tokens = await _load_tokens_from_db()
            if tokens:
                _current_tokens = tokens
                logger.info("✅ Tokens pre-loaded from database into memory")
        except Exception as e:
            logger.warning(f"Could not preload tokens from DB: {e}")


# ==================== OAUTH ====================
REQUEST_TOKEN_URL = "https://api.etrade.com/oauth/request_token"
AUTHORIZE_URL = "https://us.etrade.com/e/t/etws/authorize"
ACCESS_TOKEN_URL = "https://api.etrade.com/oauth/access_token"


@app.api_route("/etrade/auth/start", methods=["GET", "POST"])
@app.api_route("/link", methods=["GET", "POST"])
async def etrade_auth_start():
    global _latest_request_token
    try:
        etrade_session = OAuth1Session(client_key=CONSUMER_KEY, client_secret=CONSUMER_SECRET, callback_uri="oob")
        # Request tokens are disposable — fetching is safe to retry with
        # backoff (unlike the access-token exchange, whose verifier is
        # single-use and must NEVER be retried).
        try:
            fetch_response = await asyncio.to_thread(
                _sync_etrade_call, etrade_session.fetch_request_token, REQUEST_TOKEN_URL,
                source="request_token",
            )
        except Exception as fetch_err:
            # E*TRADE's OAuth service throws intermittent 500s (observed
            # 2026-08-09 12:37 UTC — request_token AND access_token both 500'd
            # for minutes). A raw 500 here read as "the bot is broken"; it is
            # E*TRADE's sign-in service, and waiting a minute fixes it.
            logger.error(f"Request token fetch failed: {fetch_err}")
            raise HTTPException(
                503,
                "E*TRADE's sign-in service returned an error while starting the "
                "link — this is a hiccup on their side, not yours. Wait about a "
                "minute and tap Link Account again.",
            )
        token_val = fetch_response.get("oauth_token")
        secret_val = fetch_response.get("oauth_token_secret")
        if not token_val or not secret_val:
            raise Exception("Failed to get request token from E*TRADE")
        # E*TRADE request tokens are base64-style and often contain '+', '/'
        # and '='. Unencoded, the browser decodes '+' as a space and E*TRADE
        # rejects the token with "Due to a logon delay or other issue...".
        # Percent-encode both query params so the token survives intact.
        # CRITICAL: percent-encode ONLY the parameter VALUES, never the
        # separators. Encoding the whole query string turns `token=` into
        # `token%3D`, so E*TRADE receives no token param at all and shows
        # "Due to a logon delay or other issue..." on the authorize page.
        encoded_key = quote(str(CONSUMER_KEY or ""), safe="")
        encoded_token = quote(str(token_val), safe="")
        auth_url = f"{AUTHORIZE_URL}?key={encoded_key}&token={encoded_token}"

        # Hard guard: never return a malformed URL. The literal separators
        # `?key=` and `&token=` must survive, and the token value must decode
        # back to exactly the raw token E*TRADE issued.
        from urllib.parse import parse_qs, urlsplit
        parsed_query = parse_qs(urlsplit(auth_url).query)
        if parsed_query.get("token", [None])[0] != str(token_val) or parsed_query.get("key", [None])[0] != str(CONSUMER_KEY or ""):
            logger.error(f"[{BOT_VERSION}] MALFORMED AUTH URL blocked — separators were encoded")
            raise Exception("Internal error building authorize URL — please retry")

        # PRIMARY store: in-memory. Keep the last few so a duplicate tap on
        # "Link" doesn't orphan the token the user actually authorized.
        _pending_request_tokens[str(token_val)] = str(secret_val)
        while len(_pending_request_tokens) > _MAX_PENDING_REQUEST_TOKENS:
            _pending_request_tokens.pop(next(iter(_pending_request_tokens)))
        _latest_request_token = str(token_val)

        # BACKUP store: DB (best-effort — never fail the start on a DB error).
        if async_session:
            try:
                async with async_session() as session:
                    async with session.begin():
                        state = ETradeSessionState(id="active_state", oauth_token=str(token_val), oauth_token_secret=str(secret_val))
                        await session.merge(state)
            except Exception as db_err:
                logger.warning(f"Could not persist request token to DB (memory store still active): {db_err}")

        # Diagnostic (token masked): confirms which code version built the URL
        # and whether the token needed percent-encoding ('+', '/', '=' chars).
        raw = str(token_val)
        specials = "".join(sorted({c for c in raw if c in "+/="})) or "none"
        logger.info(
            f"[{BOT_VERSION}] auth URL generated | token={raw[:4]}...{raw[-4:]} "
            f"len={len(raw)} special_chars={specials} encoded_tail=...{auth_url[-24:]}"
        )
        # Return the request token so the app can cache it and echo it back on
        # /auth/complete — lets us verify we exchange the SAME token the user
        # authorized, even across duplicate starts.
        return {"status": "success", "auth_url": auth_url, "authorize_url": auth_url, "request_token": str(token_val), "bot_version": BOT_VERSION}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, detail=str(e))


def _classify_exchange_error(msg: str) -> Tuple[int, str]:
    """Map a raw access-token exchange failure to (http_status, user message).
    E*TRADE's OAuth service fails in three distinct ways and each needs a
    different user action — an opaque 500 with a Tomcat HTML blob (observed
    live 2026-08-09 12:37 UTC) told the user nothing."""
    low = str(msg).lower()
    if "token_rejected" in low or "401" in str(msg):
        return 400, (
            "E*TRADE rejected the request token — it expired (5-minute limit) or "
            "was already used. Tap Link Account again and paste the fresh code right away."
        )
    if "verifier" in low:
        return 400, "E*TRADE rejected the verification code. Double-check the code and try again."
    if "500" in str(msg) or "internal server error" in low:
        return 502, (
            "E*TRADE's sign-in service had an internal error during the final step — "
            "this happens on their side from time to time. Tap Link Account again for "
            "a fresh link and code."
        )
    return 502, f"E*TRADE token exchange failed: {str(msg)[:200]} — tap Link Account again for a fresh link."


@app.post("/etrade/auth/complete")
@app.post("/complete-link")
async def etrade_auth_complete(data: dict = Body(...)):
    global _latest_request_token
    try:
        verifier = str(data.get("oauth_verifier") or data.get("verifier") or data.get("code") or "").strip()
        if not verifier:
            raise HTTPException(400, "Missing verification code")

        # The app echoes back the request token it received from /auth/start.
        provided = data.get("request_token") or data.get("oauth_token")
        provided = str(provided).strip() if provided else None

        token_val: Optional[str] = None
        secret_val: Optional[str] = None

        # 1) Exact match on the token the app says the user authorized.
        if provided and provided in _pending_request_tokens:
            token_val, secret_val = provided, _pending_request_tokens[provided]
        # 2) Latest request token issued by this process.
        elif _latest_request_token and _latest_request_token in _pending_request_tokens:
            token_val = _latest_request_token
            secret_val = _pending_request_tokens[token_val]
        # 3) DB backup (e.g. the bot restarted between start and complete).
        elif async_session:
            try:
                async with async_session() as session:
                    cached = await session.get(ETradeSessionState, "active_state")
                    if cached:
                        token_val = cached.oauth_token
                        secret_val = cached.oauth_token_secret
            except Exception as db_err:
                logger.warning(f"DB lookup for request token failed: {db_err}")

        if not token_val or not secret_val:
            raise HTTPException(400, "No active request token found. Tap Link Account again and complete within 5 minutes.")

        # NEVER silently exchange a different token than the one the user
        # authorized — E*TRADE would reject it (oauth_problem=token_rejected).
        if provided and token_val != provided:
            logger.error("Request token mismatch: app authorized a different token than the one stored")
            raise HTTPException(409, "The link session was replaced by a newer one. Tap Link Account again and use the newest code.")

        etrade_session = OAuth1Session(CONSUMER_KEY, CONSUMER_SECRET, resource_owner_key=token_val, resource_owner_secret=secret_val, verifier=verifier)
        try:
            access_tokens = etrade_session.fetch_access_token(ACCESS_TOKEN_URL)
        except Exception as oauth_err:
            msg = str(oauth_err)
            logger.error(f"Access token exchange failed: {msg}")
            # The request token is SINGLE-USE — a failed exchange may have
            # consumed it at E*TRADE. Discard it so a retry can never re-send
            # a dead token (guaranteed token_rejected); the user restarts with
            # a fresh link instead.
            _pending_request_tokens.pop(str(token_val), None)
            if _latest_request_token == token_val:
                _latest_request_token = None
            status_code, friendly = _classify_exchange_error(msg)
            raise HTTPException(status_code, friendly)

        final_token = access_tokens.get("oauth_token")
        final_secret = access_tokens.get("oauth_token_secret")
        if not final_token or not final_secret:
            raise HTTPException(500, "E*TRADE did not return access tokens")
        save_tokens(final_token, final_secret)

        # Request tokens are single-use — clear all pending state.
        _pending_request_tokens.clear()
        _latest_request_token = None

        return {
            "status": "success",
            "message": "E*TRADE account linked successfully",
            "linked": True,
            "env": ENV,
            "oauth_token": final_token,
            "oauth_token_secret": final_secret,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Complete link failed: {e}")
        raise HTTPException(500, detail=str(e))


@app.get("/etrade/account")
async def get_etrade_account():
    tokens = load_tokens()
    if not tokens:
        return {"status": "not_linked", "linked": False}
    # Best-effort account enumeration so the app can show which account will
    # receive orders. Never fail the linked check on an enumeration error.
    accounts_out = []
    # Bound BEFORE the try: enumeration fails on every expired token (401), and
    # the routed-identity block below reads `raw` unconditionally. Leaving it
    # unbound turned a recoverable "session expired" into an UnboundLocalError
    # 500 on /etrade/account — so the app could not even render the relink
    # prompt that fixes it (observed live 2026-08-05 05:07 UTC).
    raw: List[dict] = []
    try:
        accounts_api = pyetrade.ETradeAccounts(
            CONSUMER_KEY, CONSUMER_SECRET,
            tokens["oauth_token"], tokens["oauth_token_secret"],
            dev=is_sandbox,
        )
        resp = await _etrade_call(accounts_api.list_accounts, resp_format="json", source="list_accounts")
        raw = (((resp or {}).get("AccountListResponse") or {}).get("Accounts") or {}).get("Account") or []
        if isinstance(raw, dict):
            raw = [raw]
        for a in raw:
            accounts_out.append({
                "accountIdKey": a.get("accountIdKey"),
                "accountId": a.get("accountId"),
                "accountType": a.get("accountType"),
                "accountStatus": a.get("accountStatus"),
                "accountDesc": a.get("accountDesc"),
                "accountName": a.get("accountName"),
                "institutionType": a.get("institutionType"),
            })
        # A successful authenticated call proves the session is alive.
        _mark_token_session(True, "account enumeration ok")
    except Exception as e:
        logger.warning(f"Account enumeration failed (still linked): {e}")
        if _looks_like_auth_failure(e):
            _mark_token_session(False, "E*TRADE rejected the session (token expired at midnight ET or revoked) — relink required")
    # Real balances so the app can size positions off the TRUE account value
    # instead of a stale default. Best-effort — never fail the linked check.
    balances = await _fetch_broker_balance() or {}

    # IDENTITY OF THE ROUTED ACCOUNT, flat at the response root.
    # The app reads snake_case scalars (`account_id`, `account_type`, …) — it
    # does NOT walk the `accounts` array. Returning only the array meant the
    # app showed "Account —" forever even with a perfectly healthy link.
    # These name the ONE account orders actually route to, using the exact
    # same precedence as order placement (resolved key → first ACTIVE → first).
    routed: Dict[str, Any] = {}
    if raw:
        resolved_key = _resolved_account_id_key
        if not resolved_key:
            try:
                resolved_key = await _resolve_account_id_key(tokens)
            except Exception as e:
                logger.warning(f"Account key resolution failed during /etrade/account: {e}")
        try:
            chosen = _account_for_balance(raw, resolved_key)
        except Exception:
            chosen = raw[0]
        acct_id = str(chosen.get("accountId") or "").strip()
        routed = {
            "account_id": acct_id or None,
            "account_id_key": str(chosen.get("accountIdKey") or "").strip() or None,
            "account_type": chosen.get("accountType") or None,
            "account_status": chosen.get("accountStatus") or None,
            "account_desc": chosen.get("accountDesc") or chosen.get("accountName") or None,
            "account_last4": acct_id[-4:] if acct_id else None,
            "institution_type": chosen.get("institutionType") or None,
        }

    pinned = await _load_pinned_account()
    return {
        "status": "linked",
        "linked": True,
        "accounts": accounts_out,
        **routed,
        # Which account the USER pinned from the app (null = auto-select).
        "pinned_account_id": pinned,
        "account_pin_source": (
            "pinned" if pinned else ("env" if (TARGET_ACCOUNT_ID or "").strip() else "auto")
        ),
        "env_account_id": (TARGET_ACCOUNT_ID or "").strip() or None,
        # Provenance for the pick above — lets the app say "pinned" vs
        # "fell back to this one" without a second /status round-trip.
        "account_binding": _account_binding,
        "equity": balances.get("total"),
        "cash_buying_power": balances.get("available"),
        # Session health — `linked` means "tokens on file", these fields say
        # whether those tokens can actually place orders RIGHT NOW.
        **_token_session_fields(),
    }


@app.post("/etrade/account/select")
async def select_etrade_account(data: dict = Body(default={})):
    """Pin the E*TRADE account that real orders route to — from the app.

    Previously the routed account could only be changed by editing the
    ETRADE_ACCOUNT_ID env var and redeploying; with several accounts linked and
    no env var set, orders silently went to the first ACTIVE one. This endpoint
    lets the user choose, and the choice is persisted in the state store so it
    survives restarts and applies to every worker.

    Safety: switching accounts while positions are open would strand those
    positions (their resting stops live at the OLD account and reconciliation
    reads the NEW one), so an open position blocks the switch unless the caller
    passes `force: true`.

    Body: {"account_id": "146261816"} | {"clear": true} | {"account_id": null}
    """
    tokens = load_tokens()
    if not tokens:
        raise HTTPException(401, "E*TRADE account not linked")

    requested = str(data.get("account_id") or data.get("account_id_key") or "").strip()
    clearing = bool(data.get("clear")) or not requested
    force = bool(data.get("force"))

    current_pin = await _load_pinned_account()
    if clearing and not current_pin:
        # Nothing to clear — idempotent success, no broker call needed.
        return {"status": "success", "changed": False, "pinned_account_id": None,
                "message": "No account was pinned; the bot auto-selects."}

    # Never silently re-route a live book.
    open_positions = await state.all_positions()
    if open_positions and not force:
        raise HTTPException(
            409,
            f"{len(open_positions)} position(s) are open ({', '.join(sorted(open_positions))}). "
            f"Switching the trading account would strand their resting stops at the "
            f"current account — close or flatten first, then re-pick.",
        )

    matched: Optional[Dict[str, Any]] = None
    account_list: List[Dict[str, Any]] = []
    if not clearing:
        # Validate against the broker's real list — a typo must fail HERE, not
        # at the next order placement with "Error 102: invalid Account Key".
        try:
            accounts_api = pyetrade.ETradeAccounts(
                CONSUMER_KEY, CONSUMER_SECRET,
                tokens["oauth_token"], tokens["oauth_token_secret"],
                dev=is_sandbox,
            )
            resp = await _etrade_call(accounts_api.list_accounts, resp_format="json", source="select_account")
        except Exception as e:
            logger.error(f"Account select failed to enumerate accounts: {e}")
            raise HTTPException(502, f"Could not read your E*TRADE accounts: {e}")
        account_list = (((resp or {}).get("AccountListResponse") or {}).get("Accounts") or {}).get("Account") or []
        if isinstance(account_list, dict):
            account_list = [account_list]
        for acct in account_list:
            if requested in {str(acct.get("accountId", "")), str(acct.get("accountIdKey", ""))}:
                matched = acct
                break
        if not matched:
            raise HTTPException(
                404,
                f"Account {requested} is not one of the {len(account_list)} account(s) "
                f"linked to this E*TRADE session.",
            )
        if str(matched.get("accountStatus", "")).upper() == "CLOSED":
            raise HTTPException(400, f"Account {requested} is CLOSED at E*TRADE and cannot be traded.")

    # Persist the pin by ACCOUNT ID (stable and human-recognisable); the opaque
    # accountIdKey is re-resolved from it on the next order.
    pin_value = str(matched.get("accountId") or requested).strip() if matched else None
    await _save_pinned_account(pin_value)

    resolved_key: Optional[str] = None
    try:
        resolved_key = await _resolve_account_id_key(tokens)
    except Exception as e:
        logger.warning(f"Account select: re-resolution failed (will retry on next use): {e}")

    acct_id = str((matched or {}).get("accountId") or "").strip()
    logger.info(
        f"📌 Trading account {'pinned to ****' + acct_id[-4:] if acct_id else 'pin cleared (auto-select)'}"
        f"{' [forced with open positions]' if (open_positions and force) else ''}"
    )
    await alerts.send(
        "info", "account_pin_changed",
        (f"Trading account pinned to ****{acct_id[-4:]} "
         f"({(matched or {}).get('accountDesc', 'n/a')}) from the app."
         if pin_value else
         "Trading account pin cleared — the bot will auto-select again."),
        dedupe_key=f"acctpin:set:{pin_value or 'cleared'}",
    )

    return {
        "status": "success",
        "changed": pin_value != current_pin,
        "pinned_account_id": pin_value,
        "account_id": acct_id or None,
        "account_id_key": str((matched or {}).get("accountIdKey") or "").strip() or None,
        "account_desc": (matched or {}).get("accountDesc") or (matched or {}).get("accountName") or None,
        "account_type": (matched or {}).get("accountType") or None,
        "account_status": (matched or {}).get("accountStatus") or None,
        "account_last4": acct_id[-4:] if acct_id else None,
        "resolved_account_id_key": resolved_key,
        "account_binding": _account_binding,
        "forced_with_open_positions": bool(open_positions and force),
    }


# ==================== RENEW ====================
@app.post("/etrade/auth/renew")
async def etrade_auth_renew(data: dict = Body(...)):
    try:
        access_token = data.get("access_token") or os.getenv("ETRADE_ACCESS_TOKEN")
        access_token_secret = data.get("access_token_secret") or os.getenv("ETRADE_ACCESS_TOKEN_SECRET")
        if not access_token or not access_token_secret:
            tokens = load_tokens()
            if tokens:
                access_token = access_token or tokens["oauth_token"]
                access_token_secret = access_token_secret or tokens["oauth_token_secret"]
        if not access_token or not access_token_secret:
            raise HTTPException(400, "Missing access tokens")
        try:
            accounts = pyetrade.ETradeAccounts(CONSUMER_KEY, CONSUMER_SECRET, access_token, access_token_secret, dev=is_sandbox)
            await asyncio.to_thread(accounts.list_accounts, resp_format="json")
            _mark_token_session(True, "renew check: tokens still valid")
            return {"status": "success", "message": "Tokens are still valid", "renewed": False}
        except Exception:
            logger.info("Current tokens appear invalid. Attempting renewal...")
        auth_manager = pyetrade.ETradeAccessManager(CONSUMER_KEY, CONSUMER_SECRET, access_token, access_token_secret)
        renewed = await _etrade_call(auth_manager.renew_access_token, source="token_renew")
        if renewed:
            save_tokens(auth_manager.oauth_token, auth_manager.oauth_token_secret)
            return {"status": "success", "message": "Tokens renewed successfully", "renewed": True}
        raise HTTPException(400, "Token renewal failed")
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Renew failed: {e}")
        if _looks_like_auth_failure(e):
            _mark_token_session(False, "token renewal rejected — hard-expired at midnight ET, relink required")
        raise HTTPException(500, detail="Renewal failed")


async def _forget_persisted_tokens() -> bool:
    """Delete the persisted access-token row so a disconnect survives a restart."""
    if not async_session:
        return False
    try:
        async with async_session() as session:
            async with session.begin():
                row = await session.get(ETradeSessionState, "active_tokens")
                if row is not None:
                    await session.delete(row)
        return True
    except Exception as e:
        logger.warning(f"could not delete persisted tokens on disconnect: {e}")
        return False


@app.post("/etrade/disconnect")
async def etrade_disconnect():
    """Fully unlink the broker session.

    Clearing only the in-memory token left three things behind: the persisted
    DB row (so `preload_tokens()` silently RE-LINKED the account on the next
    restart/redeploy), the resolved account binding still shown by /status, and
    a `token_valid: true` session flag — i.e. the app could keep reporting a
    trusted live session for an account the user had just disconnected.
    """
    global _current_tokens, _resolved_account_id_key, _account_binding
    _current_tokens = None
    _resolved_account_id_key = None
    _account_binding = None
    _mark_token_session(False, "account disconnected by user")
    _parked_signals.clear()
    purged = await _forget_persisted_tokens()
    logger.info(f"User requested account disconnect (persisted tokens purged={purged})")
    return {
        "status": "success",
        "message": "Disconnect request received",
        "linked": False,
        "persisted_tokens_cleared": purged,
    }


# ==================== RESTORE ====================
@app.post("/etrade/auth/restore")
async def etrade_auth_restore(data: dict = Body(...)):
    """Adopt access tokens the APP persisted locally so the session self-heals
    after a bot cold start/redeploy without a full OAuth relink. The tokens
    are validated against E*TRADE BEFORE being adopted — dead tokens (e.g.
    expired at midnight ET) can never clobber a working session, and the app
    gets a clean 401 telling it a fresh relink is required."""
    token = str(data.get("oauth_token") or data.get("access_token") or "").strip()
    token_secret = str(data.get("oauth_token_secret") or data.get("access_token_secret") or "").strip()
    if not token or not token_secret:
        raise HTTPException(400, "Missing oauth_token / oauth_token_secret")
    current = load_tokens()
    if current and current.get("oauth_token") == token and current.get("oauth_token_secret") == token_secret:
        return {"status": "success", "restored": False, "linked": True, "env": ENV,
                "message": "Session already active with these tokens"}
    try:
        accounts = pyetrade.ETradeAccounts(CONSUMER_KEY, CONSUMER_SECRET, token, token_secret, dev=is_sandbox)
        await asyncio.to_thread(accounts.list_accounts, resp_format="json")
    except Exception as e:
        logger.warning(f"auth/restore rejected — pushed tokens invalid: {e}")
        raise HTTPException(401, "E*TRADE rejected the restored tokens (expired at midnight ET or revoked) — a fresh relink is required")
    save_tokens(token, token_secret)
    logger.info("✅ Session restored from app-persisted tokens")
    return {"status": "success", "restored": True, "linked": True, "env": ENV}


# ==================== QUOTE ====================
# Quote status values E*TRADE stamps on every QuoteData entry. Anything that
# is not explicitly realtime is treated as delayed by the app's live gate.
_REALTIME_QUOTE_STATUSES = {"REALTIME", "EH_REALTIME"}


def normalize_quote_response(resp: Dict[str, Any]) -> Dict[str, Any]:
    """Flatten E*TRADE's QuoteResponse into the flat contract the app parses.

    THE BUG THIS FIXES (audit 2026-08-15): this endpoint returned E*TRADE's raw
    payload — {"QuoteResponse": {"QuoteData": [{"All": {"lastTrade": ...}}]}} —
    while the app read `json.quotes` and snake_case fields (`price`,
    `change_percent`, `quote_status`). `json.quotes` was therefore ALWAYS
    undefined, so the app parsed ZERO broker quotes on every single call, logged
    "E*TRADE returned 0/N real-time broker quotes", recorded a feed failure,
    engaged the cooldown gate, and silently fell through to TradingView / Yahoo /
    Stooq.

    The consequence: the broker's real-time feed — the whole point of linking the
    account, and the only feed that matches what the order will actually fill
    against — has never once priced a decision. Every displayed price, every
    score, and every dispatched entry ran on a fallback feed, and the app's
    `isEtradeDelayed` check could never fire because there were no quotes to
    check.

    `quote_time_utc` is passed through so the app can age a quote against the
    BROKER'S OWN timestamp rather than against when the HTTP call returned — a
    stalled feed that keeps re-serving the same 09:47 print is otherwise
    indistinguishable from a live one.

    Pure function: no I/O, unit-tested in test_bot_fixes.py.
    """
    def num(node: Dict[str, Any], key: str) -> float:
        val = node.get(key)
        if val is None or val == "":
            return 0.0
        try:
            f = float(val)
        except (TypeError, ValueError):
            return 0.0
        return f if math.isfinite(f) else 0.0

    data = ((resp or {}).get("QuoteResponse") or {}).get("QuoteData")
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list):
        return {"quotes": []}

    quotes: List[Dict[str, Any]] = []
    for entry in data:
        if not isinstance(entry, dict):
            continue
        all_q = entry.get("All") or {}
        product = entry.get("Product") or {}
        symbol = str(product.get("symbol") or entry.get("symbol") or "").upper().strip()
        price = num(all_q, "lastTrade")
        # A row with no last trade cannot price anything; dropping it here means
        # the app sees an honest gap instead of a $0.00 quote.
        if not symbol or price <= 0:
            continue
        status = str(entry.get("quoteStatus") or "").upper().strip()
        previous_close = num(all_q, "previousClose")
        change = num(all_q, "changeClose")
        change_pct = num(all_q, "changeClosePercentage")
        # Derive whichever of the pair the broker omitted rather than shipping a
        # confident zero — a 0.00% change on a moving stock reads as "flat tape".
        if change == 0.0 and previous_close > 0:
            change = round(price - previous_close, 4)
        if change_pct == 0.0 and previous_close > 0:
            change_pct = round((change / previous_close) * 100, 4)
        quotes.append({
            "symbol": symbol,
            "price": price,
            "previous_close": previous_close,
            "change": change,
            "change_percent": change_pct,
            "open": num(all_q, "open"),
            "high": num(all_q, "high"),
            "low": num(all_q, "low"),
            "volume": num(all_q, "totalVolume"),
            "bid": num(all_q, "bid"),
            "ask": num(all_q, "ask"),
            "market_cap": num(all_q, "marketCap"),
            "name": str(all_q.get("companyName") or product.get("symbol") or symbol),
            # Empty status is reported as-is: the app treats unknown as delayed,
            # which is the safe direction. Never invent "REALTIME".
            "quote_status": status,
            "realtime": status in _REALTIME_QUOTE_STATUSES,
            "quote_time_utc": entry.get("dateTimeUTC"),
        })
    return {"quotes": quotes}


@app.get("/etrade/quote")
async def get_quotes(symbols: str = Query(...)):
    tokens = load_tokens()
    if not tokens:
        raise HTTPException(401, "E*TRADE account not linked")
    market = pyetrade.ETradeMarket(CONSUMER_KEY, CONSUMER_SECRET, tokens["oauth_token"], tokens["oauth_token_secret"], dev=is_sandbox)
    symbol_list = [s.strip() for s in symbols.split(",") if s.strip()]
    try:
        # Exponential backoff covers throttles, 5xx AND the post-renewal 401s
        # the old hand-rolled fixed-sleep loop existed for.
        raw = await _etrade_call(market.get_quote, symbol_list, resp_format="json", source="quote")
        normalized = normalize_quote_response(raw)
        delayed = [q["symbol"] for q in normalized["quotes"] if not q["realtime"]]
        if delayed:
            logger.warning(
                f"E*TRADE served DELAYED quotes for {len(delayed)} symbol(s) "
                f"({', '.join(delayed[:5])}) — the real-time market data agreement "
                f"is not accepted on this account; the app will refuse live entries priced off them"
            )
        # Raw payload stays available for debugging without changing the contract.
        return {**normalized, "raw": raw} if DEBUG_QUOTES else normalized
    except Exception as e:
        raise HTTPException(500, detail=str(e))


@app.get("/etrade/positions")
async def get_etrade_positions(refresh: bool = Query(False)):
    """THE ACCOUNT ITSELF — what E*TRADE holds, not what the bot remembers.

    Until now the only position data leaving this server was `state.all_positions()`
    on /status: the bot's own record of trades the bot itself placed. The app
    labelled that "broker truth", but it cannot see a manual trade, a leftover
    lot from a crashed process, a stop that filled unobserved, or a partial-close
    remainder — precisely the positions with no stop, no trail and no risk
    accounting behind them.

    The real portfolio was already being fetched every reconcile pass and then
    discarded. This serves the published snapshot, and `?refresh=true` pays for
    a live round-trip when the caller needs the account as of this second.
    """
    if not load_tokens():
        raise HTTPException(401, "E*TRADE account not linked")

    if refresh:
        try:
            portfolio_resp, orders_resp = await asyncio.gather(
                _reconcile_fetch_portfolio(), _reconcile_fetch_orders(),
            )
            snapshot = reconciliation.build_account_snapshot(
                reconciliation.parse_broker_positions(portfolio_resp),
                reconciliation.parse_open_orders(orders_resp),
                await state.all_positions(),
                await state.all_guards(),
                balances=await _fetch_broker_balance(),
                now=time.time(),
            )
            await state.set(reconciliation.ACCOUNT_SNAPSHOT_KEY, json.dumps(snapshot))
            return {"source": "live", "age_seconds": 0.0, **snapshot}
        except Exception as e:
            logger.warning(f"live positions fetch failed, serving cache: {e}")

    snapshot = await _load_account_snapshot()
    if snapshot is None:
        # No pass has completed yet. Say so plainly rather than returning an
        # empty position list, which reads identically to a flat account.
        return {
            "source": "none",
            "age_seconds": None,
            "positions": [],
            "open_orders": [],
            "untracked": [],
            "ghosts": [],
            "unprotected": [],
            "counts": {},
            "error": "no reconciliation pass has published an account snapshot yet",
        }
    return {"source": "snapshot", "age_seconds": _snapshot_age(snapshot), **snapshot}


async def _load_account_snapshot() -> Optional[dict]:
    """Last published broker-truth snapshot, or None when none exists."""
    try:
        raw = await state.get(reconciliation.ACCOUNT_SNAPSHOT_KEY)
        if not raw:
            return None
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else None
    except Exception as e:
        logger.debug(f"account snapshot read failed: {e}")
        return None


def _snapshot_age(snapshot: Optional[dict]) -> Optional[float]:
    """Seconds since the snapshot was built. A consumer that cannot tell a
    2-second-old view from a 6-hour-old one will trust a stale account."""
    if not snapshot:
        return None
    try:
        epoch = float(snapshot.get("epoch") or 0)
    except (TypeError, ValueError):
        return None
    if epoch <= 0:
        return None
    return round(max(time.time() - epoch, 0.0), 1)


@app.post("/app/heartbeat")
async def app_heartbeat(data: dict = Body(default={})):
    """The app tells the server it is alive, armed, and what it believes.

    The bot trades autonomously — the scanner places real orders with nobody
    watching. It had no way to know whether the operator's app was open, armed,
    or running in a different money mode than the server, so an app showing
    PAPER while the server traded LIVE was undetectable from either side.
    """
    beat = {
        "ts": _utcnow().isoformat(),
        "received_epoch": time.time(),
        "armed": bool(data.get("armed")) if isinstance(data.get("armed"), bool) else None,
        "mode": str(data.get("mode") or "").lower() or None,
        "app_version": str(data.get("app_version") or "") or None,
        "open_positions": data.get("open_positions"),
        "symbols": data.get("symbols") if isinstance(data.get("symbols"), list) else None,
        "daily_pnl_usd": data.get("daily_pnl_usd"),
    }
    try:
        await state.set(APP_HEARTBEAT_KEY, json.dumps(beat), ex=APP_HEARTBEAT_TTL_SECONDS)
    except Exception as e:
        logger.warning(f"app heartbeat store failed: {e}")
        raise HTTPException(500, detail="heartbeat not stored")

    link = await _app_link_snapshot()
    # A divergence found here is a real safety event: the operator and the
    # server disagree about money. Alert once per kind (deduped), never on
    # every 60-second beat.
    for div in link.get("divergences") or []:
        if div.get("severity") != "critical":
            continue
        try:
            await alerts.send(
                "critical", f"app_link_{div['kind']}", div["detail"],
                dedupe_key=f"applink:{div['kind']}",
            )
        except Exception:
            logger.debug("app link alert delivery failed", exc_info=True)

    return {"ok": True, "bot_version": BOT_VERSION, "link": link}


# ==================== DATABASE ====================
async def init_db():
    """Initialize the async DB engine used for token persistence.

    FIX FOR THE DAILY RELINK CYCLE: hosting platforms (Railway, Render, …)
    provide DATABASE_URL as "postgres://…" or "postgresql://…" WITHOUT the
    async driver suffix. create_async_engine requires asyncpg in the URL —
    previously the raw URL was passed straight through, engine creation
    failed silently, async_session stayed None, and tokens only lived in RAM
    (lost on every container restart → forced daily relink). This normalizes
    the URL to postgresql+asyncpg:// (preserving credentials/host/params),
    enables pool_pre_ping for stale-connection recovery, and logs the exact
    hostname/credential problem when the connection still fails before
    falling back to SQLite so the bot keeps running.
    """
    global engine, async_session
    engine = None
    async_session = None

    if DATABASE_URL:
        url = DATABASE_URL.strip()
        original_url_for_log = url
        # Normalize common postgres URLs to the asyncpg driver.
        if url.startswith("postgres://"):
            url = "postgresql+asyncpg://" + url[len("postgres://"):]
        elif url.startswith("postgresql://") and "+asyncpg" not in url:
            url = "postgresql+asyncpg://" + url[len("postgresql://"):]
        if url.startswith("postgresql+") and "+asyncpg" not in url:
            # e.g. postgresql+psycopg2://… → force asyncpg
            _prefix, rest = url.split("://", 1)
            url = "postgresql+asyncpg://" + rest

        try:
            import asyncpg  # noqa: F401  # ensure the driver is installed
            engine = create_async_engine(
                url,
                echo=False,
                pool_pre_ping=True,  # detect/recover stale cloud-DB connections
            )
            safe_log = url.split("@", 1)[1] if "@" in url else url
            logger.info(f"✅ DATABASE_URL normalized — postgres engine created @ {safe_log}")
        except ImportError:
            logger.warning(
                "asyncpg not installed — cannot use postgres DATABASE_URL "
                "(pip install asyncpg). Tokens will use the SQLite fallback "
                "and will NOT persist across restarts."
            )
            engine = None
        except Exception as conn_err:
            masked = original_url_for_log.split("@")[-1] if "@" in original_url_for_log else original_url_for_log
            logger.error(
                f"❌ Database connection FAILED (wrong hostname, port, credentials, "
                f"SSL, or network issue): {conn_err} | DATABASE_URL host (masked): {masked}"
            )
            logger.warning("→ Falling back to SQLite — tokens will NOT survive restarts until DATABASE_URL is fixed")
            engine = None

    if engine is None:
        try:
            engine = create_async_engine("sqlite+aiosqlite:///etrade_cache.db", echo=False)
        except Exception as sqlite_err:
            logger.error(f"Even the SQLite fallback failed: {sqlite_err}")
            engine = None
            async_session = None
            return  # bot continues without DB; tokens won't persist at all

    try:
        async_session = sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)
        async with engine.begin() as conn:
            await conn.run_sync(Base.metadata.create_all)
        logger.info("✅ Database ready (tokens will persist across restarts)")
    except Exception as e:
        logger.error(f"Database table creation / sessionmaker error: {e}")
        async_session = None  # downstream checks must see the failure


# ==================== DURABLE STATE (Postgres write-through) ====================
# The production deployment runs LIVE with no REDIS_URL — every container
# restart erased open positions, ratcheted trails, today's realized P&L (the
# daily loss limit's memory), the kill switch, AND the "immutable" trade ledger
# (the JSONL file lives on an ephemeral disk; it rebooted with 0 records).
# DATABASE_URL already exists for token persistence, so the same engine now
# backs a key-value table the StateStore writes through to in memory mode, and
# a ledger table that mirrors every hash-chained record.

_STATE_TABLE_SQL = (
    "CREATE TABLE IF NOT EXISTS bot_state ("
    "key TEXT PRIMARY KEY, "
    "kind TEXT NOT NULL, "
    "value TEXT NOT NULL, "
    "updated_at TEXT)"
)
_LEDGER_TABLE_SQL = (
    "CREATE TABLE IF NOT EXISTS bot_ledger ("
    "hash TEXT PRIMARY KEY, "
    "seq BIGINT NOT NULL, "
    "line TEXT NOT NULL)"
)


class PgStatePersistence:
    """Duck-typed persistence adapter for StateStore's durable memory mode.
    All methods are best-effort from the caller's perspective — StateStore
    swallows and logs adapter failures so a DB blip never blocks an order."""

    def __init__(self, db_engine) -> None:
        self._engine = db_engine

    async def save(self, key: str, kind: str, value: str) -> None:
        async with self._engine.begin() as conn:
            await conn.execute(
                sql_text(
                    "INSERT INTO bot_state (key, kind, value, updated_at) "
                    "VALUES (:key, :kind, :value, :ts) "
                    "ON CONFLICT (key) DO UPDATE SET "
                    "kind = :kind, value = :value, updated_at = :ts"
                ),
                {"key": key, "kind": kind, "value": value, "ts": _utcnow().isoformat()},
            )

    async def delete(self, key: str) -> None:
        async with self._engine.begin() as conn:
            await conn.execute(sql_text("DELETE FROM bot_state WHERE key = :key"), {"key": key})

    async def load_all(self):
        async with self._engine.connect() as conn:
            result = await conn.execute(sql_text("SELECT key, kind, value FROM bot_state"))
            return [(row[0], row[1], row[2]) for row in result.fetchall()]


_state_persistence: Optional[PgStatePersistence] = None


async def _init_durable_state() -> Optional[PgStatePersistence]:
    """Create the durable-state tables and return the adapter — None when the
    DB is unavailable (the store then falls back to plain memory, loudly)."""
    global _state_persistence
    if engine is None:
        logger.warning("durable state unavailable — no database engine")
        return None
    try:
        async with engine.begin() as conn:
            await conn.execute(sql_text(_STATE_TABLE_SQL))
            await conn.execute(sql_text(_LEDGER_TABLE_SQL))
        _state_persistence = PgStatePersistence(engine)
        return _state_persistence
    except Exception as e:
        logger.error(f"durable state init failed — falling back to plain memory: {e}")
        return None


async def _ledger_mirror(seq: int, rec_hash: str, line: str) -> None:
    """Mirror one ledger record to Postgres (PK on hash → naturally idempotent)."""
    if engine is None:
        return
    async with engine.begin() as conn:
        await conn.execute(
            sql_text(
                "INSERT INTO bot_ledger (hash, seq, line) VALUES (:hash, :seq, :line) "
                "ON CONFLICT (hash) DO NOTHING"
            ),
            {"hash": rec_hash, "seq": int(seq), "line": line},
        )


async def _restore_ledger_from_db() -> None:
    """Rebuild the local JSONL ledger from the Postgres mirror when the local
    file was wiped by a redeploy. Never overwrites a non-empty local file."""
    if engine is None:
        return
    try:
        async with engine.connect() as conn:
            result = await conn.execute(sql_text("SELECT line FROM bot_ledger ORDER BY seq"))
            lines = [row[0] for row in result.fetchall()]
        if lines:
            trade_ledger.restore_lines(TRADE_LEDGER_FILE, lines)
    except Exception as e:
        logger.error(f"ledger restore from DB failed (non-fatal): {e}")


# ==================== ACCOUNT KEY RESOLUTION ====================
async def _load_pinned_account() -> Optional[str]:
    """Read the user's pinned account id from the state store into memory.

    Called at startup and before every resolution so a pin set on ANOTHER
    worker is honoured here too (the cached key is per-process, the pin is not).
    """
    global _pinned_account_id
    try:
        raw = await state.get(ACCOUNT_PIN_KEY)
    except Exception as e:
        logger.warning(f"could not read pinned account: {e}")
        return _pinned_account_id
    pinned = (raw or "").strip() or None
    if pinned != _pinned_account_id:
        logger.info(f"Pinned trading account is now {pinned or 'unset (auto-select)'}")
        # A different pin invalidates this process's cached accountIdKey.
        global _resolved_account_id_key
        _resolved_account_id_key = None
    _pinned_account_id = pinned
    return _pinned_account_id


async def _save_pinned_account(account_id: Optional[str]) -> None:
    """Persist (or clear) the pinned account and drop the cached key."""
    global _pinned_account_id, _resolved_account_id_key, _account_binding
    value = (account_id or "").strip() or None
    if value:
        await state.set(ACCOUNT_PIN_KEY, value)
    else:
        await state.delete(ACCOUNT_PIN_KEY)
    _pinned_account_id = value
    # Force re-resolution so the very next order routes to the new account.
    _resolved_account_id_key = None
    _account_binding = None


async def _resolve_account_id_key(tokens: Dict[str, str]) -> str:
    """Return the E*TRADE accountIdKey required by order/balance APIs.

    E*TRADE rejects the plain account number with
    "Error 102: Please enter valid Account Key". The real accountIdKey is an
    opaque value only obtainable from /accounts/list. If ETRADE_ACCOUNT_ID is
    set, match it against BOTH accountId and accountIdKey; otherwise (or if no
    match) fall back to the first ACTIVE account. Cached per linked session.

    Precedence: user pin (POST /etrade/account/select) → ETRADE_ACCOUNT_ID →
    first ACTIVE → first. The pin wins because it is a deliberate in-app choice
    the user can see and change; the env var needs a redeploy.
    """
    global _resolved_account_id_key
    # Refresh the pin FIRST — a pin set on another worker must invalidate this
    # process's cached key before we return it.
    pinned = await _load_pinned_account()
    if _resolved_account_id_key:
        return _resolved_account_id_key

    accounts_api = pyetrade.ETradeAccounts(
        CONSUMER_KEY, CONSUMER_SECRET,
        tokens["oauth_token"], tokens["oauth_token_secret"],
        dev=is_sandbox,
    )
    resp = await _etrade_call(accounts_api.list_accounts, resp_format="json", source="resolve_account")
    account_list = (((resp or {}).get("AccountListResponse") or {}).get("Accounts") or {}).get("Account") or []
    if isinstance(account_list, dict):
        account_list = [account_list]
    if not account_list:
        raise Exception("E*TRADE returned no accounts for the linked session")

    target = (TARGET_ACCOUNT_ID or "").strip()
    chosen = None
    matched = False
    source = "fallback"
    if pinned:
        for acct in account_list:
            if pinned in {str(acct.get("accountId", "")), str(acct.get("accountIdKey", ""))}:
                chosen = acct
                matched = True
                source = "pinned"
                break
        if not chosen:
            logger.warning(
                f"⚠️ Pinned account {pinned} matches none of the {len(account_list)} "
                f"linked account(s) — the pin is stale (account closed or a different "
                f"E*TRADE login is linked). Falling back."
            )
    if not chosen and target:
        for acct in account_list:
            if target in {str(acct.get("accountId", "")), str(acct.get("accountIdKey", ""))}:
                chosen = acct
                matched = True
                source = "env"
                break
        if not chosen:
            logger.warning(
                f"⚠️ ETRADE_ACCOUNT_ID does not match any accountId/accountIdKey "
                f"among {len(account_list)} account(s) — falling back to first ACTIVE account"
            )
    if not chosen:
        chosen = next(
            (a for a in account_list if str(a.get("accountStatus", "")).upper() == "ACTIVE"),
            account_list[0],
        )

    key = chosen.get("accountIdKey")
    if not key:
        raise Exception("Matched E*TRADE account has no accountIdKey")
    _resolved_account_id_key = str(key)
    acct_id = str(chosen.get("accountId", ""))
    logger.info(f"✅ Resolved accountIdKey for account ****{acct_id[-4:]} (desc={chosen.get('accountDesc', 'n/a')})")

    # Account-binding transparency. Real orders route to whichever account was
    # resolved here — if that was a FALLBACK pick (configured id matched
    # nothing, or no id configured at all among several accounts), the user is
    # trading an account they never named. Record it so /status can surface it
    # and fire a one-shot alert instead of leaving it buried in a log line.
    global _account_binding
    _account_binding = {
        "configured": target or None,
        "pinned": pinned,
        "source": source,
        "resolved_account_id": acct_id or None,
        "resolved_account_id_key": _resolved_account_id_key,
        "resolved_last4": acct_id[-4:] if acct_id else None,
        "resolved_description": chosen.get("accountDesc") or None,
        "account_count": len(account_list),
        "matched_configured": matched,
        "fallback": (not matched),
        "ambiguous": (not matched) and len(account_list) > 1,
        "pin_stale": bool(pinned) and source != "pinned",
    }
    if pinned and source != "pinned":
        await alerts.send(
            "warning", "account_pin_stale",
            f"Pinned account {pinned} is not among the {len(account_list)} linked "
            f"accounts — orders route to ****{acct_id[-4:] or '????'} instead. "
            f"Re-pick the account in the app.",
            dedupe_key=f"acctpin:stale:{pinned}",
        )
    elif source == "pinned":
        # Deliberate in-app choice — nothing ambiguous to warn about.
        pass
    elif target and not matched:
        await alerts.send(
            "warning", "account_binding_mismatch",
            f"ETRADE_ACCOUNT_ID ({target}) matched none of {len(account_list)} linked accounts — "
            f"orders will route to ****{acct_id[-4:] or '????'} ({chosen.get('accountDesc', 'n/a')}). "
            f"Fix ETRADE_ACCOUNT_ID or clear it to silence this.",
            dedupe_key=f"acctbind:{target}:{acct_id}",
        )
    elif not target and len(account_list) > 1:
        await alerts.send(
            "warning", "account_binding_unset",
            f"ETRADE_ACCOUNT_ID is not set and {len(account_list)} accounts are linked — "
            f"orders route to the first ACTIVE one (****{acct_id[-4:] or '????'}, "
            f"{chosen.get('accountDesc', 'n/a')}). Pick the account in the app "
            f"(E*TRADE Account → Trading account) to pin it.",
            dedupe_key=f"acctbind:unset:{acct_id}",
        )
    return _resolved_account_id_key


# ==================== SAFETY (distributed circuit breaker) ====================
async def _breaker_is_open() -> bool:
    return await state.exists(BREAKER_OPEN_KEY)


async def _reset_circuit_breaker(reason: str) -> None:
    try:
        if await state.exists(BREAKER_OPEN_KEY):
            logger.info(f"🔓 Circuit breaker reset — {reason}")
            await alerts.send("info", "circuit_breaker_reset",
                              f"Circuit breaker reset — {reason}",
                              dedupe_key="breaker_reset")
        await state.delete(BREAKER_OPEN_KEY, BREAKER_FAILURES_KEY)
    except Exception as e:
        logger.warning(f"breaker reset failed: {e}")


async def _record_api_success() -> None:
    """A successful broker call closes the failure streak."""
    await state.delete(BREAKER_FAILURES_KEY)


async def _record_api_failure(source: str, error: str) -> None:
    """Count a broker/API failure toward the DISTRIBUTED breaker; trip it
    (TTL = cooldown → auto-reset) and alert when the threshold is crossed."""
    try:
        fails = await state.incr(BREAKER_FAILURES_KEY, ex=BREAKER_FAILURE_WINDOW_SECONDS)
    except Exception as e:
        logger.warning(f"breaker failure count error: {e}")
        return
    logger.warning(f"⚠️ API failure {fails}/{MAX_CONSECUTIVE_FAILURES} ({source}): {error}")
    if fails >= MAX_CONSECUTIVE_FAILURES and not await state.exists(BREAKER_OPEN_KEY):
        await state.set(BREAKER_OPEN_KEY, source, ex=CIRCUIT_BREAKER_COOLDOWN_SECONDS)
        logger.error(
            f"⛔ Circuit breaker OPEN after {fails} consecutive API failures ({source}) "
            f"— all workers halted; auto-resets in {CIRCUIT_BREAKER_COOLDOWN_SECONDS // 60} minutes"
        )
        await trade_ledger.record("circuit_breaker_tripped", {
            "source": source, "failures": fails, "last_error": str(error)[:300],
            "cooldown_seconds": CIRCUIT_BREAKER_COOLDOWN_SECONDS,
        })
        await alerts.send(
            "critical", "circuit_breaker_tripped",
            f"Order placement HALTED after {fails} consecutive API failures ({source}): {error}",
            dedupe_key="breaker_trip",
        )


# Failures that are the BOT'S OWN verdict, not the broker's. These must never
# count toward the API circuit breaker: five benign rejections in a row (five
# signals arriving after hours, five duplicate tickers, five fail-closed sizing
# refusals) used to trip the breaker and halt ALL placement — including
# protective exits — for the full cooldown.
_LOCAL_REFUSAL_MARKERS = (
    "kill switch active",
    "market closed",
    "order lock busy",
    "fail-closed sizing",
    "close refused",
    "insufficient funds:",  # our own pre-flight refusal (broker's 8400 has no colon)
    "tokens not set",
    "missing strike or expiration",
    "refusing to double-sell",
    # The breaker's own refusal counted as a broker failure, so every attempt
    # while it was open refreshed the failure window and re-tripped it the
    # moment it closed — a breaker that latched itself open.
    "circuit breaker open",
    # Intent-preserving reprice rejection is OUR verdict on OUR estimate.
    "refusing to multiply",
    "short equity entries are not supported",
)


def _is_local_refusal(err: str) -> bool:
    """True when a failure came from this bot's own gating rather than from a
    broker API call — it says nothing about broker health."""
    low = str(err).lower()
    return any(marker in low for marker in _LOCAL_REFUSAL_MARKERS)


def _raw_place_fallback_safe(status_code: Optional[int], is_connect_error: bool) -> bool:
    """True ONLY when a raw-path order failure provably happened BEFORE the
    broker could accept the order, making a pyetrade re-place safe.

    - connect error: the request never reached E*TRADE → safe to re-send.
    - 4xx: the broker's own verdict — the order was REJECTED, not placed →
      safe to re-send through the fallback transport.
    - anything else (read timeout after send, 5xx on place.json): the order
      MAY have been accepted. Re-placing here was a double-fill machine —
      two live orders, one tracked. Ambiguity must surface as a failure and
      let the reconciler heal whatever state actually resulted.
    """
    if is_connect_error:
        return True
    try:
        code = int(status_code or 0)
    except (TypeError, ValueError):
        return False
    return 400 <= code < 500


def plan_option_route(action: str, is_close: bool, requested_right: str) -> Tuple[str, str]:
    """Route an option payload by INTENT, never by the action verb.

    Returns (order_action, call_put). Every option this bot opens is LONG —
    a bearish signal expresses direction through the PUT right, not a short
    sale. The old `action != "BUY"` test sent a SELL ENTRY down the CLOSE
    flow: it cancelled the ticker's resting protective stop, marked the guard
    closed_by_app, and placed SELL_CLOSE on a contract the account doesn't
    even hold (broker rejection at best, a naked short PUT at worst).
    """
    right = str(requested_right or "CALL").upper()
    right = "CALL" if right.startswith("C") else "PUT"
    if is_close:
        return "SELL_CLOSE", right
    if str(action or "BUY").upper() in {"SELL", "SHORT"}:
        return "BUY_OPEN", "PUT"
    return "BUY_OPEN", right


def _close_cover_qty(pos: Optional[dict], requested: Any) -> int:
    """Quantity a close order must cover: the broker-synced TRACKED size when
    one exists, else the caller's number.

    The payload's contract count is guaranteed stale whenever the entry was
    resized (intent-preserving reprice, 8400 funds clamp) and defaults to 1
    when the app omits it. Closing the payload's count either leaves a
    remainder live at the broker — untracked, unstopped, invisible — or
    oversells into a naked short. The equity close path already reads the
    tracked size; this gives options the same discipline.
    """
    try:
        tracked = int((pos or {}).get("filled_qty") or (pos or {}).get("qty") or 0)
    except (TypeError, ValueError):
        tracked = 0
    if tracked > 0:
        return tracked
    try:
        return max(1, int(requested or 0))
    except (TypeError, ValueError):
        return 1


def plan_scale_out(qty: Any, first_target_pct: float = None) -> Dict[str, Any]:
    """Split a position into a partial to bank and a runner to let work.

    THE CAPTURE PROBLEM. Measured on real broker fills (2026-08-11/12):

        PLTR 2c  +21.18%   IWM 3c  -1.93%   AAPL 1c -11.87%
        NVDA 4c   +6.48%   SPY 1c -14.73%

    Winners averaged +13.8%, losers -9.5%, average hold SEVEN MINUTES with
    exits recorded at 0m. Every winner was closed in FULL at the first exit,
    so no winner was ever big enough to pay for the losers. At the journal's
    17% win rate that is -5.5% of expectancy per trade: a daily dollar target
    is unreachable by arithmetic, not by effort.

    Banking half at the capture the book actually achieves, while the rest
    runs on the ratcheting trail, is the only lever that raises the average
    winner without touching win rate or size. The extra contract on an odd lot
    goes to the RUNNER — the tail is where the outsized winner comes from.

    A single contract cannot be split; the plan says so explicitly rather than
    silently doing nothing, because that is an argument for sizing entries in
    even lots when risk allows.
    """
    try:
        n = max(0, int(qty or 0))
    except (TypeError, ValueError):
        n = 0
    target = float(first_target_pct if first_target_pct is not None else SCALE_OUT_FIRST_TARGET_PCT)
    if n < 2:
        return {
            "enabled": False,
            "scale_qty": 0,
            "runner_qty": n,
            "first_target_pct": target,
            "reason": (
                f"single contract — all-or-nothing position, every winner is capped at the "
                f"first exit (2+ contracts would bank half at +{target:.1f}% and run the rest)"
            ),
        }
    scale_qty = n // 2
    return {
        "enabled": True,
        "scale_qty": scale_qty,
        "runner_qty": n - scale_qty,
        "first_target_pct": target,
        "reason": (
            f"bank {scale_qty} of {n} at +{target:.1f}% premium, run {n - scale_qty} on the trail"
        ),
    }


def plan_profit_lock(realized_usd: Any, target_usd: float = None,
                     min_cushion: float = None) -> Dict[str, Any]:
    """Largest loss that still leaves the day at or above the profit target.

    Giving a made day back to chase a bigger one is the most expensive habit a
    daily-target system can form. Once the target is banked the only trades
    worth taking are ones whose FULL loss still finishes at target.
    """
    target = float(target_usd if target_usd is not None else DAILY_PROFIT_TARGET_USD)
    cushion_floor = float(min_cushion if min_cushion is not None else PROFIT_LOCK_MIN_CUSHION_USD)
    try:
        realized = float(realized_usd or 0.0)
    except (TypeError, ValueError):
        realized = 0.0
    cushion = realized - target
    if target <= 0 or cushion <= 0:
        return {"locked": False, "max_risk_usd": 0.0, "cushion_usd": 0.0,
                "reason": "objective not banked — normal risk rules apply"}
    if cushion < cushion_floor:
        return {
            "locked": True, "max_risk_usd": 0.0, "cushion_usd": round(cushion, 2),
            "reason": (
                f"daily objective BANKED (${realized:,.0f} vs ${target:,.0f}) with only "
                f"${cushion:,.0f} of cushion — no further risk, the day is made"
            ),
        }
    return {
        "locked": False, "max_risk_usd": round(cushion, 2), "cushion_usd": round(cushion, 2),
        "reason": (
            f"daily objective BANKED (${realized:,.0f} vs ${target:,.0f}) — further risk "
            f"capped at ${cushion:,.0f} so a full loss still finishes at target"
        ),
    }


def plan_risk_budget(account_size: Any, realized_usd: Any, open_risk_usd: Any,
                     profit_lock_max_risk: Any = None,
                     loss_limit_pct: float = None) -> Dict[str, Any]:
    """The day's risk budget in DOLLARS — what replaced the trade-count cap.

    A trade count is not a risk control. Six trades at 1% risk is 6% of the
    account; twenty at 0.25% is 5%. The old cap allowed the first and refused
    the second, and on a day where the first six setups all worked it refused
    the seventh — the most valuable trade available.

    Two rules are load-bearing here:

      1. Realized losses AND committed open risk draw from the SAME budget.
         Counting only realized losses lets three open positions each risking 1%
         coexist with a 2% limit; the breach is then discovered at the close.
      2. Profits expand the budget at HALF credit, capped at +50% of the base.
         The cushion is real, but full credit is how a +$900 day becomes a
         −$200 day.

    Mirrors `services/riskBudget.ts` in the app. Fails toward LESS risk on any
    unreadable input — an unmeasurable budget must never read as a full one.
    """
    limit_pct = float(loss_limit_pct if loss_limit_pct is not None else DAILY_LOSS_LIMIT_PCT)

    def num(value: Any, default: float = 0.0) -> float:
        try:
            out = float(value if value is not None else default)
        except (TypeError, ValueError):
            return default
        return out if math.isfinite(out) else default

    account = max(0.0, num(account_size))
    base_budget = account * abs(limit_pct) / 100.0
    realized = num(realized_usd)

    # Rule 2: half credit on profits, capped at +50% of the base budget.
    credit = min(max(0.0, realized) * 0.5, base_budget * 0.5)
    budget = base_budget + credit

    # Rule 1: realized losses and open risk both consume it.
    used = max(0.0, -realized) + max(0.0, num(open_risk_usd))
    remaining = max(0.0, budget - used)

    # The profit lock is a CEILING on what remains, never an expansion of it.
    if profit_lock_max_risk is not None:
        remaining = min(remaining, max(0.0, num(profit_lock_max_risk)))

    return {
        "budget_usd": round(budget, 2),
        "base_budget_usd": round(base_budget, 2),
        "used_usd": round(used, 2),
        "remaining_usd": round(remaining, 2),
        "utilization_pct": round(min(100.0, (used / budget * 100.0) if budget > 0 else 100.0), 2),
        "reason": (
            f"${remaining:,.0f} of ${budget:,.0f} risk budget left — there is no trade-count "
            f"cap, dollars are the limit"
        ),
    }


def assess_entry_cost(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Round-trip trading cost for the payload's contract, as % of premium.

    Charges the FULL round trip: the bid/ask spread crossed on the way out (a
    protective stop is a market order in disguise) plus commission both ways.
    Counting only the entry under-reports the real cost by roughly half.

    Cheap contracts are the trap: ${COMMISSION_PER_CONTRACT} each way on a $0.30
    option is 4.3% before the spread is considered. Returns `prohibitive` only
    when a real premium was priced — an unpriced payload is not evidence of a
    bad contract, and refusing it here would block the connectivity test.
    """
    def num(key: str) -> float:
        try:
            value = float(payload.get(key) or 0)
        except (TypeError, ValueError):
            return 0.0
        return value if math.isfinite(value) else 0.0

    premium = num("limit_price") or num("premium") or num("contract_premium")
    if premium <= 0:
        return {"prohibitive": False, "total_pct": 0.0, "priced": False,
                "reason": "no contract premium in payload — cost not measurable"}

    bid = num("contract_bid")
    ask = num("contract_ask")
    spread_pct = ((ask - bid) / premium * 100.0) if (ask > bid > 0) else 0.0
    commission_pct = (COMMISSION_PER_CONTRACT * 2.0) / (premium * 100.0) * 100.0
    total_pct = spread_pct + commission_pct

    if total_pct > MAX_ROUND_TRIP_COST_PCT:
        return {
            "prohibitive": True,
            "total_pct": round(total_pct, 2),
            "priced": True,
            "reason": (
                f"execution cost {total_pct:.1f}% of premium (spread {spread_pct:.1f}% + "
                f"commission {commission_pct:.1f}%) over the {MAX_ROUND_TRIP_COST_PCT:.0f}% "
                f"ceiling on a ${premium:.2f} contract — the round trip eats the edge"
            ),
        }
    return {"prohibitive": False, "total_pct": round(total_pct, 2), "priced": True,
            "reason": f"round-trip cost {total_pct:.1f}% of premium"}


def trail_exit_allowed(held_seconds: Any, is_hard_stop: bool) -> Tuple[bool, str]:
    """May a TRAILING exit fire yet? Hard stops are never delayed.

    The journal recorded exits at 0m on +0.31R and +0.92R and a 0m 'BREAKEVEN'
    at +0.92R. Those were the option's own bid/ask crossing a trail that armed
    the instant the fill printed — not trades ending. Each one converted a live
    winner into a few dollars.

    Fails OPEN: an unreadable hold time must never pin a protective trail shut.
    """
    if is_hard_stop:
        return True, "hard stop — never delayed"
    try:
        held = float(held_seconds)
    except (TypeError, ValueError):
        return True, "hold time unreadable — failing open"
    if not math.isfinite(held):
        return True, "hold time unreadable — failing open"
    if held >= MIN_HOLD_SECONDS_FOR_TRAIL:
        return True, ""
    return False, (
        f"trail held: {held:.0f}s since entry (min {MIN_HOLD_SECONDS_FOR_TRAIL}s) — "
        f"0-1m exits were the option's own spread; the hard stop still protects"
    )


def _is_option_close(pos: Optional[dict], exit_premium: Optional[float]) -> bool:
    """An option close is proven by the tracked contract OR by the caller
    passing a real fill premium. Deriving it from the tracked position alone
    meant an option close arriving for an untracked ticker (restart with lost
    state, replayed close) dropped its premium and mixed units — booking a
    $2.50 premium against a $250 underlying entry as a fake −99% that tripped
    the daily loss limit instantly."""
    if bool((pos or {}).get("contract")):
        return True
    try:
        return exit_premium is not None and float(exit_premium) > 0
    except (TypeError, ValueError):
        return False


def _final_cancel_verdict(verdict: str, status: str, call_ok: bool, broker_answered: bool) -> str:
    """Map a settled cancel poll onto the caller-facing outcome.

    NOT_FOUND is only proof of death when the cancel CALL itself succeeded or
    the broker returned a real 4xx verdict for the order id. The order list
    is ONE page of recent orders — on a busy day a still-live stop simply
    falls off the page, and 'cancel call failed + not on the page' used to
    read as CANCEL_CONFIRMED: the trailing engine then rested a SECOND stop
    against the same contracts (over-commitment, or a naked short when both
    triggered).
    """
    if verdict == "filled":
        return CANCEL_FILLED
    if verdict == "terminal":
        if str(status or "").upper() == "NOT_FOUND" and not (call_ok or broker_answered):
            return CANCEL_LIVE
        return CANCEL_CONFIRMED
    if verdict == "pending":
        return CANCEL_CONFIRMED
    return CANCEL_CONFIRMED if call_ok else CANCEL_LIVE


async def check_risk_limits(is_close: bool = False) -> None:
    """Refuse new work while the broker-API breaker is open.

    A CLOSE is exempt: exits REDUCE risk, and a breaker tripped by flaky reads
    must never be the reason a protective exit can't be sent. Entries still
    wait for the cooldown."""
    if is_close:
        return
    if await _breaker_is_open():
        raise HTTPException(
            503,
            f"Circuit breaker open — broker API failing; auto-resets within "
            f"{CIRCUIT_BREAKER_COOLDOWN_SECONDS // 60} minutes (or relink the account)",
        )


# ==================== E*TRADE CALL BACKOFF ====================
# Every E*TRADE API call goes through exponential backoff with jitter — the
# raw async client retries inside etrade_async._request; the pyetrade paths
# retry through _etrade_call / _sync_etrade_call below.
_RETRYABLE_ERROR_MARKERS = (
    "408", "429", "500", "502", "503", "504",
    "timeout", "timed out", "connection", "temporarily", "unavailable",
    "reset by peer", "max retries", "401", "unauthorized",
)


def _backoff_delay(attempt: int, exact: bool = False) -> float:
    """Exponential backoff: base * 2^attempt capped at the max.
    exact=True (429 throttle) honours the full schedule — 2s, 4s, 8s with the
    defaults — because a throttle wait must never be shortened. Other errors
    apply a [0.5, 1.0] jitter factor to de-synchronize workers."""
    delay = min(ETRADE_RETRY_MAX_SECONDS, ETRADE_RETRY_BASE_SECONDS * (2 ** attempt))
    if exact:
        return delay
    return delay * (0.5 + random.random() * 0.5)


def _is_throttle(e: Exception) -> bool:
    """429 rate-limit errors: the broker never processed the request, so a
    retry is safe even for order placement."""
    return "429" in str(e)


def _is_retryable_error(e: Exception) -> bool:
    """Transient broker failures worth retrying: throttles (429), 5xx, network
    drops, and 401s (E*TRADE tokens briefly 401 right after issue/renewal).
    Validation rejections (1011/2040/2009, missing params) are NOT retried."""
    text = str(e).lower()
    return any(marker in text for marker in _RETRYABLE_ERROR_MARKERS)


def _sync_etrade_call(fn, *args, source: str = "etrade", **kwargs):
    """Exponential-backoff wrapper for SYNC pyetrade calls running inside a
    worker thread (e.g. contract snapping) — blocking sleeps are fine there."""
    for attempt in range(ETRADE_RETRY_ATTEMPTS):
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            if attempt >= ETRADE_RETRY_ATTEMPTS - 1 or not _is_retryable_error(e):
                raise
            delay = _backoff_delay(attempt, exact=_is_throttle(e))
            logger.warning(
                f"E*TRADE {source} failed (attempt {attempt + 1}/{ETRADE_RETRY_ATTEMPTS}): {e} "
                f"— retrying in {delay:.1f}s"
            )
            time.sleep(delay)


async def _etrade_call(fn, *args, source: str = "etrade", idempotent: bool = True, **kwargs):
    """Run a sync pyetrade call in a thread with exponential backoff + jitter.
    idempotent=False (order placement) executes EXACTLY once — a failed place
    may still have reached the broker, so a blind retry risks a double order
    (the reconciliation engine heals whatever state results)."""
    for attempt in range(ETRADE_RETRY_ATTEMPTS):
        try:
            return await asyncio.to_thread(fn, *args, **kwargs)
        except Exception as e:
            # A 429 was never processed by the broker — safe to retry even for
            # non-idempotent calls (order placement). Anything else follows the
            # exactly-once rule for non-idempotent requests.
            throttled = _is_throttle(e)
            if (not idempotent and not throttled) or attempt >= ETRADE_RETRY_ATTEMPTS - 1 or not _is_retryable_error(e):
                raise
            delay = _backoff_delay(attempt, exact=throttled)
            logger.warning(
                f"E*TRADE {source} failed (attempt {attempt + 1}/{ETRADE_RETRY_ATTEMPTS}): {e} "
                f"— retrying in {delay:.1f}s"
            )
            await asyncio.sleep(delay)


# ==================== STOP GUARD ====================
# Makes the protective stop REST AT THE BROKER. The entry order goes in first;
# an async watcher polls the broker until the entry fills, then places a real
# STOP order at E*TRADE sized to the filled quantity (re-placed as partial
# fills grow — never two live stops at once). Entries with zero fill by
# ENTRY_FILL_TIMEOUT_MIN are cancelled. Guard state persists to STATE_FILE and
# resumes after a restart.
_TERMINAL_ORDER_STATUSES = {"EXECUTED", "CANCELLED", "REJECTED", "EXPIRED"}


def _order_id_from_place(placed: Any) -> Optional[str]:
    """Extract the numeric orderId from a PlaceOrderResponse."""
    try:
        body = placed.get("PlaceOrderResponse", placed) if isinstance(placed, dict) else {}
        ids = body.get("OrderIds") or body.get("orderIds") or []
        if isinstance(ids, dict):
            ids = [ids]
        for entry in ids:
            oid = entry.get("orderId") if isinstance(entry, dict) else entry
            if oid:
                return str(oid)
        oid = body.get("orderId") or body.get("OrderId")
        return str(oid) if oid else None
    except (AttributeError, TypeError):
        return None


def _orders_client(tokens: Dict[str, str]) -> "pyetrade.ETradeOrder":
    return pyetrade.ETradeOrder(
        CONSUMER_KEY, CONSUMER_SECRET,
        tokens["oauth_token"], tokens["oauth_token_secret"],
        dev=is_sandbox,
    )


def _raw_client(tokens: Dict[str, str]) -> ETradeAsyncClient:
    """Async httpx client with raw JSON Order API payloads (primary path)."""
    return ETradeAsyncClient(
        CONSUMER_KEY, CONSUMER_SECRET,
        tokens["oauth_token"], tokens["oauth_token_secret"],
        sandbox=is_sandbox,
    )


async def _place_order_smart(kind: str, common: dict, tokens: Dict[str, str]) -> Any:
    """Primary path: raw async JSON payload against E*TRADE's Order API
    (full control, true multi-leg capable). Fallback: pyetrade flat kwargs —
    the proven v4 path. `common` uses the flat pyetrade vocabulary so both
    paths share one source of truth."""
    if USE_RAW_ORDER_API:
        try:
            client = _raw_client(tokens)
            acct = common["accountIdKey"]
            cid = str(common["clientOrderId"])
            price_type = str(common.get("priceType") or "MARKET")
            limit_price = common.get("limitPrice")
            stop_price = common.get("stopPrice")
            if kind == "option":
                return await client.place_option(
                    acct, cid, str(common["symbol"]), str(common["callPut"]),
                    float(common["strikePrice"]), str(common["expiryDate"]),
                    str(common["orderAction"]), int(common["quantity"]),
                    price_type, limit_price=limit_price, stop_price=stop_price,
                )
            return await client.place_equity(
                acct, cid, str(common["symbol"]), str(common["orderAction"]),
                int(common["quantity"]), price_type,
                limit_price=limit_price, stop_price=stop_price,
            )
        except ETradeAPIError as e:
            if _raw_place_fallback_safe(e.status_code, False):
                logger.warning(f"RAW order path rejected ({e}) — falling back to pyetrade")
            else:
                # A 5xx on place.json may FOLLOW acceptance — re-placing through
                # pyetrade risks a double fill. Surface the ambiguity instead.
                raise
        except httpx.ConnectError as e:
            logger.warning(f"RAW order path unreachable before send ({e}) — falling back to pyetrade")
    orders = _orders_client(tokens)
    fn = orders.place_option_order if kind == "option" else orders.place_equity_order
    # NON-IDEMPOTENT — executed exactly once (no blind retry of a place).
    return await _etrade_call(fn, source=f"place_{kind}", idempotent=False, **common)


_INSUFFICIENT_FUNDS_QTY_RE = re.compile(
    r"maximum allowable quantity was estimated to be\s+(\d+)", re.IGNORECASE
)


def _max_qty_from_insufficient_funds(message: str) -> Optional[int]:
    """Parse E*TRADE error 8400's embedded max quantity hint.

    E*TRADE rejects over-sized orders with:
      "Code: 8400 ... insufficient funds ... the maximum allowable quantity
       was estimated to be 57."
    Returns the parsed integer, or None when the message carries no hint.
    """
    if not message or ("8400" not in message and "insufficient funds" not in message.lower()):
        return None
    m = _INSUFFICIENT_FUNDS_QTY_RE.search(message)
    if not m:
        return None
    try:
        qty = int(m.group(1))
        return qty if qty > 0 else None
    except ValueError:
        return None


FUNDS_SAFETY_MARGIN = float(os.getenv("FUNDS_SAFETY_MARGIN", "0.95"))


async def _place_entry_with_funds_clamp(
    kind: str, common: dict, tokens: Dict[str, str], unit_cost: Optional[float] = None,
) -> Tuple[Any, int]:
    """Place an ENTRY order with three layers of funds protection:

    1. PRE-FLIGHT (proactive): when the per-unit cost is known, clamp the
       quantity so the estimated cost fits within tracked available funds
       (95% safety margin) — and refuse outright when even ONE unit is
       unaffordable, so oversized orders never reach the broker at all.
    2. BACKSTOP (reactive): on an 8400 insufficient-funds rejection anyway,
       clamp to the broker's own max-quantity hint and retry ONCE with a
       fresh clientOrderId.
    3. LEDGER: debit the tracked balance by the placed cost so back-to-back
       entries can't over-spend between broker balance refreshes.

    Never used for closes — a close must always cover the full position.
    Returns (broker_response, quantity_actually_sent).
    """
    requested = int(common["quantity"])
    unit_name = "contract" if kind == "option" else "share"
    if unit_cost is not None and unit_cost > 0:
        available = await _available_funds()
        if available is not None:
            budget = max(0.0, available) * FUNDS_SAFETY_MARGIN
            affordable = int(budget // unit_cost)
            if affordable < 1:
                raise Exception(
                    f"insufficient funds: available ≈${available:.2f}, one {unit_name} of "
                    f"{common.get('symbol')} costs ≈${unit_cost:.2f} — trade refused before reaching broker"
                )
            if requested > affordable:
                logger.warning(
                    f"💰 Pre-flight size clamp: {common.get('symbol')} qty {requested} → {affordable} "
                    f"(available ≈${available:.2f}, {unit_name} cost ≈${unit_cost:.2f})"
                )
                common = dict(common)
                common["quantity"] = affordable
                requested = affordable
        else:
            logger.warning(
                f"⚠️ No balance available for pre-flight sizing of {common.get('symbol')} — "
                f"relying on broker-side 8400 clamp backstop"
            )

    placed_qty = requested
    try:
        final = await _place_order_smart(kind, common, tokens)
    except Exception as e:
        max_qty = _max_qty_from_insufficient_funds(str(e))
        if max_qty is None:
            raise
        clamped = max(1, int(max_qty * 0.95))
        if clamped >= requested:
            raise  # hint doesn't actually reduce the order — don't loop
        retry = dict(common)
        retry["quantity"] = clamped
        # A rejected order may still burn the clientOrderId — retry with a
        # fresh one (E*TRADE caps clientOrderId at 20 chars).
        retry["clientOrderId"] = (str(common["clientOrderId"])[:19] + "R")
        logger.warning(
            f"💰 Insufficient funds for qty={requested} {common.get('symbol')} — "
            f"broker max ≈{max_qty}; retrying ONCE with clamped qty={clamped}"
        )
        final = await _place_order_smart(kind, retry, tokens)
        logger.info(f"✅ Clamped retry accepted: {clamped}x {common.get('symbol')} (was {requested})")
        placed_qty = clamped
    if unit_cost is not None and unit_cost > 0:
        try:
            await state.adjust_balance(-float(unit_cost) * placed_qty)
        except Exception as e:
            logger.warning(f"balance debit failed (non-fatal): {e}")
    return final, placed_qty


async def _order_state(order_id: Optional[str], client_id: Optional[str]) -> Tuple[str, int]:
    """Return (status, total filled quantity) for an order, matched by orderId
    or clientOrderId in the account's recent orders. ('NOT_FOUND', 0) when the
    order is not in the list."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE tokens not set")
    acct_key = await _resolve_account_id_key(tokens)
    orders = _orders_client(tokens)
    resp = await _etrade_call(orders.list_orders, acct_key, resp_format="json", source="list_orders")
    root = (resp or {}).get("OrdersResponse", {}) if isinstance(resp, dict) else {}
    order_list = root.get("Order") or []
    if isinstance(order_list, dict):
        order_list = [order_list]
    for o in order_list:
        if not isinstance(o, dict):
            continue
        oid = str(o.get("orderId") or "")
        details = o.get("OrderDetail") or []
        if isinstance(details, dict):
            details = [details]
        matches = bool(order_id) and oid == str(order_id)
        if not matches and client_id:
            matches = any(
                str(d.get("clientOrderId") or "") == client_id
                for d in details if isinstance(d, dict)
            )
        if not matches:
            continue
        status = "OPEN"
        filled = 0
        for d in details:
            if not isinstance(d, dict):
                continue
            status = str(d.get("status") or status).upper()
            instruments = d.get("Instrument") or []
            if isinstance(instruments, dict):
                instruments = [instruments]
            for inst in instruments:
                if not isinstance(inst, dict):
                    continue
                try:
                    filled += int(float(inst.get("filledQuantity") or 0))
                except (TypeError, ValueError):
                    pass
        return status, filled
    return "NOT_FOUND", 0


# ---- Close-fill truth --------------------------------------------------------
# Every close the bot itself placed used to be booked WITHOUT its fill price:
# `_record_close(..., None, ...)` fell back to exit = entry — a fake breakeven.
# The 2026-08-07 SPY close (order 765, MARKET) is the canonical case: the real
# loss never reached the ledger, the daily loss limit or the learning stack.
# Broker-side stop fills were fixed by fill capture (5.20); these helpers close
# the remaining half: closes the bot places either book their ACTUAL executed
# price, or the position stays tracked (pending_close) until the reconciler's
# fill capture prices it from the broker's own order history. NOTHING is ever
# booked as a guessed breakeven again.
EXIT_FILL_POLL_SECONDS = 1.5
EXIT_FILL_TIMEOUT_SECONDS = 8.0


async def _resolve_exit_fill(order_id, timeout_s: float = EXIT_FILL_TIMEOUT_SECONDS) -> Optional[float]:
    """Poll the broker's order list for a closing order's ACTUAL average
    execution price. Returns None when the order has not EXECUTED (or has no
    readable price) within the window — callers must then DEFER the booking to
    the reconciler, never guess an exit."""
    if not order_id:
        return None
    deadline = time.monotonic() + max(0.0, float(timeout_s))
    while True:
        try:
            resp = await _reconcile_fetch_orders()
            for order in reconciliation.parse_open_orders(resp):
                if str(order.get("order_id") or "") != str(order_id):
                    continue
                if str(order.get("status") or "") == "EXECUTED":
                    price = float(order.get("exec_price") or 0)
                    if price > 0:
                        return price
        except Exception as e:
            logger.warning(f"[CLOSE FILL] fill poll for order {order_id} failed: {e}")
        if time.monotonic() >= deadline:
            return None
        await asyncio.sleep(EXIT_FILL_POLL_SECONDS)


async def _defer_close_to_reconciler(ticker: str, close_order_id, note: str) -> None:
    """A close was placed (or a stop filled) but its execution price is not
    readable yet. Do NOT book a fake breakeven: keep the position tracked,
    tagged with the closing order id, and let the reconciler's fill capture
    book the REAL exit from the broker's order history on its next pass."""
    ticker = str(ticker).upper()
    pos = await state.get_position(ticker)
    if not pos:
        logger.warning(f"[CLOSE FILL] {ticker} close unpriced and no tracked position — nothing to defer ({note})")
        return
    pos["pending_close"] = True
    if close_order_id:
        pos["close_order_id"] = str(close_order_id)
    await state.set_position(ticker, pos)
    logger.warning(
        f"[CLOSE FILL] {ticker} exit fill not yet priced ({note}) — position held for "
        f"reconciler fill capture instead of booking a fake breakeven"
    )


# ---- Intent-preserving entry repricing ---------------------------------------
# 2026-08-07: every option entry was sized on the APP'S ESTIMATED premium, then
# silently repriced to the real ask WITH THE SAME QUANTITY:
#   MSTR est 1.12 → paid 5.70 (409% drift — 5× the planned dollars)
#   CRM  est 1.34 ×4 → paid 2.65 ×4 (intended ≈$536, spent ≈$1,060)
#   SPY  est 1.38 ×4 → paid 2.25 ×4 (intended ≈$552, spent ≈$900)
# Roughly double the intended risk on every entry is why the day bled out. The
# bot honored the app's PRICE intent (reprice to ask so the order fills) but
# ignored its DOLLAR intent (the risk the position was sized for). Past a small
# drift the quantity now shrinks to the intended outlay; when even one contract
# multiplies the planned risk, the entry is REJECTED — the trade premise
# (sizing, stop distance, R math) was computed on a price that doesn't exist.
ENTRY_REPRICE_DRIFT_PCT = 10.0
ENTRY_MAX_OVERSPEND_FACTOR = 1.25


def plan_entry_reprice(app_limit, qty, real_price) -> Dict[str, Any]:
    """Pure sizing decision for a repriced option entry.

    `app_limit` is the premium the app sized the trade on, `qty` its requested
    contracts, `real_price` the premium actually about to be paid (sanitized
    limit / real ask). Returns {action, qty, drift_pct, intended_usd,
    actual_unit_usd}:

      proceed — keep the requested quantity (no intent expressed, repriced
                cheaper, or drift within ENTRY_REPRICE_DRIFT_PCT);
      resize  — shrink quantity so real cost stays inside the intended outlay
                (app_limit × 100 × qty);
      reject  — even ONE contract exceeds the intent by more than
                ENTRY_MAX_OVERSPEND_FACTOR — refuse to multiply planned risk.
    """
    try:
        est = float(app_limit or 0)
        px = float(real_price or 0)
        q = int(qty or 0)
    except (TypeError, ValueError):
        return {"action": "proceed", "qty": qty, "drift_pct": 0.0,
                "intended_usd": None, "actual_unit_usd": None}
    unit = round(px * 100.0, 2) if px > 0 else None
    if est <= 0 or px <= 0 or q < 1:
        # No price intent (MARKET entry) or no market reference — nothing to
        # preserve here; the funds clamp still applies downstream.
        return {"action": "proceed", "qty": q if q >= 1 else qty, "drift_pct": 0.0,
                "intended_usd": None, "actual_unit_usd": unit}
    drift_pct = (px - est) / est * 100.0
    intended = round(est * 100.0 * q, 2)
    if drift_pct <= ENTRY_REPRICE_DRIFT_PCT:
        # Cheaper than planned, or within tolerance — the sizing premise holds.
        return {"action": "proceed", "qty": q, "drift_pct": round(drift_pct, 2),
                "intended_usd": intended, "actual_unit_usd": unit}
    resized = int(intended // (px * 100.0))
    if resized < 1:
        # One contract already busts the plan. Allow a modest overshoot so a
        # near-miss single contract can still trade; beyond that, refuse.
        if px * 100.0 <= intended * ENTRY_MAX_OVERSPEND_FACTOR:
            resized = 1
        else:
            return {"action": "reject", "qty": 0, "drift_pct": round(drift_pct, 2),
                    "intended_usd": intended, "actual_unit_usd": unit}
    if resized >= q:
        return {"action": "proceed", "qty": q, "drift_pct": round(drift_pct, 2),
                "intended_usd": intended, "actual_unit_usd": unit}
    return {"action": "resize", "qty": resized, "drift_pct": round(drift_pct, 2),
            "intended_usd": intended, "actual_unit_usd": unit}


# ---- Entry-fill truth --------------------------------------------------------
# Broker statements from 2026-08-07 proved the last untrue number in the
# pipeline: ENTRIES were booked at the LIMIT price, never the actual fill.
#   MSTR booked 5.70 — actually filled ≈ 5.105 (broker: $510.51 for 1)
#   CRM  booked 2.65 — actually filled ≈ 2.435 (broker: $974.05 for 4)
#   SPY  booked 2.25 — actually filled ≈ 2.195 (broker: $878.05 for 4)
# Every P&L percent, R-multiple, account-scaled daily contribution and ledger
# dollar figure was computed off an entry that didn't happen. The stop guard
# already polls the entry order for its fill — it now also reads the average
# execution price and TRUES UP the tracked entry the moment a fill is seen.


async def _true_up_entry_fill(ticker: str, guard: dict) -> bool:
    """Replace the position's booked entry (the sanitized LIMIT price) with the
    broker's ACTUAL average execution price for the entry order. Options true
    up `entry_premium` (the P&L basis); equities true up `entry`. Returns True
    when a price was readable (booked, or already accurate), False when the
    broker hasn't reported one yet — the caller retries on the next poll."""
    entry_order_id = guard.get("entry_order_id")
    if not entry_order_id:
        return False
    actual = 0.0
    try:
        resp = await _reconcile_fetch_orders()
        for order in reconciliation.parse_open_orders(resp):
            if str(order.get("order_id") or "") != str(entry_order_id):
                continue
            price = float(order.get("exec_price") or 0)
            if price > 0 and int(order.get("filled") or 0) > 0:
                actual = price
                break
    except Exception as e:
        logger.warning(f"[ENTRY FILL] {ticker} true-up poll failed (will retry): {e}")
        return False
    if actual <= 0:
        return False
    pos = await state.get_position(ticker)
    if not pos:
        return True  # price readable but nothing tracked — nothing to true up
    is_option = bool(pos.get("contract"))
    key = "entry_premium" if is_option else "entry"
    booked = float(pos.get(key) or 0)
    if booked > 0 and abs(actual - booked) / booked < 0.001:
        return True  # already accurate
    pos[key] = round(actual, 4)
    await state.set_position(ticker, pos)
    drift = round((actual - booked) / booked * 100.0, 2) if booked > 0 else None
    await trade_ledger.record("entry_fill_trued", {
        "ticker": ticker,
        "basis": "premium" if is_option else "underlying",
        "booked": round(booked, 4) if booked > 0 else None,
        "actual": round(actual, 4),
        "drift_pct": drift,
        "entry_order_id": str(entry_order_id),
    })
    logger.info(
        f"[ENTRY FILL] ⚖️ {ticker} entry trued {booked or '?'} → {actual} "
        f"({'premium' if is_option else 'underlying'}"
        f"{f', {drift:+.1f}% vs booked' if drift is not None else ''}) — "
        f"P&L now measures from the REAL fill"
    )
    return True


# ---- Broker-verified cancel -------------------------------------------------
# Cancel outcomes. The distinction between "gone" and "filled" is the whole
# point: a protective stop that EXECUTED means the position is already flat, so
# replacing it (trailing engine) or selling again (exit path) is a double-sell.
CANCEL_NONE = "none"
CANCEL_CONFIRMED = "cancelled"
CANCEL_FILLED = "filled"
CANCEL_LIVE = "live"

# Broker statuses that PROVE the order is no longer working AND that the broker
# has released the shares/contracts it had pledged to it.
_CANCEL_TERMINAL_STATUSES = {"CANCELLED", "REJECTED", "EXPIRED", "NOT_FOUND"}
# CANCEL_REQUESTED is NOT terminal. E*TRADE has accepted the cancel but the order
# is still on the book, still holding its allocation. Treating it as "gone" is
# what produced the 1037/3004 storm: cancel at T+0.0s, replacement order at
# T+0.6s, broker still counting the old order, rejection — and on the trailing
# path that left a live option position with NO resting stop at all.
_CANCEL_PENDING_STATUSES = {"CANCEL_REQUESTED", "CANCEL_REQUEST", "CANCELLING"}
# Kept as the union for callers that only care "is it still working?".
_CANCEL_CONFIRMED_STATUSES = _CANCEL_TERMINAL_STATUSES | _CANCEL_PENDING_STATUSES


def classify_cancel_status(status: Optional[str], filled: int) -> str:
    """Pure classification of a broker order status during a cancel.

    Returns 'filled' | 'terminal' | 'pending' | 'working'.

    'terminal' is the ONLY verdict that means the broker has released the
    shares/contracts. 'pending' means the cancel was accepted but the allocation
    is still held — anything sent now races the broker and loses.
    """
    s = str(status or "").upper().strip()
    try:
        filled_n = int(filled or 0)
    except (TypeError, ValueError):
        filled_n = 0
    if s == "EXECUTED" or (filled_n > 0 and s in _CANCEL_CONFIRMED_STATUSES):
        return "filled"
    if s in _CANCEL_TERMINAL_STATUSES:
        return "terminal"
    if s in _CANCEL_PENDING_STATUSES:
        return "pending"
    return "working"


async def _await_cancel_settled(order_id: str) -> Tuple[str, int, str]:
    """Poll the broker until a cancelled order reaches a TERMINAL status, so the
    allocation it held is provably released before we place anything against the
    same contract. Returns (verdict, filled, last_status).

    Bounded by CANCEL_SETTLE_TIMEOUT_SECONDS — this sits in the trailing-ratchet
    and panic-exit paths, so it must never block them indefinitely.
    """
    deadline = time.time() + max(0.0, CANCEL_SETTLE_TIMEOUT_SECONDS)
    verdict, filled, status = "working", 0, "UNKNOWN"
    attempt = 0
    while True:
        try:
            status, filled = await _order_state(str(order_id), None)
            verdict = classify_cancel_status(status, filled)
        except Exception as e:
            logger.warning(f"cancel verification unavailable for order {order_id}: {e}")
            verdict, status = "working", "UNKNOWN"
        if verdict in ("filled", "terminal"):
            return verdict, filled, status
        if time.time() >= deadline:
            return verdict, filled, status
        attempt += 1
        if attempt == 1 and verdict == "pending":
            logger.info(
                f"[CANCEL] order {order_id} is {status} — waiting for the broker to release "
                f"the allocation before placing against this contract"
            )
        await asyncio.sleep(min(CANCEL_SETTLE_POLL_SECONDS * attempt, 2.0))


async def _cancel_order_call(order_id: str) -> None:
    """Issue the cancel request. The raw async client goes first because
    E*TRADE answers PUT /orders/cancel.json with an EMPTY body — pyetrade
    json-decodes that and dies with "Expecting value: line 1 column 1 (char 0)"
    even though the broker cancelled the order. The raw client treats an empty
    2xx as success; pyetrade remains the fallback transport."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE tokens not set")
    acct_key = await _resolve_account_id_key(tokens)
    if USE_RAW_ORDER_API:
        try:
            await _raw_client(tokens).cancel_order(acct_key, int(order_id))
            return
        except ETradeAPIError as e:
            # A 4xx is a real broker verdict (already cancelled / filled / bad
            # id) — surface it so verification can classify it. Anything else
            # is transport noise worth retrying on the pyetrade path.
            if 400 <= e.status_code < 500:
                raise
            logger.warning(f"raw cancel path failed for {order_id} ({e}) — falling back to pyetrade")
    orders = _orders_client(tokens)
    await _etrade_call(orders.cancel_order, acct_key, int(order_id), resp_format="json", source="cancel_order")


async def _cancel_order_verified(order_id: Optional[str]) -> str:
    """Cancel a resting broker order and VERIFY the outcome against the
    broker's own order book. Returns one of:

      CANCEL_NONE      — nothing to cancel (no order id)
      CANCEL_CONFIRMED — provably no longer working: safe to replace the stop
                         or send a closing order
      CANCEL_FILLED    — the order EXECUTED (the stop triggered): the position
                         is already flat — never replace it, never sell again
      CANCEL_LIVE      — not confirmed gone; assume it may still fill

    Verification is what makes this trustworthy. The cancel *call* can fail for
    reasons that have nothing to do with the broker (empty body, dropped
    socket) while the cancel itself went through. Trusting the exception alone
    froze the trailing engine: every ratchet reported "could not cancel", yet
    the stop really was gone, so positions sat unprotected until the reconciler
    re-armed them at the ORIGINAL level and the trail never moved.
    """
    if not order_id:
        return CANCEL_NONE

    call_ok = True
    broker_answered = False
    try:
        await _cancel_order_call(str(order_id))
    except Exception as e:
        call_ok = False
        # A 4xx is the broker's real verdict on this order id (already
        # cancelled / filled / unknown id) — trustworthy context for a
        # NOT_FOUND below. Transport noise is not. Read duck-typed so this
        # function stays liftable without the etrade_async import.
        code = getattr(e, "status_code", None)
        broker_answered = isinstance(code, int) and 400 <= code < 500
        logger.warning(f"order cancel call failed ({order_id}): {e} — verifying against broker order book")

    # Wait for the broker to actually retire the order. Returning on the first
    # CANCEL_REQUESTED is what caused every "not enough available contracts"
    # rejection: the order was dying, but its allocation was still held.
    verdict, filled, status = await _await_cancel_settled(str(order_id))

    outcome = _final_cancel_verdict(verdict, status, call_ok, broker_answered)
    if outcome == CANCEL_FILLED:
        logger.warning(
            f"[CANCEL] order {order_id} already filled at the broker "
            f"(status={status}, filled={filled}) — treating as FILLED, not cancelled"
        )
        return CANCEL_FILLED
    if verdict == "terminal":
        if outcome == CANCEL_LIVE:
            # NOT_FOUND after a FAILED cancel call proves nothing — the order
            # list is one page and a still-live stop can simply roll off it.
            logger.warning(
                f"[CANCEL] order {order_id} NOT_FOUND after a failed cancel call — "
                f"cannot prove it is gone; treating as LIVE (no replacement placed)"
            )
            return CANCEL_LIVE
        logger.info(f"[CANCEL] order {order_id} confirmed gone at broker (status={status})")
        return CANCEL_CONFIRMED
    if verdict == "pending":
        # Accepted but never went terminal inside the window. The order IS dying,
        # so it is not "live" in the double-sell sense, but the allocation may
        # still be held — say so plainly instead of pretending it settled.
        logger.warning(
            f"[CANCEL] order {order_id} still {status} after "
            f"{CANCEL_SETTLE_TIMEOUT_SECONDS:.0f}s — proceeding; a follow-on order may be "
            f"rejected for allocation while the broker finishes the cancel"
        )
        return CANCEL_CONFIRMED
    if call_ok:
        # Cancel accepted and no fill seen; the order book can lag a few seconds.
        logger.info(f"[CANCEL] cancelled order {order_id}")
        return CANCEL_CONFIRMED
    return CANCEL_LIVE


async def _cancel_order_safe(order_id: Optional[str]) -> bool:
    """Boolean view of `_cancel_order_verified`: True only when the order is
    provably no longer working. A FILLED stop is deliberately NOT "cancelled" —
    callers that must tell the two apart use `_cancel_order_verified`."""
    return await _cancel_order_verified(order_id) == CANCEL_CONFIRMED


async def _current_bid_ask(ticker: str, contract: Optional[dict] = None) -> Tuple[float, float]:
    """Best-effort live (bid, ask) for an equity — or a specific option
    contract via E*TRADE's SYMBOL:YYYY:MM:DD:TYPE:STRIKE quote syntax.
    Returns (0.0, 0.0) when no quote is available; callers must handle it."""
    tokens = load_tokens()
    if not tokens:
        return 0.0, 0.0
    try:
        market = pyetrade.ETradeMarket(
            CONSUMER_KEY, CONSUMER_SECRET,
            tokens["oauth_token"], tokens["oauth_token_secret"], dev=is_sandbox,
        )
        sym = ticker
        if contract:
            exp = str(contract.get("expiration") or "")[:10]
            parts = exp.split("-")
            if len(parts) == 3 and contract.get("strike") is not None:
                right = "CALL" if str(contract.get("right") or "").upper().startswith("C") else "PUT"
                sym = f"{ticker}:{int(parts[0])}:{int(parts[1])}:{int(parts[2])}:{right}:{float(contract['strike']):g}"
        resp = await _etrade_call(market.get_quote, [sym], resp_format="json", source="stop_reprice_quote")
        data = (((resp or {}).get("QuoteResponse") or {}).get("QuoteData")) or []
        if isinstance(data, dict):
            data = [data]
        for q in data:
            all_q = q.get("All") or {}
            try:
                bid = max(0.0, float(all_q.get("bid") or 0))
                ask = max(0.0, float(all_q.get("ask") or 0))
                return bid, ask
            except (TypeError, ValueError):
                continue
    except Exception as e:
        logger.warning(f"reprice quote failed for {ticker}: {e}")
    return 0.0, 0.0


async def _place_protective_stop(ticker: str, action: str, qty: int, stop_price: float) -> dict:
    """Rest a protective STOP order at E*TRADE for a filled equity entry."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE tokens not set")
    acct_key = await _resolve_account_id_key(tokens)
    exit_side = "SELL" if action == "BUY" else "BUY_TO_COVER"
    client_id = str(uuid.uuid4().int)[:18]
    common = dict(
        resp_format="json",
        accountIdKey=acct_key,
        symbol=ticker,
        orderAction=exit_side,
        clientOrderId=client_id,
        priceType="STOP",
        stopPrice=round(float(stop_price), 2),
        quantity=int(qty),
        orderTerm="GOOD_FOR_DAY",
        marketSession="REGULAR",
        allOrNone=False,
    )
    try:
        placed = await _place_order_smart("equity", common, tokens)
    except Exception as e:
        # E*TRADE 2084: a SELL stop must rest ≥ $0.01 BELOW the current bid
        # (BUY_TO_COVER: above the ask). Retrying the same price forever is a
        # guaranteed CRITICAL-alert loop ending in a 60s timeout flatten —
        # instead reprice just past the live market and retry ONCE. The guard
        # loop re-attempts (with a fresh reprice) on later polls anyway.
        if "2084" not in str(e):
            raise
        bid, ask = await _current_bid_ask(ticker)
        if exit_side == "SELL":
            adjusted = round(min(float(stop_price), bid - 0.01), 2) if bid > 0.02 else round(float(stop_price) * 0.99, 2)
        else:
            adjusted = round(max(float(stop_price), ask + 0.01), 2) if ask > 0 else round(float(stop_price) * 1.01, 2)
        if adjusted <= 0 or abs(adjusted - round(float(stop_price), 2)) < 0.005:
            raise
        logger.warning(
            f"[STOP GUARD] {ticker} stop {float(stop_price):.2f} rejected (2084 — must rest past the market) "
            f"— repricing to {adjusted:.2f} (bid={bid} ask={ask}) and retrying"
        )
        stop_price = adjusted
        client_id = str(uuid.uuid4().int)[:18]
        common["stopPrice"] = adjusted
        common["clientOrderId"] = client_id
        placed = await _place_order_smart("equity", common, tokens)
    order_id = _order_id_from_place(placed)
    logger.info(
        f"[STOP GUARD] protective stop RESTING at broker: {exit_side} {ticker} "
        f"qty={qty} stop={stop_price:.2f} (order={order_id})"
    )
    await trade_ledger.record("protective_stop_placed", {
        "ticker": ticker, "kind": "equity", "side": exit_side,
        "qty": int(qty), "stop": round(float(stop_price), 2), "order_id": order_id,
    })
    return {"order_id": order_id, "client_id": client_id, "qty": int(qty), "stop": round(float(stop_price), 2)}


async def _place_option_protective_stop(ticker: str, contract: dict, qty: int, stop_premium: float) -> dict:
    """Rest a protective SELL_CLOSE STOP at E*TRADE on the same OCC contract
    for a filled option entry — the option-side equivalent of the equity stop
    guard. `stop_premium` is the option PREMIUM trigger, tick-rounded."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE tokens not set")
    if not contract or not contract.get("right") or not contract.get("expiration"):
        raise Exception(f"option guard for {ticker} missing contract details")
    acct_key = await _resolve_account_id_key(tokens)
    client_id = str(uuid.uuid4().int)[:18]
    stop_px = _round_to_option_tick(float(stop_premium), "down")
    common = dict(
        resp_format="json",
        accountIdKey=acct_key,
        symbol=ticker,
        orderAction="SELL_CLOSE",
        clientOrderId=client_id,
        priceType="STOP",
        stopPrice=stop_px,
        quantity=int(qty),
        orderTerm="GOOD_FOR_DAY",
        marketSession="REGULAR",
        allOrNone=False,
        callPut=str(contract["right"]).upper(),
        strikePrice=float(contract["strike"]),
        expiryDate=str(contract["expiration"])[:10],
    )
    try:
        placed = await _place_order_smart("option", common, tokens)
    except Exception as e:
        # Same 2084 handling as the equity guard: the premium stop must rest
        # below the option's live bid — reprice just below it and retry once.
        if "2084" not in str(e):
            raise
        bid, _ask = await _current_bid_ask(ticker, contract)
        if bid > 0.02:
            adjusted = _round_to_option_tick(min(stop_px, bid - 0.01), "down")
        else:
            adjusted = _round_to_option_tick(stop_px * 0.9, "down")
        if adjusted <= 0 or adjusted >= stop_px:
            raise
        logger.warning(
            f"[STOP GUARD] {ticker} option stop {stop_px:.2f} rejected (2084 — must rest below the bid) "
            f"— repricing to {adjusted:.2f} (bid={bid}) and retrying"
        )
        stop_px = adjusted
        client_id = str(uuid.uuid4().int)[:18]
        common["stopPrice"] = adjusted
        common["clientOrderId"] = client_id
        placed = await _place_order_smart("option", common, tokens)
    order_id = _order_id_from_place(placed)
    logger.info(
        f"[STOP GUARD] option protective stop RESTING at broker: SELL_CLOSE {ticker} "
        f"{contract.get('right')} {contract.get('strike')} {contract.get('expiration')} "
        f"qty={qty} stop_premium={stop_px:.2f} (order={order_id})"
    )
    await trade_ledger.record("protective_stop_placed", {
        "ticker": ticker, "kind": "option", "side": "SELL_CLOSE",
        "qty": int(qty), "stop_premium": stop_px, "order_id": order_id,
        "contract": {"right": contract.get("right"), "strike": contract.get("strike"),
                     "expiration": contract.get("expiration")},
    })
    return {"order_id": order_id, "client_id": client_id, "qty": int(qty), "stop": stop_px}


async def _emergency_flatten(ticker: str, guard: dict, qty: int) -> Optional[str]:
    """LAST-RESORT market close of a filled-but-unprotected entry (stop
    placement timeout). Certainty of fill beats price — always MARKET."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE tokens not set")
    acct_key = await _resolve_account_id_key(tokens)
    client_id = str(uuid.uuid4().int)[:18]
    is_option = str(guard.get("kind") or "equity") == "option"
    if is_option:
        contract = dict(guard.get("contract") or {})
        if not contract.get("right") or not contract.get("expiration"):
            raise Exception(f"cannot flatten {ticker} — option contract details missing")
        common = dict(
            resp_format="json",
            accountIdKey=acct_key,
            symbol=ticker,
            orderAction="SELL_CLOSE",
            clientOrderId=client_id,
            priceType="MARKET",
            quantity=int(qty),
            orderTerm="GOOD_FOR_DAY",
            marketSession="REGULAR",
            allOrNone=False,
            callPut=str(contract["right"]).upper(),
            strikePrice=float(contract["strike"]),
            expiryDate=str(contract["expiration"])[:10],
        )
        placed = await _place_order_smart("option", common, tokens)
    else:
        exit_side = "SELL" if str(guard.get("action") or "BUY").upper() == "BUY" else "BUY_TO_COVER"
        common = dict(
            resp_format="json",
            accountIdKey=acct_key,
            symbol=ticker,
            orderAction=exit_side,
            clientOrderId=client_id,
            priceType="MARKET",
            quantity=int(qty),
            orderTerm="GOOD_FOR_DAY",
            marketSession="REGULAR",
            allOrNone=False,
        )
        placed = await _place_order_smart("equity", common, tokens)
    return _order_id_from_place(placed)


async def _place_option_market_close(ticker: str, contract: dict, qty: int) -> Optional[str]:
    """MARKET SELL_CLOSE for `qty` contracts of an OCC contract we hold."""
    tokens = load_tokens()
