async def _maybe_scale_out(ticker: str, pos: dict, mark: float) -> bool:
    """Bank half the position at the first target and let the rest run.

    THE CAPTURE FIX. On the real book every winner was closed in FULL at the
    first exit — NVDA's four contracts came off together at +6.48% after ZERO
    minutes — so the average winner (+13.8%) never grew big enough to pay for
    the average loser (−9.5%). No daily dollar objective survives that shape.

    Here the position sells `scale_qty` at market once the premium clears the
    first target, then re-arms the protective stop over the REMAINING
    contracts. The runner keeps ratcheting on the normal trail, so the tail
    that actually pays for the losers is finally allowed to develop.

    Returns True when contracts were sold (the caller must re-read state).
    Every failure path leaves the position PROTECTED: if the partial cannot be
    placed the original stop is re-armed over the full size before returning.
    """
    if not SCALE_OUT_ENABLED or pos.get("scaled_out"):
        return False
    contract = dict(pos.get("contract") or {})
    if not contract.get("right"):
        return False  # options only — equity sizing is share-based
    try:
        entry_premium = float(pos.get("entry_premium") or 0.0)
        qty = int(pos.get("filled_qty") or pos.get("qty") or 0)
    except (TypeError, ValueError):
        return False
    if entry_premium <= 0 or qty < 2 or mark <= 0:
        return False

    split = plan_scale_out(qty)
    if not split["enabled"]:
        return False
    gain_pct = (mark - entry_premium) / entry_premium * 100.0
    if gain_pct < split["first_target_pct"]:
        return False

    scale_qty = int(split["scale_qty"])
    runner_qty = int(split["runner_qty"])
    stop_order_id = pos.get("stop_order_id")

    # The resting stop covers the FULL size. It must come off before a partial
    # close, or the stop and the scale-out can both fill and oversell into a
    # naked short. CANCEL_FILLED means the stop beat us — the position is flat
    # and there is nothing left to scale.
    if stop_order_id:
        outcome = await _cancel_order_verified(stop_order_id)
        if outcome == CANCEL_FILLED:
            logger.warning(f"[SCALE-OUT] {ticker} protective stop filled first — nothing to scale")
            return False
        if outcome != CANCEL_CONFIRMED:
            logger.warning(
                f"[SCALE-OUT] {ticker} could not confirm the resting stop is dead ({outcome}) — "
                f"skipping the scale-out rather than risking a double sale"
            )
            return False
        pos["stop_order_id"] = None
        await state.set_position(ticker, pos)

    try:
        close_id = await _place_option_market_close(ticker, contract, scale_qty)
    except Exception as e:
        logger.error(f"[SCALE-OUT] {ticker} partial close FAILED: {e} — re-arming the full stop")
        try:
            await _reconcile_rearm_guard(ticker, pos)
        except Exception as re:
            logger.error(f"[SCALE-OUT] {ticker} stop re-arm after failed scale-out ALSO failed: {re}")
            await alerts.send(
                "critical", "scale_out_unprotected",
                f"{ticker}: scale-out failed AND the protective stop could not be re-armed — "
                f"position is UNPROTECTED, manual review needed",
            )
        return False

    fill = await _resolve_exit_fill(close_id)
    logger.info(
        f"[SCALE-OUT] {ticker} banked {scale_qty}/{qty} at +{gain_pct:.1f}% premium "
        f"(entry {entry_premium:.2f} → mark {mark:.2f}), {runner_qty} left running"
    )
    await trade_ledger.record("scaled_out", {
        "ticker": ticker, "scale_qty": scale_qty, "runner_qty": runner_qty,
        "entry_premium": round(entry_premium, 4), "mark": round(mark, 4),
        "gain_pct": round(gain_pct, 2), "order_id": close_id,
        "exit_premium": round(fill, 4) if fill else None,
    })

    # Book the realized half so the daily objective counter sees the money.
    realized = ((fill or mark) - entry_premium) * 100.0 * scale_qty
    try:
        await state.add_realized_usd(realized)
        await state.adjust_balance((fill or mark) * 100.0 * scale_qty)
    except Exception as e:
        logger.warning(f"[SCALE-OUT] {ticker} accounting update failed (non-fatal): {e}")

    # The position now tracks ONLY the runner. Its cost basis is unchanged (the
    # per-contract entry premium), so the trail's R math stays correct.
    pos["filled_qty"] = runner_qty
    pos["qty"] = runner_qty
    pos["scaled_out"] = True
    pos["scaled_out_qty"] = scale_qty
    pos["scaled_out_at"] = _utcnow().isoformat()
    await state.set_position(ticker, pos)

    # Re-arm protection over the runner immediately — an unprotected runner is
    # exactly the naked-position failure the whole guard architecture exists to
    # prevent.
    try:
        await _reconcile_rearm_guard(ticker, pos)
    except Exception as e:
        logger.error(f"[SCALE-OUT] {ticker} runner stop re-arm FAILED: {e}")
        await alerts.send(
            "critical", "scale_out_runner_unprotected",
            f"{ticker}: {runner_qty} runner contract(s) left WITHOUT a protective stop after "
            f"scale-out — manual review needed",
        )
    # SELL ALERT for the banked half. This is a REAL sale of real contracts and
    # never reaches `_record_close` (the position survives as the runner), so it
    # needs its own notice — otherwise the money hits the account silently.
    # `fill` is the broker's price; when it is unavailable the alert says the
    # dollars are marked, not filled, rather than presenting an estimate as fact.
    await _alert_fill(
        {
            "side": "SELL",
            "ticker": ticker,
            "contract": contract,
            "qty": scale_qty,
            "price": float(fill or mark),
            "price_confirmed": bool(fill),
            "entry_price": entry_premium,
            "realized_usd": round(realized, 2),
            "realized_pct": round(gain_pct, 2),
            "remaining_qty": runner_qty,
            "reason": "scale_out",
            "order_id": close_id,
        },
        dedupe_key=f"sellfill:scale:{close_id}:{scale_qty}",
    )
    return True


def plan_flatten(positions: dict, guards: dict) -> list:
    """Build the ordered EMERGENCY EXIT plan for every tracked position.

    The kill switch was a HALF-KILL: /kill set the killed flag so no new entries
    could dispatch, but every position already open kept running with only its
    resting stop for company. A "kill" that leaves live risk on the table is the
    most dangerous kind of safety control - it feels like an exit and isn't one.

    This is the pure planning half, so the sequencing is testable without a
    broker. Two rules matter and both cost real money when broken:

      CANCEL BEFORE CLOSE - the resting protective stop already pledges the
        shares/contracts. Sending a market close while it rests earns E*TRADE
        error 3004 ("already allocated to an existing open order") and the
        flatten silently fails on exactly the position you most wanted gone.

      NEVER GUESS A CONTRACT - an option close needs right + expiration +
        strike. Missing any of them, _emergency_flatten would raise mid-loop and
        abandon every remaining position, so those are reported BLOCKED instead
        and the loop carries on.

    Returns one entry per tracked ticker, sorted for deterministic execution.
    """
    plan: list = []
    for ticker in sorted(positions.keys()):
        pos = dict(positions.get(ticker) or {})
        guard = dict((guards or {}).get(ticker) or {})
        contract = pos.get("contract") or guard.get("contract") or None
        kind = str(guard.get("kind") or ("option" if contract else "equity"))
        try:
            qty = int(pos.get("filled_qty") or pos.get("qty") or guard.get("guarded_qty") or 0)
        except (TypeError, ValueError):
            qty = 0
        item = {
            "ticker": ticker,
            "qty": qty,
            "kind": kind,
            "contract": contract,
            "action": str(pos.get("action") or guard.get("action") or "BUY").upper(),
            "stop_order_id": pos.get("stop_order_id") or guard.get("stop_order_id") or None,
            "blocked": None,
        }
        if qty <= 0:
            item["blocked"] = "no tracked quantity to close"
        elif kind == "option":
            c = dict(contract or {})
            missing = [k for k in ("right", "expiration", "strike") if not c.get(k)]
            if missing:
                item["blocked"] = f"option contract incomplete (missing {', '.join(missing)})"
        plan.append(item)
    return plan


async def _finish_guard(ticker: str, result: str) -> None:
    await state.update_guard(ticker, done=True, result=result)
    logger.info(f"[STOP GUARD] {ticker} finished: {result}")
    await trade_ledger.record("guard_finished", {"ticker": ticker, "result": result})


async def _stop_guard_worker(ticker: str) -> None:
    """Poll the entry order; once (partially) filled, rest a protective STOP at
    the broker sized to the filled quantity (equity STOP, or SELL_CLOSE STOP on
    the same OCC contract for options). Cancel entries with zero fill at the
    deadline. Guard state lives in Redis (survives restarts); the per-ticker
    distributed lock guarantees exactly one worker guards a ticker across all
    instances."""
    lock = state.lock(f"guard:{ticker}", ttl_ms=(STOP_GUARD_POLL_SECONDS + 60) * 1000, wait_timeout=0.5)
    if not await lock.try_acquire():
        logger.info(f"[STOP GUARD] {ticker} already guarded by another worker — skipping")
        return
    logger.info(f"[STOP GUARD] watching {ticker} entry fill")
    try:
        while True:
            await lock.extend()
            guard = await state.get_guard(ticker)
            if not guard or guard.get("done"):
                return
            is_option = str(guard.get("kind") or "equity") == "option"

            status = str(guard.get("last_status") or "OPEN")
            filled = int(guard.get("last_filled") or 0)
            try:
                status, filled = await _order_state(guard.get("entry_order_id"), guard.get("entry_client_id"))
            except Exception as e:
                logger.warning(f"[STOP GUARD] {ticker} poll failed: {e}")

            # TIMEOUT CIRCUIT BREAKER anchor — the moment the FIRST fill is
            # detected, the stop-placement clock restarts: the protective stop
            # must rest at the broker within STOP_PLACEMENT_TIMEOUT_SECONDS of
            # the fill (not of entry placement), or the breaker below trips.
            if filled > 0 and not guard.get("fill_detected_ts") and STOP_PLACEMENT_TIMEOUT_SECONDS > 0:
                guard = await state.update_guard(
                    ticker,
                    fill_detected_ts=time.time(),
                    stop_deadline_ts=time.time() + STOP_PLACEMENT_TIMEOUT_SECONDS,
                ) or guard

            # ENTRY-FILL TRUTH — the tracked entry starts as the sanitized
            # LIMIT price; replace it with the broker's actual average
            # execution price as soon as a fill (or a bigger partial) is seen,
            # so every downstream P&L number measures from reality. `trued_qty`
            # re-arms the true-up when partials grow the position (the average
            # price moves with each partial).
            if filled > int(guard.get("trued_qty") or 0):
                if await _true_up_entry_fill(ticker, guard):
                    guard = await state.update_guard(ticker, trued_qty=filled) or guard
                    # BUY ALERT — fired here, not at placement: this is the first
                    # moment a real average execution price exists. The dedupe key
                    # carries the cumulative qty, so a re-poll cannot double-post
                    # while a growing partial still announces itself.
                    await _alert_entry_fill(ticker, guard, filled)

            guarded = int(guard.get("guarded_qty") or 0)
            if filled > guarded:
                # (Re)place the protective stop for the total filled quantity.
                can_place = True
                if guard.get("stop_order_id"):
                    # Replace flow: only place a new stop if the old one is truly
                    # cancelled — never risk two live stops double-selling, and
                    # never re-arm behind a stop that already filled.
                    replace_outcome = await _cancel_order_verified(guard.get("stop_order_id"))
                    can_place = replace_outcome == CANCEL_CONFIRMED
                    if replace_outcome == CANCEL_FILLED:
                        logger.warning(
                            f"[STOP GUARD] {ticker} protective stop already executed — position closed, "
                            f"not re-arming"
                        )
                        await _finish_guard(ticker, "closed_by_stop")
                        stop_fill = await _resolve_exit_fill(guard.get("stop_order_id"))
                        payload_g = {"ticker": ticker, "action": guard.get("action") or "BUY"}
                        if stop_fill and is_option:
                            await _record_close(ticker, None, payload_g, exit_premium=stop_fill, close_reason="stop_fill")
                        elif stop_fill:
                            await _record_close(ticker, stop_fill, payload_g, close_reason="stop_fill")
                        else:
                            await _defer_close_to_reconciler(ticker, guard.get("stop_order_id"),
                                                             "guard stop executed — fill price unavailable")
                        return
                if can_place:
                    try:
                        if is_option:
                            stop_info = await _place_option_protective_stop(
                                ticker, dict(guard.get("contract") or {}), filled,
                                float(guard.get("stop") or 0),
                            )
                        else:
                            stop_info = await _place_protective_stop(
                                ticker, str(guard.get("action") or "BUY"), filled,
                                float(guard.get("stop") or 0),
                            )
                        guard = await state.update_guard(
                            ticker,
                            guarded_qty=filled,
                            stop_order_id=stop_info["order_id"],
                            stop_client_id=stop_info["client_id"],
                        ) or guard
                        pos = await state.get_position(ticker)
                        if pos:
                            pos["stop_order_id"] = stop_info["order_id"]
                            pos["filled_qty"] = filled
                            await state.set_position(ticker, pos)
                        guarded = filled
                    except Exception as e:
                        # The OLD stop was already cancelled above and the new one
                        # did not stick, so nothing is resting. The guard record
                        # still pointed at the dead order id, and the stop-placement
                        # timeout breaker below only fires when `stop_order_id` is
                        # falsy — so a stale-truthy id disarmed the one control that
                        # emergency-flattens an unprotected fill. Clear it: the guard
                        # must describe what is ACTUALLY resting at the broker.
                        guard = await state.update_guard(ticker, stop_order_id=None,
                                                         stop_client_id=None) or guard
                        pos = await state.get_position(ticker)
                        if pos and pos.get("stop_order_id"):
                            pos["stop_order_id"] = None
                            await state.set_position(ticker, pos)
                        logger.error(f"[STOP GUARD] {ticker} stop placement FAILED (will retry): {e}")
                        await alerts.send(
                            "critical", "stop_placement_failed",
                            f"{ticker}: protective stop placement failed (guard will retry): {e}",
                            dedupe_key=f"guard_fail:{ticker}",
                        )

            guard = await state.update_guard(ticker, last_filled=filled, last_status=status) or guard

            # STOP PLACEMENT TIMEOUT CIRCUIT BREAKER — the bracket must be
            # complete (a protective stop RESTING at the broker) within
            # STOP_PLACEMENT_TIMEOUT_SECONDS. The clock starts at entry
            # placement and RE-ANCHORS to the first detected fill (above), so a
            # fill always gets the full window. Past the deadline with NO stop:
            #   • unfilled entry → cancel the entry order immediately
            #   • filled entry   → cancel any live remainder immediately, then
            #                      emergency market-flatten (a fill cannot be
            #                      cancelled — flattening is the equivalent).
            # The stop-placement attempt above always runs FIRST, so this only
            # fires when protection genuinely failed to stick in time.
            stop_deadline = float(guard.get("stop_deadline_ts") or 0)
            if stop_deadline and not guard.get("stop_order_id") and time.time() >= stop_deadline:
                if filled > 0:
                    if status not in _TERMINAL_ORDER_STATUSES:
                        await _cancel_order_safe(guard.get("entry_order_id"))
                    try:
                        flatten_id = await _emergency_flatten(ticker, guard, filled)
                        exit_fill = await _resolve_exit_fill(flatten_id)
                        payload_g = {"ticker": ticker, "action": guard.get("action") or "BUY"}
                        if exit_fill and is_option:
                            await _record_close(ticker, None, payload_g, exit_premium=exit_fill, close_reason="emergency_flatten_fill")
                        elif exit_fill:
                            await _record_close(ticker, exit_fill, payload_g, close_reason="emergency_flatten_fill")
                        else:
                            await _defer_close_to_reconciler(ticker, flatten_id,
                                                             "emergency flatten placed — fill not yet priced")
                        await _finish_guard(ticker, "stop_timeout_flattened")
                        await trade_ledger.record("stop_timeout_flattened", {
                            "ticker": ticker, "qty": filled, "flatten_order_id": flatten_id,
                            "timeout_seconds": STOP_PLACEMENT_TIMEOUT_SECONDS,
                        })
                        await alerts.send(
                            "critical", "stop_timeout_flattened",
                            f"{ticker}: no protective stop resting {STOP_PLACEMENT_TIMEOUT_SECONDS}s after entry "
                            f"— position flattened at market (qty={filled}, order={flatten_id})",
                            dedupe_key=f"stop_timeout:{ticker}",
                        )
                        return
                    except Exception as e:
                        logger.error(f"[STOP GUARD] {ticker} emergency flatten FAILED (will retry): {e}")
                        await alerts.send(
                            "critical", "stop_timeout_flatten_failed",
                            f"{ticker}: UNPROTECTED past the {STOP_PLACEMENT_TIMEOUT_SECONDS}s stop deadline and "
                            f"the emergency flatten failed (guard keeps retrying): {e}",
                            dedupe_key=f"stop_timeout_fail:{ticker}",
                        )
                        # Fall through — next poll retries the stop placement
                        # first, then this flatten again if it still won't stick.
                else:
                    await _cancel_order_safe(guard.get("entry_order_id"))
                    # Re-poll after the cancel: a fill may have raced it. If it
                    # did, keep looping — the stop gets placed next iteration
                    # (or the flatten branch above fires).
                    late_filled = 0
                    try:
                        _s2, late_filled = await _order_state(guard.get("entry_order_id"), guard.get("entry_client_id"))
                    except Exception as e:
                        logger.warning(f"[STOP GUARD] {ticker} post-cancel poll failed: {e}")
                    if late_filled > 0:
                        logger.warning(f"[STOP GUARD] {ticker} filled during timeout cancel (qty={late_filled}) — continuing guard")
                    else:
                        await _finish_guard(ticker, "stop_timeout_entry_cancelled")
                        await state.delete_position(ticker)
                        await trade_ledger.record("stop_timeout_entry_cancelled", {
                            "ticker": ticker, "entry_order_id": guard.get("entry_order_id"),
                            "timeout_seconds": STOP_PLACEMENT_TIMEOUT_SECONDS,
                        })
                        await alerts.send(
                            "warning", "stop_timeout_entry_cancelled",
                            f"{ticker}: entry unfilled and no protective stop within "
                            f"{STOP_PLACEMENT_TIMEOUT_SECONDS}s — entry auto-cancelled",
                            dedupe_key=f"stop_timeout:{ticker}",
                        )
                        return

            if status == "EXECUTED" and filled > 0 and guarded >= filled:
                await _finish_guard(ticker, "filled_and_protected")
                return
            if status in _TERMINAL_ORDER_STATUSES and status != "EXECUTED" and filled == 0:
                await _finish_guard(ticker, f"entry_{status.lower()}_unfilled")
                await state.delete_position(ticker)
                return
            if time.time() >= float(guard.get("deadline_ts") or 0):
                if filled == 0:
                    await _cancel_order_safe(guard.get("entry_order_id"))
                    await _finish_guard(ticker, "entry_timeout_cancelled")
                    await state.delete_position(ticker)
                    return
                if guarded >= filled:
                    await _finish_guard(ticker, "partial_fill_protected")
                    return
                # Filled but stop never stuck — keep trying rather than walk away.
                logger.error(f"[STOP GUARD] {ticker} UNPROTECTED at deadline — extending guard")
                await alerts.send(
                    "critical", "position_unprotected",
                    f"{ticker}: filled entry still has NO resting stop at the guard deadline — guard extended, retrying",
                    dedupe_key=f"unprotected:{ticker}",
                )
                await state.update_guard(ticker, deadline_ts=time.time() + ENTRY_FILL_TIMEOUT_MIN * 60)
            # Poll faster while the stop deadline is live and unmet so the 60s
            # rule is enforced with tight granularity, not at the next 10s tick.
            sleep_s = float(STOP_GUARD_POLL_SECONDS)
            if stop_deadline and not guard.get("stop_order_id"):
                sleep_s = max(1.0, min(sleep_s, stop_deadline - time.time()))
            await asyncio.sleep(sleep_s)
    finally:
        await lock.release()


def _spawn_guard(ticker: str) -> None:
    asyncio.create_task(_stop_guard_worker(ticker))


async def _arm_stop_guard(ticker: str, action: str, stop_price: float,
                          entry_order_id: Optional[str], entry_client_id: str,
                          kind: str = "equity", contract: Optional[dict] = None) -> None:
    """Persist guard state to Redis (restart-safe) and spawn the watcher task.
    kind='option' guards rest a SELL_CLOSE STOP on the same OCC contract;
    `stop_price` is then the protective PREMIUM trigger."""
    await state.set_guard(ticker, {
        "ticker": ticker,
        "kind": kind,
        "action": action,
        "stop": round(float(stop_price), 2),
        "contract": contract,
        "entry_order_id": entry_order_id,
        "entry_client_id": entry_client_id,
        "guarded_qty": 0,
        "last_filled": 0,
        "last_status": "OPEN",
        "stop_order_id": None,
        "stop_client_id": None,
        "armed_ts": time.time(),
        "deadline_ts": time.time() + ENTRY_FILL_TIMEOUT_MIN * 60,
        # STOP PLACEMENT TIMEOUT deadline — initially anchored at entry
        # placement; the guard worker re-anchors it to the first detected fill
        # so protection always gets the full window after the fill.
        "stop_deadline_ts": (time.time() + STOP_PLACEMENT_TIMEOUT_SECONDS) if STOP_PLACEMENT_TIMEOUT_SECONDS > 0 else 0,
        "fill_detected_ts": None,
        "done": False,
        "result": None,
    })
    _spawn_guard(ticker)


async def _resume_guards() -> None:
    """Respawn watcher tasks for guards interrupted by a restart. The guard
    lock makes this safe when several workers boot at once — only one wins."""
    pending = await state.pending_guards()
    for t in pending:
        logger.info(f"[STOP GUARD] resuming guard for {t} after restart")
        _spawn_guard(t)


# ==================== TRADE FILL ALERTS (buy / sell to Discord) ====================
# Every other alert in this bot fires when something is WRONG. These fire when
# something happened: real contracts bought, real contracts sold, at a real
# price, for real money.
#
# Three rules make them trustworthy:
#   1. ONLY BROKER-CONFIRMED PRICES. The alert is fired from the fill-truth
#      paths, never from order placement. A limit price is a request; posting it
#      as "bought at 2.44" when the fill came back 2.61 would make Discord a
#      record of intentions rather than of trades. Where a price could not be
#      confirmed the alert says so instead of quietly printing an estimate.
#   2. THE EXACT CONTRACT, NOT THE TICKER. Three strikes on the same symbol are
#      three different positions; "NVDA filled" cannot be reconciled against a
#      brokerage statement, so strike, right, expiry and per-contract price all
#      appear.
#   3. MONEY MODE IS UNMISSABLE. A sandbox fill that reads like a real one is
#      worse than no alert at all, so the banner states which it is every time.

OPTION_MULTIPLIER = 100.0

_CLOSE_REASON_LABELS = {
    "stop_fill": "protective stop executed at the broker",
    "close_fill": "closed on signal",
    "emergency_flatten_fill": "EMERGENCY FLATTEN (no protective stop could be placed)",
    "panic_exit": "PANIC EXIT (manual flatten-all)",
    "reconciler": "close detected by broker reconciliation",
    "trailing_stop": "trailing stop executed",
    "scale_out": "scale-out at the first target",
}


def _contract_label(ticker: str, contract: Optional[dict]) -> str:
    """'NVDA $190 CALL 2026-11-21' — the position, not just the symbol."""
    c = contract or {}
    right = str(c.get("right") or "").upper()
    strike = c.get("strike")
    expiry = str(c.get("expiration") or "")[:10]
    if not right or strike in (None, ""):
        return f"{str(ticker).upper()} shares"
    try:
        strike_txt = f"${float(strike):g}"
    except (TypeError, ValueError):
        strike_txt = f"${strike}"
    return f"{str(ticker).upper()} {strike_txt} {right} {expiry}".strip()


def _money(value: Optional[float]) -> str:
    if value is None:
        return "unknown"
    try:
        v = float(value)
    except (TypeError, ValueError):
        return "unknown"
    return f"{'-' if v < 0 else ''}${abs(v):,.2f}"


def format_fill_alert(fill: dict) -> dict:
    """Render a confirmed fill as a Discord message + a one-line log headline.

    Pure: takes a dict, returns {'headline', 'text', 'event', 'severity'}. All
    money is derived here so the app, the log and Discord can never disagree.

    Recognised keys: side ('BUY'|'SELL'), ticker, contract, qty, ordered_qty,
    price (per contract/share), entry_price (sells), realized_usd, realized_pct,
    remaining_qty, reason, order_id, live (bool), sandbox (bool), stop, target,
    price_confirmed (bool).
    """
    side = "SELL" if str(fill.get("side") or "BUY").upper() in ("SELL", "SELL_CLOSE", "EXIT") else "BUY"
    ticker = str(fill.get("ticker") or "?").upper()
    contract = fill.get("contract") or None
    is_option = bool((contract or {}).get("right"))
    label = _contract_label(ticker, contract)
    unit = "contract" if is_option else "share"
    qty = int(fill.get("qty") or 0)
    units = f"{qty} {unit}{'' if qty == 1 else 's'}"
    try:
        price = float(fill.get("price") or 0.0)
    except (TypeError, ValueError):
        price = 0.0
    multiplier = OPTION_MULTIPLIER if is_option else 1.0
    per_unit_usd = price * multiplier if price > 0 else None
    gross_usd = per_unit_usd * qty if (per_unit_usd is not None and qty > 0) else None
    confirmed = bool(fill.get("price_confirmed", True)) and price > 0

    if fill.get("sandbox"):
        banner = "🧪 **SANDBOX** — E*TRADE test environment, no real money moved"
    elif fill.get("live"):
        banner = "🔴 **REAL MONEY** — live E*TRADE account"
    else:
        banner = "📝 **PAPER** — simulated, no real money moved"

    lines: List[str] = []
    if side == "BUY":
        lines.append(f"🟩 **BOUGHT — {label}**")
    else:
        try:
            pnl = float(fill.get("realized_usd")) if fill.get("realized_usd") is not None else None
        except (TypeError, ValueError):
            pnl = None
        mark = "🟦" if pnl is None else ("✅" if pnl >= 0 else "🔴")
        lines.append(f"{mark} **SOLD — {label}**")
    lines.append(banner)

    ordered = int(fill.get("ordered_qty") or 0)
    if side == "BUY" and ordered > qty > 0:
        lines.append(f"> Quantity: **{units}** of {ordered} ordered (partial fill)")
    else:
        lines.append(f"> Quantity: **{units}**")

    price_word = "Fill price" if side == "BUY" else "Exit price"
    if confirmed:
        detail = f"> {price_word}: **${price:,.2f}** per {unit}"
        if is_option:
            detail += f" ({_money(per_unit_usd)} each ×100)"
        lines.append(detail)
    else:
        lines.append(
            f"> {price_word}: **not yet confirmed by the broker** — dollars below are "
            f"the last mark, not a fill"
        )
        if price > 0:
            lines.append(f"> Last mark: ${price:,.2f} per {unit}")

    if side == "BUY":
        if gross_usd is not None:
            lines.append(f"> Total {'paid' if confirmed else 'estimated'}: **{_money(gross_usd)}**")
        stop = fill.get("stop")
        target = fill.get("target")
        if stop:
            risk = None
            if price > 0:
                risk = (float(stop) - price) * multiplier * qty
            stop_line = f"> Protective stop: ${float(stop):,.2f}"
            if risk is not None:
                stop_line += f" — risking {_money(abs(risk))} if hit"
            lines.append(stop_line)
        if target:
            lines.append(f"> Target: ${float(target):,.2f}")
    else:
        if gross_usd is not None:
            lines.append(f"> Proceeds: **{_money(gross_usd)}**")
        entry_price = fill.get("entry_price")
        if entry_price:
            try:
                ep = float(entry_price)
                cost = ep * multiplier * qty
                lines.append(f"> Entry was: ${ep:,.2f} per {unit} ({_money(cost)} for {units})")
            except (TypeError, ValueError):
                pass
        pnl_usd = fill.get("realized_usd")
        pnl_pct = fill.get("realized_pct")
        if pnl_usd is not None:
            try:
                p = float(pnl_usd)
                pct_txt = ""
                if pnl_pct is not None:
                    pct_txt = f" ({float(pnl_pct):+.1f}%)"
                lines.append(f"> **P&L: {'+' if p >= 0 else ''}{_money(p)}{pct_txt}**")
            except (TypeError, ValueError):
                pass
        elif pnl_pct is not None:
            try:
                lines.append(f"> **P&L: {float(pnl_pct):+.1f}%** (dollar figure unavailable)")
            except (TypeError, ValueError):
                pass
        remaining = int(fill.get("remaining_qty") or 0)
        if remaining > 0:
            lines.append(f"> Still open: **{remaining} {unit}{'' if remaining == 1 else 's'}** running")
        else:
            lines.append("> Position now **flat**")

    reason = fill.get("reason")
    if reason:
        lines.append(f"> Why: {_CLOSE_REASON_LABELS.get(str(reason), str(reason))}")
    if fill.get("order_id"):
        lines.append(f"> Order: `{fill.get('order_id')}`")

    verb = "BOUGHT" if side == "BUY" else "SOLD"
    headline = f"{verb} {units} {label} @ ${price:,.2f}"
    if gross_usd is not None:
        headline += f" ({_money(gross_usd)}{' total' if qty > 1 else ''})"
    if side == "SELL" and fill.get("realized_usd") is not None:
        try:
            p = float(fill["realized_usd"])
            headline += f" — P&L {'+' if p >= 0 else ''}{_money(p)}"
        except (TypeError, ValueError):
            pass
    return {
        "event": "trade_buy_filled" if side == "BUY" else "trade_sell_filled",
        "severity": "info",
        "headline": headline,
        "text": "\n".join(lines),
    }


async def _alert_fill(fill: dict, dedupe_key: Optional[str] = None) -> None:
    """Deliver a fill notice. `force_deliver` is required: a fill is honestly
    `info` severity, and the default webhook floor is `warning` — without the
    bypass the one alert the operator actually wants would be logged and then
    dropped. Never raises: alerting must not be able to break trading."""
    try:
        fill = {**fill, "live": LIVE_TRADING and not is_sandbox, "sandbox": is_sandbox}
        rendered = format_fill_alert(fill)
        await alerts.send(
            rendered["severity"], rendered["event"], rendered["headline"],
            dedupe_key=dedupe_key,
            data={k: v for k, v in fill.items() if k != "contract"} | {"contract": fill.get("contract")},
            force_deliver=True,
            webhook_text=rendered["text"],
        )
    except Exception as e:
        logger.warning(f"fill alert failed (non-fatal): {e}")


async def _alert_entry_fill(ticker: str, guard: dict, filled: int) -> None:
    """Fire the BUY alert off the trued-up entry — the broker's real average
    execution price, already written into the position by `_true_up_entry_fill`.
    Priced from the position rather than the guard's limit so Discord shows what
    was actually paid."""
    pos = await state.get_position(ticker)
    if not pos:
        return
    contract = pos.get("contract") or guard.get("contract")
    is_option = bool((contract or {}).get("right"))
    price = float((pos.get("entry_premium") if is_option else pos.get("entry")) or 0)
    await _alert_fill(
        {
            "side": "BUY",
            "ticker": ticker,
            "contract": contract,
            "qty": int(filled),
            "ordered_qty": int(pos.get("qty") or filled),
            "price": price,
            "price_confirmed": price > 0,
            "stop": pos.get("stop_premium") or guard.get("stop") or pos.get("stop"),
            "target": pos.get("target"),
            "order_id": guard.get("entry_order_id"),
        },
        dedupe_key=f"buyfill:{guard.get('entry_order_id')}:{filled}",
    )


# ==================== POSITION LEDGER (Redis-backed) ====================
async def _record_open(ticker: str, qty: int, entry: Optional[float], stop: Optional[float],
                       target: Optional[float], contract: Optional[dict],
                       action: str = "BUY") -> None:
    await state.set_position(ticker, {
        "qty": int(qty),
        "action": str(action or "BUY").upper(),
        "entry": float(entry) if entry else None,
        "stop": float(stop) if stop else None,
        "target": float(target) if target else None,
        "ts": _utcnow().isoformat(),
        "contract": contract,
    })
    await state.incr_trades_today()
    await trade_ledger.record("position_opened", {
        "ticker": ticker, "qty": int(qty), "action": str(action or "BUY").upper(),
        "entry": float(entry) if entry else None,
        "stop": float(stop) if stop else None,
        "target": float(target) if target else None,
        "contract": contract,
    })


def _entry_direction(pos: Optional[dict], payload: dict) -> float:
    """+1 for a long position, -1 for a short — always from the ENTRY side.

    P&L direction is a property of how the position was OPENED, never of the
    order that closes it. A close payload carries the EXIT action
    (SELL / EXIT / CLOSE / SELL_CLOSE), so reading direction off the payload
    inverted the sign of every app-initiated exit: a long closed for a profit
    was booked as a LOSS into `realized_pnl_today_pct`, pushing the bot toward
    its daily loss limit on winners and relieving it on losers.

    The tracked position's own `action` is therefore authoritative. The payload
    is only consulted when no position is tracked, and an exit verb there is
    treated as closing a LONG (the overwhelmingly common case, and the same
    assumption the equity close path already makes when picking its exit side).
    """
    tracked = str((pos or {}).get("action") or "").upper()
    if tracked in {"BUY", "SELL"}:
        return 1.0 if tracked == "BUY" else -1.0
    action = str(payload.get("action") or "BUY").upper()
    if action in {"EXIT", "CLOSE", "SELL"} or str(payload.get("intent") or "").lower() == "close":
        return 1.0  # closing an untracked position — assume it was long
    return 1.0 if action == "BUY" else -1.0


async def _record_close(ticker: str, exit_price: Optional[float], payload: dict,
                        exit_premium: Optional[float] = None,
                        close_reason: Optional[str] = None) -> None:
    """Pop the position and feed realized pnl (signed by the ENTRY direction)
    into the daily loss-limit accounting — plus credit equity proceeds back
    into the tracked balance so wins/losses immediately update the funds
    available for the next entry.

    `exit_premium` books an OPTION close on the PREMIUM basis — the actual
    fill price of the option order (a protective premium stop executing at the
    broker). Premium move percent and real contract dollars (×100 multiplier)
    are what the trade actually made or lost; the underlying-move percent used
    for equities means almost nothing for a levered contract. The ledger
    records `basis` so replays and the app know which unit `entry`/`exit` are
    in. `close_reason` tags how the close was detected (e.g. the reconciler's
    fill capture) for the audit trail."""
    pos = await state.delete_position(ticker)
    entry = float((pos or {}).get("entry") or payload.get("entry") or 0)
    # NO GUESSED EXITS — exit_px is the caller's REAL fill or the payload's
    # explicit exit_price, nothing else. The old `… or limit_price or entry`
    # chain could book an option PREMIUM against an underlying entry (a fake
    # −99% into the daily loss counter) or a silent fake breakeven.
    exit_px = float(exit_price or payload.get("exit_price") or 0)
    direction = _entry_direction(pos, payload)
    qty = int((pos or {}).get("filled_qty") or (pos or {}).get("qty") or 0)
    is_option = _is_option_close(pos, exit_premium)
    entry_premium = float((pos or {}).get("entry_premium") or 0)
    pnl_pct: Optional[float] = None
    realized_usd: Optional[float] = None
    basis = "underlying"
    if exit_premium is not None and is_option and float(exit_premium) > 0:
        basis = "premium"
        exit_px = float(exit_premium)
        if entry_premium > 0:
            pnl_pct = direction * ((exit_px - entry_premium) / entry_premium * 100.0)
            if qty > 0:
                realized_usd = direction * (exit_px - entry_premium) * 100.0 * qty
    elif entry > 0 and exit_px > 0:
        pnl_pct = direction * ((exit_px - entry) / entry * 100.0)
        if qty > 0 and not is_option:
            realized_usd = direction * (exit_px - entry) * qty
    # DAILY LOSS-LIMIT CONTRIBUTION — an ACCOUNT-level percent, never a raw
    # per-trade move. Summing premium moves put the counter in the wrong unit
    # entirely: two ~50% option stop-outs read as "daily loss limit (-101.76%)"
    # against a 2% account-level limit. With the trade's real dollars and a
    # tracked balance the contribution is dollars/balance; without a balance
    # the raw per-trade percent remains as a deliberately OVER-braking
    # fallback (a too-sensitive halt is safe; an insensitive one is not).
    account_pct: Optional[float] = None
    if pnl_pct is not None:
        if realized_usd is not None:
            balance = None
            try:
                balance = await state.tracked_balance()
            except Exception:
                balance = None
            if balance and float(balance) > 0:
                account_pct = realized_usd / float(balance) * 100.0
            else:
                logger.warning(
                    f"[PNL] {ticker} no tracked balance — daily counter fed the raw "
                    f"per-trade move ({pnl_pct:+.2f}%) as an over-braking fallback"
                )
        await state.add_realized_pnl(account_pct if account_pct is not None else pnl_pct)
    # DAILY OBJECTIVE CONTRIBUTION — the same close in REAL DOLLARS. The $500
    # objective is denominated in money, and a percent of a moving balance can
    # never answer it. Only broker-verified dollars count: when the close had
    # no derivable dollar figure nothing is added, so the counter under-reports
    # rather than inventing progress toward a target (which would arm the
    # profit lock on a day that never actually made the money).
    if realized_usd is not None:
        try:
            await state.add_realized_usd(float(realized_usd))
        except Exception as e:
            logger.warning(f"[OBJECTIVE] {ticker} realized-USD accumulation failed (non-fatal): {e}")
    # BALANCE TRACKING — equity closes return known proceeds (qty × exit).
    if not is_option and exit_px > 0 and qty > 0:
        try:
            await state.adjust_balance(exit_px * qty)
        except Exception as e:
            logger.warning(f"balance credit failed (non-fatal): {e}")
    # Option closes booked on the premium basis carry the REAL fill, so the
    # proceeds are exact too: premium × 100 × contracts back into tracked funds.
    if is_option and basis == "premium" and exit_px > 0 and qty > 0:
        try:
            await state.adjust_balance(exit_px * 100.0 * qty)
        except Exception as e:
            logger.warning(f"balance credit failed (non-fatal): {e}")
    await trade_ledger.record("position_closed", {
        "ticker": ticker,
        # On the premium basis, entry/exit are BOTH premiums so a replay
        # re-derives the same percent the daily counter was fed.
        "entry": (entry_premium if basis == "premium" else entry) or None,
        "exit": exit_px or None,
        "basis": basis,
        # The ENTRY side is recorded explicitly so a later replay of the ledger
        # can verify the P&L sign without having to hunt for the matching open.
        "entry_action": "BUY" if direction > 0 else "SELL",
        "realized_pnl_pct": round(pnl_pct, 4) if pnl_pct is not None else None,
        "realized_pnl_usd": round(realized_usd, 2) if realized_usd is not None else None,
        # The ACCOUNT-level percent actually fed into the daily loss counter —
        # recorded so the ledger replay/repair verifies the same unit.
        "account_pnl_pct": round(account_pct, 4) if account_pct is not None else None,
        "qty": qty or None,
        "reason": close_reason,
    })
    # SELL ALERT — every close path in the bot funnels through `_record_close`
    # (protective stop fill, signalled close, trailing exit, emergency flatten,
    # panic exit, reconciler capture), so wiring the alert here means no real
    # sale can happen without Discord hearing about it.
    await _alert_fill(
        {
            "side": "SELL",
            "ticker": ticker,
            "contract": (pos or {}).get("contract"),
            "qty": qty,
            "price": exit_px,
            "price_confirmed": exit_px > 0,
            "entry_price": (entry_premium if basis == "premium" else entry) or None,
            "realized_usd": round(realized_usd, 2) if realized_usd is not None else None,
            "realized_pct": round(pnl_pct, 2) if pnl_pct is not None else None,
            "remaining_qty": 0,
            "reason": close_reason,
        },
        dedupe_key=f"sellfill:{ticker}:{qty}:{round(exit_px, 2)}",
    )


# ==================== DAILY P&L REPAIR (ledger replay) ====================
# Before the entry-direction fix, `_record_close` signed realized P&L off the
# CLOSE payload's action, so every app-initiated exit landed in
# `realized_pnl_today_pct` with the wrong sign. That figure drives the daily
# loss limit, so a day's stored value can still be inverted after redeploy —
# winners pushing the bot toward a halt, losers relieving it.
#
# The immutable ledger holds each close's entry, exit and (as-written) pct, so
# the true figure can be recomputed and the Redis counter corrected. The repair
# is deliberately FAIL-CLOSED: it only writes when the ledger fully accounts for
# the stored number, so a lost/partial ledger can never erase a real loss and
# hand the bot a fresh risk budget.
PNL_REPAIR_EPSILON = 0.0001
PNL_REPAIR_LEDGER_SCAN = 5000


def _ledger_close_direction(rec_data: dict, opens: Dict[str, str]) -> Optional[float]:
    """Entry direction for a ledger close: the close's own `entry_action` when
    present (written since the fix), else the last `position_opened` seen for
    that ticker. None when neither is known — such a close is left untouched."""
    explicit = str(rec_data.get("entry_action") or "").upper()
    if explicit in {"BUY", "SELL"}:
        return 1.0 if explicit == "BUY" else -1.0
    opened = opens.get(str(rec_data.get("ticker") or "").upper())
    if opened in {"BUY", "SELL"}:
        return 1.0 if opened == "BUY" else -1.0
    return None


def recompute_daily_pnl(records: List[dict], day: str) -> Dict[str, Any]:
    """Replay ledger records and recompute one UTC day's realized P&L percent.

    `records` must be chronological (oldest first) and may span earlier days —
    positions opened yesterday and closed today need their open event to know
    the entry side. Only closes stamped with `day` are counted.

    Returns {recorded, corrected, delta, closes, inverted, unresolved}, where
    `recorded` is the sum that was actually fed into Redis and `corrected` is
    the sum signed off the ENTRY side.
    """
    opens: Dict[str, str] = {}
    recorded = 0.0
    corrected = 0.0
    closes = 0
    inverted: List[Dict[str, Any]] = []
    unresolved: List[str] = []
    for rec in records:
        if not isinstance(rec, dict):
            continue
        event = str(rec.get("event") or "")
        data = rec.get("data") or {}
        if not isinstance(data, dict):
            continue
        ticker = str(data.get("ticker") or "").upper()
        if event == "position_opened":
            action = str(data.get("action") or "BUY").upper()
            if ticker:
                opens[ticker] = action if action in {"BUY", "SELL"} else "BUY"
            continue
        if event != "position_closed":
            continue
        same_day = str(rec.get("ts") or "").startswith(day)
        direction = _ledger_close_direction(data, opens)
        if ticker:
            opens.pop(ticker, None)
        if not same_day:
            continue
        # Since 5.22 the daily counter is fed the ACCOUNT-level percent
        # (`account_pnl_pct`), so the replay must count the same unit —
        # summing the raw per-trade move would "repair" the counter back into
        # the broken unit. Older records carry only `realized_pnl_pct`.
        acct_raw = data.get("account_pnl_pct")
        has_account = isinstance(acct_raw, (int, float)) and not isinstance(acct_raw, bool)
        try:
            as_written = float(acct_raw) if has_account else float(data.get("realized_pnl_pct") or 0.0)
        except (TypeError, ValueError):
            as_written = 0.0
            has_account = False
        closes += 1
        recorded += as_written
        entry = _positive_float(data.get("entry"))
        exit_px = _positive_float(data.get("exit"))
        if entry is None or exit_px is None or direction is None:
            # Nothing to recompute from — keep whatever was booked and say so.
            corrected += as_written
            if ticker:
                unresolved.append(ticker)
            continue
        true_pct = direction * ((exit_px - entry) / entry * 100.0)
        if has_account:
            # Account-scaled close: entry/exit re-derive the PER-TRADE move,
            # so only the SIGN is verifiable — the magnitude depends on the
            # balance at close time. A sign flip is the inversion bug.
            if as_written == 0.0 or true_pct == 0.0 or (true_pct > 0) == (as_written > 0):
                corrected += as_written
            else:
                corrected += -as_written
                inverted.append({
                    "ticker": ticker,
                    "booked_pct": round(as_written, 4),
                    "true_pct": round(-as_written, 4),
                })
            continue
        corrected += true_pct
        if abs(true_pct - as_written) > PNL_REPAIR_EPSILON:
            inverted.append({
                "ticker": ticker,
                "booked_pct": round(as_written, 4),
                "true_pct": round(true_pct, 4),
            })
    return {
        "day": day,
        "recorded": round(recorded, 6),
        "corrected": round(corrected, 6),
        "delta": round(corrected - recorded, 6),
        "closes": closes,
        "inverted": inverted,
        "unresolved": unresolved,
    }


def _pnl_repair_key(day: str) -> str:
    return f"daily_pnl_repair:{day}"


async def _repair_daily_pnl() -> Dict[str, Any]:
    """Correct today's stored `realized_pnl_today_pct` if the sign bug polluted
    it. Runs once per startup; safe to re-run (already-applied corrections are
    remembered per day, so a second pass is a no-op)."""
    day = _utcnow().date().isoformat()
    result: Dict[str, Any] = {"day": day, "status": "clean", "applied_delta": 0.0}
    try:
        stored = float((await state.get_daily())["realized_pnl_today_pct"])
        previous = 0.0
        raw_prev = await state.get(_pnl_repair_key(day))
        if raw_prev:
            try:
                previous = float((json.loads(raw_prev) or {}).get("applied_delta") or 0.0)
            except (json.JSONDecodeError, TypeError, ValueError):
                previous = 0.0
        replay = recompute_daily_pnl(trade_ledger.recent(PNL_REPAIR_LEDGER_SCAN), day)
        result.update({
            "stored": round(stored, 6),
            "ledger_recorded": replay["recorded"],
            "ledger_corrected": replay["corrected"],
            "closes": replay["closes"],
            "inverted": replay["inverted"],
            "unresolved": replay["unresolved"],
            "previously_applied": round(previous, 6),
        })
        needed = replay["delta"] - previous
        # FAIL-CLOSED: the ledger must explain the stored number (allowing for a
        # correction already applied). If it doesn't, the ledger is incomplete
        # (fresh disk after redeploy, closes booked before the ledger existed) —
        # correcting from it could wipe a genuine loss, so refuse and shout.
        if abs((replay["recorded"] + previous) - stored) > 0.01:
            result["status"] = "unverifiable"
            logger.warning(
                f"[PNL-REPAIR] ledger does not account for stored daily P&L "
                f"(stored={stored:.4f}%, ledger={replay['recorded']:.4f}%, "
                f"already_applied={previous:.4f}%) — leaving it untouched"
            )
            if replay["closes"] or abs(stored) > PNL_REPAIR_EPSILON:
                await alerts.send(
                    "warning", "daily_pnl_unverifiable",
                    f"Daily realized P&L ({stored:.2f}%) can't be verified against the trade "
                    f"ledger ({replay['recorded']:.2f}% over {replay['closes']} close(s)). "
                    "Left as-is — the daily loss limit still applies.",
                    dedupe_key=f"pnl_repair_unverifiable:{day}",
                )
        elif abs(needed) <= PNL_REPAIR_EPSILON:
            logger.info(
                f"[PNL-REPAIR] daily P&L verified against ledger — {stored:.4f}% "
                f"over {replay['closes']} close(s), no correction needed"
            )
        else:
            new_value = await state.add_realized_pnl(needed)
            result.update({
                "status": "repaired",
                "applied_delta": round(needed, 6),
                "new_value": round(float(new_value), 6),
            })
            names = ", ".join(i["ticker"] for i in replay["inverted"][:5]) or "—"
            logger.warning(
                f"[PNL-REPAIR] ✅ corrected daily realized P&L {stored:.4f}% → "
                f"{float(new_value):.4f}% ({len(replay['inverted'])} mis-signed close(s): {names})"
            )
            await trade_ledger.record("daily_pnl_repaired", {
                "day": day, "was": round(stored, 4), "now": round(float(new_value), 4),
                "delta": round(needed, 4), "closes": replay["closes"],
                "inverted": replay["inverted"],
            })
            await alerts.send(
                "warning", "daily_pnl_repaired",
                f"Daily realized P&L corrected {stored:.2f}% → {float(new_value):.2f}% — "
                f"{len(replay['inverted'])} close(s) were booked with an inverted sign.",
                dedupe_key=f"pnl_repair:{day}",
            )
        payload = dict(result)
        payload["applied_delta"] = round(previous + float(result.get("applied_delta") or 0.0), 6)
        payload["ts"] = _utcnow().isoformat()
        await state.set(_pnl_repair_key(day), json.dumps(payload), ex=3 * 24 * 3600)
    except Exception as e:
        result["status"] = "error"
        result["error"] = str(e)
        logger.error(f"[PNL-REPAIR] failed (non-fatal): {e}")
    return result


def _positive_float(value: Any) -> Optional[float]:
    """Parse a broker-reported number; None unless strictly positive."""
    try:
        f = float(value)
        return f if f > 0 else None
    except (TypeError, ValueError):
        return None


def _account_for_balance(acct_list: List[Dict[str, Any]], resolved_key: Optional[str]) -> Dict[str, Any]:
    """Pick the account record whose accountIdKey is the one orders route to.

    Falls back to the first ACTIVE account, then to the first record, mirroring
    `_resolve_account_id_key`'s own precedence so balance and orders can never
    disagree about which account is being traded."""
    if resolved_key:
        for acct in acct_list:
            if str(acct.get("accountIdKey") or "") == str(resolved_key):
                return acct
    return next(
        (a for a in acct_list if str(a.get("accountStatus", "")).upper() == "ACTIVE"),
        acct_list[0],
    )


async def _get_balance_compat(accounts: "pyetrade.ETradeAccounts", acct: Dict[str, Any]) -> Any:
    """Version-tolerant get_account_balance. pyetrade's signature changed
    across releases — older builds accept institution_type, newer ones raise
    "unexpected keyword argument 'institution_type'" (the exact failure seen
    in production). Try the richest kwargs first and strip unsupported ones
    on TypeError so balance-aware sizing works on every deployed pyetrade."""
    kwarg_sets: List[Dict[str, Any]] = [
        dict(account_type=acct.get("accountType"),
             institution_type=acct.get("institutionType", "BROKERAGE"),
             resp_format="json"),
        dict(account_type=acct.get("accountType"), real_time=True, resp_format="json"),
        dict(account_type=acct.get("accountType"), resp_format="json"),
        dict(resp_format="json"),
    ]
    last_error: Optional[Exception] = None
    for kwargs in kwarg_sets:
        try:
            return await _etrade_call(
                accounts.get_account_balance, acct["accountIdKey"],
                source="balance", **kwargs,
            )
        except TypeError as e:
            if "unexpected keyword argument" not in str(e):
                raise
            last_error = e
    raise last_error or TypeError("get_account_balance: no compatible signature found")


async def _fetch_broker_balance() -> Optional[Dict[str, Optional[float]]]:
    """ONE E*TRADE balance call → {'total': totalAccountValue, 'available':
    cash available for new orders}. Returns None on any failure — callers
    decide whether to fail closed or fall back to the tracked snapshot."""
    try:
        tokens = load_tokens()
        if not tokens:
            return None
        accounts = pyetrade.ETradeAccounts(
            CONSUMER_KEY, CONSUMER_SECRET,
            tokens["oauth_token"], tokens["oauth_token_secret"],
            dev=is_sandbox,
        )
        lst = await _etrade_call(accounts.list_accounts, resp_format="json", source="equity_accounts")
        acct_list = (((lst or {}).get("AccountListResponse") or {}).get("Accounts") or {}).get("Account") or []
        if isinstance(acct_list, dict):
            acct_list = [acct_list]
        if not acct_list:
            return None
        # Read the balance of the account orders ACTUALLY route to. Blindly
        # taking acct_list[0] read a DIFFERENT account whenever the resolved
        # key came from ETRADE_ACCOUNT_ID or the first-ACTIVE fallback (this
        # user has 3 linked accounts and hits that fallback every session) —
        # so pre-flight funds clamps, fail-closed sizing and the equity shown
        # in the app were all measured against money the bot cannot spend.
        acct = _account_for_balance(acct_list, await _resolve_account_id_key(tokens))
        bal = await _get_balance_compat(accounts, acct)
        computed = ((bal or {}).get("BalanceResponse", {}) or {}).get("Computed", {}) or {}
        real_time = computed.get("RealTimeValues", {}) or {}
        total = _positive_float(real_time.get("totalAccountValue"))
        # Cash actually spendable on new orders — the number that prevents
        # 8400 insufficient-funds rejections. Order of preference matches
        # E*TRADE's own "purchasing power" semantics for cash accounts.
        available = (
            _positive_float(computed.get("cashBuyingPower"))
            or _positive_float(computed.get("cashAvailableForInvestment"))
            or _positive_float(computed.get("marginBuyingPower"))
            or total
        )
        return {"total": total, "available": available}
    except Exception as e:
        logger.error(f"balance fetch failed ({e})")
        return None


async def _live_equity() -> Optional[float]:
    """Fetch real account equity from E*TRADE. Returns None on any failure —
    live sizing must FAIL CLOSED (reject the trade) rather than silently size
    off a default."""
    bal = await _fetch_broker_balance()
    return (bal or {}).get("total")


async def _available_funds() -> Optional[float]:
    """Best estimate of funds available for a NEW entry. A fresh broker fetch
    is always preferred (and refreshes the tracked snapshot); during broker
    hiccups it falls back to the last snapshot ± the win/loss/cost delta
    accumulated since. None when neither source is usable."""
    bal = await _fetch_broker_balance()
    fresh = (bal or {}).get("available")
    if fresh is not None and fresh > 0:
        try:
            await state.set_balance_snapshot(fresh)
        except Exception as e:
            logger.warning(f"balance snapshot store failed (non-fatal): {e}")
        return fresh
    tracked = await state.tracked_balance()
    if tracked is not None:
        logger.warning(
            f"💰 broker balance fetch unavailable — sizing from tracked balance ≈${tracked:.2f} "
            f"(last snapshot ± wins/losses/open orders)"
        )
        return tracked
    return None


# ==================== EXPIRY HELPER ====================
def _resolve_expiry_string(payload: dict) -> Optional[str]:
    """Return a clean 'YYYY-MM-DD' expiry string for pyetrade.

    pyetrade parses expiryDate with dateutil, so a plain ISO date string is the
    most reliable input. Prefer the explicit hint; otherwise rebuild it from the
    discrete year/month/day fields the app also sends.
    """
    raw = payload.get("expiration_hint") or payload.get("expiry")
    if raw:
        return str(raw)[:10]
    y = payload.get("expiration_year")
    m = payload.get("expiration_month")
    d = payload.get("expiration_day")
    if y and m and d:
        return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    return None


# ==================== OPTION PRICE SANITY ====================
def _round_to_option_tick(price: float, direction: str = "nearest") -> float:
    """Round an option premium to E*TRADE's accepted increments.

    E*TRADE Error 2040 rejects limit prices that aren't in valid increments:
    $0.05 ticks below $3.00 and $0.10 ticks at/above $3.00. Rounding to these
    ticks is accepted for ALL contracts (penny-pilot names simply allow finer
    increments too), so it is always safe.
    """
    price = max(0.01, float(price))
    tick = 0.05 if price < 3.0 else 0.10
    ticks = price / tick
    if direction == "up":
        ticks = math.ceil(ticks - 1e-9)
    elif direction == "down":
        ticks = math.floor(ticks + 1e-9)
    else:
        ticks = round(ticks)
    return max(tick, round(ticks * tick, 2))


def _clamp_option_stop_premium(candidate: float, fill_ref: float) -> tuple:
    """Clamp an app-supplied protective stop PREMIUM into the sanity band.

    The app derives this level from the underlying stop through delta, which is
    what finally makes broker-side risk equal the risk the user sized. It is
    still a number from another process, so it is bounded here:

      * tighter than OPTION_STOP_MIN_HAIRCUT_PCT of the fill — inside ordinary
        option noise; the position would scratch on the first tick.
      * wider than OPTION_STOP_MAX_HAIRCUT_PCT of the fill — risks MORE than
        the blind percentage stop this replaces.
      * at/above the fill, or non-positive — not a protective level at all.

    Returns `(stop, note)`; `note` is empty when the value passed untouched and
    is a human-readable explanation when it was clamped.
    """
    try:
        stop = float(candidate)
    except (TypeError, ValueError):
        return None, "was not a number — falling back to the percentage stop"
    if not math.isfinite(stop) or stop <= 0:
        return None, "was not positive — falling back to the percentage stop"
    try:
        fill = float(fill_ref)
    except (TypeError, ValueError):
        fill = 0.0
    if not math.isfinite(fill) or fill <= 0:
        # No reference premium to judge against; accept as-is (the guard still
        # reprices below the live bid if the broker rejects it).
        return round(stop, 2), ""

    tightest = fill * (1.0 - OPTION_STOP_MIN_HAIRCUT_PCT / 100.0)
    widest = fill * (1.0 - OPTION_STOP_MAX_HAIRCUT_PCT / 100.0)
    if widest <= 0:
        return None, "band collapsed (max haircut ≥ 100%) — falling back to the percentage stop"

    if stop > tightest:
        return round(tightest, 2), (
            f"{stop:.2f} risks only {((fill - stop) / fill * 100.0):.1f}% of the {fill:.2f} fill — "
            f"widened to {tightest:.2f} ({OPTION_STOP_MIN_HAIRCUT_PCT:.0f}% floor)"
        )
    if stop < widest:
        return round(widest, 2), (
            f"{stop:.2f} risks {((fill - stop) / fill * 100.0):.1f}% of the {fill:.2f} fill — "
            f"tightened to {widest:.2f} ({OPTION_STOP_MAX_HAIRCUT_PCT:.0f}% ceiling)"
        )
    return round(stop, 2), ""


# ==================== CONTRACT SNAP ====================
def _snap_option_contract(market, symbol: str, expiry: str, strike: float, call_put: str):
    """Snap a requested option expiry/strike to REAL listed contract values.

    Returns (expiry, strike, bid, ask). bid/ask are the REAL quote of the
    snapped contract straight from E*TRADE's chain (0.0 when unavailable) —
    used to sanitize the app's estimated limit price, which is modeled from
    the stock price and can drift far from the true premium (Error 1011) or
    land on an invalid tick (Error 2040).

    E*TRADE rejects orders for contracts that don't exist with
    "Error 2009: The symbol you entered does not appear to be valid" — the
    classic trigger is a 0DTE expiry landing on a market holiday (e.g.
    2026-07-03, July 4th observed) or an unlisted strike. Ask the option chain
    what actually exists and snap to the nearest listed expiry >= today and
    the nearest listed strike. Best effort: any lookup failure returns the
    original values so an order is never blocked by this helper.
    """
    snapped_expiry = str(expiry)[:10]
    snapped_strike = float(strike)
    real_bid = 0.0
    real_ask = 0.0

    try:
        requested = datetime.strptime(snapped_expiry, "%Y-%m-%d").date()
    except ValueError:
        logger.warning(f"Contract snap skipped — unparseable expiry '{expiry}'")
        return snapped_expiry, snapped_strike, real_bid, real_ask
    today = datetime.utcnow().date()

    try:
        resp = _sync_etrade_call(market.get_option_expire_date, symbol, resp_format="json", source="option_expiry")
        raw_dates = (((resp or {}).get("OptionExpireDateResponse") or {}).get("ExpirationDate")) or []
        if isinstance(raw_dates, dict):
            raw_dates = [raw_dates]
        listed = []
        for entry in raw_dates:
            try:
                listed.append(date(int(entry["year"]), int(entry["month"]), int(entry["day"])))
            except (KeyError, TypeError, ValueError):
                continue
        valid = [x for x in listed if x >= today]
        if valid and requested not in valid:
            best = min(valid, key=lambda x: abs((x - requested).days))
            logger.warning(
                f"⚠️ Expiry {requested} is not a listed {symbol} expiration "
                f"(holiday/weekend?) — snapping to {best}"
            )
            requested = best
            snapped_expiry = best.strftime("%Y-%m-%d")
    except Exception as e:
        logger.warning(f"Expiry snap skipped for {symbol}: {e}")
        return snapped_expiry, snapped_strike, real_bid, real_ask

    try:
        chains = _sync_etrade_call(
            market.get_option_chains,
            symbol,
            expiry_date=requested,
            chain_type=("CALL" if str(call_put).upper() == "CALL" else "PUT"),
            strike_price_near=int(round(snapped_strike)),
            no_of_strikes=10,
            resp_format="json",
            source="option_chain",
        )
        pairs = (((chains or {}).get("OptionChainResponse") or {}).get("OptionPair")) or []
        if isinstance(pairs, dict):
            pairs = [pairs]
        strikes = []
        for pair in pairs:
            leg = pair.get("Call") or pair.get("Put") or {}
            sp = leg.get("strikePrice")
            try:
                if sp is not None:
                    strikes.append((float(sp), leg))
            except (TypeError, ValueError):
                continue
        if strikes:
            nearest, best_leg = min(strikes, key=lambda t: abs(t[0] - snapped_strike))
            if abs(nearest - snapped_strike) > 1e-9:
                logger.warning(
                    f"⚠️ Strike {snapped_strike} not listed for {symbol} {snapped_expiry} "
                    f"— snapping to {nearest}"
                )
            snapped_strike = nearest
            try:
                real_bid = max(0.0, float(best_leg.get("bid") or 0))
                real_ask = max(0.0, float(best_leg.get("ask") or 0))
                logger.info(
                    f"📊 Real quote for {symbol} {snapped_expiry} {snapped_strike} {call_put}: "
                    f"bid={real_bid} ask={real_ask}"
                )
            except (TypeError, ValueError):
                real_bid = real_ask = 0.0
    except Exception as e:
        logger.warning(f"Strike snap skipped for {symbol} {snapped_expiry}: {e}")

    return snapped_expiry, snapped_strike, real_bid, real_ask


# ==================== LIVE TRADING ====================
async def execute_live_order(payload: dict):
    mode = payload.get("mode", "paper").lower()
    instrument = payload.get("instrument", "stock").lower()
    ticker = payload.get("ticker", "UNKNOWN")
    action = payload.get("action", "UNKNOWN").upper()

    logger.info(f"📥 Received signal → mode={mode}, instrument={instrument}, ticker={ticker}, action={action}")

    if mode != "live" or not LIVE_TRADING or is_sandbox:
        logger.info(f"⏭️ Skipping trade (mode={mode}, LIVE_TRADING={LIVE_TRADING}, sandbox={is_sandbox})")
        # Verbose reason so the app's dispatch log shows the true gate that
        # blocked the live send (mode vs env config) instead of a bare status.
        return {
            "status": "skipped",
            "reason": f"mode={mode}, LIVE_TRADING={LIVE_TRADING}, sandbox={is_sandbox}",
        }

    # A queued job may execute after conditions changed — re-check the hard
    # gates for ENTRIES here too (closes always pass: they reduce risk).
    is_close = _is_close_payload(payload)
    await check_risk_limits(is_close=is_close)

    if not is_close:
        if await state.is_killed():
            raise Exception("kill switch active — entry refused")
        if not _is_market_open() and not bool(payload.get("force_execute")):
            raise Exception("market closed — entry refused (exchange-aware calendar)")

    tokens = load_tokens()
    if not tokens:
        logger.error("❌ No E*TRADE tokens available")
        raise Exception("E*TRADE tokens not set")

    # NEVER pass the raw env value straight through — E*TRADE needs the opaque
    # accountIdKey from /accounts/list (Error 102 otherwise).
    account_id_key = await _resolve_account_id_key(tokens)

    client_order_id = str(uuid.uuid4().int)[:18]

    # DISTRIBUTED CRITICAL SECTION — one worker at a time may place/close
    # orders for this ticker (prevents double-placement across instances).
    order_lock = state.lock(f"order:{str(ticker).upper()}", ttl_ms=120_000, wait_timeout=30.0)
    try:
        await order_lock.acquire()
    except LockNotAcquired:
        raise Exception(f"order lock busy for {ticker} — another worker is placing/closing this ticker")

    try:
        if instrument == "option":
            symbol = payload["ticker"]
            strike = payload.get("strike_hint") or payload.get("strike")
            expiry = _resolve_expiry_string(payload)
            # The app sends `option_contracts`; accept `contracts`/`quantity`
            # aliases so hand-rolled test payloads size correctly too.
            quantity = int(
                payload.get("option_contracts")
                or payload.get("contracts")
                or payload.get("quantity")
                or 1
            )
            # INTENT ROUTING — a SELL signal is a bearish ENTRY (long PUT),
            # never a close. Only an explicit close intent reaches SELL_CLOSE.
            order_action, call_put = plan_option_route(
                action, is_close,
                payload.get("option_right") or payload.get("call_put") or "CALL",
            )
            is_exit = order_action == "SELL_CLOSE"

            if not strike or not expiry:
                raise Exception(f"Missing strike or expiration for option order. Got strike={strike}, expiry={expiry}")

            # Snap to a contract that actually exists on E*TRADE's chain.
            # Without this, a 0DTE expiry on a market holiday (or an unlisted
            # strike) fails with Error 2009 "symbol not valid".
            market = pyetrade.ETradeMarket(
                CONSUMER_KEY, CONSUMER_SECRET,
                tokens["oauth_token"], tokens["oauth_token_secret"],
                dev=is_sandbox,
            )
            expiry, strike, real_bid, real_ask = await asyncio.to_thread(
                _snap_option_contract, market, symbol, expiry, float(strike), call_put
            )

            # A LIMIT with a real premium is the most reliable for options; fall
            # back to MARKET only if no premium was supplied. NOTE: the app's
            # option_limit_price is an ESTIMATE modeled from the stock price —
            # it must be sanitized against the real bid/ask captured above or
            # E*TRADE rejects it (1011: too far from market; 2040: bad tick).
            limit_price = payload.get("option_limit_price") or payload.get("limit_price")

            # FLAT kwargs — pyetrade builds Order/Instrument/Product itself and
            # auto-previews (no manual previewId needed).
            common = dict(
                resp_format="json",
                accountIdKey=account_id_key,
                symbol=symbol,
                orderAction=order_action,
                clientOrderId=client_order_id,
                quantity=quantity,
                orderTerm="GOOD_FOR_DAY",
                marketSession="REGULAR",
                allOrNone=False,
                callPut=call_put,
                strikePrice=float(strike),
                expiryDate=expiry,  # "YYYY-MM-DD" string
            )

            if is_exit:
                # CLOSE FLOW: cancel the broker-resting protective option stop
                # FIRST (same discipline as equity) so the close can never
                # double-sell against it.
                sym_u = str(symbol).upper()
                pos = await state.get_position(sym_u) or {}
                # CLOSE QUANTITY TRUTH — cover what the account actually holds.
                # The payload count is stale whenever the entry was resized.
                cover_qty = _close_cover_qty(pos, quantity)
                if cover_qty != quantity:
                    logger.warning(
                        f"[CLOSE] {sym_u} covering tracked {cover_qty} contract(s) — payload said {quantity}"
                    )
                    quantity = cover_qty
                    common["quantity"] = quantity
                opt_guard = await state.get_guard(sym_u) or {}
                resting_stop_id = pos.get("stop_order_id") or opt_guard.get("stop_order_id")
                stop_outcome = await _cancel_order_verified(resting_stop_id)
                if stop_outcome == CANCEL_FILLED:
                    await _finish_guard(sym_u, "closed_by_stop")
                    stop_fill = await _resolve_exit_fill(resting_stop_id)
                    if stop_fill:
                        await _record_close(sym_u, None, payload, exit_premium=stop_fill, close_reason="stop_fill")
                    else:
                        await _defer_close_to_reconciler(sym_u, resting_stop_id,
                                                         "option stop executed — fill price unavailable")
                    logger.info(f"[LIVE option CLOSE] {sym_u} already closed by resting stop {resting_stop_id}")
                    return {
                        "status": "success",
                        "response": {"note": "resting protective stop already executed at broker", "stop_order_id": resting_stop_id},
                    }
                if stop_outcome == CANCEL_LIVE:
                    raise Exception(
                        f"could not cancel resting option stop {resting_stop_id} — refusing to double-sell {sym_u}"
                    )
                await _finish_guard(sym_u, "closed_by_app")

                # EXIT (SELL_CLOSE): protective exits must FILL. Default to
                # MARKET. An explicit `exit_limit_price` overrides; a resting
                # broker-side STOP is placed only when the app explicitly asks
                # (`broker_stop: true` + a stop level). Trailing-stop levels
                # are otherwise tracked app-side by the Auto-Exit engine.
                exit_limit = payload.get("exit_limit_price")
                broker_stop_level = payload.get("stop_price") or payload.get("trail_stop") or payload.get("stop")
                if exit_limit and float(exit_limit) > 0:
                    desired = float(exit_limit)
                    # A sell limit far BELOW the market is rejected (1011);
                    # clamp a stale low estimate up to the real bid, and round
                    # DOWN to a valid tick so the order stays marketable.
                    if real_bid > 0 and desired < real_bid:
                        logger.warning(f"Exit limit {desired} below real bid {real_bid} — lifting to bid")
                        desired = real_bid
                    common["priceType"] = "LIMIT"
                    common["limitPrice"] = _round_to_option_tick(desired, "down")
                elif payload.get("broker_stop") and broker_stop_level and float(broker_stop_level) > 0:
                    common["priceType"] = "STOP"
                    common["stopPrice"] = _round_to_option_tick(float(broker_stop_level), "down")
                    logger.info(f"Placing resting broker-side STOP close at {common['stopPrice']}")
                else:
                    common["priceType"] = "MARKET"
            else:
                # ENTRY (BUY_OPEN): NEVER a STOP/TRAILING_STOP price type — that
                # turns the entry into a trigger order instead of a fill (the
                # v2.8.0 design flaw). Stop/trail fields on entries are stored
                # app-side and enforced by the Auto-Exit engine.
                desired = float(limit_price) if limit_price and float(limit_price) > 0 else None
                if real_ask > 0:
                    # Sanitize against the REAL quote. The app's estimate is
                    # frequently far off the true premium:
                    #  - above ask → E*TRADE 1011 (limit too far above market)
                    #    and would overpay anyway → cap at ask
                    #  - below bid → resting order that never fills → lift to ask
                    #  - inside the spread → keep it
                    # Then round UP to a valid $0.05/$0.10 tick (2040 guard);
                    # one tick above ask is a normal marketable limit.
                    if desired is None or desired > real_ask or desired < real_bid:
                        if desired is not None:
                            logger.warning(
                                f"⚠️ App limit {desired} outside real market "
                                f"[{real_bid}, {real_ask}] — repricing to ask"
                            )
                        desired = real_ask
                    common["priceType"] = "LIMIT"
                    common["limitPrice"] = _round_to_option_tick(desired, "up")
                elif desired is not None:
                    # No real quote available — at minimum fix the tick size.
                    common["priceType"] = "LIMIT"
                    common["limitPrice"] = _round_to_option_tick(desired)
                else:
                    common["priceType"] = "MARKET"
                if payload.get("stop") or payload.get("trail_stop") or payload.get("stop_price"):
                    logger.info(
                        f"Entry stop telemetry noted (app-managed): stop={payload.get('stop') or payload.get('stop_price')} "
                        f"trail_stop={payload.get('trail_stop')} trail_amount={payload.get('trail_amount') or payload.get('trailing_stop_amount')}"
                    )

                # INTENT-PRESERVING SIZING — the app sized this trade on its
                # estimated premium. If the real market repriced the entry
                # upward, shrink the quantity to the app's intended DOLLARS
                # (or refuse when even one contract multiplies the plan).
                reprice = plan_entry_reprice(
                    limit_price, quantity,
                    float(common.get("limitPrice") or 0) or float(real_ask or 0),
                )
                if reprice["action"] == "reject":
                    await trade_ledger.record("entry_reprice_rejected", {
                        "ticker": str(symbol).upper(),
                        "estimate": float(limit_price or 0) or None,
                        "real": float(common.get("limitPrice") or 0) or float(real_ask or 0),
                        "qty_requested": quantity,
                        "drift_pct": reprice["drift_pct"],
                        "intended_usd": reprice["intended_usd"],
                        "one_contract_usd": reprice["actual_unit_usd"],
                    })
                    await alerts.send(
                        "warning", "entry_reprice_rejected",
                        f"{symbol}: entry REJECTED — real premium is {reprice['drift_pct']:.0f}% above the "
                        f"app's estimate (≈${reprice['actual_unit_usd']:.0f}/contract vs "
                        f"≈${reprice['intended_usd']:.0f} intended outlay). The sizing premise no longer exists.",
                        dedupe_key=f"reprice_reject:{symbol}",
                    )
                    raise Exception(
                        f"entry price drifted {reprice['drift_pct']:.0f}% above the app's estimate "
                        f"(≈${reprice['actual_unit_usd']:.0f}/contract vs ≈${reprice['intended_usd']:.0f} intended) "
                        f"— refusing to multiply the planned risk"
                    )
                if reprice["action"] == "resize":
                    logger.warning(
                        f"⚖️ {symbol} intent-preserving resize: qty {quantity} → {reprice['qty']} "
                        f"(estimate {limit_price} vs real {common.get('limitPrice')}, "
                        f"drift {reprice['drift_pct']:.0f}% — intended ≈${reprice['intended_usd']:.0f} preserved)"
                    )
                    await trade_ledger.record("entry_repriced", {
                        "ticker": str(symbol).upper(),
                        "estimate": float(limit_price or 0) or None,
                        "real": float(common.get("limitPrice") or 0) or float(real_ask or 0),
                        "qty_requested": quantity,
                        "qty_placed": reprice["qty"],
                        "drift_pct": reprice["drift_pct"],
                        "intended_usd": reprice["intended_usd"],
                    })
                    await alerts.send(
                        "warning", "entry_repriced",
                        f"{symbol}: real premium {reprice['drift_pct']:.0f}% above the app's estimate — "
                        f"resized {quantity} → {reprice['qty']} contract(s) to hold the intended "
                        f"≈${reprice['intended_usd']:.0f} outlay.",
                        dedupe_key=f"reprice_resize:{symbol}",
                    )
                    quantity = reprice["qty"]
                    common["quantity"] = quantity

            logger.info(f"📤 Placing OPTION: {json.dumps({k: v for k, v in common.items() if k != 'resp_format'})}")
            if is_exit:
                # Closes must always cover the full tracked position — never clamp.
                try:
                    final = await _place_order_smart("option", common, tokens)
                except Exception:
                    # The resting protective stop was cancelled above. A failed
                    # close must NOT leave the position naked until the next
                    # reconcile pass (up to 15 min off-hours) — re-arm now.
                    if pos:
                        try:
                            await _reconcile_rearm_guard(sym_u, dict(pos))
                            logger.warning(f"[CLOSE] {sym_u} close placement failed — protective stop re-armed")
                        except Exception as re_err:
                            logger.error(f"[CLOSE] {sym_u} close failed AND stop re-arm failed: {re_err}")
                    raise
            else:
                # Per-contract cost = premium × 100 shares. Prefer the sanitized
                # limit price (set from the real ask above); fall back to the
                # raw ask for MARKET orders.
                premium_ref = float(common.get("limitPrice") or 0) or float(real_ask or 0)
                final, quantity = await _place_entry_with_funds_clamp(
                    "option", common, tokens,
                    unit_cost=premium_ref * 100.0 if premium_ref > 0 else None,
                )
            logger.info(f"✅ LIVE OPTION TRADE SUCCESS: {symbol} {call_put} {strike} {expiry}")
            await _record_api_success()
            if is_exit:
                # CLOSE-FILL TRUTH: book the close at its ACTUAL executed
                # premium. A resting STOP close won't execute now — defer it
                # straight to the reconciler; MARKET/LIMIT closes fill in
                # seconds and are polled inline.
                close_order_id = _order_id_from_place(final)
                exit_fill = None
                if common.get("priceType") != "STOP":
                    exit_fill = await _resolve_exit_fill(close_order_id)
                if exit_fill:
                    await _record_close(sym_u, None, payload, exit_premium=exit_fill, close_reason="close_fill")
                else:
                    await _defer_close_to_reconciler(sym_u, close_order_id,
                                                     "option close placed — not executed yet")
            else:
                contract = {
                    "occ_symbol": _occ_symbol(symbol, expiry, call_put, float(strike)),
                    "right": call_put,
                    "strike": float(strike),
                    "expiration": expiry,
                }
                # Recorded as BUY always: the position IS long (BUY_OPEN), even
                # when the signal said SELL (bearish → long PUT). Recording the
                # signal verb would flip `_entry_direction` to −1 and invert the
                # premium P&L of every put exit.
                await _record_open(
                    str(symbol).upper(), quantity,
                    payload.get("entry"), payload.get("stop") or payload.get("stop_price"),
                    payload.get("target"), contract, "BUY",
                )
                # OPTION STOP PROTECTION — async guard task (state in Redis,
                # survives restarts): poll the fill, then rest a SELL_CLOSE
                # STOP on the same OCC contract.
                entry_order_id = _order_id_from_place(final)
                stop_premium: Optional[float] = None
                stop_basis = "pct_default"
                explicit = payload.get("option_stop_price")
                try:
                    if explicit is not None and float(explicit) > 0:
                        stop_premium = float(explicit)
                except (TypeError, ValueError):
                    stop_premium = None
                fill_ref = float(common.get("limitPrice") or 0)
                if stop_premium is not None:
                    # App-supplied premium stop (delta-derived). Clamp into the
                    # sanity band so a bad number can never rest a stop inside
                    # the noise or wider than the percentage stop it replaces.
                    stop_premium, clamp_note = _clamp_option_stop_premium(stop_premium, fill_ref)
                    stop_basis = str(payload.get("option_stop_basis") or "app_delta")
                    if clamp_note:
                        stop_basis = f"{stop_basis}+clamped"
                        logger.warning(f"⚠️ {symbol} app option stop {clamp_note}")
                if stop_premium is None and fill_ref > 0 and OPTION_STOP_LOSS_PCT > 0:
                    stop_premium = fill_ref * (1.0 - OPTION_STOP_LOSS_PCT / 100.0)
                if stop_premium and stop_premium > 0:
                    stop_premium = _round_to_option_tick(stop_premium, "down")
                    await _arm_stop_guard(
                        str(symbol).upper(), "BUY", stop_premium, entry_order_id, client_order_id,
                        kind="option", contract=contract,
                    )
                    pos_rec = await state.get_position(str(symbol).upper())
                    if pos_rec is not None:
                        pos_rec["stop_premium"] = stop_premium
                        # Premium basis for the server-side trailing engine —
                        # without it an option position cannot be trailed.
                        if fill_ref > 0:
                            pos_rec["entry_premium"] = round(fill_ref, 2)
                        await state.set_position(str(symbol).upper(), pos_rec)
                    risk_pct = ((fill_ref - stop_premium) / fill_ref * 100.0) if fill_ref > 0 else 0.0
                    logger.info(
                        f"[STOP GUARD] option guard armed for {symbol} at premium {stop_premium:.2f} "
                        f"(risk {risk_pct:.1f}% of {fill_ref:.2f}, basis={stop_basis}, entry order={entry_order_id})"
                    )
                else:
                    logger.warning(f"⚠️ {symbol} option entry has no derivable stop premium — no broker-side stop armed")
            return {"status": "success", "response": final}

        else:
            # EQUITY ORDER
            symbol = str(ticker).upper()
            limit_price = payload.get("limit_price")
            tracked_pos = await state.get_position(symbol)
            is_equity_exit = is_close or action in {"EXIT", "CLOSE"} or (action != "BUY" and tracked_pos is not None)

            if is_equity_exit:
                # LIVE EQUITY CLOSE — cancel the broker-resting protective stop
                # FIRST so the close can never double-sell against it.
                pos = tracked_pos or {}
                guard = await state.get_guard(symbol) or {}
                stop_order_id = pos.get("stop_order_id") or guard.get("stop_order_id")
                stop_outcome = await _cancel_order_verified(stop_order_id)
                already_closed_by_stop = stop_outcome == CANCEL_FILLED
                if stop_outcome == CANCEL_LIVE:
                    raise Exception(
                        f"could not cancel resting stop {stop_order_id} — refusing to double-sell {symbol}"
                    )
                await _finish_guard(symbol, "closed_by_app")
                if already_closed_by_stop:
                    stop_fill = await _resolve_exit_fill(stop_order_id)
                    if stop_fill:
                        await _record_close(symbol, stop_fill, payload, close_reason="stop_fill")
                    else:
                        await _defer_close_to_reconciler(symbol, stop_order_id,
                                                         "equity stop executed — fill price unavailable")
                    logger.info(f"[LIVE equity CLOSE] {symbol} already closed by resting stop {stop_order_id}")
                    return {
                        "status": "success",
                        "response": {"note": "resting protective stop already executed at broker", "stop_order_id": stop_order_id},
                    }

                qty = int(pos.get("filled_qty") or pos.get("qty") or payload.get("position_size_shares") or 0)
                if qty < 1:
                    raise Exception(
                        f"close refused — unknown quantity for {symbol} (no tracked position and no position_size_shares)"
                    )
                entry_action = str(pos.get("action") or ("BUY" if action != "BUY" else "SELL")).upper()
                exit_side = "SELL" if entry_action == "BUY" else "BUY_TO_COVER"
                common = dict(
                    resp_format="json",
                    accountIdKey=account_id_key,
                    symbol=symbol,
                    orderAction=exit_side,
                    clientOrderId=client_order_id,
                    quantity=qty,
                    orderTerm="GOOD_FOR_DAY",
                    marketSession="REGULAR",
                    allOrNone=False,
                    priceType="MARKET",  # protective closes prioritize certainty of fill
                )
                logger.info(f"📤 Placing EQUITY CLOSE: {json.dumps({k: v for k, v in common.items() if k != 'resp_format'})}")
                try:
                    final = await _place_order_smart("equity", common, tokens)
                except Exception:
                    # Stop already cancelled above — a failed close must not
                    # leave the position naked until the next reconcile pass.
                    if pos:
                        try:
                            await _reconcile_rearm_guard(symbol, dict(pos))
                            logger.warning(f"[CLOSE] {symbol} close placement failed — protective stop re-armed")
                        except Exception as re_err:
                            logger.error(f"[CLOSE] {symbol} close failed AND stop re-arm failed: {re_err}")
                    raise
                close_order_id = _order_id_from_place(final)
                exit_fill = await _resolve_exit_fill(close_order_id)
                if exit_fill:
                    await _record_close(symbol, exit_fill, payload, close_reason="close_fill")
                else:
                    await _defer_close_to_reconciler(symbol, close_order_id,
                                                     "equity close placed — not executed yet")
                logger.info(f"✅ LIVE EQUITY CLOSE SUCCESS: {exit_side} {qty} {symbol}")
                await _record_api_success()
                return {"status": "success", "response": final}

            # LIVE EQUITY ENTRY — FAIL-CLOSED sizing: never default to 1 share.
            shares_raw = payload.get("position_size_shares")
            try:
                quantity = int(shares_raw) if shares_raw is not None else 0
            except (TypeError, ValueError):
                quantity = 0
            entry_px = float(payload.get("entry") or payload.get("limit_price") or 0)
            stop_px = float(payload.get("stop") or payload.get("stop_price") or 0)
            if quantity < 1:
                dist = abs(entry_px - stop_px)
                equity_val = await _live_equity()
                if equity_val and equity_val > 0 and dist > 0:
                    quantity = int((equity_val * (RISK_PER_TRADE_PCT / 100.0)) // dist)
                    logger.info(f"sized {symbol} from live equity {equity_val:.2f}: qty={quantity}")
                if quantity < 1:
                    raise Exception(
                        "fail-closed sizing: position_size_shares missing/invalid and cannot size "
                        "from live equity — refusing to default to 1 share"
                    )

            if str(action or "BUY").upper() != "BUY":
                # A bare SELL with no tracked position would OPEN a naked short
                # (and E*TRADE expects SELL_SHORT for that anyway). Bearish
                # exposure routes through long PUTs on the option path.
                raise Exception(
                    "short equity entries are not supported — bearish signals route "
                    "through PUT options (instrument=option, option_right=PUT)"
                )
            order_action = "BUY"
            common = dict(
                resp_format="json",
                accountIdKey=account_id_key,
                symbol=symbol,
                orderAction=order_action,
                clientOrderId=client_order_id,
                quantity=quantity,
                orderTerm="GOOD_FOR_DAY",
                marketSession="REGULAR",
                allOrNone=False,
            )
            if limit_price and float(limit_price) > 0:
                common["priceType"] = "LIMIT"
                common["limitPrice"] = round(float(limit_price), 2)
            else:
                common["priceType"] = "MARKET"

            # ATOMIC OTOCO BEST-EFFORT — one linked Entry + Protective Stop
            # request via the raw Order API. E*TRADE's public API doesn't
            # officially support OCO/OTOCO, so rejection falls back to the
            # proven sequential path (entry + stop guard) and is remembered.
            if (
                ENABLE_RAW_OTOCO and USE_RAW_ORDER_API and stop_px > 0
                and not await state.exists("otoco:unsupported")
            ):
                try:
                    raw = _raw_client(tokens)
                    entry_detail = raw.order_detail(
                        [raw.equity_instrument(symbol, order_action, quantity)],
                        str(common.get("priceType") or "MARKET"),
                        limit_price=common.get("limitPrice"),
                    )
                    otoco_exit_side = "SELL" if order_action == "BUY" else "BUY_TO_COVER"
                    stop_detail = raw.order_detail(
                        [raw.equity_instrument(symbol, otoco_exit_side, quantity)],
                        "STOP", stop_price=round(stop_px, 2),
                    )
                    final = await raw.place_otoco_best_effort(
                        account_id_key, client_order_id, "EQ", entry_detail, stop_detail,
                    )
                    logger.info(f"✅ ATOMIC OTOCO accepted for {symbol} — entry + protective stop in ONE request")
                    await _record_api_success()
                    await _record_open(symbol, quantity, entry_px or None, stop_px or None,
                                       payload.get("target"), None, action)
                    return {"status": "success", "response": final, "otoco": True}
                except OTOCOUnsupported as e:
                    logger.warning(
                        f"OTOCO not accepted by E*TRADE ({e.message}) — falling back to entry + stop guard "
                        f"(skipping OTOCO attempts for {OTOCO_UNSUPPORTED_TTL // 3600}h)"
                    )
                    await state.set("otoco:unsupported", "1", ex=OTOCO_UNSUPPORTED_TTL)
                except ETradeAPIError as e:
                    logger.warning(f"OTOCO attempt failed ({e}) — falling back to entry + stop guard")

            logger.info(f"📤 Placing EQUITY: {json.dumps({k: v for k, v in common.items() if k != 'resp_format'})}")
            # Per-share cost for the pre-flight funds clamp — the limit price
            # when set, otherwise the signal's entry estimate for MARKET orders.
            share_cost = float(common.get("limitPrice") or 0) or (entry_px if entry_px > 0 else 0)
            final, quantity = await _place_entry_with_funds_clamp(
                "equity", common, tokens,
                unit_cost=share_cost if share_cost > 0 else None,
            )
            logger.info(f"✅ LIVE EQUITY TRADE SUCCESS: {action} {quantity} {symbol}")
            await _record_api_success()

            await _record_open(symbol, quantity, entry_px or None, stop_px or None, payload.get("target"), None, action)
            entry_order_id = _order_id_from_place(final)
            if stop_px > 0:
                # Arm the stop guard: poll the entry fill, then rest a real STOP
                # at E*TRADE so the position stays protected even if the app
                # goes offline.
                await _arm_stop_guard(symbol, action, stop_px, entry_order_id, client_order_id)
                logger.info(f"[STOP GUARD] armed for {symbol} at {stop_px:.2f} (entry order={entry_order_id})")
            else:
                logger.warning(f"⚠️ {symbol} live entry has NO stop level — no broker-side protective stop armed")
            return {"status": "success", "response": final}

    except Exception as e:
        # Only genuine broker/API failures feed the circuit breaker — our own
        # gate refusals are working-as-intended, not signs of a sick broker.
        if _is_local_refusal(str(e)):
            logger.info(f"↩︎ {ticker} refused locally (breaker untouched): {e}")
        else:
            await _record_api_failure("order_placement", str(e))
        await trade_ledger.record("order_failed", {
            "ticker": ticker, "action": action, "instrument": instrument,
            "error": str(e)[:300],
        })
        await alerts.send(
            "error", "order_failed",
            f"{ticker} {action} ({instrument}) failed: {e}",
            dedupe_key=f"order_failed:{ticker}",
        )
        logger.error(f"❌ LIVE TRADE FAILED: {e}")
        raise
    finally:
        await order_lock.release()


# ==================== WORKER ====================
# E*TRADE access tokens go INACTIVE after ~2h of no API traffic and can then
# only be reactivated via renew_access_token (they hard-expire at midnight ET
# and require a full relink after that). Renewing every ~50 minutes keeps the
# session alive all trading day without any user action.
TOKEN_KEEPALIVE_SECONDS = 50 * 60


async def token_keepalive_worker():
    while not _worker_stop:
        await asyncio.sleep(TOKEN_KEEPALIVE_SECONDS)
        tokens = load_tokens()
        if not tokens:
            continue
        if not _keepalive_should_run(_token_session["valid"]):
            # A midnight-ET-expired token can never be renewed back to life —
            # only a relink (save_tokens → session ACTIVE) restarts renewals.
            continue
        try:
            auth_manager = pyetrade.ETradeAccessManager(
                CONSUMER_KEY, CONSUMER_SECRET,
                tokens["oauth_token"], tokens["oauth_token_secret"],
            )
            await _etrade_call(auth_manager.renew_access_token, source="keepalive_renew")
            logger.info("🔄 Keepalive: E*TRADE access token renewed")
            _mark_token_session(True, "keepalive renew ok")
        except Exception as e:
            # Renewal fails after the midnight-ET hard expiry — that requires a
            # full relink from the app, so just log it (orders will 401 and the
            # app surfaces the relink prompt).
            logger.warning(f"Keepalive renewal failed (relink may be required): {e}")
            if _looks_like_auth_failure(e):
                _mark_token_session(False, "token renewal rejected — hard-expired at midnight ET, relink required")
            await alerts.send(
                "warning", "token_keepalive_failed",
                f"E*TRADE access token renewal failed — a relink may be required: {e}",
                dedupe_key="keepalive",
            )


async def _run_queued_job(raw: str) -> None:
    """Execute one queued signal with the SAME bookkeeping the direct path does.

    The queue IS the production path (it is used whenever Redis is present), but
    it used to swallow the outcome entirely: no dispatch verdict, no signal-key
    status, and — critically — no parking of 401 failures. That made the
    parked-signal replay-after-relink recovery dead code in production and left
    /status.recent_dispatches showing every real order stuck on 'queued'.
    """
    try:
        pd = dict(json.loads(raw)["payload"])
    except (json.JSONDecodeError, KeyError, TypeError) as e:
        logger.error(f"queued job unreadable — dropped: {e}")
        return

    sig_key = _signal_key(pd)
    mode = str(pd.get("mode") or "paper").lower()
    live_intent = mode == "live" and LIVE_TRADING and not is_sandbox
    try:
        result = await execute_live_order(pd)
        inner_status = str(result.get("status") or "processed")
        await state.set(sig_key, inner_status, ex=86400)
        await _record_dispatch_verdict(
            pd,
            "placed" if inner_status == "success" else inner_status,
            "" if inner_status == "success" else str(result.get("reason") or ""),
        )
    except Exception as e:
        err = str(e)
        # Same disconnect→relink recovery the direct path has: a signal that
        # failed ONLY because the session died is parked and replayed on relink
        # instead of being silently lost.
        if live_intent and _is_auth_error(err):
            _park_signal(pd)
            await state.set(sig_key, "parked", ex=86400)
            await _record_dispatch_verdict(pd, "parked", f"auth error — replays after relink: {err[:120]}")
            return
        await state.set(sig_key, "failed", ex=86400)
        await _record_dispatch_verdict(pd, "failed", err[:200])
        logger.error(f"Queued placement failed for {pd.get('ticker')}: {e}")


async def placement_worker():
    while not _worker_stop:
        try:
            if state.is_distributed:
                job = await state.queue_pop(QUEUE_KEY)
                if job:
                    await _run_queued_job(job)
                else:
                    await asyncio.sleep(0.5)
            else:
                await asyncio.sleep(1)
        except Exception as e:
            logger.error(f"Worker error: {e}")
            await asyncio.sleep(2)


# ==================== RECONCILIATION ENGINE WIRING ====================
# Dependency-injected so reconciliation.py never imports main_bot. The engine
# runs under the distributed `lock:reconcile` — one instance at a time.
def _reconcile_has_tokens() -> bool:
    return load_tokens() is not None


async def _reconcile_fetch_portfolio() -> Dict[str, Any]:
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE not linked")
    _require_probeable_session()
    try:
        acct_key = await _resolve_account_id_key(tokens)
        result = await _raw_client(tokens).get_portfolio(acct_key)
    except Exception as e:
        # The reconciler runs every 15 min even with the app closed — it is
        # the earliest detector of a midnight-ET token expiry.
        if _looks_like_auth_failure(e):
            _mark_token_session(False, "reconcile broker fetch rejected — token expired, relink required")
        raise
    _mark_token_session(True, "reconcile broker fetch ok")
    return result


async def _reconcile_fetch_orders() -> Dict[str, Any]:
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE not linked")
    _require_probeable_session()
    try:
        acct_key = await _resolve_account_id_key(tokens)
        result = await _raw_client(tokens).list_orders(acct_key)
    except Exception as e:
        if _looks_like_auth_failure(e):
            _mark_token_session(False, "reconcile broker fetch rejected — token expired, relink required")
        raise
    _mark_token_session(True, "reconcile broker fetch ok")
    return result


async def _reconcile_cancel(order_id: str) -> bool:
    return await _cancel_order_safe(order_id)


async def _reconcile_record_close(ticker: str, pos: dict, resolution: dict) -> None:
    """Book a broker-side close the reconciler captured — a protective stop (or
    other closing order) that EXECUTED while nothing was watching. Before fill
    capture, such an exit surfaced only as "ghost position removed": the fill
    price, realized P&L and outcome were discarded, so the daily loss limit
    stayed blind to stop-outs and the learning stack never graded the trade.

    Option fills are booked on the PREMIUM basis (the executed price of an
    option order IS the premium); equity fills on the underlying basis."""
    exit_price = float(resolution.get("exit_price") or 0)
    payload = {"ticker": ticker, "action": pos.get("action") or "BUY", "intent": "close"}
    reason = f"fill_capture:{resolution.get('source') or 'unknown'}"
    if str(resolution.get("basis") or "") == "premium":
        await _record_close(ticker, None, payload, exit_premium=exit_price, close_reason=reason)
    else:
        await _record_close(ticker, exit_price, payload, close_reason=reason)


async def _reconcile_rearm_guard(ticker: str, pos: dict) -> None:
    """Re-arm a protective stop for a position the reconciler found
    UNPROTECTED (filled at broker, no live stop, no active guard). Re-arms at
    the EFFECTIVE level — the trailing engine's ratcheted trail when one is
    recorded — never back at the looser original stop."""
    qty = int(pos.get("filled_qty") or pos.get("qty") or 0)
    if qty < 1:
        return
    is_buy = str(pos.get("action") or "BUY").upper() != "SELL"
    trail = float(pos.get("trail") or 0)
    contract = pos.get("contract")
    if contract and contract.get("right"):
        premium = float(pos.get("stop_premium") or 0)
        if trail > 0:
            premium = max(premium, trail)
        if premium <= 0:
            logger.warning(f"[RECONCILE] cannot re-arm option stop for {ticker} — no stop premium recorded")
            return
        stop_info = await _place_option_protective_stop(ticker, dict(contract), qty, premium)
    else:
        stop = float(pos.get("stop") or 0)
        if trail > 0:
            stop = max(stop, trail) if is_buy else (min(stop, trail) if stop > 0 else trail)
        if stop <= 0:
            return
        stop_info = await _place_protective_stop(ticker, str(pos.get("action") or "BUY"), qty, stop)
    pos["stop_order_id"] = stop_info["order_id"]
    pos["filled_qty"] = qty
    await state.set_position(ticker, pos)
    logger.warning(f"[RECONCILE] 🛡️ re-armed protective stop for {ticker} (order={stop_info['order_id']})")


def _start_reconciler() -> None:
    asyncio.create_task(reconciliation.reconciliation_loop(
        state,
        _reconcile_fetch_portfolio,
        _reconcile_fetch_orders,
        _reconcile_cancel,
        _is_market_open,
        _reconcile_has_tokens,
        rearm_guard=_reconcile_rearm_guard,
        record_close=_reconcile_record_close,
        interval_seconds=RECONCILE_INTERVAL_SECONDS,
        offhours_interval_seconds=RECONCILE_OFFHOURS_SECONDS,
        auto_heal=RECONCILE_AUTO_HEAL,
        stop_flag=lambda: _worker_stop,
        alert=alerts.send,
        fetch_balance=_fetch_broker_balance,
    ))


# ==================== SERVER-SIDE TRAILING-STOP ENGINE ====================
# The app's tiered trail (breakeven lock at +0.75R, then 0.75R/0.50R/0.35R
# tiers) previously only ran while the phone had the app open. This worker
# runs the SAME ladder at the broker: every TRAIL_INTERVAL_SECONDS during
# market hours it marks each tracked position, ratchets the watermark, and
# cancel/replaces the RESTING protective stop when the trail improves enough.
# It keeps running when the kill switch is engaged — tightening protection is
# a defensive action, never an entry.

async def _trail_ratchet_one(ticker: str, pos: dict) -> None:
    """Mark one position, ratchet its watermark, and cancel/replace the
    resting stop when the tiered trail has improved past the min step."""
    contract = pos.get("contract")
    is_option = bool(contract and contract.get("right"))
    qty = int(pos.get("filled_qty") or pos.get("qty") or 0)
    stop_order_id = pos.get("stop_order_id")
    if qty < 1:
        return

    bid, ask = await _current_bid_ask(ticker, dict(contract) if is_option else None)
    # Long options are ALWAYS held long here (exits are SELL_CLOSE), which is
    # exactly what `plan_ratchet` assumes. Deriving `is_buy` from the raw action
    # let a position tagged SELL flip the improvement comparison below against a
    # plan computed on the BUY side, so a genuine ratchet read as a regression
    # and never replaced.
    is_buy = is_option or str(pos.get("action") or "BUY").upper() != "SELL"
    # Conservative mark: longs (and long options) trail off the BID, shorts
    # off the ASK — the trail only ratchets on prices we could actually exit at.
    mark = bid if (is_buy or is_option) else ask
    if mark <= 0:
        return

    # Live round-trip spread on the same basis as the mark. It floors the trail
    # distance so a wide chain (ARM at 10.85/11.75) is never stopped out by its
    # own quote, and floors the min ratchet step so sub-spread moves don't burn
    # a cancel/replace round-trip.
    spread = (ask - bid) if (ask > 0 and bid > 0 and ask >= bid) else None

    # CAPTURE: bank half at the first target BEFORE the trail is evaluated, so
    # the runner ratchets on its own (smaller) size from this pass onward. When
    # contracts were sold the position shape changed underneath us — re-read it
    # from state and let the NEXT pass trail the runner.
    if await _maybe_scale_out(ticker, pos, mark):
        return

    plan = trailing_engine.plan_ratchet(
        pos, mark, min_step_frac=TRAIL_MIN_STEP_FRAC, spread=spread,
    )
    if plan is None:
        return

    prev_tier = pos.get("trail_tier")
    pos["initial_stop"] = plan["initial_stop"]
    pos["trail_high"] = plan["high_since"]
    pos["trail_low"] = plan["low_since"]
    pos["trail_tier"] = plan["trail"]["tier"]
    pos["trail_r"] = plan["trail"]["r_multiple"]
    pos["breakeven_locked"] = plan["trail"]["breakeven_locked"]
    pos["trail_mfe_pct"] = plan["trail"]["mfe_percent"]
    pos["trail_giveback"] = plan["trail"]["giveback_active"]
    pos["trail_checked_at"] = _utcnow().isoformat()

    new_stop = plan["new_stop"]
    if is_option:
        new_stop = _round_to_option_tick(new_stop, "down")
    replace = plan["should_replace"] and new_stop > float(plan["current_stop"]) if is_buy \
        else plan["should_replace"] and new_stop < float(plan["current_stop"])

    if not stop_order_id:
        # No stop resting (a placement failed, or the reconciler hasn't re-armed
        # yet). The watermark still advances and the improved level is recorded
        # as `trail`, so whoever re-arms does it at the RATCHETED price instead
        # of the original stop — an unprotected minute never costs progress.
        if replace:
            pos["trail"] = new_stop
            logger.info(
                f"[TRAIL] {ticker} no resting stop — banked ratchet level {new_stop:.2f} "
                f"for re-arm ({plan['trail']['tier']}, {plan['trail']['r_multiple']:+.2f}R)"
            )
        await state.set_position(ticker, pos)
        return

    if not replace:
        await state.set_position(ticker, pos)
        return

    # Cancel/replace: never leave two live stops, and only place after the
    # cancel is confirmed against the broker's own order book.
    outcome = await _cancel_order_verified(stop_order_id)
    if outcome == CANCEL_FILLED:
        # The stop we were about to tighten already triggered — the position is
        # flat. Replacing it would rest a naked short; book the close instead.
        logger.warning(f"[TRAIL] {ticker} resting stop {stop_order_id} already executed — booking the close")
        await _finish_guard(ticker, "closed_by_stop")
        # Book the REAL fill when readable; fall back to the stop's trigger
        # level — on the CORRECT basis. This site used to pass the option
        # premium level through the underlying `exit_price` parameter, booking
        # a premium (e.g. 3.70) against an underlying entry (e.g. 317): a
        # nonsense −99% that polluted the daily counter and the ledger.
        stop_fill = await _resolve_exit_fill(stop_order_id)
        level = float(stop_fill or plan["current_stop"])
        payload_t = {"ticker": ticker, "action": pos.get("action") or "BUY"}
        trail_reason = "trail_stop_fill" if stop_fill else "trail_stop_level"
        if is_option:
            await _record_close(ticker, None, payload_t, exit_premium=level, close_reason=trail_reason)
        else:
            await _record_close(ticker, level, payload_t, close_reason=trail_reason)
        await trade_ledger.record("trail_stop_executed", {
            "ticker": ticker, "stop": plan["current_stop"], "order_id": stop_order_id,
        })
        await alerts.send(
            "info", "trail_stop_executed",
            f"{ticker}: trailing stop filled at the broker around {float(plan['current_stop']):.2f} — position closed.",
            dedupe_key=f"trail_hit:{ticker}",
        )
        return
    if outcome != CANCEL_CONFIRMED:
        logger.warning(
            f"[TRAIL] {ticker} resting stop {stop_order_id} still live at the broker — ratchet skipped this pass"
        )
        await state.set_position(ticker, pos)
        return

    stop_info = None
    last_err: Optional[Exception] = None
    used_fallback = False
    for attempt in (1, 2):
        try:
            if is_option:
                stop_info = await _place_option_protective_stop(ticker, dict(contract), qty, new_stop)
            else:
                stop_info = await _place_protective_stop(ticker, str(pos.get("action") or "BUY"), qty, new_stop)
            break
        except Exception as e:
            last_err = e
            logger.error(f"[TRAIL] {ticker} ratchet placement failed (attempt {attempt}/2): {e}")

    if stop_info is None:
        used_fallback = True
        # Old stop is cancelled and the tighter one didn't stick. Rather than
        # sit naked until the next reconcile pass, immediately re-arm at the
        # level that WAS resting — worse protection than intended still beats
        # none at all.
        try:
            if is_option:
                stop_info = await _place_option_protective_stop(
                    ticker, dict(contract), qty, float(plan["current_stop"]),
                )
            else:
                stop_info = await _place_protective_stop(
                    ticker, str(pos.get("action") or "BUY"), qty, float(plan["current_stop"]),
                )
        except Exception as e:
            logger.error(f"[TRAIL] {ticker} fallback re-arm at previous level also failed: {e}")

    # Whether the fallback ran is tracked explicitly. Inferring it by comparing
    # the placed price against `new_stop` misread a SUCCESSFUL ratchet as a
    # failure whenever the placement helper's own rounding produced a value that
    # differed in the last float bit (_round2 can return 10.130000000000001 where
    # round(x, 2) returns 10.13) — the user then got a "could not tighten the
    # stop" alert about a stop that had just tightened correctly.
    if used_fallback and stop_info is not None:
        # Fallback re-arm succeeded: protection is restored at the old level and
        # the ratcheted level is banked for the next pass.
        pos["stop_order_id"] = stop_info["order_id"]
        pos["trail"] = float(stop_info["stop"])
        if is_option:
            pos["stop_premium"] = float(stop_info["stop"])
        await state.set_position(ticker, pos)
        logger.warning(
            f"[TRAIL] {ticker} ratchet to {new_stop:.2f} failed — protection restored at "
            f"{float(stop_info['stop']):.2f} (order={stop_info['order_id']}), will retry next pass"
        )
        await alerts.send(
            "warning", "trail_ratchet_recovered",
            f"{ticker}: could not tighten the stop to {new_stop:.2f} — the previous stop at "
            f"{float(stop_info['stop']):.2f} is resting again, so the position stayed protected. "
            f"Reason: {last_err}",
            dedupe_key=f"trail_recover:{ticker}",
        )
        return

    if stop_info is None:
        # Nothing rests at the broker — the position is UNPROTECTED. Record the
        # trail level so the reconciler re-arms at the ratcheted price, and scream.
        pos["stop_order_id"] = None
        pos["trail"] = new_stop
        await state.set_position(ticker, pos)
        await trade_ledger.record("trail_ratchet_failed", {
            "ticker": ticker, "new_stop": new_stop, "error": str(last_err),
        })
        await alerts.send(
            "critical", "trail_ratchet_failed",
            f"{ticker}: trailing ratchet cancelled the old stop but the new stop at {new_stop:.2f} "
            f"failed to rest — position unprotected until the reconciler re-arms: {last_err}",
            dedupe_key=f"trail_fail:{ticker}",
        )
        return

    pos["stop_order_id"] = stop_info["order_id"]
    pos["trail"] = float(stop_info["stop"])
    if is_option:
        pos["stop_premium"] = float(stop_info["stop"])
    await state.set_position(ticker, pos)
    tier = str(plan["trail"]["tier"])
    logger.info(
        f"[TRAIL] ⤴ {ticker} stop ratcheted {plan['current_stop']:.2f} → {float(stop_info['stop']):.2f} "
        f"({tier}, {plan['trail']['r_multiple']:+.2f}R, order={stop_info['order_id']})"
    )
    await trade_ledger.record("trail_ratcheted", {
        "ticker": ticker, "kind": "option" if is_option else "equity",
        "from": plan["current_stop"], "to": float(stop_info["stop"]),
        "tier": tier, "r_multiple": plan["trail"]["r_multiple"],
        "mfe_percent": plan["trail"]["mfe_percent"],
        "giveback_active": plan["trail"]["giveback_active"],
        "breakeven_locked": plan["trail"]["breakeven_locked"],
        "order_id": stop_info["order_id"],
    })
    if tier != prev_tier:
        await alerts.send(
            "info", "trail_tier_advanced",
            f"{ticker}: {trailing_engine.TRAIL_TIER_LABEL.get(tier, tier)} — stop now {float(stop_info['stop']):.2f} "
            f"(+{plan['trail']['r_multiple']:.2f}R shown)",
            dedupe_key=f"trail_tier:{ticker}:{tier}",
        )


async def _trail_pass() -> None:
    """One trailing pass over every tracked position with a resting stop.
    Positions whose entry guard is still active are skipped — the guard owns
    the stop until it finishes.

    "Active" means `reconciliation.guard_owns_stop`, not a bare `done` check. A
    guard whose task died (worker restart, unhandled exception) never sets
    `done`, and the bare check therefore skipped that ticker on EVERY pass for
    as long as the position was held — the trail silently stopped ratcheting on
    exactly the positions whose protection had already gone wrong once. The
    reconciler learned this lesson; the trailing pass had not.
    """
    positions = await state.all_positions()
    if not positions:
        return
    guards = await state.all_guards()
    now = time.time()
    for ticker, pos in positions.items():
        if reconciliation.guard_owns_stop(guards.get(ticker), now):
            continue
        try:
            await _trail_ratchet_one(ticker, pos)
        except Exception as e:
            logger.warning(f"[TRAIL] {ticker} pass failed: {e}")


async def trailing_worker():
    """Continuous server-side trail. Runs each pass under the distributed
    `lock:trail_engine` so exactly one worker trails at a time."""
    if not TRAIL_ENGINE_ENABLED:
        logger.info("[TRAIL] server-side trailing engine DISABLED (TRAIL_ENGINE_ENABLED=false)")
        return
    logger.info(
        f"[TRAIL] server-side trailing engine started — every {TRAIL_INTERVAL_SECONDS}s in-session, "
        f"min step {TRAIL_MIN_STEP_FRAC:.0%} of initial risk"
    )
    while not _worker_stop:
        try:
            if _is_market_open() and load_tokens() is not None:
                lock = state.lock("trail_engine", ttl_ms=max(60_000, TRAIL_INTERVAL_SECONDS * 2000))
                if await lock.try_acquire():
                    try:
                        await _trail_pass()
                    finally:
                        await lock.release()
        except Exception as e:
            logger.error(f"[TRAIL] loop error: {e}")
        await asyncio.sleep(TRAIL_INTERVAL_SECONDS)


async def _startup_reconcile() -> None:
    """BLOCKING broker reconciliation at boot — sync Redis truth with E*TRADE
    BEFORE the placement worker accepts any job. Closes the biggest cold-start
    gap: acting on stale positions/guards after a restart. Best-effort: a
    broker failure or timeout never blocks boot (the background engine
    retries), but it is alerted."""
    if not load_tokens():
        logger.info("[RECONCILE] startup pass skipped — E*TRADE not linked yet")
        return
    lock = state.lock(reconciliation.RECONCILE_LOCK, ttl_ms=STARTUP_RECONCILE_TIMEOUT_SECONDS * 2000)
    if not await lock.try_acquire():
        logger.info("[RECONCILE] startup pass skipped — another worker is reconciling")
        return
    try:
        logger.info("[RECONCILE] 🚀 startup pass — syncing state with broker before accepting orders")
        report = await asyncio.wait_for(
            reconciliation.reconcile_once(
                state, _reconcile_fetch_portfolio, _reconcile_fetch_orders,
                _reconcile_cancel, rearm_guard=_reconcile_rearm_guard,
                record_close=_reconcile_record_close,
                auto_heal=RECONCILE_AUTO_HEAL, alert=alerts.send,
            ),
            timeout=STARTUP_RECONCILE_TIMEOUT_SECONDS,
        )
        summary = {
            "ok": report.get("ok"),
            "tracked_positions": report.get("tracked_positions"),
            "broker_positions": report.get("broker_positions"),
            "live_orders": report.get("live_orders"),
            "healed": report.get("healed", []),
            "warnings": report.get("warnings", []),
        }
        logger.info(
            f"[RECONCILE] ✅ startup pass done — tracked={summary['tracked_positions']} "
            f"broker={summary['broker_positions']} orders={summary['live_orders']} "
            f"healed={len(summary['healed'])} warnings={len(summary['warnings'])}"
        )
        await trade_ledger.record("startup_reconcile", summary)
        if summary["warnings"]:
            await alerts.send(
                "warning", "startup_reconcile_warnings",
                "; ".join(str(w) for w in summary["warnings"][:5]),
                dedupe_key="startup_reconcile",
            )
    except asyncio.TimeoutError:
        logger.error(f"[RECONCILE] startup pass timed out ({STARTUP_RECONCILE_TIMEOUT_SECONDS}s) — background engine will retry")
        await alerts.send(
            "error", "startup_reconcile_timeout",
            f"Startup reconciliation timed out after {STARTUP_RECONCILE_TIMEOUT_SECONDS}s — background engine will retry",
            dedupe_key="startup_reconcile",
        )
    except Exception as e:
        logger.error(f"[RECONCILE] startup pass failed: {e}")
        await alerts.send(
            "error", "startup_reconcile_failed",
            f"Startup reconciliation failed: {e} — background engine will retry",
            dedupe_key="startup_reconcile",
        )
    finally:
        await lock.release()


# ==================== SERVER-SIDE SCANNER WIRING ====================
# Dependency-injected so scanner.py never imports main_bot. The loop runs
# under the distributed `lock:scanner` — one instance scans at a time.
scanner: Optional[scanner_mod.Scanner] = None


async def _scanner_fetch_quotes(symbols: List[str]) -> Dict[str, Any]:
    """Batched E*TRADE quote read for the scanner (same client/backoff path as
    the app-facing /etrade/quote endpoint)."""
    tokens = load_tokens()
    if not tokens:
        raise Exception("E*TRADE not linked")
    market = pyetrade.ETradeMarket(
        CONSUMER_KEY, CONSUMER_SECRET,
        tokens["oauth_token"], tokens["oauth_token_secret"], dev=is_sandbox,
    )
    return await _etrade_call(market.get_quote, list(symbols), resp_format="json", source="scanner_quote")


async def _scanner_dispatch(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Send a scanner candidate down the SAME pipeline as a webhook signal.
    The payload is validated with the identical model first, so a malformed
    scanner signal fails here instead of reaching the broker."""
    try:
        pd = WebhookPayload(**payload).dict()
    except ValidationError as e:
        return {"status": "invalid", "reason": str(e.errors()[:2])}
    pd.pop("secret", None)
    return await process_signal(pd)


def _scanner_now_et() -> datetime:
    return _utcnow().astimezone(_ET_ZONE)


async def _start_scanner() -> None:
    global scanner
    # Bind the scanner's configurable floors to THIS bot's live entry gate.
    # Without it a user could set the scanner to min_score 60 / min_rvol 1.0
    # and every candidate it dispatched would be rejected by
    # _passes_entry_filters() a millisecond later — a loop that burns the
    # daily signal budget and never places a trade.
    gate = scanner_mod.set_entry_gate_floors(MIN_SCORE, MIN_RVOL)
    logger.info(f"🔭 Scanner floors bound to entry gate — score ≥ {gate['min_score']}, rvol ≥ {gate['min_rvol']}")
    scanner = scanner_mod.Scanner(
        state,
        _scanner_fetch_quotes,
        _scanner_dispatch,
        _is_market_open,
        lambda: load_tokens() is not None,
        _scanner_now_et,
        alert=alerts.send,
        stop_flag=lambda: _worker_stop,
    )
    # Stored config wins (survives restarts, changed live from the app); env
    # vars only seed the very first boot.
    stored = await scanner.load_config()
    if not await state.get(scanner_mod.CONFIG_KEY):
        seed: Dict[str, Any] = {
            "mode": SCANNER_MODE if SCANNER_ENABLED else "off",
            "interval_seconds": SCANNER_INTERVAL_SECONDS,
            "max_signals_per_day": SCANNER_MAX_SIGNALS_PER_DAY,
        }
        if SCANNER_UNIVERSE.strip():
            seed["universe"] = SCANNER_UNIVERSE
        stored = await scanner.set_config(seed)
    logger.info(
        f"🔭 Scanner wired — mode={stored['mode']}, {len(stored['universe'])} symbols, "
        f"every {stored['interval_seconds']}s, budget {stored['max_signals_per_day']}/day"
    )
    asyncio.create_task(scanner.run())


async def start_worker():
    global _worker_task
    _worker_task = asyncio.create_task(placement_worker())
    asyncio.create_task(token_keepalive_worker())
    asyncio.create_task(trailing_worker())
    await _start_scanner()


# ==================== STARTUP ====================
@app.on_event("startup")
async def on_startup():
    global state
    logger.info(f"Starting → {'SANDBOX' if is_sandbox else 'PRODUCTION'} | LIVE={LIVE_TRADING} | VERSION={BOT_VERSION}")
    # Database FIRST — it now backs durable state and the ledger mirror, so it
    # must exist before the StateStore hydrates and before the ledger restores.
    await init_db()
    persistence = await _init_durable_state()
    # State next — everything else reads through it. With no Redis, the
    # Postgres adapter makes memory mode restart-safe (positions, guards,
    # daily P&L, kill switch all hydrate back).
    state = await StateStore.create(REDIS_URL, persistence=persistence)
    # Alerting + immutable ledger come up right after state — everything
    # downstream (breaker, guards, reconciler) reports through them.
    alerts.init(state, ALERT_WEBHOOK_URL, dedupe_seconds=ALERT_DEDUPE_SECONDS)
    # A webhook saved live via POST /alerts/config overrides the env default
    # and survives restarts — no redeploy needed to change alert delivery.
    await alerts.load_persisted()
    # Rebuild the JSONL ledger from the Postgres mirror if a redeploy wiped it,
    # then resume the hash chain and mirror every new record.
    await _restore_ledger_from_db()
    trade_ledger.init(TRADE_LEDGER_FILE)
    if persistence is not None:
        trade_ledger.set_mirror(_ledger_mirror)
    # Which account the user pinned from the app (survives restarts/redeploys).
    await _load_pinned_account()
    await preload_tokens()
    # One-time migration of the legacy JSON STATE_FILE into Redis (skipped when
    # Redis already holds state; the file is renamed *.migrated afterwards).
    await state.migrate_from_file(STATE_FILE)
    # DAILY P&L REPAIR — replay the ledger and correct today's realized P&L if
    # the old sign bug inverted any close. Fail-closed: never writes unless the
    # ledger fully accounts for the stored figure.
    global _last_pnl_repair
    _last_pnl_repair = await _repair_daily_pnl()
    # STARTUP RECONCILIATION — blocking broker→Redis sync BEFORE the placement
    # worker starts, so no order is ever placed against stale cold-start state.
    await _startup_reconcile()
    # Resume stop-guards interrupted by the restart (guard lock makes this
    # multi-worker safe) and start the background reconciliation engine.
    await _resume_guards()
    _start_reconciler()
    await start_worker()
    logger.info(f"✅ Bot ready (state backend: {state.backend_name})")


@app.on_event("shutdown")
async def on_shutdown():
    global _worker_stop
    _worker_stop = True
    await state.close()


# ==================== DISPATCH VERDICT LOG ====================
# Every /webhook exit path used to answer 200 OK with the verdict buried in
# the JSON body — rejected/cooldown/duplicate/skip dispatches left ZERO trace
# in the server log. One INFO line per verdict + a capped state list surfaced
# via /status.recent_dispatches makes every dispatch outcome observable.
DISPATCH_LOG_KEY = "dispatch:recent"
DISPATCH_LOG_MAX = 50


async def _record_dispatch_verdict(pd: dict, verdict: str, reason: str = "") -> None:
    ticker = str(pd.get("ticker") or "?").upper()
    action = str(pd.get("action") or "?").upper()
    mode = str(pd.get("mode") or "paper").lower()
    line = f"📨 Dispatch verdict: {verdict.upper()} — {ticker} {action} mode={mode}"
    if reason:
        line += f" — {reason}"
    if verdict in ("rejected", "failed", "error", "parked"):
        logger.warning(line)
    else:
        logger.info(line)
    entry = {
        "ts": _utcnow().isoformat(),
        "ticker": ticker,
        "action": action,
        "mode": mode,
        "verdict": verdict,
        "reason": reason or None,
    }
    try:
        await state.list_push_capped(DISPATCH_LOG_KEY, json.dumps(entry), max_len=DISPATCH_LOG_MAX)
    except Exception as e:
        logger.warning(f"dispatch verdict record failed: {e}")


async def _recent_dispatch_verdicts(count: int = 20) -> List[dict]:
    out: List[dict] = []
    try:
        for raw in await state.list_range(DISPATCH_LOG_KEY, count):
            try:
                parsed = json.loads(raw)
                if isinstance(parsed, dict):
                    out.append(parsed)
            except json.JSONDecodeError:
                continue
    except Exception as e:
        logger.warning(f"dispatch verdict read failed: {e}")
    return out


# ==================== APP LINK — THE BOT'S EYES ON THE APP ====================
# The bot has always been able to act completely alone: the scanner finds its
# own setups and places real orders with no app involved. What it could never
# do is notice that the operator's app had gone dark, disarmed, or was running
# in a different money mode than the bot. Those are the states where autonomous
# trading is most dangerous and they were entirely invisible from the server.
APP_HEARTBEAT_KEY = "app:heartbeat"
# A phone that backgrounds the app stops beating. Three missed 60s beats is a
# real absence, not a scroll away from the screen.
APP_LINK_STALE_SECONDS = 210
APP_HEARTBEAT_TTL_SECONDS = 86_400


def assess_app_link(
    heartbeat: Optional[dict],
    tracked: Dict[str, dict],
    live_trading: bool,
    killed: bool,
    now: float,
    stale_after: int = APP_LINK_STALE_SECONDS,
) -> Dict[str, Any]:
    """What the bot can see of the app, and where the two disagree.

    Divergence between app and bot is not cosmetic. Each kind below has already
    got money at stake behind it:

    - `app_dark` — the bot is holding live positions and nobody is watching the
      screen that would show them. Alone that is fine (the bot self-heals); it
      matters because it is the state in which every OTHER divergence goes
      unnoticed.
    - `mode_mismatch` — the app believes it is paper trading while the server is
      LIVE. Someone is placing what they think are simulated orders with real
      money, which is the single most expensive misunderstanding this system can
      produce.
    - `position_mismatch` — the app's journal and the bot's book hold different
      numbers of positions. Exactly the drift the reconciler catches at the
      broker, one layer up.
    - `armed_mismatch` — the operator disarmed the app while the server-side
      scanner keeps trading. Disarming the app has never stopped the bot, and
      nothing ever said so out loud.

    Pure: no I/O, fully unit-testable.
    """
    out: Dict[str, Any] = {
        "connected": False,
        "seconds_since": None,
        "stale": True,
        "armed": None,
        "mode": None,
        "app_version": None,
        "last_seen": None,
        "divergences": [],
    }
    open_count = len(tracked)

    if not isinstance(heartbeat, dict) or not heartbeat:
        if open_count > 0 and not killed:
            out["divergences"].append({
                "kind": "app_dark",
                "severity": "warning",
                "detail": (f"No app has ever checked in, and the bot is holding {open_count} "
                           f"open position(s). Everything is running unobserved."),
            })
        return out

    try:
        received = float(heartbeat.get("received_epoch") or 0)
    except (TypeError, ValueError):
        received = 0.0
    seconds_since = max(now - received, 0.0) if received > 0 else None
    stale = seconds_since is None or seconds_since > stale_after

    mode = str(heartbeat.get("mode") or "").lower() or None
    armed = heartbeat.get("armed")
    armed = bool(armed) if isinstance(armed, bool) else None
    app_positions = heartbeat.get("open_positions")
    try:
        app_positions = int(app_positions) if app_positions is not None else None
    except (TypeError, ValueError):
        app_positions = None

    out.update({
        "connected": not stale,
        "seconds_since": round(seconds_since, 1) if seconds_since is not None else None,
        "stale": stale,
        "armed": armed,
        "mode": mode,
        "app_version": heartbeat.get("app_version"),
        "last_seen": heartbeat.get("ts"),
    })

    if stale and open_count > 0 and not killed:
        age = f"{int(seconds_since)}s" if seconds_since is not None else "an unknown time"
        out["divergences"].append({
            "kind": "app_dark",
            "severity": "warning",
            "detail": (f"The app has not checked in for {age} while the bot holds "
                       f"{open_count} open position(s). Nobody is watching the screen."),
        })

    # Only trust a FRESH heartbeat for the comparisons below — a stale one
    # describes a state the app may have left hours ago, and raising a mode
    # mismatch off a dead beat is how a safety alert becomes noise.
    if not stale:
        if live_trading and mode in {"paper", "sandbox"}:
            out["divergences"].append({
                "kind": "mode_mismatch",
                "severity": "critical",
                "detail": (f"The app reports {mode.upper()} mode but this bot is LIVE — orders "
                           f"placed from here spend real money."),
            })
        elif not live_trading and mode == "live":
            out["divergences"].append({
                "kind": "mode_mismatch",
                "severity": "warning",
                "detail": ("The app reports LIVE mode but this bot has LIVE_TRADING off — "
                           "real orders will not be placed from the server."),
            })
        if app_positions is not None and app_positions != open_count:
            out["divergences"].append({
                "kind": "position_mismatch",
                "severity": "warning",
                "detail": (f"The app journals {app_positions} open position(s); the bot's book "
                           f"holds {open_count}."),
            })
        if armed is False and open_count > 0 and not killed:
            out["divergences"].append({
                "kind": "armed_mismatch",
                "severity": "warning",
                "detail": (f"The app is DISARMED but the bot still holds {open_count} open "
                           f"position(s) and keeps managing them. Disarming the app does not "
                           f"stop the server — use the kill switch for that."),
            })

    return out


async def _load_app_heartbeat() -> Optional[dict]:
    try:
        raw = await state.get(APP_HEARTBEAT_KEY)
        if not raw:
            return None
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else None
    except Exception as e:
        logger.debug(f"app heartbeat read failed: {e}")
        return None


async def _app_link_snapshot() -> Dict[str, Any]:
    try:
        return assess_app_link(
            await _load_app_heartbeat(),
            await state.all_positions(),
            LIVE_TRADING,
            await state.is_killed(),
            time.time(),
        )
    except Exception as e:
        logger.warning(f"app link assessment failed: {e}")
        return {"connected": False, "stale": True, "divergences": [], "error": str(e)}


# ==================== ENDPOINTS ====================
# NOTE: "/" is a deliberate alias — apps configured with the bare bot host as
# their webhook URL used to hit `POST /` and 404, silently losing the order
# (observed live 2026-07-30 19:02 UTC). Root posts now land in the same
# authenticated webhook handler.
@app.post("/")
@app.post("/webhook")
async def webhook(
    request: Request,
    x_rork_secret: Optional[str] = Header(None, alias="X-Rork-Secret"),
    x_signature: Optional[str] = Header(None, alias="X-Rork-Signature"),
):
    # Raw body first — the HMAC signature (X-Rork-Signature) is computed over
    # the exact bytes the app sent. Shared secret (body field or X-Rork-Secret
    # header) is accepted as before.
    raw = await request.body()
    try:
        data = json.loads(raw or b"{}")
    except json.JSONDecodeError:
        raise HTTPException(400, "invalid json")
    if not isinstance(data, dict):
        raise HTTPException(400, "invalid payload")
    _verify_webhook_auth(raw, data.get("secret"), x_rork_secret, x_signature)
    try:
        payload = WebhookPayload(**data)
    except ValidationError as e:
        raise HTTPException(400, f"invalid payload: {e.errors()[:3]}")

    pd = payload.dict()
    pd.pop("secret", None)  # never persist/queue the shared secret
    return await process_signal(pd)


async def process_signal(pd: dict) -> dict:
    """Idempotency → gates → queue/execute for ONE signal.

    Extracted from the /webhook handler so the server-side scanner dispatches
    through the byte-identical path an app signal takes: same duplicate key,
    same market-hours check, same entry filters, same ticker cooldown, same
    queueing and the same parked-signal recovery. A scanner signal can never
    take a shortcut around a risk gate."""
    sig_key = _signal_key(pd)
    is_close = _is_close_payload(pd)
    mode = str(pd.get("mode") or "paper").lower()
    live_intent = mode == "live" and LIVE_TRADING and not is_sandbox

    # Atomic idempotency in Redis (SET NX + TTL) — a network retry or a second
    # worker can never double-place an order.
    if not await state.set(sig_key, "processing", ex=86400, nx=True):
        existing = await state.get(sig_key)
        await _record_dispatch_verdict(pd, "duplicate", f"existing_status={existing}")
        return {"status": "duplicate", "existing_status": existing, "signal_id": sig_key}

    # Server-side gates for LIVE ENTRIES. Closes always pass — a protective
    # exit must never be blocked by entry gating.
    if live_intent and not is_close:
        if not _is_market_open() and not bool(pd.get("force_execute")):
            await state.set(sig_key, "rejected", ex=86400)
            await _record_dispatch_verdict(pd, "rejected", "market_closed")
            return {"status": "rejected", "reason": "market_closed", "signal_id": sig_key}
        ok, blocked = await _passes_entry_filters(pd)
        if not ok:
            await state.set(sig_key, "rejected", ex=86400)
            await trade_ledger.record("entry_rejected", {
                "ticker": str(pd.get("ticker") or "").upper(),
                "action": pd.get("action"),
                "blocked_by": blocked,
            })
            await _record_dispatch_verdict(pd, "rejected", "; ".join(blocked))
            return {"status": "rejected", "reason": "; ".join(blocked), "signal_id": sig_key}
        cooldown_key = f"cooldown:{str(pd.get('ticker') or '').upper()}"
        # NX write doubles as the existence check — atomic even across workers.
        if not await state.set(cooldown_key, "1", ex=TICKER_COOLDOWN_MINUTES * 60, nx=True):
            await state.set(sig_key, "cooldown", ex=86400)
            await _record_dispatch_verdict(pd, "cooldown", "ticker_in_cooldown")
            return {"status": "cooldown", "reason": "ticker_in_cooldown", "signal_id": sig_key}

    job = {"payload": pd}
    if state.is_distributed:
        try:
            await state.queue_push(QUEUE_KEY, json.dumps(job))
            await state.set(sig_key, "queued", ex=86400)
            await _record_dispatch_verdict(pd, "queued", "live" if live_intent else "non-live payload")
            return {"status": "queued", "signal_id": sig_key}
        except Exception as e:
            logger.warning(f"Redis push failed, processing directly: {e}")
    try:
        result = await execute_live_order(pd)
        await state.set(sig_key, str(result.get("status") or "processed"), ex=86400)
        inner_status = str(result.get("status") or "processed")
        inner_reason = str(result.get("reason") or "") if inner_status != "success" else ""
        await _record_dispatch_verdict(
            pd,
            "placed" if inner_status == "success" else inner_status,
            inner_reason,
        )
        return {"status": "processed_directly", "result": result, "signal_id": sig_key}
    except Exception as e:
        err = str(e)
        # A 401 here means the E*TRADE session died between dispatch and
        # placement (the disconnect→relink gap). Park the signal so the relink
        # replays it instead of silently losing the trade.
        if live_intent and _is_auth_error(err):
            _park_signal(pd)
            await state.set(sig_key, "parked", ex=86400)
            await _record_dispatch_verdict(pd, "parked", f"auth error — replays after relink: {err[:120]}")
            return {
                "status": "error",
                "message": f"{err} — signal parked; auto-replays after relink",
                "parked": True,
                "signal_id": sig_key,
            }
        await state.set(sig_key, "failed", ex=86400)
        logger.error(f"Direct processing failed: {e}")
        await _record_dispatch_verdict(pd, "failed", err[:200])
        return {"status": "error", "message": str(e), "signal_id": sig_key}


