@app.get("/status")
async def status():
    """Broker-state snapshot polled by the app's Reconciliation engine. The
    shape matches etrade_bot_handler's /status (open_positions keyed by ticker
    with qty/entry/stop/target/ts/contract), now read from reconciled Redis
    state and enriched with the last reconciliation report."""
    daily = await state.get_daily()
    broker_snapshot = await _load_account_snapshot()
    last_reconcile = None
    raw_report = await state.get("reconcile:last")
    if raw_report:
        try:
            last_reconcile = json.loads(raw_report)
        except json.JSONDecodeError:
            last_reconcile = None
    return {
        "killed": await state.is_killed(),
        "env": ENV,
        "live_trading": LIVE_TRADING,
        "version": BOT_VERSION,
        "market_open": _is_market_open(),
        "open_positions": await state.all_positions(),
        "stop_guards": await state.all_guards(),
        "trades_today": daily["trades_today"],
        "realized_pnl_today_pct": daily["realized_pnl_today_pct"],
        "daily_pnl_repair": _last_pnl_repair,
        "circuit_breaker_open": await _breaker_is_open(),
        "state_backend": state.backend_name,
        "last_reconcile": last_reconcile,
        # THE ACCOUNT AS THE BROKER SEES IT. `open_positions` above is the bot's
        # own memory of trades the bot placed; this is the portfolio E*TRADE
        # actually holds, including positions nothing here opened. Served from
        # the reconciler's published snapshot so /status stays a cheap read.
        "broker_snapshot": broker_snapshot,
        "broker_snapshot_age_seconds": _snapshot_age(broker_snapshot),
        # What the server can see of the app: connected, armed, money mode, and
        # every place the two disagree.
        "app_link": await _app_link_snapshot(),
        "reconcile_interval_seconds": RECONCILE_INTERVAL_SECONDS,
        "trail_engine": {
            "enabled": TRAIL_ENGINE_ENABLED,
            "interval_seconds": TRAIL_INTERVAL_SECONDS,
            "min_step_frac": TRAIL_MIN_STEP_FRAC,
        },
        "alert_webhook_configured": alerts.webhook_configured(),
        "account_binding": _account_binding,
        "recent_dispatches": await _recent_dispatch_verdicts(20),
        "broker_linked": load_tokens() is not None,
        **_token_session_fields(),
        "scanner": await scanner.status() if scanner else None,
        "filters": {
            "min_score": MIN_SCORE,
            "min_score_trending": MIN_SCORE_TRENDING,
            "min_rvol": MIN_RVOL,
            "min_mtf": MIN_MTF,
            "allowed_setups": sorted(ALLOWED_SETUPS),
        },
    }


